/* Built by tools/build-atlas.py — do not edit. card id -> [subtitle, mechanism lead, buzzword, FA pages, [short sources]] for every card a question links to: the question bank's On the Lesion Atlas panel */
window.ATLAS_CARDS={"mody2":["Glucokinase (GCK), liver + β cell","Glucokinase is the β-cell glucose sensor: high Km, high Vmax, induced by insulin, not inhibited by G6P. A loss-of-function allele raises the glucose set-point at which insulin is released.","Mild hyperglycemia in a young patient with an affected parent","73",["Robbins ch 24","Katzung ch 41"]],"thiamine":["TPP cofactor: PDH, α-KGDH, transketolase, branched-chain ketoacid DH","Thiamine pyrophosphate is the cofactor for four dehydrogenase/transferase reactions. Highly aerobic, glucose-dependent tissues — brain and heart — decompensate first.","Alcoholism, malnutrition, bariatric surgery","64",["Marks ch 23","Robbins ch 28"]],"polyol":["Aldose reductase → sorbitol dehydrogenase","When intracellular glucose is high, aldose reductase converts it to sorbitol. Tissues with little or no sorbitol dehydrogenase — Schwann cells, lens, retina, kidney — trap osmotically active sorbitol and consume NADPH, compounding oxidative stress.","Schwann cells, Lens, Retina, Kidneys lack sorbitol dehydrogenase","79, 709",["Robbins ch 24"]],"ethanol":["Alcohol dehydrogenase → aldehyde dehydrogenase","Both oxidations generate NADH, driving the NADH:NAD⁺ ratio up. Excess NADH pushes pyruvate → lactate and oxaloacetate → malate, stripping gluconeogenesis of its substrates, and diverts acetyl-CoA into ketones and fatty-acid synthesis.","Fomepizole inhibits alcohol dehydrogenase — antidote for methanol and ethylene glycol","70",["Katzung ch 23","Marks ch 33"]],"sdhmut":["Succinate dehydrogenase (= ETC complex II)","Succinate accumulates and inhibits prolyl hydroxylase, so HIF-1α escapes degradation — \"pseudohypoxia\" driving VEGF and a highly vascular tumor.","The only TCA enzyme embedded in the inner mitochondrial membrane","",["Robbins ch 7","Robbins ch 16"]],"accreg":["Acetyl-CoA carboxylase (biotin, ATP)","ACC makes malonyl-CoA, the committed step of fatty-acid synthesis. Its product also inhibits CPT-1, so the cell physically cannot synthesize and oxidize fatty acids at the same time.","Malonyl-CoA blocks CPT-1 — the reciprocal switch","71, 87",["Marks ch 31","Marks ch 34"]],"ketones":["HMG-CoA synthase-2 (mitochondrial, rate-limiting)","When oxaloacetate is consumed by gluconeogenesis, acetyl-CoA from β-oxidation cannot enter the TCA cycle and is condensed into acetoacetate and β-hydroxybutyrate.","Acetone gives the fruity breath but is not a fuel","88, 351",["Marks ch 30","Marks ch 33"]],"statin":["HMG-CoA reductase (rate-limiting step of cholesterol synthesis)","Statins competitively inhibit conversion of HMG-CoA to mevalonate in the cytosol. Hepatic cholesterol falls, SREBP is activated, and the liver upregulates LDL receptors — that receptor upregulation, not the synthesis block itself, is what clears plasma LDL.","Rate-limiting enzyme of cholesterol synthesis","324–325",["Katzung ch 35","Marks ch 32"]],"fh":["Absent or defective LDL receptor, or defective apoB-100","Hepatocytes cannot clear LDL from plasma, so LDL and its cholesterol cargo circulate for far longer and deposit in arterial intima and tendons.","Achilles tendon xanthoma","92, 305, 325",["Marks ch 32","Katzung ch 35"]],"hypertg":["Hepatic VLDL overproduction","The liver oversecretes VLDL; often unmasked by obesity, insulin resistance, alcohol, estrogen or thiazides.","Secondary causes first: alcohol, diabetes, thiazides, estrogens","92",["Katzung ch 35","Marks ch 32"]],"pku":["Phenylalanine hydroxylase (or BH4 cofactor)","Phenylalanine cannot be hydroxylated to tyrosine, so it accumulates and is shunted to phenylketones; tyrosine becomes essential, which starves melanin, dopamine and thyroxine synthesis.","Musty odor","82",["Robbins ch 10","Marks ch 37"]],"albinism":["Tyrosinase (or tyrosine transport)","Melanocytes are present in normal number but cannot convert tyrosine to melanin.","Chédiak–Higashi: partial albinism with immunodeficiency","59, 81, 115, 484",["Robbins ch 5","Pawlina ch 15"]],"homocyst":["Cystathionine β-synthase (B6) · methionine synthase (B12) · MTHFR","Homocysteine cannot be disposed of — either by transsulfuration to cystathionine (B6-dependent CBS) or by remethylation to methionine (B12 and folate).","Marfanoid + intellectual disability + thrombosis = homocystinuria","83",["Marks ch 37","Robbins ch 5"]],"cystinuria":["Dibasic amino-acid transporter, proximal tubule + gut","Reabsorption of Cystine, Ornithine, Lysine and Arginine fails. Cystine is the least soluble and precipitates in acidic urine.","COLA","83, 617",["Costanzo ch 8","Robbins ch 20"]],"b6":["ALT · AST · ALA synthase · cystathionine β-synthase · decarboxylases","Pyridoxal phosphate is the cofactor for transamination, decarboxylation and the first step of heme synthesis, plus glycogen phosphorylase and the synthesis of GABA, serotonin, dopamine and niacin.","Isoniazid and oral contraceptives can cause B6 deficiency — co-prescribe pyridoxine with INH","66, 425",["Marks ch 36","Marks ch 37"]],"lead":["δ-ALA dehydratase AND ferrochelatase","Lead inhibits ALA dehydratase and ferrochelatase and also inhibits rRNA degradation, leaving ribosomal remnants in RBC (basophilic stippling).","LEAD — Lead Lines, Encephalopathy/Erythrocyte stippling, Abdominal colic/sideroblastic Anemia, Drops (wrist/foot)","425",["Katzung ch 57","Robbins ch 9"]],"gout":["Xanthine oxidase · URAT1 · urate oxidase","Uric acid is the end product of purine degradation in humans, who lack urate oxidase. Underexcretion (90%) or overproduction (10%) supersaturates synovial fluid, and monosodium urate crystals trigger an IL-1β-driven neutrophilic arthritis.","Allopurinol / febuxostat = xanthine oxidase inhibitors","473",["Katzung ch 36","Robbins ch 26"]],"nucdrugs":["RNR · thymidylate synthase · DHFR · IMP dehydrogenase · PRPP amidotransferase","Antimetabolites exploit the fact that dividing cells must make nucleotides de novo. Each drug sits at a named enzyme worth memorizing by position on the map.","Both MTX and 5-FU ultimately starve the cell of dTMP → \"thymineless death\"","34",["Katzung ch 54","Katzung ch 33"]],"cah21":["21-Hydroxylase (CYP21A2)","Both cortisol and aldosterone synthesis are blocked, so ACTH rises unopposed and drives adrenal hyperplasia. The accumulated 17-OH-progesterone is shunted down the only open path — androgens.","↓ BP · ↑ K⁺ · ↑ androgens","339, 353",["Robbins ch 24","Katzung ch 39"]],"cah11":["11β-Hydroxylase (CYP11B1)","Cortisol and aldosterone are still low, but the block accumulates 11-deoxycorticosterone, which is itself a weak mineralocorticoid. Enough of it builds up to cause salt retention and hypertension — the opposite blood pressure from 21-hydroxylase deficiency.","↑ BP · ↓ K⁺ · ↑ androgens","339",["Robbins ch 24","Katzung ch 39"]],"cah17":["17α-Hydroxylase / 17,20-lyase","The block sits at the entrance to both the cortisol and the sex-steroid arms, so everything is pushed into the mineralocorticoid column. It is the only CAH with low androgens.","↑ BP · ↓ K⁺ · ↓ androgens","339",["Robbins ch 24","Langman ch 16"]],"reductase5a":["5α-Reductase type 2","Testosterone is made normally but cannot be converted to dihydrotestosterone. DHT drives the external male genitalia and prostate; testosterone alone drives the internal Wolffian structures — so internal anatomy is male while external anatomy is not.","Ambiguous genitalia that virilize at puberty","640, 656",["Langman ch 16","Costanzo ch 10"]],"ais":["Androgen receptor (AR)","Enzymes are intact — the receptor is not. Testosterone and DHT are made in normal or high amounts but cannot act, while anti-Müllerian hormone from the Sertoli cells still regresses the uterus and upper vagina.","Phenotypic female with primary amenorrhea and no pubic hair","656",["Langman ch 16","Costanzo ch 10"]],"zonereg":["Zona glomerulosa · fasciculata · reticularis","Each zone expresses a different enzyme set, so each makes a different product and answers to a different signal. The glomerulosa lacks 17α-hydroxylase (so it cannot make cortisol or androgens) and uniquely expresses aldosterone synthase.","GFR — Salt, Sugar, Sex","331, 339",["Costanzo ch 9","Robbins ch 24"]],"oi":["COL1A1 / COL1A2 — type I collagen triple helix","A glycine substitution in the Gly-X-Y repeat prevents the three α-chains from packing into a helix. Because the defective chain poisons the whole trimer, a single mutant allele is enough — a classic dominant negative.","Blue sclerae + fractures + hearing loss","49",["Robbins ch 26","Robbins ch 5"]],"wilson":["ATP7B — hepatic copper excretion into bile","Copper cannot be loaded onto ceruloplasmin or excreted in bile, so it accumulates in hepatocytes, spills into blood as free copper, and deposits in brain, cornea and kidney where it catalyzes free-radical damage.","Young patient with liver disease plus a movement disorder","402",["Robbins ch 18","Katzung ch 28"]],"alport":["COL4A5 — type IV collagen α5 chain","Type IV collagen forms the meshwork of every basement membrane. A defective α-chain splits and thickens the glomerular basement membrane, and the same collagen sits in the cochlea and the lens.","\"Can't see, can't pee, can't hear a bee\"","48, 615",["Robbins ch 20","Bootcamp.com Nephrology"]],"goodpasture":["Antibodies against the α3 chain of type IV collagen","IgG binds the non-collagenous domain of α3(IV), which is shared by the glomerular and alveolar basement membranes — so one antibody attacks both organs.","Linear immunofluorescence","613, 614, 730",["Robbins ch 20","Robbins ch 15"]],"marfan":["FBN1 — fibrillin-1 microfibrils","Fibrillin forms the scaffold that elastin is deposited on, and it also sequesters TGF-β. Losing it weakens elastic tissue and releases excess TGF-β signalling, which drives aortic root dilation.","Lens up and out","50, 83",["Robbins ch 5","Robbins ch 11"]],"a1at":["Inhibitor of neutrophil elastase","Unopposed neutrophil elastase digests alveolar elastin, so the lung loses recoil.","Basilar panacinar emphysema in a young non-smoker","400",["Robbins ch 15","Robbins ch 18"]],"collagentypes":["Types I–IV","Four types cover nearly everything tested. The mnemonic is \"Be (So Totally) Cool, Read Books\" — bone/skin/tendon, cartilage, reticulin, basement membrane.","Type I = bONE","48, 212",["Pawlina ch 6","Marks ch 47"]],"b9def":["Tetrahydrofolate — one-carbon transfer, dTMP synthesis","Without THF the cell cannot make dTMP, so DNA synthesis lags while RNA and protein synthesis continue — the nucleus stays immature while the cytoplasm matures.","Supplement before conception — deficiency causes neural tube defects","426",["Katzung ch 33","Robbins ch 14"]],"b12def":["Methionine synthase · methylmalonyl-CoA mutase","B12 serves only two human enzymes. Losing methionine synthase gives the megaloblastic anemia (through the methyl-folate trap); losing methylmalonyl-CoA mutase lets methylmalonic acid accumulate, which destabilizes myelin.","Causes: pernicious anemia, gastric bypass, terminal ileal resection or Crohn disease, Diphyllobothrium latum, bacterial overgrowth, metformin, veganism","67",["Katzung ch 33","Marks ch 38"]],"vitadef":["Retinal (vision) · retinoic acid (epithelial differentiation)","Retinal is the chromophore of rhodopsin; retinoic acid is a nuclear-receptor ligand that drives epithelial differentiation and mucus production.","Teratogenic — a negative pregnancy test and two forms of contraception before isotretinoin","64",["Robbins ch 9","Katzung ch 61"]],"vitddef":["25-Hydroxylase (liver) · 1α-hydroxylase (kidney)","Calcitriol raises serum calcium and phosphate by increasing intestinal absorption of both, and permits normal bone mineralization. The final activation step is in the kidney and is stimulated by PTH and low phosphate.","Granulomatous disease (sarcoidosis, TB) makes calcitriol in macrophages → hypercalcemia","68, 468",["Robbins ch 9","Katzung ch 42"]],"vitkdef":["γ-Glutamyl carboxylase (epoxide reductase recycles it)","γ-Carboxylation adds a calcium-binding group to factors II, VII, IX, X and proteins C and S, letting them anchor to phospholipid membranes.","Refusing the newborn vitamin K shot → hemorrhagic disease of the newborn","69, 419",["Katzung ch 34","Robbins ch 14"]],"warfarin":["Vitamin K epoxide reductase (VKORC1)","Warfarin blocks vitamin K epoxide reductase, so γ-carboxylation of II, VII, IX, X, C and S fails. Protein C has a shorter half-life than factors II and X, so it falls first — producing a transient hypercoagulable window at the start of therapy.","\"The ex-PresidenT went to war(farin)\" — extrinsic pathway, PT","441",["Katzung ch 34","Marks ch 43"]],"acetaminophen":["NAPQI conjugation by reduced glutathione","At normal doses most acetaminophen is glucuronidated or sulfated, and the small amount converted by CYP2E1 to the reactive metabolite NAPQI is mopped up by glutathione.","N-acetylcysteine regenerates glutathione","73, 397, 495",["Marks ch 44","Robbins ch 18"]],"rb":["RB1 — holds E2F at the G1/S restriction point","Unphosphorylated Rb clamps the transcription factor E2F. Cyclin D–CDK4/6 phosphorylates Rb, releasing E2F and committing the cell to S phase.","Leukocoria in an infant","220, 552",["Robbins ch 7","Marks ch 17"]],"cdk46":["Cyclin D–CDK4/6","Blocking CDK4/6 leaves Rb unphosphorylated, so E2F stays clamped and the cell cannot pass the restriction point into S phase.","Cyclin D is overexpressed in mantle cell lymphoma, t(11;14)","254, 447",["Robbins ch 7","Katzung ch 54"]],"chemophase":["S phase · G2 · M · phase-nonspecific","Cell-cycle-specific agents only kill dividing cells, so they hit rapidly cycling tissue hardest — marrow, gut mucosa, hair follicles — which is exactly where their toxicity shows up.","Labile tissue (marrow, gut, hair) explains most chemo toxicity","443, 444, 445",["Katzung ch 54"]],"raasdrugs":["Renin · ACE · AT1 receptor · mineralocorticoid receptor · neprilysin","ACE has a second job: it degrades bradykinin. Blocking it therefore raises both the benefit (less angiotensin II) and the side effect (more bradykinin).","Cough → switch the -pril to a -sartan","628",["Katzung ch 13","Katzung ch 11"]],"conn":["Autonomous aldosterone secretion","An adenoma or bilateral hyperplasia secretes aldosterone independently of angiotensin II. The volume expansion suppresses renin — which is what separates primary from every secondary cause.","Hypertension + hypokalemia + metabolic alkalosis","354",["Costanzo ch 9","Robbins ch 24"]],"renovascular":["Renin release from the juxtaglomerular apparatus","A stenotic renal artery makes the kidney perceive low perfusion, so the JG cells pour out renin.","String of beads in a young woman with hypertension","623",["Robbins ch 11","Robbins ch 20"]],"natriuretic":["Natriuretic peptides · neprilysin degrades them","Atrial and ventricular stretch releases ANP and BNP, which act through cGMP to dilate the afferent arteriole, constrict the efferent, and inhibit renin, aldosterone and sodium reabsorption — the physiologic opposite of the RAAS.","Sacubitril blocks neprilysin so ANP/BNP last longer","299, 606",["Katzung ch 17","Costanzo ch 6"]],"hyperpara1":["Autonomous PTH secretion — usually a single adenoma","PTH raises calcium by three routes: osteoclastic bone resorption (indirectly, via RANKL on osteoblasts), distal tubular calcium reabsorption, and renal 1α-hydroxylase activation to make calcitriol.","Hypercalcemia found incidentally on a chemistry panel","336, 349",["Robbins ch 24","Katzung ch 42"]],"hyperpara2":["Appropriate PTH response to chronic hypocalcemia","In chronic kidney disease, failing 1α-hydroxylase lowers calcitriol while phosphate is retained. Both drive calcium down, and the parathyroids respond with sustained hypertrophy.","Low calcium with HIGH phosphate = kidney; low calcium with LOW phosphate = vitamin D","348, 349, 361",["Katzung ch 42","Robbins ch 24"]],"hypopara":["Absent or insufficient PTH","Without PTH the kidney stops reabsorbing calcium and stops making calcitriol, while phosphate is retained. The low ionized calcium lowers the threshold for nerve depolarization, producing tetany.","Tetany days after a thyroidectomy","114, 348, 609",["Robbins ch 24","Katzung ch 42"]],"pha":["GNAS — Gs-α coupling to the PTH receptor","The parathyroids work; the target tissue does not respond. A defective Gs-α subunit uncouples the PTH receptor from adenylate cyclase, so kidney and bone are blind to a rising PTH.","Short 4th and 5th knuckles","348",["Robbins ch 24","Costanzo ch 9"]],"fhh":["Calcium-sensing receptor (CASR)","An inactivating CaSR mutation makes the parathyroid and the renal tubule read the serum calcium as lower than it is. The set-point shifts upward: PTH stays inappropriately normal and the kidney avidly reabsorbs calcium.","Higher-than-normal calcium is needed to suppress PTH","349, 361",["Katzung ch 42","Robbins ch 24"]],"calciumdrugs":["Farnesyl-PP synthase · RANKL · PTH receptor · CaSR","Bone turnover is a balance between osteoclasts (resorb) and osteoblasts (build), and RANKL from osteoblasts is the signal that activates osteoclasts.","Pulsatile PTH builds bone, continuous PTH destroys it","336, 361, 462, 467, 496",["Katzung ch 42","Pawlina ch 8"]],"filtrationbarrier":["Fenestrated endothelium · GBM · podocyte foot processes","Three layers filter by size and charge. The basement membrane's heparan sulfate gives it a strong negative charge, which repels albumin. Lose the charge and you get selective albuminuria; lose the structure and you get everything.","Frothy urine with periorbital edema in a child = minimal change","599, 613",["Robbins ch 20","Pawlina ch 20"]],"diabetickidney":["Nonenzymatic glycosylation of the GBM and efferent arteriole","Glycosylation stiffens the efferent arteriole more than the afferent, so intraglomerular pressure rises — an early hyperfiltration phase that slowly scars the mesangium.","Kimmelstiel-Wilson nodule","616, 628",["Robbins ch 20","Robbins ch 24"]],"nsaidkidney":["Cyclooxygenase → afferent arteriolar prostaglandins","Prostaglandins keep the afferent arteriole dilated. When renal perfusion is already low — hypovolemia, heart failure, cirrhosis, renal artery stenosis — that dilation is the only thing preserving GFR.","ACE inhibitors dilate the EFFERENT; NSAIDs constrict the AFFERENT — both drop GFR","601, 607, 620",["Robbins ch 20","Katzung ch 15"]],"acetazolamide":["Carbonic anhydrase (proximal tubule)","Blocking carbonic anhydrase prevents bicarbonate reabsorption in the PCT, so NaHCO₃ is lost in the urine. The effect is self-limiting — once serum bicarbonate falls, the drug has little left to block.","\"ACID-azolamide causes acidosis\"","626",["Katzung ch 15","Costanzo ch 7"]],"sglt2":["Sodium-glucose cotransporter 2 (proximal tubule)","SGLT2 reabsorbs most filtered glucose in the PCT.","Glucosuria with a normal or near-normal serum glucose","316, 359",["Katzung ch 15","Katzung ch 41"]],"mannitol":["Osmotic diuretic — filtered but not reabsorbed","A freely filtered sugar alcohol that holds water in the tubular lumen along the whole nephron and pulls water out of cells into the vasculature.","Pulls water out of the brain — but can flood the lungs first","626",["Katzung ch 15","Guyton ch 32"]],"loopdiuretics":["Na⁺-K⁺-2Cl⁻ cotransporter (NKCC2), thick ascending limb","NKCC2 drives the countercurrent multiplier, so blocking it abolishes the medullary concentration gradient — the most powerful diuresis available.","Loops LOSE calcium; thiazides KEEP calcium","626",["Katzung ch 15","Costanzo ch 6"]],"bartter":["NKCC2 (thick ascending limb)","A genetic loop diuretic. The same transporter is lost, so the phenotype copies furosemide taken continuously from birth.","Looks like a patient secretly taking furosemide","604",["Katzung ch 15","Costanzo ch 6"]],"thiazides":["Na⁺-Cl⁻ cotransporter (NCC), distal convoluted tubule","Blocking NCC lowers intracellular sodium in the DCT cell, which increases basolateral Na⁺/Ca²⁺ exchange and therefore calcium reabsorption — the reason thiazides raise serum calcium and lower urinary calcium.","Thiazides KEEP calcium, loops LOSE it","627",["Katzung ch 15","Costanzo ch 6"]],"gitelman":["NCC (distal convoluted tubule)","A genetic thiazide — the same transporter, the same electrolyte signature, and like thiazides it conserves calcium.","GiTelman = DisTal convoluted tubule, and it's genTler than Bartter","604, 625",["Katzung ch 15","Costanzo ch 6"]],"ksparing":["ENaC (amiloride, triamterene) · mineralocorticoid receptor (spironolactone, eplerenone)","Sodium entering the principal cell through ENaC creates the lumen-negative potential that drives K⁺ and H⁺ secretion. Block ENaC directly, or block the aldosterone receptor that transcribes it, and you keep potassium instead of losing it.","Spironolactone for ascites: aldosterone is high in cirrhosis","627",["Katzung ch 15","Costanzo ch 6"]],"liddle":["ENaC gain of function (principal cell)","A mutation prevents ENaC from being degraded, so the channel stays in the membrane regardless of aldosterone. Sodium is reabsorbed relentlessly, which expands volume and suppresses both renin and aldosterone.","Liddle = Little aldosterone, and it responds to amiloride, not spironolactone","603, 604",["Katzung ch 15","Costanzo ch 6"]],"ame":["11β-Hydroxysteroid dehydrogenase type 2","Cortisol binds the mineralocorticoid receptor just as well as aldosterone. Normally 11β-HSD2 in the principal cell converts cortisol to inactive cortisone so it never gets the chance.","Hypertension and hypokalemia in a licorice eater","604",["Guyton ch 78","Katzung ch 39"]],"adhdrugs":["V2 receptor → cAMP → aquaporin-2 insertion","ADH acting on V2 receptors inserts aquaporin-2 into the apical membrane of the principal cell, letting water follow the medullary gradient.","Too fast correction of hyponatremia → osmotic demyelination (locked-in syndrome)","333, 342, 360, 538",["Katzung ch 15","Katzung ch 37"]],"di":["ADH production (central) or V2 response (nephrogenic)","Without ADH signal or ADH response, the collecting duct stays impermeable to water and dilute urine pours out regardless of plasma osmolality.","Desmopressin separates central from nephrogenic","342",["Katzung ch 15","Guyton ch 29"]],"siadh":["Inappropriate ADH release","ADH is secreted despite a low plasma osmolality, so water is retained and the serum sodium falls. Volume status stays near-normal because aldosterone escape and natriuretic peptides dump the excess sodium — which is why urine sodium is high.","Euvolemic hyponatremia with concentrated urine and high urine sodium","342",["Katzung ch 15","Katzung ch 37"]],"rta":["Distal H⁺ ATPase (1) · proximal HCO₃⁻ reabsorption (2) · aldosterone (4)","All three produce a normal anion gap (hyperchloremic) metabolic acidosis because the kidney, not metabolism, is the problem. What separates them is where the defect sits and what happens to potassium.","Type 1 stones are calcium PHOSPHATE because the urine is alkaline","611",["Guyton ch 31","Robbins ch 20"]],"fanconisyn":["Generalized proximal tubular reabsorption failure","Everything the PCT normally reclaims is lost at once — glucose, amino acids, phosphate, bicarbonate, uric acid. Not related to Fanconi anemia, which is a DNA repair disease.","Sugar in the urine of a patient who is not diabetic","604, 611",["Guyton ch 32","Katzung ch 15"]],"atn":["Proximal tubule and thick ascending limb epithelium","The PCT and the medullary thick ascending limb have the highest metabolic demand and the lowest oxygen tension in the kidney, so they die first in ischemia.","Muddy brown casts","621",["Robbins ch 20","Guyton ch 32"]],"ain":["Drug-induced hypersensitivity of the renal interstitium","A delayed hypersensitivity reaction to a drug hapten in the interstitium — not dose-dependent, and it can begin days to weeks after exposure.","AKI plus a rash plus eosinophils a week after a new antibiotic","620",["Robbins ch 20","Katzung ch 36"]],"ethyleneglycol":["Alcohol dehydrogenase → toxic metabolites","Alcohol dehydrogenase converts ethylene glycol to glycolic and then oxalic acid, which precipitates as calcium oxalate in the tubules, and methanol to formic acid, which poisons the retina.","Envelope-shaped crystals with AKI = ethylene glycol","70, 617",["Katzung ch 23","Katzung ch 58"]],"rhabdo":["Myoglobin cast nephropathy","Myoglobin released from dying muscle is filtered, precipitates in the tubules and is directly toxic to tubular epithelium — a cause of ATN.","Blood on dipstick, no red cells under the microscope","191, 465, 566",["Robbins ch 20","Robbins ch 27"]],"stones":["Urinary supersaturation and pH","Stone type is decided by what is supersaturated and at what urine pH it precipitates — which is why the same patient's chemistry predicts the crystal.","Staghorn = struvite (or cystine)","617",["Robbins ch 20","Katzung ch 15"]],"prerenal":["↓ Renal perfusion — the kidney itself is intact","Blood flow falls, so GFR falls — but the tubules are undamaged and starving for sodium. Under aldosterone and ADH they reabsorb sodium and water avidly, and urea is dragged along with the water.","The kidney is not injured, it is thirsty","118, 601, 607, 612, 620",["Robbins ch 20","Costanzo ch 6"]],"class2":["β1 receptor → cAMP → phase 4 slope","Blocking β1 lowers cAMP, which flattens the phase 4 slope in nodal tissue and slows AV conduction. Rate falls, the AV node protects the ventricle, and myocardial oxygen demand drops.","β-blockers are treatment for aortic dissection, and for rate control in AF","244, 327",["Katzung ch 10","Katzung ch 14"]],"class3":["Delayed rectifier K⁺ channel (phase 3)","Blocking the repolarizing potassium current prolongs the action potential and the refractory period — which is therapeutic, and which is also why every drug in this class lengthens the QT.","Amiodarone: check the lungs, liver and thyroid","328",["Katzung ch 14"]],"afib":["Chaotic atrial re-entry, usually from the pulmonary veins","Multiple disorganized re-entrant wavelets replace the coordinated P wave. The AV node filters them irregularly, so the ventricular response is irregularly irregular.","Irregularly irregular with absent P waves","311",["Robbins ch 12","Katzung ch 14"]],"wpw":["Accessory pathway (bundle of Kent)","An accessory bundle bypasses the AV node and pre-excites part of the ventricle, so the PR shortens and the QRS begins with a slurred delta wave.","Delta wave with a short PR","303, 311",["Katzung ch 14"]],"longqt":["Delayed rectifier K⁺ channels (or drugs that block them)","Slower repolarization lengthens the QT and creates a window for early afterdepolarizations, which trigger a polymorphic ventricular tachycardia that twists around the baseline — torsades de pointes.","Deafness plus syncope in a child = Jervell and Lange-Nielsen","312",["Katzung ch 14"]],"hf":["Impaired ejection (HFrEF) or impaired filling (HFpEF)","A failing ventricle drops cardiac output, which triggers RAAS and sympathetic activation.","S3 in a dilated volume-overloaded ventricle; S4 in a stiff hypertrophied one","299, 316",["Robbins ch 12","Guyton ch 22"]],"cardiomyopathy":["Sarcomere, cytoskeleton or infiltrate","Three geometries, three physiologies: a dilated thin ventricle that cannot eject, a thick ventricle that cannot fill or that obstructs outflow, and a stiff infiltrated ventricle that cannot expand.","Young athlete who collapses during exertion → hypertrophic cardiomyopathy","315",["Robbins ch 12"]],"mi":["Coronary supply vs myocardial oxygen demand","The left ventricle is perfused almost entirely during diastole, so tachycardia shortens supply exactly when demand rises.","Inferior MI with hypotension after nitroglycerin → right ventricular infarct, give fluids","308, 310, 314, 315",["Robbins ch 12","Katzung ch 12"]],"nitrates":["NO → guanylate cyclase → cGMP → venodilation","Nitrates release nitric oxide, raising cGMP in vascular smooth muscle. They dilate veins much more than arteries, so the dominant effect is a fall in preload, which cuts wall tension and myocardial oxygen demand.","Monday disease: industrial nitrate exposure, tolerance over the week, headache and tachycardia on return","322",["Katzung ch 12","Katzung ch 19"]],"deadspace":["Anatomic vs physiologic dead space","The first ~150 mL of each breath never reaches an alveolus. Anything ventilated but not perfused adds to it, so physiologic dead space is the sum of the plumbing and the wasted alveoli.","Pulmonary embolism is the classic cause of increased dead space","680, 682",["Costanzo ch 5","Guyton ch 38"]],"aagradient":["PAO₂ = 150 − PaCO₂ / 0.8 (room air, sea level)","Comparing the oxygen the alveolus should contain with what actually reaches the artery separates problems of ventilation from problems of gas exchange.","Hypoxemia that will not correct with 100% oxygen = shunt","685, 686",["Costanzo ch 5","Guyton ch 43"]],"vq":["Ventilation-to-perfusion ratio","6). Hypoxic pulmonary vasoconstriction diverts blood away from poorly ventilated alveoli to limit mismatch.","Apex: high V/Q, TB reactivation. Base: low V/Q, most blood flow","684, 685, 686",["Costanzo ch 5","Robbins ch 15"]],"hypoxemia":["","Ordering them by A–a gradient and response to oxygen solves almost every arterial blood gas question.","Only shunt fails to correct with 100% oxygen","686, 687",["Costanzo ch 5","Guyton ch 43"]],"cohb":["Hemoglobin O₂ binding (and cytochrome c oxidase)","CO binds hemoglobin with more than 200 times the affinity of oxygen, so it both removes carrying capacity and left-shifts the curve on the remaining hemes, making them release less oxygen to tissue.","Pulse oximeter lies in CO poisoning","689",["Katzung ch 56","Katzung ch 58"]],"methb":["Heme iron oxidized Fe²⁺ → Fe³⁺","Ferric heme cannot bind oxygen at all, and it left-shifts the remaining ferrous hemes, so delivery falls twice over.","Blue patient, brown blood, normal PaO₂","688",["Katzung ch 58","Costanzo ch 5"]],"asthma":["Bronchial hyperresponsiveness and type 2 inflammation","Allergen cross-links IgE on mast cells → early bronchospasm; recruited eosinophils and Th2 cytokines drive the late phase and remodeling. Obstruction is reversible, which is the defining feature.","Pulsus paradoxus in a severe attack","317, 693",["Robbins ch 15","Katzung ch 20"]],"copd":["Protease–antiprotease imbalance · mucous gland hypertrophy","Smoke recruits neutrophils and macrophages whose elastase overwhelms α1-antitrypsin, destroying alveolar walls. Losing the walls also loses the radial traction that holds small airways open, so they collapse on expiration — irreversible airflow limitation.","DLCO separates emphysema (low) from asthma and chronic bronchitis (normal)","692, 693",["Robbins ch 15","Costanzo ch 5"]],"asthmadrugs":["β2 · muscarinic · leukotriene · IgE · phosphodiesterase","Relievers relax smooth muscle immediately; controllers suppress the inflammation that causes the hyperresponsiveness. Only controllers change the disease.","LABA alone in asthma raises asthma deaths — always pair with an inhaled steroid","704",["Katzung ch 20","Katzung ch 55"]],"cf":["CFTR chloride channel (ΔF508)","A misfolded CFTR never reaches the membrane, so chloride (and water) cannot be secreted onto airway surfaces. Mucus becomes thick and immobile.","Salty-tasting baby","58",["Robbins ch 10","Robbins ch 17"]],"nrds":["Surfactant (dipalmitoylphosphatidylcholine) from type II pneumocytes","Surfactant lowers alveolar surface tension. By Laplace's law (P = 2T/r) small alveoli would otherwise collapse into large ones; without surfactant they do, producing diffuse atelectasis and a massive right-to-left shunt.","Supplemental O₂ complications: Retinopathy of prematurity, Intraventricular hemorrhage, Bronchopulmonary dysplasia (RIB); persistent PDA","679",["Robbins ch 10"]],"ards":["Diffuse alveolar damage","An inflammatory insult makes the alveolar-capillary membrane leak protein-rich fluid. Surfactant is inactivated, alveoli collapse and flood, and the result is a large intrapulmonary shunt that oxygen alone cannot fix.","Hyaline membranes in an adult after sepsis","697",["Robbins ch 15","Costanzo ch 5"]],"pe":["Occlusion of pulmonary arterial flow","A thrombus — usually from the deep veins of the leg — lodges in the pulmonary artery. The lung distal to it is ventilated but not perfused, the definition of dead space.","Increased dead space with a normal chest radiograph","321, 691",["Robbins ch 4","Robbins ch 15"]],"pulmhtn":["Endothelin · nitric oxide · prostacyclin imbalance","Sustained elevation of pulmonary arterial pressure forces the thin-walled right ventricle to work against a load it was never built for, ending in right heart failure — cor pulmonale.","Parasternal heave of RV hypertrophy","698, 706",["Robbins ch 12","Robbins ch 15"]],"ild":["Fibroblast proliferation in the interstitium","Repeated alveolar injury heals by fibrosis instead of regeneration. A thickened stiff interstitium restricts expansion and lengthens the diffusion path — a restrictive pattern with a low DLCO.","Fine dry crackles with clubbing → pulmonary fibrosis","694, 695",["Robbins ch 15"]],"pneumoconiosis":["Inhaled mineral dust ingested by alveolar macrophages","Inhaled mineral dust reaches the alveolus and is taken up by macrophages, which release fibrogenic factors that drive fibrosis around the dust.","Eggshell calcification → silicosis; then think TB","696",["Robbins ch 15"]],"altitude":["Hypoxic ventilatory response and renal compensation","Barometric pressure falls, so inspired PO₂ falls while the fraction of oxygen stays 21%. Peripheral chemoreceptors drive hyperventilation, which produces a respiratory alkalosis that the kidney then compensates by excreting bicarbonate.","Acetazolamide prevents and treats it — the bicarbonate diuresis creates a metabolic acidosis that lets the patient keep hyperventilating","688",["Costanzo ch 5","Guyton ch 44"]],"nsaids":["Cyclooxygenase — reversible, both isoforms","Reversible competitive inhibition of COX-1 and COX-2.","AKI risk is highest with pre-existing kidney disease or volume depletion","287, 495, 496",["Katzung ch 36","Katzung ch 18"]],"aspirin":["Cyclooxygenase — irreversible acetylation","Aspirin covalently acetylates a serine in the COX active site, so the enzyme is inactivated for good. Platelets have no nucleus and cannot make new COX-1, so the effect lasts for the platelet's 7–10 day lifespan.","Irreversible, so the effect tracks platelet turnover, not the half-life","254, 496, 693",["Katzung ch 36","Robbins ch 9"]],"coxibs":["COX-2","COX-2 is the inducible isoform at sites of inflammation, so blocking it selectively spares the COX-1 that protects gastric mucosa and platelets.","Good for the stomach, bad for the arteries","496",["Katzung ch 18","Katzung ch 36"]],"cortico":["Phospholipase A₂ (via annexin A1 / lipocortin)","Glucocorticoids induce annexin A1, which inhibits phospholipase A₂ — the step that liberates arachidonic acid from membrane phospholipid. Because that is upstream of the branch point, they shut down the COX arm and the lipoxygenase arm together.","Steroids block BOTH arms; NSAIDs block only COX","495",["Katzung ch 18","Katzung ch 39"]],"pgdrugs":["PGE₁ · PGE₂ · PGF₂α · PGI₂ receptors","Given as drugs, prostaglandins do exactly what they do physiologically — which makes each one's use predictable from its receptor.","Ductus patency depends on PGE₂ — give PGE₁ to keep it open, an NSAID to close it","287, 406, 568, 706",["Katzung ch 18"]],"crohn":["Transmural vs mucosal inflammation","Crohn is transmural and can hit anywhere from mouth to anus with skip lesions — and when it takes the terminal ileum, it takes exactly the two things only that segment absorbs: B12 and bile acids.","Crohn = skip lesions, transmural, granulomas, terminal ileum","389",["Robbins ch 17","Katzung ch 62"]],"pancins":["Pancreatic lipase, proteases, amylase","Losing pancreatic enzymes means food is never broken into absorbable pieces — but the intestinal wall itself is healthy, which is why D-xylose (a sugar needing no digestion) is absorbed normally.","Steatorrhea with a normal D-xylose test","388, 404",["Robbins ch 19","Costanzo ch 8"]],"hemochrom":["HFE · hepcidin · ferroportin","There is no regulated route to excrete iron — the body controls its stores entirely at absorption.","Vitamin C increases iron absorption; high serum iron also predisposes to severe Vibrio vulnificus wound infection","67, 144, 402, 712",["Robbins ch 18","Robbins ch 14"]],"vwd":["von Willebrand factor","vWF does two jobs: it bridges subendothelial collagen to platelet GpIb for adhesion, and it carries factor VIII and protects it from degradation.","Normal platelet count with a long bleeding time","417, 433",["Robbins ch 14","Robbins ch 4"]],"itp":["Anti-GpIIb/IIIa autoantibodies","IgG against platelet surface glycoproteins tags them for splenic macrophage destruction. Production is fine — the marrow actually compensates with more and larger platelets — but consumption outruns it.","Isolated low platelets in a well-looking patient","432",["Robbins ch 14","Katzung ch 55"]],"ttp":["ADAMTS13 (TTP) · Shiga toxin endothelial injury (HUS)","ADAMTS13 normally chops ultra-large vWF multimers down to size. Without it, those giant multimers grab platelets out of flowing blood and form microthrombi throughout small vessels — consuming platelets and shredding red cells as they pass.","Normal coags with schistocytes = TTP/HUS. Prolonged coags with schistocytes = DIC","432",["Robbins ch 14","Robbins ch 20"]],"factorv":["Activated protein C · antithrombin III","Thrombin bound to endothelial thrombomodulin activates protein C, which with protein S inactivates factors Va and VIIIa — the body's own brake on the cascade.","Unprovoked DVT in a young patient with a family history","433",["Robbins ch 4","Katzung ch 34"]],"heparin":["Antithrombin III","Heparin does not inactivate anything itself — it binds antithrombin III and greatly accelerates its activity. Unfractionated heparin is long enough to bridge antithrombin to thrombin (IIa) and Xa both; LMWH is shorter and mainly potentiates anti-Xa activity.","Heparin works instantly and is monitored by PTT; warfarin takes days and is monitored by PT/INR","440, 441",["Katzung ch 34","Marks ch 43"]],"bcellreg":["VDJ recombination · BTK · CD40L · AID","B cells mature in the bone marrow to the point of making a surface receptor, then finish the job in the periphery after meeting antigen. Each inherited defect stops the line at a specific rung, and the lab pattern tells you which one.","Count the B cells first, then the immunoglobulins — the combination names the defect","103, 114, 115",["Robbins ch 6","Robbins ch 13"]],"xla":["Bruton tyrosine kinase (BTK)","BTK carries the signal from the pre-B-cell receptor. Without it the line arrests at the pre-B stage, so no mature B cells are ever made and no immunoglobulin of any class is produced.","A boy with no tonsils","114",["Robbins ch 6"]],"igadef":["IgA class switching","The commonest primary immunodeficiency by a wide margin, and usually asymptomatic — the other isotypes compensate at mucosal surfaces. It matters mostly for two things: mucosal infection and transfusion reactions.","Anaphylaxis after a transfusion in an otherwise healthy person","113, 114",["Robbins ch 6","Robbins ch 14"]],"hyperigm":["CD40L on T cells (or CD40 / AID on B cells)","The B cell needs a second signal — CD40L delivered by a helper T cell — before it will class switch. Without it the B cell can only make the isotype it started with, so IgM piles up while IgG, IgA and IgE are never made.","High IgM with everything else low","115",["Robbins ch 6","Katzung ch 55"]],"tcellreg":["Positive selection (cortex) · negative selection (medulla)","A thymocyte has to pass two opposite tests. In the cortex it must bind self-MHC well enough to be useful — fail and it dies by neglect. In the medulla it must not bind self-antigen too strongly — fail and it is deleted.","Positive selection is in the cortex, negative in the medulla","100",["Robbins ch 6","Pawlina ch 14"]],"digeorge":["3rd and 4th pharyngeal pouch development","2 microdeletion derails the third and fourth pharyngeal pouches, which is where the thymus and the parathyroids come from. The result is a T-cell defect and hypocalcaemia arriving together, plus the conotruncal cardiac lesions from neural crest involvement.","Neonatal tetany plus a heart murmur plus no thymic shadow","114",["Langman ch 17","Robbins ch 24"]],"scidx":["Common γ chain of the IL-2 receptor family","The common γ chain is shared by the receptors for IL-2, 4, 7, 9, 15 and 21.","The \"bubble boy\" disease","115",["Robbins ch 6"]],"aps1":["AIRE — autoimmune regulator","AIRE makes medullary thymic epithelium express tissue-specific self-antigens — insulin, thyroglobulin and so on — so that T cells reactive to them can be deleted.","Thrush plus tetany plus adrenal failure in a child","100",["Robbins ch 24","Robbins ch 6"]],"blsyn":["MHC class II transcription factors","CD4 cells are selected by binding MHC class II in the thymic cortex. If class II is never expressed, positive selection of the CD4 lineage cannot happen, and the antigen presentation that CD4 cells depend on afterwards is missing too.","Low CD4 with a negative HIV test","",["Robbins ch 6"]],"il12r":["IL-12 receptor β1 — Th1 differentiation","IL-12 from macrophages is the signal that pushes T cells down the Th1 path, and Th1 cells make the interferon-γ that activates macrophages to kill intracellular organisms.","Disseminated disease after a BCG vaccine","114",["Robbins ch 8","Robbins ch 6"]],"cgd":["NADPH oxidase (gp91phox and others)","The neutrophil's respiratory burst uses NADPH oxidase to convert O₂ into superoxide and then hydrogen peroxide, which is what actually kills the ingested organism.","Nitroblue tetrazolium fails to turn blue · \"granny's cats keep her positive\"","126",["Robbins ch 6","Robbins ch 3"]],"complementreg":["Classical · alternative · lectin pathways → C3 → MAC","Three different triggers converge on one step. C3 is the hub: everything above it is about how the cascade got started, and everything below it is the shared effector arm.","\"General Motors makes classic cars\" — IgG and IgM activate the classical pathway","104",["Robbins ch 3","Robbins ch 6"]],"thelperreg":["IL-12 · IL-4 · IL-6+TGF-β · TGF-β+IL-2","A naive CD4 cell is uncommitted. The cytokine present when it meets antigen decides what it becomes, and each subset then secretes the cytokine that reinforces itself and suppresses the others.","The cytokine in the room at the time decides the subset","100",["Robbins ch 6","Katzung ch 55"]],"ipex":["FOXP3 — the Treg master transcription factor","FOXP3 is what makes a CD4 cell into a regulatory T cell. Without Tregs there is no peripheral tolerance — the autoreactive clones that escaped thymic deletion are never restrained, so autoimmunity begins in infancy and hits several organs at once.","Neonatal diabetes plus intractable diarrhoea plus eczema in a boy","100",["Robbins ch 6","Robbins ch 24"]],"acutephase":["IL-1 · IL-6 · TNF-α","An activated macrophage releases these three together, and between them they produce almost everything we recognize as systemic inflammation: fever at the hypothalamus, a change in what the liver makes, and endothelial activation.","IL-1 is the endogenous pyrogen","106, 209",["Robbins ch 3"]],"sepsistnf":["TNF-α","In the right amount TNF-α is protective — it walls off infection and maintains granulomas.","TNF-α holds granulomas together — which is why blocking it reactivates tuberculosis","106, 317",["Robbins ch 4","Robbins ch 8"]],"tnfdrugs":["TNF-α","Monoclonal antibodies against TNF-α, except etanercept, which is a decoy receptor — a TNF receptor fused to an Fc fragment that mops up TNF before it reaches a real receptor.","Etanercept is a decoy receptor, not an antibody, and it fails in IBD","498",["Katzung ch 36","Katzung ch 55"]],"il6drugs":["IL-6 receptor (tocilizumab, sarilumab) · IL-6 (siltuximab)","Tocilizumab and sarilumab block the IL-6 receptor; siltuximab binds IL-6 itself. IL-6 is the main driver of the hepatic acute-phase response.","The drug for cytokine storm","106, 209",["Katzung ch 55","Katzung ch 36"]],"il17drugs":["IL-17A · the p40 subunit shared by IL-12 and IL-23","Ustekinumab binds the p40 subunit that IL-12 and IL-23 share, so it hits the Th1 and Th17 axes together. Secukinumab and ixekizumab block IL-17A itself, further downstream.","Ustekinumab hits the shared p40 subunit","498",["Katzung ch 36","Katzung ch 55"]],"igedrugs":["Free IgE","Binds the Fc portion of free IgE so it cannot dock onto the FcεRI receptor on mast cells and basophils. Crucially it binds only free IgE, not IgE already on a cell, so it cannot itself trigger degranulation.","Binds free IgE only — which is exactly why it is safe to give","705",["Katzung ch 20","Katzung ch 55"]],"sexdevreg":["SRY → AMH + testosterone → DHT","Three decisions in sequence, and each one is made by a different signal. Genetic sex sets gonadal sex, the gonad's secretions set the internal ducts, and DHT sets the external genitalia.","SRY makes the testis; the testis makes everything else","639–640",["Langman ch 16","Pawlina ch 22"]],"swyer":["SRY","The Y chromosome is present but SRY fails, so no testis forms — only a fibrous streak gonad.","46,XY with a uterus","640, 655, 656",["Langman ch 16"]],"mullerianfusion":["Fusion and resorption of the paired ducts","The uterus is built by fusing two ducts and then resorbing the septum between them.","","640",["Robbins ch 22","Langman ch 16"]],"ductremnants":["Vestiges of the regressed duct","Neither duct disappears completely. The remnants are clinically minor but are asked about precisely because naming them tests whether you know which duct is which.","Gartner duct cyst is a Wolffian leftover in a woman","639",["Langman ch 16"]],"klinefelter":["Extra X — seminiferous tubule dysgenesis","SRY is present so a testis forms and the male pathway runs, but the extra X causes seminiferous tubule dysgenesis. Sertoli cells fail first and Leydig function declines later, so inhibin falls before testosterone does — which is why FSH rises earliest.","Tall man with small firm testes and gynecomastia","655",["Robbins ch 5","Guyton ch 81"]],"kallmann":["Failure of GnRH neurons to migrate from the olfactory pit","GnRH neurons are born in the olfactory placode and migrate into the hypothalamus alongside the olfactory nerves.","Delayed puberty plus cannot smell","656",["Katzung ch 37"]],"antiandrogens":["5α-reductase · the androgen receptor","The androgen axis can be interrupted at three places, and which one a drug hits determines its effect and its side effects: synthesis, conversion to DHT, or the receptor itself.","Finasteride blocks conversion of testosterone to DHT","676",["Katzung ch 40","Katzung ch 39"]],"gnrhanalogues":["The GnRH receptor on the gonadotroph","The pituitary responds to the pattern of GnRH, not just its presence. Pulsatile delivery stimulates LH and FSH release; continuous delivery downregulates the receptor and shuts the axis off after an initial surge.","Pulsatile stimulates, continuous suppresses — the same molecule either way","674",["Katzung ch 37","Katzung ch 40"]],"axisreg":["Hypothalamus → pituitary → target gland","Every axis is the same three-step chain with negative feedback from the end product.","Opposite directions = the gland. Same direction = the pituitary or above","353",["Robbins ch 24","Costanzo ch 9"]],"cushing":["Cortisol excess — ACTH-dependent or not","Cushing syndrome is the clinical state of cortisol excess from any cause. Cushing disease is specifically a corticotroph adenoma driving it.","ACTH first, then dexamethasone — the two tests locate it","352",["Robbins ch 24","Katzung ch 39"]],"addison":["Cortisol ± aldosterone deficiency","Whether aldosterone is also lost is what separates the two levels, and it explains every difference between them. Primary destroys the whole cortex, so mineralocorticoid goes too.","Hyperpigmentation and high potassium mean primary","353",["Robbins ch 24","Katzung ch 39"]],"acromegaly":["Growth hormone → hepatic IGF-1","Growth hormone does little directly — it acts by driving the liver to make IGF-1, which is the actual growth signal. Excess before the epiphyses close gives linear growth (gigantism); after closure it thickens instead (acromegaly).","IGF-1 to screen, glucose suppression to confirm","343",["Robbins ch 24","Katzung ch 37"]],"prolactinoma":["Prolactin — tonically inhibited by dopamine","Prolactin is the one anterior pituitary hormone under tonic inhibition: dopamine from the hypothalamus continuously suppresses it. Anything that removes dopamine raises prolactin.","Treated medically, not surgically — the exception among pituitary tumours","334",["Katzung ch 37","Robbins ch 24"]],"sheehan":["Infarction of the anterior pituitary","The anterior pituitary doubles in size during pregnancy without a matching increase in its blood supply, leaving it vulnerable. Postpartum haemorrhage drops perfusion and infarcts it.","A woman who cannot breastfeed after a postpartum haemorrhage","343",["Robbins ch 24","Katzung ch 37"]],"thyroidreg":["Thyroid peroxidase · 5′-deiodinase","One enzyme does three jobs and is the target of the main drugs. Thyroid peroxidase oxidizes iodide, organifies it onto thyroglobulin tyrosines, and couples them.","Peroxidase does oxidation, organification and coupling — both PTU and methimazole block it; PTU also blocks peripheral 5′-deiodinase","335",["Katzung ch 38","Guyton ch 77"]],"hypothyroid":["Thyroid peroxidase autoantibodies","Autoimmune lymphocytic destruction of the gland — the commonest cause where iodine is sufficient. Worldwide, iodine deficiency remains the leading cause.","Delayed relaxation of the ankle jerk","345",["Katzung ch 38","Robbins ch 24"]],"hyperthyroid":["TSH receptor stimulating antibody","In Graves, an IgG antibody binds and activates the TSH receptor, so the gland is driven continuously and is not suppressible. The same antibody acts on retro-orbital and pretibial fibroblasts, which is why only Graves has the eye and skin findings.","Eye and skin signs mean Graves; lid lag does not","346",["Robbins ch 24","Katzung ch 38"]],"craniopharyngioma":["Remnant of Rathke pouch","A tumour arising from surface-ectoderm remnants of Rathke pouch, the same structure that forms the anterior pituitary. It sits above the sella and presses downward and forward.","A calcified suprasellar cystic mass in a child with growth failure","542, 734",["Robbins ch 24","Katzung ch 37"]],"men":["MEN1 (menin) · RET proto-oncogene","All three are autosomal dominant. MEN1 is a tumour suppressor, MEN2A and 2B are RET, a proto-oncogene — which is why prophylactic thyroidectomy is offered in the RET syndromes and not in MEN 1.","MEN 1 is a tumour suppressor; MEN 2 is an oncogene","356",["Robbins ch 24","Robbins ch 17"]],"pitdrugs":["Dopamine · somatostatin · GH and cortisol pathways","Each drug exploits one of the axis's own control points — the tonic dopamine brake, the somatostatin brake, the GH receptor, or a step in cortisol synthesis.","Prolactinoma is the pituitary tumour treated with a pill, not a knife","360",["Katzung ch 37","Katzung ch 39"]],"thyroiddrugs":["Thyroid peroxidase · 5′-deiodinase","The thionamides both block thyroid peroxidase, so they stop new hormone synthesis but do nothing to hormone already stored — which is why the clinical effect takes weeks and why a β-blocker is added for symptoms.","PTU in Pregnancy's first trimester and in storm; Methimazole for Most other cases","360",["Katzung ch 38"]],"ida":["Iron supply to ferrochelatase","The last step of heme synthesis inserts Fe²⁺ into protoporphyrin. Without iron no heme, and without heme no hemoglobin, so erythroblasts keep dividing and release small, pale cells.","Microcytic anemia with a high TIBC","423–424",["Robbins ch 14","Katzung ch 33"]],"acd":["Hepcidin → ferroportin","Inflammation drives IL-6, which makes the liver release hepcidin. Hepcidin binds and degrades ferroportin, the only iron exporter, so iron is locked inside macrophages and enterocytes — plentiful in the body but unavailable to the marrow.","Microcytic anemia with a high ferritin and a low TIBC","427",["Robbins ch 14","Katzung ch 33"]],"ironrx":["Oral and IV iron · iron chelators","Oral iron is absorbed as Fe²⁺ in the duodenum; vitamin C increases absorption. Reticulocytes rise in about 5–7 days, followed by a steady rise in blood counts.","Iron is absorbed as Fe²⁺ — vitamin C helps","247, 431, 688",["Katzung ch 33","Katzung ch 57"]],"aplastic":["Hematopoietic stem cells","The stem cell pool is destroyed — most often by autoreactive cytotoxic T cells — so every lineage falls together and the marrow empties into fat.","Pancytopenia with an empty, fatty marrow","427",["Robbins ch 14","Katzung ch 33"]],"sickle":["β-globin — Glu6Val (HbS)","One point mutation replaces glutamate with valine at position 6 of β-globin. Deoxygenated HbS exposes that hydrophobic valine, and the molecules polymerize into long fibers that bend the cell into a sickle.","Glu to Val at position 6 of β-globin","428",["Robbins ch 14","Marks ch 6"]],"sickletrait":["One β-globin allele Glu6Val","With about 40% HbS and 60% HbA, cells sickle only under extreme conditions. The one place those conditions are routine is the renal medulla — hypoxic, acidic and hypertonic — so the kidney is where trait shows itself.","Painless hematuria in a young patient with sickle trait","428",["Robbins ch 14","Robbins ch 20"]],"warmaiha":["IgG against red cell surface antigens","IgG autoantibodies coat red cells at body temperature. Splenic macrophages carry Fc receptors and nibble away the antibody-coated membrane, so the cell loses surface area, becomes a spherocyte and is removed — an extravascular hemolysis.","Warm is IgG, extravascular, and makes spherocytes","429",["Robbins ch 14","Katzung ch 55"]],"coldaiha":["IgM — fixes complement below 37°C","IgM autoantibodies bind red cells in the cool peripheral circulation, agglutinate them and fix complement.","Cold is IgM and complement — Mycoplasma and mono","429",["Robbins ch 14"]],"ansreg":["Preganglionic and postganglionic neurons","Every autonomic pathway is two neurons. The preganglionic neuron always releases ACh onto nicotinic Nₙ receptors in the ganglion, sympathetic or parasympathetic.","Preganglionic is always ACh on nicotinic","234",["Katzung ch 6","Guyton ch 61"]],"botulinum":["SNARE proteins (synaptobrevin · SNAP-25)","The toxin is a protease that cleaves the SNARE proteins an ACh vesicle needs to fuse with the membrane, so the nerve cannot release ACh.","The 5 D's: diplopia, dysarthria, dysphagia, dyspnea, descending flaccid paralysis","136",["Robbins ch 8","Robbins ch 27"]],"lems":["Presynaptic P/Q-type voltage-gated Ca²⁺ channel","Antibodies block the presynaptic voltage-gated calcium channels, so less Ca²⁺ enters with each action potential and fewer ACh vesicles are released.","Gets stronger with use","480",["Robbins ch 27","Katzung ch 7"]],"mg":["Postsynaptic nicotinic ACh receptor (Nₘ)","Antibodies against the postsynaptic nicotinic receptor block it, cross-link it for internalization and fix complement to the end plate.","Fatigable ptosis worse in the evening","480",["Robbins ch 27","Katzung ch 7"]],"organophosphate":["Acetylcholinesterase — irreversibly phosphorylated","Organophosphate insecticides and nerve agents phosphorylate acetylcholinesterase, so ACh piles up at every cholinergic synapse — muscarinic, nicotinic and central.","Wet patient with pinpoint pupils — DUMBBELSS","239",["Katzung ch 7","Katzung ch 58"]],"achei":["Acetylcholinesterase (reversible)","Reversibly blocking acetylcholinesterase lets ACh linger and act again. Which drug is used depends on where it goes: quaternary amines (neostigmine, pyridostigmine) stay out of the brain; tertiary ones (physostigmine, donepezil) cross the blood–brain barrier.","Physostigmine reaches the brain — anticholinergic delirium","239",["Katzung ch 7"]],"antimusc":["Muscarinic receptors M₁–M₃","Competitive blockade of muscarinic receptors removes parasympathetic tone and cholinergic sweating. Each drug is chosen for the organ it reaches — eye, airway, bladder, gut or brain.","Hot, dry, red, blind, mad, full","240",["Katzung ch 8","Katzung ch 58"]],"muscagon":["Muscarinic receptors (agonists)","Choline esters and alkaloids that stimulate muscarinic receptors directly; most resist acetylcholinesterase. They mimic parasympathetic firing at the organ chosen.","Bethanechol activates bowel and bladder","239",["Katzung ch 7"]],"nmb":["Nicotinic Nₘ receptor at the end plate","Succinylcholine is a depolarizing agonist: it opens the Nₘ channel and holds it open, so the muscle fasciculates and then cannot repolarize (phase I block).","Succinylcholine: hyperkalemia and malignant hyperthermia","566",["Katzung ch 27","Katzung ch 25"]],"alpha1drugs":["α₁ receptor — Gq → IP₃ → Ca²⁺","α₁ receptors contract vascular smooth muscle, the pupillary dilator, and the smooth muscle of the prostate and bladder neck. Agonists raise pressure and dilate the pupil; blockers lower pressure and relax the urinary outlet.","-osin for BPH — first-dose faint","243",["Katzung ch 9","Katzung ch 10"]],"alpha2drugs":["α₂ receptor — Gi → ↓ cAMP","α₂ receptors sit on the presynaptic terminal as a brake: stimulating them reduces norepinephrine release. Central α₂ agonists therefore cut sympathetic outflow from the brainstem, and pressure and heart rate fall.","Stop clonidine suddenly — rebound hypertension","243, 568",["Katzung ch 9","Katzung ch 11"]],"pressors":["α₁ · β₁ · β₂ · D₁ · V₁","Each catecholamine is defined by the receptors it hits, and the receptors predict the result: α₁ constricts, β₁ drives rate and contractility, β₂ dilates vessels and airways, D₁ dilates renal and splanchnic vessels.","Septic shock: norepinephrine","241–242",["Katzung ch 9","Katzung ch 17"]],"pheo":["Chromaffin cells — catecholamine excess","A tumour of the chromaffin cells of the adrenal medulla (a paraganglioma if extra-adrenal) releases norepinephrine and epinephrine in bursts.","Headache, sweating, palpitations — in spells","355",["Robbins ch 24","Katzung ch 10"]],"neuroblastoma":["Neural crest precursors of the adrenal medulla","The most common extracranial solid tumour of childhood arises from neural crest cells along the sympathetic chain, most often in the adrenal medulla.","Crosses the midline · HVA and VMA","354",["Robbins ch 10"]],"indirectsymp":["Vesicular release of norepinephrine","Indirect agents are carried into the terminal, displace norepinephrine from its vesicles and run the reuptake transporter backwards, pumping NE out.","Cheese and wine on an MAOI: hypertensive crisis","238, 241, 587",["Katzung ch 9","Katzung ch 30"]],"cocaine":["Reuptake transporters NET · DAT · SERT","Cocaine blocks reuptake of norepinephrine, dopamine and serotonin, so they stay in the synapse — intense α and β stimulation peripherally, and dopamine in the reward pathway centrally.","Young patient, MI, dilated pupils","241, 243, 589",["Kaplan & Sadock ch 4","Katzung ch 32"]],"horner":["Oculosympathetic pathway (three neurons)","Sympathetic fibres to the eye run in a three-neuron chain: hypothalamus down to a synapse in the lateral horn of the cord; out to the superior cervical ganglion; then along the internal carotid to the eye.","Ptosis, miosis, anhidrosis","555",["Fundamental Neuroscience ch 9","Fundamental Neuroscience ch 28"]],"glaucomadrugs":["Aqueous humor production and outflow","The ciliary epithelium makes aqueous humor — β receptors and carbonic anhydrase drive it, α₂ receptors restrain it. It drains through the trabecular meshwork, opened by ciliary muscle contraction (M₃), and the uveoscleral route, opened by prostaglandin F₂α.","Timolol, brimonidine and dorzolamide make less; latanoprost and pilocarpine let more out","551, 568",["Katzung ch 10","Katzung ch 7"]],"parkinson":["Dopamine neurons of the substantia nigra pars compacta","Nigrostriatal dopamine neurons die and α-synuclein aggregates into Lewy bodies. Losing striatal dopamine weakens the direct pathway and releases the indirect one, so the basal ganglia brake movement.","Resting tremor, rigidity, bradykinesia, postural instability","507, 534, 563",["Katzung ch 28","Fundamental Neuroscience ch 26"]],"parkinsondrugs":["Dopamine supply · receptors · breakdown","Dopamine cannot cross the blood–brain barrier, so levodopa is given and decarboxylated in the brain. Carbidopa blocks DOPA decarboxylase in the periphery only, so more levodopa reaches the brain with less nausea and hypotension.","Carbidopa keeps levodopa intact until it reaches the brain","563",["Katzung ch 28"]],"dapathways":["Mesolimbic · mesocortical · nigrostriatal · tuberoinfundibular","Antipsychotics block D₂ receptors in all four pathways at once, but only one of them is the target. Each of the others explains a side effect.","Positive symptoms = mesolimbic excess","509, 577, 591",["Katzung ch 29","Kaplan & Sadock ch 5"]],"antipsychotics":["D₂ receptor (typicals) · D₂ + 5-HT₂A (atypicals)","All antipsychotics block D₂ receptors. Typical agents do little else, so the high-potency ones cause the most extrapyramidal effects. Atypicals also block 5-HT₂A, which lets dopamine back into the striatum and cuts EPS — at the price of metabolic effects.","Clozapine: agranulocytosis","591",["Katzung ch 29","Kaplan & Sadock ch 21"]],"eps":["Nigrostriatal D₂ blockade","Blocking D₂ in the striatum leaves acetylcholine unopposed and the indirect pathway overactive. The syndromes appear in a fixed order over time.","Oculogyric crisis hours after haloperidol","587, 591",["Katzung ch 28","Katzung ch 29"]],"nms":["Abrupt central D₂ blockade","Sudden loss of dopamine signalling in the hypothalamus and striatum disrupts temperature control and produces intense rigidity; the rigid muscle makes heat and breaks down.","Lead-pipe rigidity, fever and a huge CK after haloperidol","587",["Kaplan & Sadock ch 21","Katzung ch 29"]],"stimulants":["DAT · NET","Methylphenidate blocks dopamine and norepinephrine reuptake; amphetamines also reverse the transporters and release them.","Atomoxetine: a non-stimulant ADHD option","588, 589, 590",["Kaplan & Sadock ch 21","Kaplan & Sadock ch 2"]],"tca":["NET · SERT (plus H₁, M, α₁ and Na⁺ channels)","TCAs block norepinephrine and serotonin reuptake, but they also block histamine H₁, muscarinic and α₁ receptors and cardiac fast Na⁺ channels.","Wide QRS after an overdose: sodium bicarbonate","593",["Katzung ch 30","Kaplan & Sadock ch 21"]],"snri":["SERT + NET","Serotonin–norepinephrine reuptake inhibitors raise both transmitters without the receptor blockade of TCAs. The noradrenergic half strengthens the descending pathways that inhibit pain.","Venlafaxine raises blood pressure","593",["Katzung ch 30","Kaplan & Sadock ch 21"]],"atypicalad":["NET/DAT · α₂ · 5-HT₂A","Three antidepressants that avoid blocking SERT, and so avoid most SSRI side effects. Each is chosen for what it does not do, or for a side effect that helps.","Bupropion: seizures, not sexual dysfunction","594",["Katzung ch 30","Kaplan & Sadock ch 21"]],"ssri":["Serotonin reuptake transporter (SERT)","Blocking SERT raises synaptic serotonin within hours, but mood improves only after weeks. SSRIs are first line for depression and most anxiety disorders because they lack the receptor blockade of older drugs.","Weeks to work","593",["Kaplan & Sadock ch 21","Katzung ch 30"]],"maoi":["Monoamine oxidase A and B","MAO in the nerve terminal breaks down cytoplasmic serotonin, norepinephrine and dopamine; MAO-A in the gut and liver also destroys dietary tyramine.","Wine and cheese: hypertensive crisis","593",["Kaplan & Sadock ch 21","Katzung ch 30"]],"serodrugs":["5-HT₁A · 5-HT₁B/₁D · 5-HT₃ · 5-HT₂","Serotonin acts through seven receptor families, six G protein–coupled and one (5-HT₃) a ligand-gated ion channel — each of these drugs targets one, which is why they do something quite different from an SSRI.","No triptans with coronary disease","562",["Katzung ch 16","Katzung ch 62"]],"serotoninsyndrome":["Excess 5-HT₁A and 5-HT₂A stimulation","Too much synaptic serotonin — usually from two serotonergic drugs together — overstimulates brainstem and spinal receptors.","Clonus and diarrhea hours after tramadol is added","587",["Kaplan & Sadock ch 21","Katzung ch 16"]],"carcinoid":["Serotonin from neuroendocrine (enterochromaffin) tumour cells","Well-differentiated neuroendocrine tumours of the gut make serotonin, which the liver inactivates before it reaches the systemic circulation.","Flushing, diarrhea, wheeze, right-heart valves","357",["Katzung ch 16","Robbins ch 17"]],"benzos":["GABA-A receptor — chloride channel","Both classes bind allosteric sites on the GABA-A chloride channel.","Frequency (benzodiazepines) versus duration (barbiturates)","561, 562",["Katzung ch 22","Kaplan & Sadock ch 21"]],"alcoholwd":["Downregulated GABA-A · upregulated NMDA","Chronic ethanol potentiates GABA-A and inhibits NMDA receptors, and the brain adapts with fewer GABA-A and more NMDA receptors. When drinking stops, that adapted brain is left under-braked and over-excited.","Delirium tremens 2–4 days after the last drink","562, 588",["Kaplan & Sadock ch 4","Katzung ch 23"]],"tetanus":["Synaptobrevin in inhibitory interneurons (Renshaw cells)","Tetanospasmin travels retrogradely up motor axons to the spinal cord and cleaves synaptobrevin in the inhibitory interneurons, blocking release of GABA and glycine.","Lockjaw and risus sardonicus","136",["Fundamental Neuroscience ch 4","Robbins ch 8"]],"huntington":["Huntingtin (HTT) — CAG repeat","An expanded CAG repeat in HTT on chromosome 4 makes a toxic protein that kills GABAergic medium spiny neurons of the striatum, starting with the caudate.","Chorea, dementia, caudate atrophy","534",["Katzung ch 28","Robbins ch 28"]],"nmdadrugs":["NMDA glutamate receptor","The NMDA receptor opens only when glutamate binds, glycine is present and the membrane is depolarized enough to expel its Mg²⁺ plug; then it lets Ca²⁺ in.","Nystagmus and violence: phencyclidine","564, 589, 706",["Katzung ch 21","Katzung ch 25"]],"alzheimer":["Cholinergic neurons of the nucleus basalis of Meynert","Extracellular β-amyloid plaques (from cleavage of APP) and intracellular neurofibrillary tangles of hyperphosphorylated tau spread outward from the entorhinal cortex and hippocampus.","Plaques of amyloid, tangles of tau","534",["Robbins ch 28","Kaplan & Sadock ch 3"]],"opioids":["μ-opioid receptor (Gi)","μ receptors are Gi-coupled: they open K⁺ channels and close presynaptic Ca²⁺ channels, so neurons hyperpolarize and release less transmitter — substance P and glutamate in pain pathways, and the respiratory drive in the medulla.","Pinpoint pupils and apnea: naloxone","567, 588",["Katzung ch 31","Katzung ch 32"]],"lithium":["Inositol monophosphatase · GSK-3","Lithium inhibits inositol monophosphatase, so cells firing Gq receptors hard run short of inositol to rebuild PIP₂, and it inhibits GSK-3.","Lithium: nephrogenic DI, hypothyroidism, Ebstein anomaly","587, 592",["Kaplan & Sadock ch 21","Katzung ch 29"]],"antiepileptics":["Na⁺ channels · T-type Ca²⁺ · GABA · SV2A · α₂δ","Each drug quiets neurons one of four ways: hold voltage-gated Na⁺ channels inactivated (phenytoin, carbamazepine, lamotrigine, lacosamide); block thalamic T-type Ca²⁺ channels (ethosuximide); boost GABA (benzodiazepines, barbiturates, vigabatrin, tiagabine);…","Phenytoin: gums, hair, nystagmus","560, 632",["Katzung ch 24","Kaplan & Sadock ch 21"]],"epilepsyreg":["Thalamocortical circuits · T-type Ca²⁺","Focal seizures start in one area, most often the medial temporal lobe; generalized seizures involve both hemispheres from the outset.","Absence: ethosuximide","531, 560, 660",["Katzung ch 24"]],"t1dm":["β cells destroyed — absolute insulin deficiency","T cells destroy the β cells (insulitis), and classic symptoms appear once more than 90% of them are gone.","Anti-GAD65 · low C-peptide","350",["Robbins ch 24","Katzung ch 41"]],"t2dm":["Insulin resistance + progressive β-cell failure","Muscle, fat and liver respond poorly to insulin, largely because of visceral obesity — free fatty acids and inflammatory adipokines blunt signalling beyond the receptor.","Insulin resistance and islet amyloid","351, 358, 359",["Katzung ch 41","Robbins ch 24"]],"dka":["Insulin absent · glucagon unopposed","With no insulin and plenty of glucagon, lipolysis floods the liver with fatty acids that are oxidized to acetoacetate and β-hydroxybutyrate.","Kussmaul breathing, fruity breath, anion gap","350, 351",["Katzung ch 41","Robbins ch 24"]],"insulinoma":["Autonomous β-cell insulin secretion","An insulinoma secretes insulin whatever the glucose, so insulin stays high even as glucose falls. C-peptide, cut from proinsulin in equal amounts, separates insulin the body made from insulin that was injected.","Whipple triad","338, 357",["Robbins ch 24","Marks ch 19"]],"dmcomplications":["Nonenzymatic glycation · sorbitol · hyaline arteriolosclerosis","Chronic hyperglycemia injures tissue two ways. Nonenzymatic glycation of proteins (HbA1c is the measurable example) forms advanced glycation end-products that thicken basement membranes and stiffen arteries.","Glycation and sorbitol","350, 556, 616",["Robbins ch 24","Robbins ch 20"]],"glucagonoma":["α-cell tumour — glucagon excess","A tumour of pancreatic α cells secretes glucagon continuously, driving glycogen breakdown and gluconeogenesis.","Necrolytic migratory erythema","357",["Robbins ch 24"]],"somatostatinoma":["δ-cell tumour — somatostatin excess","Somatostatin is the universal brake: it inhibits insulin, glucagon, gastrin, CCK, secretin and pancreatic enzymes. A tumour of δ cells makes too much, so all of those actions fail at once.","Diabetes, gallstones, steatorrhea","357",["Robbins ch 24","Katzung ch 62"]],"vipoma":["Vasoactive intestinal peptide excess","VIP raises cAMP in the intestinal epithelium, driving chloride and water secretion much as cholera toxin does, and it inhibits gastric acid.","WDHA — pancreatic cholera","357, 378",["Robbins ch 24","Robbins ch 17"]],"insulins":["Insulin receptor (tyrosine kinase)","All insulins are the same hormone engineered to absorb at different speeds. Rapid analogues resist forming hexamers and absorb in minutes; long-acting ones precipitate or bind albumin at the injection site and release slowly.","Regular insulin IV for DKA and hyperkalemia","358",["Katzung ch 41"]],"metformin":["Hepatic gluconeogenesis (via AMP-activated protein kinase)","Metformin inhibits mitochondrial glycerol-3-phosphate dehydrogenase and activates AMP kinase. The main effect is less hepatic gluconeogenesis, with better peripheral insulin sensitivity.","No hypoglycemia, no weight gain","359",["Katzung ch 41"]],"sulfonylureas":["SUR1 subunit of the β-cell K-ATP channel","These drugs bind SUR1 and close the K-ATP channel just as ATP does, so the β cell depolarizes, Ca²⁺ enters and insulin is released — whatever the glucose.","Close the K-ATP channel, release insulin","338, 359",["Katzung ch 41","Robbins ch 24"]],"glp1ra":["GLP-1 receptor (Gs → cAMP)","GLP-1 from intestinal L cells amplifies glucose-dependent insulin release, suppresses glucagon, slows gastric emptying and signals satiety centrally.","-glutides: weight loss, nausea, pancreatitis","359",["Katzung ch 41","Katzung ch 16"]],"dpp4i":["Dipeptidyl peptidase-4","DPP-4 cleaves native GLP-1 and GIP within minutes. Blocking it roughly doubles endogenous incretin levels — a milder, oral version of a GLP-1 agonist.","-gliptins: oral and weight neutral","359",["Katzung ch 41","Robbins ch 24"]],"tzd":["PPAR-γ (nuclear receptor)","Pioglitazone activates PPAR-γ, a nuclear transcription factor, and changes adipocyte gene expression: more GLUT4, more adiponectin, and fatty acids stored in subcutaneous fat rather than liver and muscle.","-glitazones: PPAR-γ, edema and heart failure","359",["Katzung ch 41"]],"agi":["Brush-border α-glucosidases","Acarbose and miglitol block the brush-border enzymes that split disaccharides and starch into glucose, so carbohydrate is absorbed slowly and further down the gut — flattening the post-meal glucose spike.","Acarbose: gas","359",["Katzung ch 41","Marks ch 21"]],"penicillins":["Penicillin-binding proteins (transpeptidases)","β-lactams mimic the D-Ala-D-Ala end of the peptidoglycan precursor and acylate the transpeptidases (PBPs) that cross-link the wall. Autolysins keep cutting while new cross-links fail, so dividing bacteria burst — bactericidal, and only against growing cells.","Mimics D-Ala-D-Ala to block transpeptidation","144, 183, 184",["Katzung ch 43","Katzung ch 51"]],"abxresistance":["β-lactamases · altered targets · efflux · porins","Resistance comes down to four moves: destroy the drug (β-lactamases, aminoglycoside-modifying enzymes), change the target, pump it out, or keep it out by losing porins.","MRSA = PBP2a (mecA)","183, 185, 186",["Katzung ch 43","Katzung ch 44"]],"vancomycin":["D-Ala-D-Ala terminus of the peptidoglycan precursor","Vancomycin binds the D-Ala-D-Ala tail of the precursor itself, physically blocking transglycosylation and transpeptidation. It is too large to cross the outer membrane of gram-negatives, so it is gram-positive only.","Binds D-Ala-D-Ala","183, 186",["Katzung ch 43"]],"aminoglycosides":["30S subunit — initiation complex and mRNA reading","Aminoglycosides bind the 30S subunit, block formation of the initiation complex and cause misreading of mRNA; the faulty proteins insert into the membrane and let in more drug.","Useless against anaerobes — uptake needs oxygen","187",["Katzung ch 45","Katzung ch 51"]],"tetracyclines":["30S subunit — aminoacyl-tRNA binding (A site)","Tetracyclines stop aminoacyl-tRNA from docking at the A site of the 30S subunit. Bacteriostatic. Bacteria concentrate them actively, they collect in bone and teeth, and they chelate divalent cations.","Stained teeth, sunburn, no milk","188",["Katzung ch 44"]],"macrolides":["50S — 23S rRNA, translocation","Macrolides bind the 23S rRNA of the 50S subunit and block translocation. Bacteriostatic. Erythromycin also stimulates motilin receptors, and erythromycin and clarithromycin inhibit CYP3A4.","Atypical pneumonia · QT","189",["Katzung ch 44","Katzung ch 62"]],"sulfonamides":["Dihydropteroate synthase · dihydrofolate reductase","Bacteria must make their own folate. Sulfonamides are PABA analogues that block dihydropteroate synthase; trimethoprim blocks bacterial dihydrofolate reductase.","Two steps of folate synthesis","190",["Katzung ch 46"]],"fluoroquinolones":["DNA gyrase (topoisomerase II) · topoisomerase IV","Fluoroquinolones trap DNA gyrase (the main gram-negative target) and topoisomerase IV (the main gram-positive target) on the DNA after they cut it, turning the enzymes into DNA-breaking machines.","Achilles rupture on ciprofloxacin","191",["Katzung ch 46"]],"rifamycins":["DNA-dependent RNA polymerase (β subunit, rpoB)","Rifampin blocks bacterial DNA-dependent RNA polymerase and halts transcription. A single rpoB mutation confers resistance, so it is never used alone for active infection.","Orange tears; induces everything","192",["Katzung ch 47"]],"tbdrugs":["Mycolic acid · arabinogalactan synthesis","The mycobacterial wall is mycolic acid on an arabinogalactan scaffold. Isoniazid is a prodrug activated by the bacterial catalase-peroxidase KatG; it then blocks mycolic acid synthesis.","Isoniazid: give B6 · pyrazinamide: gout · ethambutol: eyes","192",["Katzung ch 47"]],"amphotericin":["Ergosterol in the fungal membrane","Polyenes bind ergosterol and form pores in the fungal membrane, so K⁺ and other ions leak out. They also bind the cholesterol of human membranes — less avidly, but enough to make amphotericin notoriously toxic.","Kidneys, potassium, magnesium, rigors","194",["Katzung ch 48"]],"azoles":["Lanosterol 14α-demethylase","Azoles block the fungal cytochrome P450 that converts lanosterol to ergosterol, so toxic sterols accumulate and the membrane fails. They inhibit human CYP enzymes too — the source of their interactions and endocrine side effects.","Azoles block ergosterol synthesis — and your CYP enzymes","195",["Katzung ch 48","Katzung ch 39"]],"hiv":["CD4⁺ T cells · CCR5 / CXCR4 co-receptors","HIV's gp120 binds CD4 and then a co-receptor — CCR5 early in infection, CXCR4 later — so it infects helper T cells, macrophages and dendritic cells.","CD4 below 200 = AIDS","172, 173, 197",["Robbins ch 6","Katzung ch 49"]],"hivpi":["HIV aspartyl protease (Gag-Pol cleavage)","New virions bud with Gag and Gag-Pol still joined; the viral protease must cut them apart to make a mature, infectious particle. Protease inhibitors leave virions immature and non-infectious.","-navir: protease","198",["Katzung ch 49","Katzung ch 4"]],"hsvvzv":["Latent virus in sensory ganglia","HSV-1, HSV-2 and VZV infect skin or mucosa, travel up sensory nerves and stay latent in sensory ganglia — trigeminal for HSV-1, sacral for HSV-2, dorsal root and cranial nerve ganglia for VZV — then reactivate along the same nerve.","Temporal lobe encephalitis = HSV-1 — start IV acyclovir","162, 163",["Robbins ch 8","Robbins ch 28"]],"cmv":["Latent in monocytes and other cells","CMV is a herpesvirus that stays latent after a usually silent first infection. Disease comes from reactivation when cell-mediated immunity fails — advanced HIV, transplantation — or from infection of a fetus.","Owl's eye inclusions","162, 173, 180",["Robbins ch 8","Katzung ch 49"]],"acyclovir":["Viral thymidine kinase → viral DNA polymerase","Acyclovir is a guanosine analogue that only viral thymidine kinase phosphorylates efficiently, so it is activated only in HSV- or VZV-infected cells.","Needs viral thymidine kinase — works only in infected cells","196, 197",["Katzung ch 49","Katzung ch 51"]],"flu":["Hemagglutinin · neuraminidase","An orthomyxovirus with a segmented, negative-sense RNA genome. Hemagglutinin binds sialic acid to enter cells and neuraminidase cuts sialic acid to release new virions.","Drift = epidemics · shift = pandemics","166, 398, 496",["Robbins ch 8","Robbins ch 15"]],"nai":["Influenza neuraminidase (A and B)","New influenza virions stay stuck to sialic acid on the cell that made them until neuraminidase cleaves it. Blocking neuraminidase traps them, so infection spreads more slowly.","Oseltamivir: start within 48 hours","196",["Katzung ch 49"]],"m2inh":["Influenza A M2 proton channel","The M2 channel lets protons into the virion inside the endosome, which frees the viral genome. Amantadine and rimantadine block it — influenza A only, since influenza B has no M2.","M2 blockers: influenza A only, now in disuse","563",["Katzung ch 49","Katzung ch 28"]],"hbv":["HBV reverse transcriptase · cccDNA","HBV is a partly double-stranded DNA virus that replicates through an RNA intermediate using its own reverse transcriptase.","Anti-HBc IgM is the window-period marker","170, 171, 172",["Robbins ch 18","Katzung ch 49"]],"covidav":["SARS-CoV-2 RNA polymerase · main (3CL) protease","The same two targets as HIV and hepatitis C, in a coronavirus. Remdesivir is an adenosine analogue that the viral RNA-dependent RNA polymerase incorporates, stalling synthesis.","Ritonavir boosts, and interacts","196",["Katzung ch 49"]],"rsvab":["RSV fusion (F) protein","RSV enters airway cells by refolding its F (fusion) protein. Monoclonal antibodies against F give passive immunity through the RSV season — they prevent infection, they do not treat it.","Nirsevimab and palivizumab prevent, not treat","166",["Katzung Appendix 1","Robbins ch 8"]],"tabes":["Dorsal roots & dorsal columns","Years after untreated syphilis, spirochetes damage the dorsal roots and the dorsal columns they feed. Position and vibration sense are lost, so balance depends on vision, and the damaged roots fire as sudden lancinating pains.","Argyll Robertson pupil — accommodates, doesn't react","145, 544",["Robbins ch 8","Robbins ch 28"]],"friedreich":["Frataxin (FXN) — mitochondrial iron handling","An expanded GAA repeat in the first intron of FXN (chromosome 9) silences frataxin, a mitochondrial protein needed to build the iron-sulfur clusters of complexes I and II.","Staggering child with a big heart and high arches","545",["Robbins ch 28","Fundamental Neuroscience ch 33"]],"syringomyelia":["Central canal → anterior white commissure","A fluid-filled, gliosis-lined cavity (syrinx) forms in the cord, usually between C2 and T9.","Cape-like pain and temperature loss","502",["Fundamental Neuroscience ch 9","Robbins ch 28"]],"als":["Upper and lower motor neurons","Motor neurons die in the cortex (upper) and in the brainstem nuclei and anterior horns (lower), while sensory pathways are spared. The lateral corticospinal tracts scar and harden — 'lateral sclerosis' — and denervated muscle wastes — 'amyotrophic'.","UMN plus LMN signs, sensation intact","544",["Robbins ch 28","Fundamental Neuroscience ch 9"]],"polio":["Anterior horn cells — enterovirus","Poliovirus spreads from the gut to the blood and, in a small fraction of infections, into anterior horn motor neurons, which it destroys. Only lower motor neurons are lost, so the weakness is purely flaccid and sensation is normal.","Flaccid, asymmetric, after a fever","544",["Robbins ch 28","Robbins ch 8"]],"sma":["SMN1 — survival motor neuron protein","Loss of SMN1 leaves too little survival motor neuron protein, and anterior horn cells degenerate. How severe it is depends on how many copies of the backup gene SMN2 remain.","Floppy baby with tongue fasciculations","544",["Robbins ch 28","Robbins ch 27"]],"brownsequard":["Half the cord at one level","Cutting one half of the cord separates the tracts by where they cross. The dorsal columns and lateral corticospinal tract are still uncrossed in the cord, so their loss is ipsilateral.","Stab wound to the back","545",["Fundamental Neuroscience ch 9","Fundamental Neuroscience ch 25"]],"asa":["Anterior spinal artery — anterior two-thirds of the cord","One anterior spinal artery supplies the anterior two-thirds of the cord — the corticospinal and spinothalamic tracts and the anterior horns.","Paraplegia after aortic aneurysm repair","544",["Robbins ch 28","Fundamental Neuroscience ch 9"]],"centralcord":["Central gray matter and medial (arm) corticospinal fibers","In the lateral corticospinal tract the arm fibers run medially and the leg fibers laterally.","Neck hyperextension, weak arms, legs spared","521",["Fundamental Neuroscience ch 25","Moore ch 2"]],"caudaequina":["Lumbosacral nerve roots below the conus (L1–L2)","The cord ends at L1–L2 (conus medullaris); below it the lumbar and sacral roots hang free as the cauda equina.","Back pain + saddle numbness + retention = surgical emergency","520",["Moore ch 2","Fundamental Neuroscience ch 9"]],"gbs":["Peripheral nerve myelin and roots — molecular mimicry","Antibodies made against an infection cross-react with peripheral nerve gangliosides and Schwann-cell myelin (molecular mimicry). Demyelination slows or blocks conduction in nerve roots and nerves; the brain and cord are untouched.","Weakness climbing up the legs after diarrhea","538",["Robbins ch 27"]],"umnlmn":["Corticospinal tract vs anterior horn and its nerve","An upper motor neuron lesion removes the cortex's inhibitory control over spinal reflex arcs that are still intact — so tone and reflexes rise.","Lower motor neuron = everything lowered: tone, reflexes, bulk","543, 544",["Fundamental Neuroscience ch 25","Fundamental Neuroscience ch 33"]],"mcastroke":["Middle cerebral artery — lateral cortex","The MCA feeds the lateral frontal, parietal and temporal cortex — the face and arm areas of the motor and sensory strips and, on the dominant (usually left) side, the language areas.","Face and arm worse than leg, with aphasia or neglect","524, 525, 526",["Fundamental Neuroscience ch 16","Fundamental Neuroscience ch 8"]],"acastroke":["Anterior cerebral artery — medial frontal and parietal cortex","The ACA supplies the medial surface of the hemisphere, where the motor and sensory strips map the leg and foot, plus frontal areas for drive and bladder control.","Leg worse than arm = ACA","524, 525, 526",["Fundamental Neuroscience ch 16","Fundamental Neuroscience ch 8"]],"lacunar":["Lenticulostriate and other small penetrating arteries","Unmanaged hypertension thickens the walls of small penetrating arteries (hyaline arteriolosclerosis, lipohyalinosis, microatheroma) until one occludes, leaving a small deep infarct (< 15 mm) — putamen, globus pallidus, thalamus, internal capsule, deep white…","Pure motor, no cortical signs, in a hypertensive patient","525, 526, 528",["Robbins ch 28"]],"pcastroke":["Posterior cerebral artery — occipital lobe and thalamus","The PCA feeds the occipital (visual) cortex, the medial temporal lobe and much of the thalamus. Collateral branches of the MCA can also supply the caudal visual cortex, where central vision is mapped, so central (macular) vision can survive.","Hemianopia with macular sparing","526",["Fundamental Neuroscience ch 20","Robbins ch 28"]],"wallenberg":["PICA or vertebral artery — lateral medulla","The lateral medulla holds the nucleus ambiguus (IX, X), the spinal trigeminal nucleus (face pain, uncrossed), the spinothalamic tract (body pain, already crossed), descending sympathetic fibers, the vestibular nuclei and the inferior cerebellar peduncle.","\"Don't pick a (PICA) lame (lateral medullary) horse (hoarseness) that can't eat (dysphagia)\"","527",["Fundamental Neuroscience ch 14","Fundamental Neuroscience ch 10"]],"aicastroke":["AICA — lateral pons and inner ear","The AICA supplies the lateral pons — the facial nucleus, vestibular and cochlear nuclei, spinal trigeminal nucleus, spinothalamic tract and sympathetics — and, through the labyrinthine artery, the inner ear.","Facial nerve nucleus signs are specific to AICA","526",["Fundamental Neuroscience ch 14","Robbins ch 28"]],"medialmedullary":["Anterior spinal artery and vertebral branches — medial medulla","The medial medulla carries the pyramids (not yet crossed), the medial lemniscus (already crossed) and the hypoglossal nucleus. So the body findings are contralateral and the tongue finding is ipsilateral.","Tongue points to the lesion, body weak on the other side · \"Ants love M&Ms\" (ASA → medial medullary)","527",["Fundamental Neuroscience ch 25","Fundamental Neuroscience ch 10"]],"lockedin":["Basilar artery — ventral pons","An infarct of the ventral pons cuts the corticospinal and corticobulbar tracts on both sides, but spares the reticular activating system (dorsal) and the midbrain centers for vertical gaze.","Awake and aware, can only blink and look up","526",["Robbins ch 28","Fundamental Neuroscience ch 10"]],"weber":["Paramedian branches of the PCA and basilar — medial midbrain","In the medial midbrain the exiting oculomotor fibers run beside the cerebral peduncle, which carries the corticospinal tract before it crosses.","Blown pupil on one side, weakness on the other","526",["Fundamental Neuroscience ch 25","Fundamental Neuroscience ch 13"]],"aphasia":["Broca (inferior frontal) · Wernicke (superior temporal) · arcuate fasciculus","Language lives in the dominant hemisphere. Broca's area (inferior frontal gyrus) produces speech, Wernicke's area (superior temporal gyrus) understands it, and the arcuate fasciculus links the two — which is what repeating a phrase tests.","Broca = broken boca · Wernicke = word salad","529",["Fundamental Neuroscience ch 32"]],"cn3palsy":["Oculomotor nerve — motor core and surface pupil fibers","CN III moves four of the six eye muscles and lifts the lid, while parasympathetic fibers on its outer surface constrict the pupil.","Down and out","530, 556",["Moore ch 9","Fundamental Neuroscience ch 28"]],"bell":["Facial nerve (CN VII) — peripheral","The upper face gets corticobulbar input from both hemispheres, the lower face only from the opposite one. So a cortical (UMN) lesion weakens only the contralateral lower face, while a lesion of the nucleus or nerve (LMN) paralyzes the whole ipsilateral face.","Forehead involved = peripheral (LMN)","546",["Fundamental Neuroscience ch 14","Moore ch 9"]],"ms":["CNS myelin — oligodendrocytes","Autoreactive T and B cells cross the blood-brain barrier and strip myelin from CNS axons, forming plaques — in periventricular white matter, optic nerves, brainstem and cord — separated in time and space.","Bilateral INO in a young adult = MS","537, 558",["Robbins ch 28","Katzung ch 55"]],"cerebellar":["Hemispheres (limbs) · vermis (trunk)","Each cerebellar hemisphere coordinates the limbs on its own side — its output crosses and the corticospinal tract crosses back — so hemisphere lesions cause ipsilateral signs.","Hemisphere = same-side limbs","510, 524",["Fundamental Neuroscience ch 27","Guyton ch 57"]],"epidural":["Middle meningeal artery","A skull fracture at the pterion tears the middle meningeal artery, a branch of the maxillary artery. Arterial blood strips the dura off the skull; because the dura is anchored at the sutures, the clot is lens-shaped and does not cross them.","Lucid interval","528, 543",["Moore ch 9","Robbins ch 28"]],"subdural":["Bridging veins","Bridging veins run from the cortex to the dural sinuses. Brain atrophy (age, alcohol) stretches them, so a minor jolt tears them. Venous bleeding is slow and spreads under the dura across the suture lines — crescent-shaped.","Crescent that crosses sutures","528",["Moore ch 9","Robbins ch 28"]],"sah":["Berry (saccular) aneurysm — circle of Willis","Saccular aneurysms form at branch points of the circle of Willis, most often the anterior communicating artery. Rupture floods the subarachnoid space around the brain and the CSF with arterial blood.","Worst headache of my life","530",["Robbins ch 28","Fundamental Neuroscience ch 7"]],"ich":["Charcot-Bouchard microaneurysms of small penetrating arteries","Long-standing hypertension weakens small penetrating arteries, forming Charcot-Bouchard microaneurysms that rupture into deep brain. In the elderly, cerebral amyloid angiopathy instead causes lobar (cortical) hemorrhages.","Putamen bleed in an untreated hypertensive","528",["Robbins ch 28"]],"egfr":["Epidermal growth factor receptor (ERBB1)","Two ways to switch EGFR off: small molecules that block its kinase domain (erlotinib, gefitinib, osimertinib) and monoclonal antibodies that block ligand binding (cetuximab, panitumumab).","KRAS-mutant colon cancer: no cetuximab","220, 446, 447",["Katzung ch 54","Katzung ch 55"]],"kras":["RAS GTPase — stuck GTP-bound","RAS is a small G protein that is 'on' with GTP bound and switches itself off by hydrolyzing the GTP. Activating point mutations wreck that GTPase, so RAS stays on and drives RAF–MEK–ERK without any growth factor.","RAS: the oncogene of pancreas and colon","220",["Robbins ch 7","Marks ch 17"]],"nf1":["Neurofibromin — a RAS GTPase-activating protein","Neurofibromin is a GAP: it speeds RAS's hydrolysis of GTP, switching RAS off. Losing both copies (a tumor suppressor) leaves RAS on in neural-crest-derived cells.","Café-au-lait spots + Lisch nodules","539",["Robbins ch 27","Robbins ch 7"]],"braf":["BRAF V600E kinase → MEK","The V600E mutation lets BRAF signal to MEK without RAS. Vemurafenib and dabrafenib block mutant BRAF; trametinib and cobimetinib block MEK one step down.","Melanoma, hairy cell, papillary thyroid = BRAF","220, 447",["Katzung ch 54","Robbins ch 7"]],"mycamp":["MYC transcription factor","MYC is the transcription factor at the end of many growth pathways; it switches on genes for ribosome building, metabolism and entry into the cell cycle.","t(8;14) — Burkitt, starry sky","220",["Robbins ch 13","Robbins ch 7"]],"pten":["PTEN phosphatase — removes PIP3's 3-phosphate","PI3K adds a phosphate to make PIP3, which recruits and activates AKT. PTEN takes that phosphate back off. Losing PTEN leaves AKT and mTOR switched on.","Cowden: hamartomas plus breast, thyroid and endometrial cancer","220",["Robbins ch 7"]],"tsc":["Hamartin (TSC1) · tuberin (TSC2) — the brake on mTOR","The TSC1–TSC2 complex is a GTPase-activating protein for the small G protein Rheb, and Rheb-GTP activates mTOR. Losing either gene leaves mTOR on, so hamartomas grow in brain, skin, kidney and heart.","Ash-leaf spots plus seizures","539",["Robbins ch 28","Robbins ch 12"]],"mtorinh":["mTORC1 (drug bound to FKBP12)","Sirolimus binds FKBP12, and the pair blocks mTORC1 — the kinase that lets T cells respond to IL-2 and lets cells build protein and grow. Unlike the calcineurin inhibitors, they do not block IL-2 production, only the response to it.","-limus blocks mTOR","118",["Katzung ch 55","Katzung ch 24"]],"vhl":["VHL E3 ubiquitin ligase — degrades HIF-1α","When oxygen is present, HIF-1α is hydroxylated and the VHL protein tags it for destruction. Without VHL, cells behave as if they were hypoxic: HIF drives VEGF, PDGF and erythropoietin, so the tumors are highly vascular.","VHL on chromosome 3 — three letters","539, 623",["Robbins ch 7","Robbins ch 28"]],"jak2":["JAK2 kinase — always active","The receptors for EPO, TPO and G-CSF have no kinase of their own; they use JAK2 to activate STAT. The V617F mutation turns JAK2 on without any cytokine, so the marrow overproduces red cells, platelets or both.","High hematocrit with low EPO = polycythemia vera","438, 447",["Robbins ch 13"]],"fap":["APC — part of the β-catenin destruction complex","Without a Wnt signal, APC helps a destruction complex break down β-catenin. When APC is lost, β-catenin reaches the nucleus and switches on MYC and cyclin D.","APC on chromosome 5 — five letters in 'polyp'","394",["Robbins ch 17","Robbins ch 7"]],"serm":["Estrogen receptor — agonist in some tissues, antagonist in others","SERMs block the estrogen receptor in some tissues and activate it in others. Tamoxifen blocks the breast receptor but stimulates the endometrium and bone; raloxifene blocks breast and endometrium and stimulates bone.","Tamoxifen: endometrial cancer and clots","446, 674",["Katzung ch 40","Katzung ch 42"]],"checkpoint":["PD-1 · PD-L1 · CTLA-4","T cells carry brakes: CTLA-4, which competes with CD28 for B7 during priming, and PD-1, which PD-L1 on tumor cells engages to exhaust T cells inside the tumor.","Release the brakes → autoimmunity anywhere","218, 446",["Katzung ch 55","Katzung ch 54"]],"rituximab":["CD20 on B cells (not on plasma cells)","CD20 sits on B cells from the pre-B stage to mature B cells, but not on plasma cells. Anti-CD20 antibodies kill B cells through complement and antibody-dependent cytotoxicity; antibody levels fall only slowly because plasma cells survive.","Anti-CD20: screen for hepatitis B first","171, 446",["Katzung ch 55","Katzung ch 36"]],"myositis":["Muscle capillaries (dermatomyositis) · muscle fibers (polymyositis)","In dermatomyositis, complement-mediated injury to capillaries leaves the fibers at the edge of each bundle atrophic. In polymyositis, CD8 T cells invade the muscle fibers themselves.","Heliotrope rash + Gottron papules","477",["Robbins ch 27","Robbins ch 6"]],"periodicpara":["DHP receptor (CACNA1S) or skeletal Na⁺ channel (SCN4A)","The mutant muscle channels make the membrane abnormally sensitive to a fall in serum potassium, so when potassium moves into cells the muscle stops firing.","Weak after pizza and a nap","",["Robbins ch 27"]],"osteopetrosis":["Osteoclast acid — carbonic anhydrase II, proton pump, chloride channel","Osteoclasts are present but cannot acidify the resorption pit, so old bone is never removed. Bone becomes dense but brittle, and bone fills in the marrow space and the skull foramina.","Dense bones that break, plus anemia and blindness","468",["Robbins ch 26"]],"paget":["Overactive osteoclasts, then chaotic osteoblast repair","Focal, overactive osteoclasts resorb bone, then osteoblasts rebuild it fast and chaotically. The result is thick but weak woven bone laid down in a mosaic pattern, with high blood flow.","Isolated high ALP in an older man","468",["Robbins ch 26","Katzung ch 42"]],"osteoporosis":["Resorption outpaces formation — less bone, normal mineral","Bone mass peaks around 30 and then declines. Estrogen restrains RANKL and shortens osteoclast life, so its loss at menopause speeds resorption, especially of trabecular bone.","T-score −2.5 or lower","462, 467",["Katzung ch 42","Robbins ch 26"]],"achondroplasia":["FGFR3 — gain of function","FGFR3 is a brake on growth-plate chondrocyte proliferation. An activating mutation presses the brake too hard, so endochondral (long-bone) growth is stunted while membranous ossification (skull vault, face) is normal.","FGFR3 switched on — too much brake","58, 461, 467",["Robbins ch 26","Robbins ch 5"]],"fibrousdys":["GNAS — Gsα stuck on (mosaic)","An activating GNAS mutation keeps Gsα signaling, so cAMP stays high. In bone precursors, fibrous tissue and disorganized woven bone replace normal bone.","Precocious puberty plus bone lesions","55",["Robbins ch 26","Robbins ch 24"]],"pcos":["Theca-cell androgen excess · insulin resistance · high LH:FSH","Theca cells overproduce androgens under a high LH:FSH ratio, and insulin resistance contributes. Follicles stall at small sizes — no dominant follicle, no LH surge, no ovulation — leaving unruptured cysts.","Irregular periods + hirsutism + obesity","662, 673",["Katzung ch 40","Robbins ch 22"]],"ocp":["Estrogen + progestin → negative feedback on GnRH, FSH and LH","Steady estrogen and progestin suppress FSH (no dominant follicle) and prevent the LH surge (no ovulation). The progestin also thickens cervical mucus and thins the endometrium.","Smoker over 35: no estrogen","674, 675",["Katzung ch 40"]],"gtd":["Trophoblast — hCG in excess","A complete mole is an empty egg fertilized by one sperm that duplicates (46,XX, all paternal): no fetus, swollen villi, very high hCG. A partial mole is triploid (69,XXY) with fetal parts.","Snowstorm on ultrasound","659",["Robbins ch 22"]],"menopause":["Follicles run out — no inhibin or estradiol feedback","As ovarian follicles run out, estrogen falls and negative feedback on FSH is lost, so FSH rises (specific for menopause) along with LH and GnRH.","Highest FSH of life","653",["Katzung ch 40","Guyton ch 82"]],"gdm":["Placental hPL and other hormones → insulin resistance","In the second half of pregnancy, placental hormones (hPL, progesterone, cortisol) blunt maternal insulin action so glucose passes to the fetus.","Macrosomia + newborn hypoglycemia","73, 358, 652",["Robbins ch 24","Robbins ch 10"]],"saureus":["Protein A · coagulase · TSST-1 · exfoliative toxin · enterotoxin · PVL","Gram-positive cocci in clusters, catalase- and coagulase-positive. It causes disease two ways: by invading tissue (abscesses, pneumonia, endocarditis, osteomyelitis) and by toxins that act at a distance.","Cocci in clusters, coagulase-positive","133",["Robbins ch 8","Katzung ch 51"]],"spneumo":["Polysaccharide capsule · IgA protease · pneumolysin","Lancet-shaped gram-positive diplococci, α-hemolytic, optochin sensitive and bile soluble. The capsule is the key virulence factor — it resists phagocytosis, so clearing it depends on antibody and the spleen.","Lancet-shaped diplococci","125, 134",["Robbins ch 8","Robbins ch 15"]],"viridans":["Dextrans that stick to fibrin–platelet clumps","α-hemolytic mouth streptococci that resist optochin. S. mutans makes dextran from sucrose and causes dental caries; S. sanguinis sticks to fibrin–platelet deposits on damaged valves.","Dental work → subacute endocarditis","134",["Robbins ch 8","Robbins ch 12"]],"gas":["M protein · streptolysin O · SpeA (erythrogenic toxin) · hyaluronic acid capsule","β-hemolytic and bacitracin sensitive. M protein resists phagocytosis — and antibodies against it cross-react with cardiac myosin, the root of rheumatic fever.","Sandpaper rash + strawberry tongue","134",["Robbins ch 8","Robbins ch 12"]],"gbsstrep":["Polysaccharide capsule","β-hemolytic, bacitracin resistant, CAMP-positive and hippurate-positive. It colonizes the vagina and rectum and passes to the baby during birth.","Group B for Babies","135",["Robbins ch 8","Katzung ch 51"]],"cperfringens":["α-toxin (lecithinase, phospholipase C) · enterotoxin","An anaerobic spore-former whose α-toxin is a phospholipase that splits lecithin in cell membranes, lysing muscle, red cells and platelets. It thrives in dead tissue.","Crepitus in a crushed limb","131, 136",["Robbins ch 8"]],"meningococcus":["Polysaccharide capsule · lipooligosaccharide endotoxin · IgA protease","An encapsulated gram-negative diplococcus that lives in the nasopharynx, enters the blood and seeds the meninges. Its endotoxin (LOS) drives septic shock and DIC.","Petechial rash + meningitis in a college dorm","140",["Robbins ch 8","Katzung ch 51"]],"gonococcus":["Pili that keep changing their antigens · no capsule","An unencapsulated diplococcus whose pili switch antigens constantly, so there is no lasting immunity and no vaccine. It ferments glucose only.","Gonorrhea ferments glucose only","140, 179, 181",["Robbins ch 8","Katzung ch 51"]],"hflu":["Type b polysaccharide capsule (PRP) · IgA protease","A small gram-negative coccobacillus that needs factor X (hemin) and factor V (NAD⁺) to grow. The type b capsule caused invasive disease in children until the conjugate vaccine; unencapsulated (nontypeable) strains now cause mucosal infections.","Epiglottitis with a thumb sign","140",["Robbins ch 8"]],"pertussis":["Pertussis toxin (ADP-ribosylates Gi → ↑ cAMP) · tracheal cytotoxin","Pertussis toxin ADP-ribosylates the inhibitory G protein (Gi), so cAMP stays high — disabling phagocytes and causing lymphocytosis. Tracheal cytotoxin destroys ciliated cells, so mucus cannot be cleared.","Whoop + vomiting after coughing","141",["Robbins ch 8"]],"ecoli":["Fimbriae · heat-labile and heat-stable toxins (ETEC) · Shiga toxin (EHEC) · K1 capsule","The commonest gram-negative rod — a fast lactose fermenter. Different strains carry different weapons: fimbriae for the bladder, a capsule for the newborn's meninges, toxins or invasion for the gut.","Hamburger → bloody diarrhea → HUS","143",["Robbins ch 8","Robbins ch 17"]],"klebsiella":["Large polysaccharide capsule · urease","A heavily encapsulated lactose fermenter with very mucoid colonies; the capsule resists phagocytosis, and multidrug-resistant strains (including carbapenemase producers) are a major hospital problem.","Currant jelly sputum in an alcoholic","143",["Robbins ch 15","Robbins ch 8"]],"pseudomonas":["Exotoxin A (ADP-ribosylates EF-2) · pyocyanin · alginate biofilm","An aerobic, oxidase-positive rod that does not ferment lactose and lives in water. Pyocyanin makes it blue-green and generates reactive oxygen species; exotoxin A ADP-ribosylates EF-2 like diphtheria toxin; an alginate biofilm protects it in CF lungs.","Grape smell, blue-green pus","141",["Robbins ch 8","Katzung ch 43"]],"proteus":["Urease · swarming motility","Urease splits urea into ammonia, making the urine alkaline so magnesium ammonium phosphate (struvite) precipitates. The stones grow into staghorn calculi that shelter the bacteria.","Alkaline urine + staghorn calculus","617",["Robbins ch 20","Katzung ch 43"]],"campylobacter":["Mucosal invasion; lipooligosaccharide that mimics nerve gangliosides","A comma- or S-shaped, oxidase-positive rod that grows at 42 °C (a bird's body temperature). One of the leading causes of bacterial diarrhea worldwide; its lipooligosaccharide mimics gangliosides on peripheral nerves.","Chicken → diarrhea → Guillain-Barré","143",["Robbins ch 17","Robbins ch 8"]],"vibrio":["Cholera toxin — ADP-ribosylates Gs (↑ cAMP)","A comma-shaped, oxidase-positive rod that likes alkaline conditions. Its toxin ADP-ribosylates Gs, locking adenylate cyclase on: cAMP opens CFTR, and chloride and water pour into the gut.","Rice-water stool","130, 144",["Robbins ch 17","Robbins ch 8"]],"legionella":["Survives inside macrophages and amoebae","A gram-negative rod that stains poorly and lives inside amoebae in water systems, then inside alveolar macrophages once inhaled.","Pneumonia + diarrhea + hyponatremia","141",["Robbins ch 15","Katzung ch 46"]],"syphilis":["Spirochete with few surface antigens","A spirochete too thin to see on a Gram stain. It enters through mucosa and spreads by blood early; an inflammation of small vessels (endarteritis) causes the damage of late disease.","Painless chancre","144, 145, 146",["Robbins ch 8","Robbins ch 28"]],"lyme":["Spirochete that switches its outer surface proteins","A spirochete transmitted by the Ixodes deer tick (also the vector for Anaplasma and Babesia); the mouse is the reservoir. It spreads from the skin through the blood to joints, heart and nerves.","Key Lyme pie to the FACE: Facial palsy, Arthritis, Cardiac block, Erythema migrans","144",["Robbins ch 8"]],"chlamydia":["Elementary body (infects) → reticulate body (replicates)","An obligate intracellular bacterium with almost no peptidoglycan, so β-lactams fail. The elementary body enters the cell; the reticulate body divides inside an inclusion.","Elementary body infects, reticulate body replicates","140, 146, 179",["Robbins ch 8","Katzung ch 44"]],"mycoplasma":["No cell wall — cholesterol in the membrane","It has no cell wall at all — so β-lactams do nothing and a Gram stain shows nothing. Its membrane contains sterols.","Walking pneumonia with cold agglutinins","148",["Robbins ch 15"]],"pdeinh":["Phosphodiesterase 3 or 4 — breaks cAMP down","Phosphodiesterases end a Gs signal by hydrolysing cAMP to AMP.","Milrinone: inotrope + vasodilator","245, 251, 704",["Katzung ch 13","Katzung ch 34"]],"pde5":["Phosphodiesterase 5 — breaks cGMP down","Nitric oxide raises cGMP in smooth muscle and PDE5 breaks it down. Blocking PDE5 lets cGMP build up wherever NO is being released — the corpus cavernosum during arousal, and the pulmonary vessels — so the smooth muscle relaxes and blood flows in.","Sildenafil plus nitroglycerin = life-threatening hypotension","245",["Katzung ch 12","Katzung ch 19"]],"laron":["Growth hormone receptor — defective","The GH receptor cannot signal, so the liver makes almost no IGF-1 despite plenty of GH. With no IGF-1 feedback, GH climbs higher still. The picture is growth hormone deficiency with a high GH level.","High GH with low IGF-1 = the receptor, not the pituitary","333",["Guyton ch 76","Katzung ch 37"]],"jakinh":["JAK1/3 (tofacitinib) · JAK1/2 (baricitinib, ruxolitinib) · JAK1 (upadacitinib)","Cytokine receptors have no kinase of their own; they borrow JAKs to phosphorylate STATs.","-citinib = JAK inhibitor","438",["Katzung ch 36","Katzung ch 55"]],"endotoxin":["Lipid A → TLR4 with CD14 on macrophages","LPS is structural, not secreted: O-antigen, core polysaccharide and lipid A, the toxic part. It is shed as the bacteria grow and released in bulk when they lyse.","ENDOTOXINS: Edema, Nitric oxide, DIC/Death, Outer membrane, TNF-α, O-antigen, eXtremely heat stable, IL-1 and IL-6, Neutrophil chemotaxis, Shock","131",["Robbins ch 8","Robbins ch 3"]],"transform":["Competence machinery binds and imports free DNA","When a bacterium lyses, its chromosome spills out as short naked fragments. A competent bacterium binds those fragments, pulls one strand inside and recombines it into its own chromosome.","SHiN = the naturally competent trio","128",["Robbins ch 8"]],"alleuk":["Lymphoblasts arrested before maturity — TdT ⊕","A B- or T-cell precursor stops maturing while it is still a blast. Because it is so early it still carries TdT, the enzyme that adds random nucleotides during receptor gene rearrangement, and B-lineage blasts carry CD10.","TdT ⊕ = lymphoblast (pre-B or pre-T)","437",["Robbins ch 13","Katzung ch 54"]],"burkitt":["c-MYC switched on permanently by the immunoglobulin heavy-chain promoter","The translocation moves c-MYC from chromosome 8 beside the immunoglobulin heavy-chain locus on 14, which is always active in a B cell. MYC drives the cell cycle nonstop — Burkitt is the fastest-growing human tumor, with nearly every cell dividing.","t(8;14) = Burkitt (Burk-8)","435, 439, 440",["Robbins ch 13","Robbins ch 7"]],"pcnsl":["EBV-driven B-cell lymphoma confined to the brain","When T-cell surveillance fails, EBV-infected B cells proliferate unchecked, and in the brain they form a lymphoma, usually of the diffuse large B-cell type.","AIDS + single ring-enhancing lesion = primary CNS lymphoma (EBV ⊕ B-cell tumor)","173, 435",["Robbins ch 13","Robbins ch 28"]],"malt":["Chronic antigen stimulation keeps marginal-zone B cells dividing","Marginal-zone B cells answer chronic antigen stimulation. When the stimulation never stops — H. pylori gastritis, Sjögren syndrome, Hashimoto thyroiditis — a clone emerges.","H. pylori + gastric lymphoma = MALT lymphoma — it may regress with antibiotics","435",["Robbins ch 13","Robbins ch 17"]],"hodgkin":["Reed-Sternberg cells — crippled germinal-center B cells that recruit a reactive crowd","The malignant cell is the Reed-Sternberg cell, a germinal-center B cell that has lost its B-cell program. RS cells are few; most of the node is reactive lymphocytes, eosinophils, histiocytes and fibrosis drawn in by the cytokines they secrete.","2 owl eyes × 15 = 30: Reed-Sternberg cells are CD15 ⊕ CD30 ⊕","434",["Robbins ch 13","Katzung ch 54"]],"myeloma":["One plasma-cell clone fills the marrow and secretes a monoclonal immunoglobulin","A malignant plasma-cell clone fills the marrow and secretes one immunoglobulin, the M protein — IgG most often, then IgA, or light chains alone.","CRAB = myeloma","208, 436, 447",["Robbins ch 13","Katzung ch 54"]],"lch":["A clone of immature Langerhans cells, often with BRAF V600E (55–60%)","Langerhans cells are the dendritic antigen-presenting cells of the skin. In LCH a clone of immature Langerhans cells proliferates and infiltrates bone, skin and other organs.","Birbeck granules (tennis rackets) = Langerhans cell histiocytosis","439",["Robbins ch 13"]],"tls":["Dying tumor cells dump potassium, phosphate and nucleic acids","When a large, rapidly dividing tumor is killed at once, its contents flood the blood. Potassium causes arrhythmias. Phosphate binds calcium, dropping serum calcium and depositing calcium phosphate crystals in the kidney.","Tumor lysis: everything rises except calcium","440, 497",["Katzung ch 54","Robbins ch 26"]],"ebv":["Latent EBV proteins keep infected B cells alive and dividing","EBV infects B cells through CD21 and stays latent for life. Its latent membrane protein LMP1 acts like a constitutively active CD40 receptor and pushes infected B cells to proliferate; cytotoxic T cells normally hold them in check.","Must be 21 to drink Beer in a Barr — EBV binds CD21","162, 173",["Robbins ch 8","Robbins ch 13"]],"hpv":["E6 degrades p53; E7 inactivates Rb","High-risk types (16, 18) integrate into the genome of squamous epithelium and express two oncoproteins. E6 tags p53 for destruction, so damaged cells no longer arrest or undergo apoptosis.","E6 ⊣ p53, E7 ⊣ Rb (6 before 7, P before R)","161, 663",["Robbins ch 22","Robbins ch 7"]],"npc":["EBV-infected nasopharyngeal epithelium turns malignant","Nasopharyngeal carcinoma is the epithelial EBV cancer, arising beside the opening of the eustachian tube.","Adult of Asian descent + epistaxis + one-sided middle-ear effusion = nasopharyngeal carcinoma","690",["Robbins ch 16","Robbins ch 13"]],"bladderca":["Urothelium bathed in carcinogens concentrated in urine","Carcinogens absorbed anywhere are concentrated in the urine, so the whole urothelium — calyces, renal pelvis, ureters and bladder — is at risk and tumors are often multifocal.","Painless hematuria in a smoker = bladder cancer until proven otherwise","221, 624",["Robbins ch 21"]],"lungca":["Carcinogens in smoke and air hit the bronchial and alveolar epithelium","The leading cause of cancer death. Central tumors — squamous cell and small cell — are the ones most tied to smoking (sentral). Peripheral tumors are adenocarcinoma and large cell.","Squamous and small cell are sentral (central)","221, 703",["Robbins ch 15","Robbins ch 7"]],"mesothelioma":["Asbestos fibers lodge in the pleura and drive chronic injury","Long, thin asbestos fibers reach the pleura, where macrophages cannot clear them. Chronic inflammation and oxidant injury transform the mesothelial cells.","Asbestos → lung cancer more often than mesothelioma","695, 696",["Robbins ch 15"]],"hcmalig":["Tumor PTHrP, tumor calcitriol, or bone destroyed directly","Three routes. PTHrP from squamous cell carcinomas (lung, head and neck) and from renal, bladder, breast and ovarian carcinomas acts on the PTH receptor, releasing bone calcium and holding calcium in the kidney — the most common route.","High calcium with suppressed PTH = malignancy until proven otherwise","224, 336, 342, 349",["Robbins ch 24","Katzung ch 42"]],"mtx":["Dihydrofolate reductase — competitive inhibitor","A folic acid analog that competitively inhibits dihydrofolate reductase, so DHF cannot be recycled to THF. Without THF the cell cannot make dTMP or purines, and DNA synthesis stops.","Methotrexate ⊣ DHFR; leucovorin rescues","190, 444",["Katzung ch 54","Katzung ch 36"]],"cyclophos":["Cross-link DNA — need liver activation","Nitrogen mustards that must be activated by hepatic P-450 enzymes, then alkylate and cross-link DNA (guanine N-7). Cell-cycle nonspecific. A byproduct, acrolein, is excreted in urine and burns the bladder lining.","CYclophosphamide → hemorrhagic CYstitis; mesna binds acrolein","445",["Katzung ch 54"]],"topo2":["Topoisomerase II","Topoisomerase II cuts both strands to untangle DNA. Etoposide and teniposide inhibit it, leaving DNA strand breaks. Arrest in S and G2.","Etoposide and teniposide cut both sides: topo II","445",["Katzung ch 54","Marks ch 12"]],"antiemetic":["Block 5-HT₃, D₂ or NK₁ receptors","Chemotherapy releases serotonin from enterochromaffin cells in the gut, stimulating vagal 5-HT₃ receptors, and acts on the chemoreceptor trigger zone.","Acute chemo nausea → 5-HT₃ blocker; delayed → NK₁ blocker (aprepitant)","407",["Katzung ch 62"]],"pgp":["ATP-dependent efflux pump","An ATP-dependent pump that pushes drugs back out of the cell. Some tumors overexpress it and become resistant to many structurally unrelated chemotherapy drugs at once — one mechanism by which responsiveness falls over time.","P-glycoprotein (MDR1) pumps chemotherapy out → multidrug resistance","223, 443",["Katzung ch 54","Katzung ch 1"]],"polyposis":["Inherited polyp-forming syndromes","Besides FAP (APC) and Lynch syndrome (mismatch repair), several inherited syndromes fill the gut with polyps. Some are adenomatous (Gardner, Turcot, MUTYH); others are hamartomatous (Peutz-Jeghers, juvenile polyposis).","Freckled lips + GI hamartomas = Peutz-Jeghers","394",["Robbins ch 17"]],"crc":["Chromosomal instability (APC → KRAS → TP53) or microsatellite instability (mismatch repair lost)","Two main roads. Chromosomal instability: loss of APC → KRAS mutation → loss of TP53 and DCC, the adenoma-carcinoma sequence (“Always kill polyps”) — FAP and most sporadic, usually left-sided cancers.","Always kill polyps: APC → KRAS → P53","395",["Robbins ch 17","Robbins ch 7"]],"breastca":["Terminal duct lobular unit — ER/PR and HER2 status set the treatment","Most breast cancers arise in the terminal duct lobular unit. Ductal carcinoma in situ fills ducts without breaching the basement membrane and shows up as microcalcifications.","Lobular = lost E-cadherin → single file","668",["Robbins ch 23","Katzung ch 40"]],"rcc":["VHL lost (chromosome 3p) → HIF-1α builds up → VEGF drives the tumor","Arises from the proximal convoluted tubule. Losing VHL on chromosome 3p means HIF-1α is never tagged for destruction, so the cell acts as if it were hypoxic and pumps out VEGF and other growth signals.","RCC = 3 letters = chromosome 3 = VHL","623",["Robbins ch 20","Robbins ch 7"]],"oncocytoma":["Benign collecting-duct tumor packed with mitochondria","A benign epithelial tumor from the collecting duct made of large eosinophilic cells full of mitochondria. It has a well-circumscribed edge and a central scar.","Mitochondria-packed eosinophilic cells + central scar = oncocytoma","624",["Robbins ch 20"]],"wilms":["WT1 or WT2 lost (chromosome 11)","The most common renal malignancy of early childhood. Loss-of-function mutations in the tumor suppressors WT1 or WT2 on chromosome 11 (W11ms) leave embryonic kidney tissue proliferating, so the tumor contains embryonic glomerular structures.","Child + unilateral flank mass + aniridia = WAGR (Wilms)","624",["Robbins ch 10","Robbins ch 20"]],"bph":["DHT-driven hyperplasia of the transition zone","Common after 50. Dihydrotestosterone drives hyperplasia (not hypertrophy) of the transition zone, whose nodules squeeze the urethra into a slit.","Transition zone = BPH; peripheral zone = cancer","672",["Robbins ch 21","Katzung ch 10"]],"prostateca":["Androgen-dependent adenocarcinoma of the peripheral zone","Arises most often in the peripheral zone (posterior lobe), which is why it can be felt on digital rectal exam and rarely causes early urinary symptoms.","Older man + back pain + osteoblastic lesions + high PSA = prostate cancer","672",["Robbins ch 21","Katzung ch 40"]],"testisgct":["Germ cells gone wrong — each type has its own marker","About 95% of testicular tumors come from germ cells. They can stay undifferentiated (seminoma), become embryonal carcinoma, or differentiate into extra-embryonic tissue (yolk sac tumor, choriocarcinoma) or somatic tissue (teratoma).","AFP = yolk sac; hCG = choriocarcinoma; PLAP = seminoma","671",["Robbins ch 21"]],"testisstromal":["Hormone-making cells of the testis","About 5% of testicular tumors come from the sex cord-stroma, mostly benign. Leydig cell tumors make androgens or estrogens; Sertoli cell tumors (androblastomas) are usually silent.","Reinke crystals = Leydig cell tumor","665, 670",["Robbins ch 21","Robbins ch 22"]],"ovgerm":["Oocytes differentiate into somatic or extra-embryonic tissue, or not at all","Germ cell tumors mirror the testis. They may form somatic tissue from all three germ layers (teratoma), extra-embryonic tissue (yolk sac tumor) or stay undifferentiated (dysgerminoma, the ovarian seminoma).","Dermoid cyst with teeth and hair = mature cystic teratoma","664",["Robbins ch 22"]],"endomca":["Estrogen unopposed by progesterone drives the glands to proliferate","Estrogen stimulates endometrial glands; progesterone normally stops them. When estrogen runs unopposed, endometrial hyperplasia develops, and with nuclear atypia it progresses to endometrioid carcinoma, the most common subtype.","Postmenopausal bleeding → endometrial biopsy","666",["Robbins ch 22","Katzung ch 40"]],"gbm":["Malignant astrocytes — EGFR amplification","The common, highly malignant primary brain tumor of adults, arising from astrocytes in the cerebral hemispheres. It grows along white-matter tracts and can cross the corpus callosum, giving the butterfly shape.","Pseudopalisading necrosis + butterfly across the corpus callosum = glioblastoma","540",["Robbins ch 28"]],"oligo":["Oligodendrocyte-derived, slow growing","A relatively rare, slow-growing glioma of oligodendrocytes, most often in the frontal lobes and often calcified.","Fried eggs + chicken wire + calcified frontal mass = oligodendroglioma","540",["Robbins ch 28"]],"meningioma":["Arachnoid cap cells — extra-axial","A common, typically benign tumor of arachnoid cells on the surface of the brain or spinal cord. It sits outside the brain parenchyma (extra-axial) and pushes rather than invades.","Dural tail + whorls + psammoma bodies = meningioma","540",["Robbins ch 28"]],"schwannoma":["Schwann cells — benign, S-100 ⊕","A benign tumor of Schwann cells, classically on CN VIII at the cerebellopontine angle or in the internal acoustic meatus, but it can arise on any peripheral nerve (also CN V and VII).","One-sided hearing loss + tinnitus + CPA mass = vestibular schwannoma","540",["Robbins ch 27","Robbins ch 28"]],"nf2":["Merlin (schwannomin) lost — chromosome 22","Loss of the tumor suppressor merlin (schwannomin) on chromosome 22 — a cytoskeletal protein that switches on Hippo growth-control signaling — lets Schwann, meningeal and ependymal cells grow into tumors.","NF2 affects 2 ears and 2 eyes (bilateral schwannomas, juvenile cataracts)","539",["Robbins ch 27","Robbins ch 28"]],"hemangioblastoma":["Blood vessel-origin tumor, often VHL","A vascular tumor, most often in the cerebellum, made of tightly packed thin-walled capillaries. With retinal angiomas it points to von Hippel-Lindau disease.","Cerebellar tumor + polycythemia = hemangioblastoma","540",["Robbins ch 28"]],"pilocytic":["Low-grade astrocytoma of childhood","The most common primary brain tumor of childhood. A benign, well-circumscribed astrocytoma, usually in the posterior fossa (cerebellum), that often forms a cyst with a mural nodule.","Child + cystic cerebellar mass with a mural nodule + Rosenthal fibers = pilocytic astrocytoma","542",["Robbins ch 28"]],"medullo":["Primitive neuroectodermal tumor of the cerebellum","The most common malignant brain tumor of childhood, a primitive neuroectodermal tumor (small round blue cells) of the cerebellum. Vermis involvement causes truncal ataxia; compression of the 4th ventricle causes noncommunicating hydrocephalus.","Child + vermis mass + Homer-Wright rosettes + drop metastases = medulloblastoma","542",["Robbins ch 28"]],"ependymoma":["Ependymal cells lining the ventricles","A tumor of the ependymal cells that line the ventricles, most often in the 4th ventricle of children, where it blocks CSF flow and causes noncommunicating hydrocephalus.","4th-ventricle mass + perivascular pseudorosettes = ependymoma","542",["Robbins ch 28","Fundamental Neuroscience ch 6"]],"pineal":["Extragonadal germ cell tumor of the pineal region","Most pineal-region tumors are extragonadal germ cell tumors, histologically like testicular seminoma. A mass here compresses the cerebral aqueduct (hydrocephalus) and the dorsal midbrain (Parinaud syndrome).","Upward gaze palsy + hydrocephalus in a boy = pineal germinoma (Parinaud)","542",["Robbins ch 28"]],"thyroidca":["Follicular-cell carcinomas: RET/PTC and BRAF (papillary), RAS and PAX8-PPARγ (follicular)","Carcinomas of the thyroid's follicular cells, diagnosed by fine needle aspiration and treated by thyroidectomy. Papillary (most common, good prognosis) spreads to cervical nodes.","Papi and Moma adopted Orphan Annie: papillary = psammoma bodies + Orphan Annie nuclei","347",["Robbins ch 24","Robbins ch 7"]],"medullary":["C cells — calcitonin; RET gain of function","A carcinoma of the parafollicular C cells, which make calcitonin. The calcitonin forms amyloid in the stroma. Germline RET mutations cause it in MEN2A and MEN2B, where prophylactic thyroidectomy is recommended.","MEN2llary carcinoma — RET","356",["Robbins ch 24"]],"bcc":["Basal keratinocytes — sun damage","The most common skin cancer, arising in sun-exposed skin, typically on the face above the upper lip. Locally invasive but rarely metastasizes.","Pearly papule with telangiectasias on the nose = basal cell carcinoma","494",["Robbins ch 25"]],"melanoma":["Melanocytes — often an activating BRAF mutation","A malignant tumor of melanocytes with a high risk of metastasis. Many are driven by an activating BRAF mutation. The depth of invasion (Breslow thickness) correlates with the risk of metastasis.","ABCDE mole = melanoma","494",["Robbins ch 25","Katzung ch 54"]],"osteosarcoma":["Malignant osteoblasts making osteoid","The most common malignant primary bone tumor in young people (about 20% of primary bone cancers): malignant osteoblasts lay down disorganized osteoid in the metaphysis of long bones, usually around the knee.","Teenager + knee metaphysis + Codman triangle / sunburst = osteosarcoma","471",["Robbins ch 26","Bootcamp.com MSK"]],"ewing":["EWS-FLI1 fusion from t(11;22)","An aggressive tumor of anaplastic small round blue cells of neuroectodermal origin in the diaphysis of long bones and the flat bones of the pelvis.","11 + 22 = 33, Patrick Ewing's jersey number","471",["Robbins ch 26","Bootcamp.com MSK"]],"gct":["Neoplastic stromal cells express RANKL and recruit osteoclast-like giant cells","A locally aggressive benign tumor in the epiphysis of long bones after growth plates close, often around the knee. The neoplastic mononuclear cells express RANKL, which recruits the multinucleated osteoclast-like giant cells that erode the bone.","Epiphysis + soap bubble in a young adult = giant cell tumor","470",["Robbins ch 26"]],"osteochondroma":["Lateral outgrowth of the growth plate with a cartilage cap","The most common benign bone tumor: a bony projection from the metaphysis, continuous with the marrow space, capped by cartilage and pointing away from the joint.","Most common benign bone tumor = osteochondroma","470",["Robbins ch 26"]],"chondrosarcoma":["Malignant chondrocytes","A malignant cartilage tumor of older adults in the medulla of the pelvis, proximal femur and humerus. It may arise from a pre-existing osteochondroma.","Older adult + pelvic lytic lesion with calcifications = chondrosarcoma","471",["Robbins ch 26"]],"nephritic":["Glomerular inflammation damages the GBM — red cells leak into the urine","Inflammation breaks the glomerular basement membrane, so red cells squeeze into Bowman's space and are deformed on the way (dysmorphic RBCs).","Hematuria + RBC casts + hypertension = nephritic","613, 614",["Robbins ch 20","Pawlina ch 20"]],"nephrotic":["Podocyte injury — the charge barrier fails and protein pours out","When podocytes are injured, the filter loses its charge and size selectivity, and albumin floods into the urine.","Massive proteinuria + edema + hypoalbuminemia + hyperlipidemia = nephrotic","613",["Robbins ch 20"]],"psgn":["Immune complexes deposit as subepithelial humps (type III hypersensitivity)","Antibodies against streptococcal antigens form immune complexes that lodge on the outer side of the GBM, activate complement and draw in neutrophils.","Child + recent strep + cola urine + low C3 = PSGN","614",["Robbins ch 20"]],"igan":["IgA immune complexes deposit in the mesangium","Abnormally glycosylated IgA forms immune complexes that lodge in the mesangium. Because IgA is made at mucosal surfaces, flares come during an upper respiratory or GI infection — not weeks later, as in poststreptococcal GN.","Hematuria during (not after) a URI = IgA nephropathy","479, 614",["Robbins ch 20","Robbins ch 11"]],"rpgn":["Crescents of fibrin, parietal cells and macrophages fill Bowman's space","Severe glomerular injury ruptures the capillary wall; fibrin and plasma proteins (C3b) spill into Bowman's space, and parietal cells, monocytes and macrophages proliferate into a crescent that squeezes the tuft.","Crescent moon glomeruli = RPGN","479, 614, 730",["Robbins ch 20"]],"dpgn":["Subendothelial immune complexes — wire loops","DNA-anti-DNA immune complexes deposit beneath the endothelium, thickening the capillary walls into rigid wire loops. It is the most common and most severe form of lupus nephritis and often produces nephritic and nephrotic features together.","Think wire lupus","476, 614",["Robbins ch 20","Robbins ch 6"]],"mcd":["Podocyte foot processes efface — glomeruli look normal on light microscopy","Cytokine-mediated injury flattens the podocyte foot processes, so the charge barrier fails and albumin leaks out selectively. Nothing shows on light microscopy — only electron microscopy reveals the effacement.","Child with nephrotic syndrome + normal light microscopy = minimal change","616",["Robbins ch 20"]],"fsgs":["Segments of some glomeruli scar","Podocytes are injured and lost; the bare capillary loops collapse and scar, first in some glomeruli (focal) and only part of each tuft (segmental).","Black adult or HIV + nephrotic syndrome = FSGS","616",["Robbins ch 20"]],"membranous":["Subepithelial immune complexes — spike and dome","Antibodies bind antigens on the podocyte (the phospholipase A2 receptor in primary disease) and form immune complexes on the outer side of the GBM.","Adult + nephrotic + spike and dome = membranous","616",["Robbins ch 20"]],"amyloidosis":["Misfolded proteins form β-pleated sheets that deposit in tissues","Proteins misfold into insoluble β-pleated sheets. AL amyloid comes from immunoglobulin light chains (myeloma, MGUS); AA from serum amyloid A in chronic inflammation (rheumatoid arthritis, IBD, chronic infection, familial Mediterranean fever).","Apple-green birefringence = amyloid","208",["Robbins ch 6","Robbins ch 20"]],"casts":["Protein molds of the tubule — they prove the kidney is the source","Casts form when cells or debris are trapped in a matrix of Tamm-Horsfall protein (uromodulin) inside the tubule, so any cast means the problem is in the kidney itself.","Casts = kidney origin","612",["Robbins ch 20"]],"agma":["An unmeasured acid is added — the gap widens","When a strong acid is added, bicarbonate buffers it and falls; the acid's anion (lactate, ketoacids, formate, glycolate) stays in the blood but is not measured, so the anion gap — Na⁺ − (Cl⁻ + HCO₃⁻) — rises above 12.","GOLDMARK = anion gap acidosis","70, 351, 609, 610",["Costanzo ch 7","Katzung ch 58"]],"nagma":["Bicarbonate is lost and replaced by chloride — the gap stays 8–12","Bicarbonate is lost through the gut or kidney (or diluted by saline), and chloride rises to keep the charges balanced, so the anion gap stays normal.","SHARDS = normal anion gap acidosis","610",["Costanzo ch 7","Guyton ch 31"]],"metalk":["H⁺ is lost or HCO₃⁻ retained; volume and chloride depletion keep it going","Losing gastric acid or chloride-rich fluid raises bicarbonate, and volume depletion makes the kidney hold on to it (contraction alkalosis).","Vomiting → hypochloremic, hypokalemic metabolic alkalosis","603, 610",["Costanzo ch 7","Katzung ch 15"]],"respacid":["CO₂ builds up because ventilation falls","Whatever reduces alveolar ventilation raises PCO₂ and lowers pH. The kidney compensates slowly (days) by reabsorbing more bicarbonate, so chronic respiratory acidosis has a high HCO₃⁻.","Opioid overdose → respiratory acidosis","609, 610",["Costanzo ch 7","Katzung ch 31"]],"respalk":["CO₂ is blown off faster than it is made","Overbreathing lowers PCO₂ and raises pH. Alkalosis increases albumin binding of calcium, so ionized calcium falls — causing perioral tingling and carpopedal spasm.","Aspirin overdose: respiratory alkalosis first, then anion gap acidosis","337, 609, 610",["Costanzo ch 7","Costanzo ch 9"]],"hyperk":["Potassium leaves cells or is not excreted","Potassium is mostly inside cells. It shifts out with insulin deficiency, β-blockade, acidosis, digoxin (Na⁺/K⁺-ATPase blocked), hyperosmolality (solvent drag), cell lysis and succinylcholine.","Peaked T waves = hyperkalemia","608, 609",["Katzung ch 15","Katzung ch 14"]],"hypok":["Potassium moves into cells or is lost","Potassium shifts into cells with insulin, β₂-agonists and alkalosis. It is lost through the kidney with loop or thiazide diuretics, hyperaldosteronism, Bartter or Gitelman syndrome and hypomagnesemia, and through the gut with diarrhea.","U waves = hypokalemia","342, 351, 604, 609",["Costanzo ch 6","Katzung ch 15"]],"sodiumdis":["Sodium concentration reflects water balance","Serum sodium reflects water more than sodium. Hyponatremia means relative water excess — ADH is high (SIADH, heart failure, cirrhosis, volume depletion, thiazides) or intake overwhelms excretion (primary polydipsia).","Correct hyponatremia too fast → osmotic demyelination (pons)","342, 538, 609",["Guyton ch 25","Guyton ch 29"]],"mgpo4":["Mg²⁺ stabilizes membranes and releases PTH; phosphate is bound to calcium","Magnesium is needed for PTH release and for the kidney to hold potassium, so hypomagnesemia drags calcium and potassium down with it. Hypermagnesemia depresses deep tendon reflexes and the heart (bradycardia, hypotension, cardiac arrest).","Torsades → give IV magnesium","349, 440, 584, 609, 660",["Katzung ch 42","Katzung ch 62"]],"gca":["Granulomatous inflammation of large arteries — branches of the carotid","Granulomatous inflammation with giant cells thickens the wall of the temporal, vertebral and ophthalmic arteries. Ophthalmic artery involvement (anterior ischemic optic neuropathy) can cause blindness, which is why treatment starts before the biopsy.","Older woman + headache + jaw claudication + high ESR = GCA","478",["Robbins ch 11","Katzung ch 36"]],"takayasu":["Granulomatous thickening of the aortic arch and great vessels","Granulomatous inflammation thickens and narrows the aortic arch and the proximal great vessels, so the pulses weaken in the arms.","Young Asian woman + weak arm pulses = Takayasu","478",["Robbins ch 11"]],"pan":["Transmural necrotizing inflammation of medium arteries — spares the lungs","Immune complexes (containing hepatitis B surface antigen in about a third of patients) inflame the full thickness of medium arteries, with fibrinoid necrosis.","Hepatitis B + string of pearls = PAN","478",["Robbins ch 11","Robbins ch 6"]],"mpa":["Pauci-immune necrotizing small-vessel vasculitis — no granulomas","Antibodies against neutrophil myeloperoxidase activate neutrophils against small-vessel walls in the lungs, kidneys and skin. Unlike GPA there are no granulomas and no nasopharyngeal disease.","p-ANCA + GN + lungs, no granulomas, no sinuses = MPA","478, 614",["Robbins ch 11","Robbins ch 20"]],"gpa":["Necrotizing granulomatous vasculitis of the upper airway, lungs and kidneys","Antibodies against proteinase 3 (PR3) activate neutrophils against small vessels. Granulomas destroy the nasal septum and sinuses, form cavitating lung nodules, and a pauci-immune crescentic GN destroys the kidneys.","Sinuses + lungs + kidneys + c-ANCA = GPA","479",["Robbins ch 11","Robbins ch 15"]],"cryo":["Mixed IgG and IgM immune complexes that precipitate in the cold","Usually driven by chronic hepatitis C: mixed IgG and IgM immune complexes precipitate in the cold, deposit in small vessels and activate complement.","HCV + purpura + arthralgia + weakness = mixed cryoglobulinemia","479",["Robbins ch 20","Robbins ch 11"]],"raynaud":["Arteriolar vasospasm in response to cold or stress","Small arteries and arterioles of the fingers and toes spasm in the cold or under stress: white (ischemia), then blue (hypoxia), then red (reperfusion).","White, blue, red fingers in the cold = Raynaud","480",["Robbins ch 11","Robbins ch 6"]],"cyanide":["Blocks cytochrome c oxidase (complex IV)","Cyanide binds cytochrome a3 in complex IV (cytochrome c oxidase), so oxygen is present but cannot be used and oxidative phosphorylation stops.","Fire victim + lactic acidosis despite normal PaO₂ = cyanide (± CO)","689",["Katzung ch 58","Katzung ch 12"]],"anticoagrev":["Each anticoagulant has its own antidote","Protamine is a positively charged peptide that binds negatively charged heparin. Vitamin K restores synthesis of factors II, VII, IX, X (slowly); PCC or FFP replaces them immediately.","Protamine: ⊕ binds ⊝ heparin","442",["Katzung ch 34"]],"toxidromes":["Patterns of vital signs, pupils, skin and mental status","A few exam findings sort most poisonings: pupils, skin moisture, bowel sounds, temperature and mental status.","Dilated pupils + dry skin = anticholinergic; dilated + sweaty = sympathomimetic","239, 240",["Katzung ch 58","Katzung ch 8"]],"cypinducers":["More enzyme is made — substrate levels fall","Inducers switch on transcription of the CYP genes (through nuclear receptors such as PXR), so the liver makes more enzyme. Substrates are cleared faster and fail; prodrugs are activated faster.","St John's funny funny (phen-phen) mom never refuses greasy carbs and chronic alcohol","198, 251",["Katzung ch 4","Katzung ch 49"]],"cyp3a4":["Metabolizes over half of liver-metabolized prescription drugs — liver and gut wall","CYP3A4 handles the largest share of drug metabolism, in the liver and in the intestinal wall (which is why grapefruit juice, acting in the gut, raises levels).","Grapefruit juice inhibits intestinal CYP3A4","251",["Katzung ch 67","Katzung ch 4"]],"cyp2d6":["Activates codeine, tramadol and tamoxifen; clears many psychiatric and cardiac drugs","No inducers of CYP2D6 are known — its activity is set mainly by genetics. Poor metabolizers accumulate its substrates and get no effect from prodrugs; ultrarapid metabolizers (gene duplication) convert prodrugs to active drug too fast.","No inducers worth knowing — genetics rules 2D6","251, 567",["Katzung ch 4","Katzung ch 67"]],"cyp2c9":["Clears S-warfarin (the potent enantiomer), phenytoin, sulfonylureas, NSAIDs","CYP2C9 inactivates the more potent S-enantiomer of warfarin, so its inhibitors raise the INR sharply. Variants in CYP2C9 and in VKORC1 (warfarin's target) together explain much of the spread in warfarin doses.","The warfarin enzyme: 2C9 + VKORC1","251, 441",["Katzung ch 4","Katzung ch 67"]],"cyp2c19":["Activates clopidogrel; clears PPIs, citalopram, diazepam","Clopidogrel is a prodrug that needs CYP2C19 to become active. Poor metabolizers (loss-of-function alleles, common in East Asian patients) and patients taking CYP2C19 inhibitors get too little active drug and are at risk of stent thrombosis.","2C19 turns clopidogrel on — block it and the stent clots","251",["Katzung ch 4","Katzung ch 67"]],"cyp1a2":["Clears theophylline, caffeine, clozapine, olanzapine, tizanidine","CYP1A2 is induced by polycyclic aromatic hydrocarbons in tobacco smoke and charcoal-broiled meat.","Smoking induces 1A2 — quitting raises clozapine","251",["Katzung ch 4","Katzung ch 67"]],"calcineurin":["Calcineurin blocked → no NFAT → no IL-2 transcription","Cyclosporine binds cyclophilin and tacrolimus binds FKBP; both complexes block calcineurin, the phosphatase that activates NFAT, so T cells cannot transcribe IL-2.","Calcineurin inhibitors: nephrotoxic","118",["Katzung ch 55","Katzung ch 48"]],"ppi":["PPIs irreversibly block the parietal-cell H⁺/K⁺-ATPase; H₂ blockers block histamine receptors","PPIs (-prazole) irreversibly inhibit the H⁺/K⁺-ATPase, the final step of acid secretion. H₂ blockers (-tidine) reversibly block histamine H₂ receptors on parietal cells.","Cimetidine: the H₂ blocker with CYP inhibition and gynecomastia","406",["Katzung ch 62"]],"hs1":["Antigen cross-links IgE on mast cells → degranulation","A sensitized person already has allergen-specific IgE on mast cells and basophils. Re-exposure cross-links that IgE, and within minutes the cells release histamine, tryptase and leukotrienes (immediate phase).","First and Fast","110, 705",["Robbins ch 6","Katzung ch 16"]],"hs2":["IgG or IgM binds antigens on cells or matrix","Antibodies bind antigens fixed on cells or basement membranes.","Type II: the antibody targets a fixed antigen on a cell","110",["Robbins ch 6","Robbins ch 14"]],"hs3":["Antigen-antibody complexes deposit and fix complement","Circulating antigen-antibody complexes (mostly IgG) deposit in vessels, glomeruli and joints, activate complement and draw in neutrophils, whose lysosomal enzymes damage the tissue.","Type III = immune complexes = vasculitis, GN, arthritis","111",["Robbins ch 6","Katzung ch 55"]],"hs4":["Sensitized T cells — no antibody involved","Two T-cell mechanisms: CD8⁺ cytotoxic T cells kill antigen-bearing cells directly, or CD4⁺ Th1 cells recognize antigen and release cytokines that recruit and activate macrophages.","4 Ts: T cells, Transplant rejections, TB skin tests, Touching (contact dermatitis)","111",["Robbins ch 6"]],"candida":["Opportunistic yeast with pseudohyphae","A normal commensal that overgrows when bacterial flora, T-cell immunity or neutrophils are lost. Mucosal disease reflects T-cell failure; disseminated disease reflects neutrophil failure.","White plaques that scrape off = thrush (hairy leukoplakia does not scrape off)","150, 173",["Robbins ch 8","Katzung ch 48"]],"aspergillus":["Septate hyphae branching at acute (45°) angles","Airborne mold. Because it is catalase ⊕, it is a classic infection in chronic granulomatous disease. It can invade vessels in neutropenic patients, grow as a fungus ball in an old cavity, or trigger an allergic reaction in the airways.","Acute-angle septate hyphae = Aspergillus","150",["Robbins ch 8","Robbins ch 15"]],"pcp":["Yeast-like fungus causing diffuse interstitial pneumonia","Most people carry it silently; with falling T-cell immunity it fills the alveoli with foamy exudate.","Start prophylaxis when CD4 < 200","151",["Robbins ch 15","Robbins ch 8"]],"giardia":["Trophozoites coat the small bowel and block fat absorption","Cysts in untreated stream water become trophozoites that attach to the duodenal mucosa and interfere with fat absorption. IgA deficiency raises susceptibility.","Camper + fatty diarrhea = Giardia (Ghirardelli chocolate)","152",["Robbins ch 8","Katzung ch 52"]],"schisto":["Blood flukes whose eggs lodge in tissue","Adult flukes live in venous plexuses. Eggs trapped in the liver (S. mansoni, S. japonicum) cause granulomas and fibrosis; eggs in the bladder wall (S.","Freshwater swim in Egypt + hematuria = S. haematobium","157",["Robbins ch 8","Katzung ch 53"]],"entero":["Picornaviruses — naked + ssRNA","Enteroviruses (polio, echo, coxsackie) are acid-stable picornaviruses that start in the gut and can spread to the meninges, heart, skin and muscle.","Viral meningitis → enterovirus is the usual identified cause","164–165",["Robbins ch 8","Robbins ch 28"]],"arbo":["Enveloped + ssRNA viruses carried by mosquitoes or ticks","Arthropod-borne (arbo) viruses from the flavivirus and togavirus families.","Pregnant traveler + mosquito exposure → Zika → microcephaly","168",["Robbins ch 8","Robbins ch 28"]],"corona":["Enveloped + ssRNA; SARS-CoV-2 binds ACE2","Positive-sense, single-stranded RNA viruses. Seasonal types cause common colds; SARS-CoV-2 enters cells through ACE2 and can cause viral pneumonia, a hypercoagulable state and multiorgan injury.","SARS-CoV-2 receptor = ACE2","163, 169",["Robbins ch 8","Robbins ch 15"]],"parainfl":["Enveloped − ssRNA paramyxovirus","Parainfluenza virus inflames the larynx and trachea, narrowing the subglottic airway.","Barking cough + steeple sign = croup","167",["Robbins ch 15","Robbins ch 8"]],"rsv":["Enveloped − ssRNA pneumovirus; F protein fuses cells into syncytia","RSV infects the small airways of infants. Its F (fusion) protein fuses infected respiratory epithelial cells into multinucleated syncytia.","Infant with bronchiolitis = RSV","164, 166",["Katzung ch 49","Robbins ch 8"]],"truncus":["The aorticopulmonary septum never forms — one great vessel","Neural crest cells fail to build the aorticopulmonary septum, so a single trunk leaves the heart over a VSD and carries mixed blood to the body and lungs.","The 1st T: Truncus — 1 vessel","285, 302",["Langman ch 13","Robbins ch 12"]],"tof":["Anterosuperior displacement of the infundibular septum","One embryologic error — the infundibular septum is displaced forward — produces all four features (PROVe): Pulmonary infundibular stenosis, Right ventricular hypertrophy, Overriding aorta, VSD.","The 4th T: Tetralogy (tetra = 4)","302",["Robbins ch 12","Langman ch 13"]],"ebstein":["Tricuspid leaflets displaced down into the RV","The tricuspid leaflets attach low in the RV, so part of the ventricle functions as atrium, and the valve leaks.","Lithium in pregnancy → Ebstein anomaly","302",["Langman ch 13","Kaplan & Sadock ch 21"]],"vsd":["Hole in the interventricular septum — left-to-right shunt","The most common congenital heart defect. Blood shunts from the high-pressure LV to the RV, raising pulmonary flow. Small defects often close on their own; large ones overload the lungs and LV and, left alone, lead to Eisenmenger syndrome.","Most common congenital heart defect","298, 303",["Robbins ch 12","Guyton ch 23"]],"pphn":["Pulmonary resistance stays high after birth","The pulmonary vessels fail to relax after birth, so blood keeps shunting right to left through the foramen ovale and ductus as in the fetus.","Meconium aspiration + hypoxemia out of proportion = PPHN","304",["Katzung ch 19"]],"adinh":["One mutant allele is enough — often structural genes","Disease appears in every generation, in both sexes. Autosomal dominant disorders often involve structural proteins and are pleiotropic and variably expressive, so a family history is crucial.","Structural gene defects, every generation, 50% risk","57–58",["Robbins ch 5","Marks ch 18"]],"arinh":["Both alleles must be lost — usually enzyme deficiencies","Usually one generation affected, siblings rather than parents. Most are enzyme deficiencies, typically more severe than dominant disorders and presenting in childhood.","Oh, please! Can students who score high grades tell me features of the kidney disorder ARPKD?","58",["Robbins ch 5","Marks ch 18"]],"xlrinh":["Males with one mutant X are affected; females are usually carriers","No male-to-male transmission; it skips generations through carrier females. Females are affected only if homozygous, if they have Turner syndrome (45,X), or through skewed X-inactivation (lyonization).","No male-to-male transmission","57, 59",["Robbins ch 5","Marks ch 18"]],"fragilex":["CGG expansion in FMR1 → hypermethylation → gene silenced","Expansion of CGG repeats in FMR1 leads to hypermethylation that shuts off the gene. It shows anticipation. Premutation carriers (50–200 repeats) can develop tremor, ataxia and primary ovarian insufficiency.","Chin (protruding), Giant Gonads — CGG","60",["Robbins ch 5"]],"down":["Extra chromosome 21 — usually maternal meiosis I nondisjunction","Most cases come from meiotic nondisjunction, usually in maternal meiosis I, and the risk climbs with maternal age. Chromosome 21 carries the amyloid precursor protein gene, so Alzheimer disease comes early.","Drinking age (21)","61",["Robbins ch 5","Marks ch 18"]],"imprinting":["One parent's copy is silenced by methylation; the other is deleted or mutated","On chromosome 15, some genes are expressed only from the father's copy and UBE3A only from the mother's. Prader-Willi: the paternal region is deleted (or both copies come from the mother — maternal uniparental disomy, 25%).","POP: Prader-Willi, Obesity, Paternal deletion","56",["Robbins ch 5","Marks ch 18"]],"oa":["Mechanical stress wears down articular cartilage faster than chondrocytes repair it","Chronic mechanical stress destroys cartilage; chondrocyte-mediated repair is inadequate. Bone remodels underneath with spurs, sclerosis and cysts.","DIP involvement = osteoarthritis (RA spares the DIP)","472",["Robbins ch 26"]],"ra":["Autoimmune synovitis forms a pannus that erodes cartilage and bone","Autoimmune inflammation of the synovium produces proliferative granulation tissue — the pannus — that erodes articular cartilage and bone. Rheumatoid factor is an IgM against the Fc portion of IgG; anti-CCP antibodies are more specific.","HLA-DR4: the 4-walled rheum","472",["Robbins ch 26","Robbins ch 6"]],"cppd":["Calcium pyrophosphate crystals deposit in cartilage and joints","Calcium pyrophosphate crystals form in cartilage and are shed into the joint, causing acute attacks (pseudogout) or chronic degeneration (pseudo-osteoarthritis).","The blue P's of CPPD: blue when parallel, positive birefringence, calcium pyrophosphate, pseudogout","473",["Robbins ch 26","Katzung ch 36"]],"ankspond":["HLA-B27 enthesitis of the spine and sacroiliac joints → fusion","Inflammation at entheses (where ligaments insert into bone) of the spine and sacroiliac joints heals with new bone, so the vertebrae gradually fuse.","Young man + morning back stiffness better with exercise = ankylosing spondylitis","475",["Robbins ch 26","Katzung ch 36"]],"reactive":["Immune reaction to a distant GI or genitourinary infection","Weeks after a GI or GU infection, an HLA-B27-linked immune response inflames joints, eyes and urethra even though the joint is sterile.","She Caught Students Cheating Yesterday and overreacted (Shigella, Campylobacter, Salmonella, Chlamydia, Yersinia)","475",["Robbins ch 26","Robbins ch 8"]],"sle":["Immune complexes (type III) and autoantibodies (type II) damage many organs","Loss of tolerance produces antinuclear antibodies. DNA-anti-DNA immune complexes deposit in kidneys, skin, joints and serosa (type III), and antibodies against blood cells destroy them (type II).","Lupus patients die with redness in their cheeks: renal disease, infections, cardiovascular disease","113, 476",["Robbins ch 6","Katzung ch 36"]],"aps":["Antibodies against phospholipid-binding proteins make blood clot","Antibodies against phospholipid-binding proteins (lupus anticoagulant, anticardiolipin, anti-β2 glycoprotein I) create a hypercoagulable state.","Clots + miscarriages + prolonged PTT = antiphospholipid syndrome","146, 476",["Robbins ch 4","Robbins ch 6"]],"mctd":["Overlap of SLE, scleroderma and polymyositis","Patients have features of several connective tissue diseases at once, tied together by one antibody.","Anti-U1 RNP = mixed connective tissue disease","113, 476",["Robbins ch 6"]],"sjogren":["Lymphocytes destroy lacrimal and salivary glands","Lymphocytic infiltration destroys the exocrine glands, especially lacrimal and salivary glands. The chronic B-cell stimulation raises the risk of MALT lymphoma.","Dry eyes + dry mouth + anti-Ro/La = Sjögren","113, 474",["Robbins ch 6","Katzung ch 7"]],"sclero":["Autoimmunity + vasculopathy + collagen deposition with fibrosis","Autoimmune injury of small vessels triggers fibroblasts to lay down collagen in the skin and organs. Diffuse disease spreads widely and early to the viscera; limited disease stays on the fingers and face and runs a milder course (CREST).","Anticentromere = CREST (limited)","113, 323, 481",["Robbins ch 6"]],"pmr":["Inflammation around the shoulder and hip girdles","Pain and stiffness of the shoulder and hip girdles without true weakness; CK stays normal because the muscle itself is not damaged.","Proximal pain + high ESR + normal CK = PMR (myositis has high CK and weakness)","477, 478",["Robbins ch 11","Katzung ch 36"]],"septicarth":["Bacteria in the joint or bone","Bacteria reach the joint or bone through the blood or by direct spread. Without prompt drainage the joint can be irreversibly damaged.","Sickle cell + osteomyelitis = Salmonella","474",["Robbins ch 26","Robbins ch 8"]],"jia":["Systemic autoinflammatory arthritis in children","A systemic inflammatory disease of children under 16 — fever and rash as well as arthritis.","Child + quotidian fever + salmon rash + arthritis = systemic JIA","474",["Katzung ch 36","Katzung ch 55"]],"malehpg":["LH drives Leydig cells; FSH drives Sertoli cells","Pulsatile GnRH releases LH and FSH. LH acts on Leydig cells in the interstitium, which make testosterone. FSH acts on Sertoli cells lining the seminiferous tubules, which nurse developing sperm.","Sertoli cells Support Sperm synthesis and are Sensitive to heat","646",["Costanzo ch 10","Katzung ch 40"]],"spermatogenesis":["Meiosis in the seminiferous tubules, supported by Sertoli cells","Begins at puberty. Spermatogonia (2N) divide to make primary spermatocytes, which complete meiosis I to secondary spermatocytes and meiosis II to haploid spermatids.","Gonium is going to be a sperm; zoon is zooming to the egg","647",["Pawlina ch 22","Guyton ch 81"]],"anabolic":["Androgen receptor agonists","Outside testosterone shuts down the hypothalamic-pituitary-gonadal axis. LH and FSH fall, so the testis stops making its own testosterone — and intratesticular testosterone, which spermatogenesis depends on, drops even though blood levels are high.","Bodybuilder with small testes and gynecomastia","653",["Katzung ch 40","Guyton ch 81"]],"erection":["NO → cGMP relaxes cavernosal smooth muscle","Erection is parasympathetic (pelvic splanchnic nerves, S2–S4): nitric oxide raises cGMP, the smooth muscle of the corpus cavernosum relaxes, and blood fills the sinusoids.","Point, squeeze and shoot","645",["Moore ch 6","Guyton ch 81"]],"priapism":["Blood trapped in the corpora cavernosa","A painful erection lasting more than 4 hours. In ischemic priapism, venous drainage is blocked — sickled red cells jam the cavernosal channels, or drugs keep the smooth muscle relaxed — and the trapped blood becomes hypoxic and acidotic.","Sickle cell disease or trazodone + a painful erection over 4 hours","669",["Katzung ch 12","Kaplan & Sadock ch 21"]],"ed":["Too little NO-driven inflow, or venous leak","Erection needs intact pelvic parasympathetic nerves, NO synthesis to relax the cavernosal smooth muscle, and adequate arterial inflow. Causes sort into PENIS: Psychological, Endocrine, Neurogenic, Insufficient blood flow, Substances.","Nocturnal erections present → psychogenic","584",["Kaplan & Sadock ch 16","Katzung ch 12"]],"torsion":["The testis twists on its spermatic cord and loses its blood supply","When the testis is not anchored to the tunica vaginalis it lies horizontally and can spin on the cord (the bell clapper deformity). Twisting first blocks the veins, then the artery — the testis infarcts within hours.","Teenager with sudden scrotal pain and no cremasteric reflex","669",["Robbins ch 21"]],"varicocele":["Dilated pampiniform plexus veins","The left gonadal vein drains into the left renal vein at a right angle, so pressure on the left is higher and the pampiniform plexus dilates.","Bag of worms, left side, worse standing","669",["Moore ch 5","Pawlina ch 22"]],"cryptorchid":["The testis never finishes its descent into the scrotum","A testis kept at body temperature makes sperm poorly, because Sertoli cells are heat-sensitive; Leydig cells are not, so testosterone is usually normal.","Undescended testis → infertility and seminoma risk","669",["Robbins ch 21","Langman ch 16"]],"prostatitis":["Bacterial or nonbacterial inflammation of the prostate","Acute bacterial prostatitis is usually an ascending urinary infection. Chronic prostatitis may be bacterial or nonbacterial — after a previous infection, nerve problems or chemical irritation.","Fever, perineal pain and a boggy, tender prostate","672",["Robbins ch 21","Katzung ch 51"]],"hypospadias":["The urethra opens on the wrong surface of the penis","Hypospadias: the urethral folds fail to fuse, so the opening is on the ventral (under) surface. Epispadias: the genital tubercle is positioned wrongly, so the opening is on the dorsal (top) surface.","Hypo = below (ventral); epi = above (dorsal)","641",["Langman ch 16","Robbins ch 21"]],"peyronie":["Fibrous plaque in the tunica albuginea","Repeated small injuries heal as a fibrous plaque in the tunica albuginea. The scarred side cannot stretch during erection, so the penis curves toward it.","Curved erection from a palpable plaque","669",["Robbins ch 21"]],"penilescc":["HPV-driven squamous carcinoma","The most common penile cancer. It has three in-situ precursors that are named by where they sit and what they look like.","Red plaque on the glans = erythroplasia of Queyrat","669",["Robbins ch 21"]],"papnecrosis":["The renal papillae infarct and slough","The papillae sit at the end of the vasa recta, in the most hypoxic, hypertonic part of the kidney.","SAAD papa with papillary necrosis","621",["Robbins ch 20","Bootcamp.com Nephrology"]],"cystitis":["Bacteria ascend the urethra into the bladder","A short female urethra lets perineal bacteria reach the bladder. Anything that leaves urine sitting in the bladder — catheters, obstruction, neurogenic bladder — raises the risk.","Dysuria + frequency without fever = cystitis","619",["Robbins ch 21","Robbins ch 20"]],"pyelo":["Neutrophils infiltrate the renal interstitium","Usually an ascending infection (E coli most often), less often hematogenous. Neutrophils fill the interstitium and tubules of the cortex while the glomeruli and vessels are relatively spared.","WBC casts = pyelonephritis (or interstitial nephritis)","619",["Robbins ch 20","Katzung ch 51"]],"chronicpyelo":["Scarring from repeated upper tract infection","Recurrent or undertreated acute pyelonephritis, almost always on top of something that keeps infection coming back — vesicoureteral reflux in children, obstructing stones in adults.","Thyroidization of the kidney = chronic pyelonephritis","619",["Robbins ch 20"]],"hydroneph":["The renal pelvis and calyces dilate above a blockage","Urine backs up and dilates everything proximal to the obstruction. The pressure compresses the cortex and medulla and can lead to atrophy. Other causes besides a physical block: retroperitoneal fibrosis and vesicoureteral reflux.","Dilated calyces on ultrasound + rising creatinine → look for bilateral obstruction (BPH, cervical cancer)","618",["Robbins ch 20","Robbins ch 21"]],"incontinence":["Weak outlet, overactive detrusor, or a bladder that never empties","Three mechanisms, three treatments. Stress: the outlet is incompetent (urethral hypermobility or sphincter deficiency), so urine leaks when abdominal pressure rises.","Leaks with a sneeze = stress","618",["Moore ch 6","Robbins ch 21"]],"ckd":["Progressive loss of nephrons","As GFR falls in stages, the kidney stops excreting acid, potassium, salt, water and nitrogenous waste, and stops making erythropoietin and calcitriol.","FGF23 fights f(ph)osphate","616, 621, 622",["Robbins ch 20","Guyton ch 32"]],"uremia":["Retained nitrogenous waste","A syndrome of high blood urea and other retained toxins once kidney function is very low. The toxins also impair platelet function.","Pericarditis or asterixis in kidney failure → start dialysis","319, 432, 621",["Robbins ch 20","Katzung ch 37"]],"renalod":["Low calcitriol and high phosphate drive the parathyroids","Failing kidneys cannot hydroxylate vitamin D or excrete phosphate. Low 1,25-(OH)₂D₃ means less calcium absorbed from the gut, and high phosphate binds calcium and deposits in tissues.","CKD + ↑ PTH + ↑ phosphate = secondary hyperparathyroidism","349, 361, 622",["Katzung ch 42","Robbins ch 26"]],"adpkd":["Polycystin — PKD1 (chromosome 16) or PKD2 (chromosome 4)","Mutations in polycystin genes let cysts grow throughout the cortex and medulla of both kidneys. The enlarging kidneys destroy the parenchyma over decades, and cyst-related ischemia raises renin — hence hypertension.","Big cystic kidneys + thunderclap headache = ADPKD with a ruptured berry aneurysm","622",["Robbins ch 20","Robbins ch 11"]],"arpkd":["Fibrocystin (PKHD1)","Mutations in PKHD1 (fibrocystin) cause cystic dilation of the collecting ducts, often seen on prenatal ultrasound. Poor fetal urine output means oligohydramnios.","Infant with huge kidneys and hepatic fibrosis = ARPKD","58, 596, 622",["Robbins ch 20","Robbins ch 10"]],"aortstenosis":["Calcified valve obstructs LV outflow","The LV must generate far more pressure than the aorta to push blood through a narrowed valve, so it hypertrophies concentrically. Flow through the valve is delayed and weakened, and demand outstrips coronary supply.","Old person + syncope on exertion + murmur to the carotids","296",["Robbins ch 12","Guyton ch 23"]],"mitralregurg":["Incompetent AV valve leaks backward during systole","Throughout systole the ventricle pressure exceeds the atrial pressure, so a leaky AV valve regurgitates for the whole of systole — a holosystolic murmur.","New holosystolic murmur days after an MI → papillary muscle rupture","296",["Robbins ch 12","Guyton ch 23"]],"mvp":["Myxomatous leaflets billow into the left atrium","Floppy myxomatous leaflets prolapse into the left atrium during systole. The chordae snap tight as they do — the midsystolic click — and a late regurgitant murmur follows.","Midsystolic click that moves earlier when the patient stands","296",["Robbins ch 12","Guyton ch 23"]],"maneuvers":["Change preload or afterload and watch the murmur","Most murmurs get louder when more blood flows across the valve.","Louder with Valsalva: HCM (and MVP)","295",["Robbins ch 12","Guyton ch 23"]],"hcm":["Thick, stiff septum — diastolic dysfunction and outflow obstruction","Sarcomere mutations cause concentric hypertrophy (sarcomeres added in parallel), usually of the septum, with myofibrillar disarray and fibrosis.","Young athlete collapses on the field","315",["Robbins ch 12","Guyton ch 23"]],"takotsubo":["Catecholamine surge stuns the apex","A catecholamine surge after extreme stress stuns the left ventricle — most often the apex, which balloons outward.","Chest pain after a spouse's death, clean coronaries, ballooned apex","315",["Robbins ch 12"]],"rheumfever":["Antibodies to streptococcal M protein cross-react with cardiac myosin","A nonsuppurative, immune-mediated (type II hypersensitivity) consequence of group A β-hemolytic strep pharyngitis — not a direct effect of bacteria.","Sore throat weeks ago, now migratory arthritis and a new murmur","319",["Robbins ch 12","Robbins ch 8"]],"endocarditis":["Microbes colonize a vegetation of platelets and fibrin on a valve","Endothelial injury lets platelets and fibrin gather on a valve, and circulating microbes seed the clot. The vegetation destroys the valve (regurgitation) and throws off septic emboli — to the body from the left heart, to the lungs from the right.","Don't tri drugs — tricuspid endocarditis in injection drug use","318",["Robbins ch 12","Robbins ch 8"]],"nbte":["Sterile, platelet-rich thrombi on the valves","A hypercoagulable state deposits sterile platelet thrombi on the mitral or aortic valve. They are loosely attached and embolize easily. In SLE this is called Libman-Sacks endocarditis.","Culture-negative vegetations in a patient with pancreatic cancer","318",["Robbins ch 12","Robbins ch 4"]],"myocarditis":["Inflammation of the myocardium","Direct infection or immune injury inflames the heart muscle. A lymphocytic infiltrate with focal necrosis strongly suggests a viral cause.","Young adult with heart failure after a viral illness","320",["Robbins ch 12"]],"cirrhosis":["Stellate cells lay down bridging fibrosis around regenerative nodules","Chronic injury activates hepatic stellate cells, which lay down diffuse bridging fibrosis that traps regenerative nodules and wrecks the lobular architecture.","Caput medusae + spider angiomas + gynecomastia = cirrhosis","244, 372, 396, 397",["Robbins ch 18","Robbins ch 17"]],"ascites":["High sinusoidal pressure pushes fluid into the peritoneum","Portal hypertension raises hepatic sinusoidal pressure and fluid weeps into the peritoneal cavity. The serum-to-ascites albumin gradient tells whether the cause is portal hypertension.","Cirrhotic with ascites and new confusion → tap for SBP","185, 396, 397, 627",["Robbins ch 18","Robbins ch 17"]],"hepenceph":["Ammonia bypasses the liver and reaches the brain","Portosystemic shunting and failing hepatocytes let gut-derived ammonia reach the brain, where astrocytes detoxify it and swell. It is reversible.","Asterixis in a cirrhotic after a GI bleed","399",["Robbins ch 18","Marks ch 36"]],"lfts":["Hepatocellular vs cholestatic vs synthetic markers","Aminotransferases leak from injured hepatocytes; ALP and GGT rise when bile cannot flow; albumin and PT measure what the liver still makes.","AST:ALT over 2 = alcohol","222, 397, 398, 401",["Robbins ch 18","Kaplan & Sadock ch 1"]],"jaundice":["Too much bilirubin made, or too little taken up, conjugated or excreted","Yellow skin and sclera from bilirubin deposition. Common causes: Hemolysis, Obstruction, Tumor, Liver disease. Which fraction rises tells you where the problem is: before conjugation (unconjugated, indirect) or after it (conjugated, direct).","Dark urine + pale stool = conjugated (obstructive) jaundice","400",["Robbins ch 18","Robbins ch 10"]],"cholecystitis":["A stone blocks the cystic duct","Biliary colic: after a fatty meal CCK squeezes the gallbladder and forces a stone into the cystic duct — pain without inflammation. If the stone stays impacted, the wall inflames — calculous cholecystitis.","Murphy sign","403",["Robbins ch 18","Moore ch 5"]],"acutepanc":["Pancreatic enzymes digest the pancreas","Premature activation of pancreatic enzymes digests the gland and surrounding fat. Released fatty acids bind calcium (saponification), and the systemic inflammatory response can injure lungs, kidneys and circulation.","Epigastric pain boring to the back + lipase over 3×","205, 404",["Robbins ch 19","Robbins ch 18"]],"pemphigoid":["IgG against hemidesmosomes at the basement membrane","A type II hypersensitivity against the hemidesmosomes that anchor basal keratinocytes to the basement membrane — the antibodies are \"bullow\" the epidermis.","Elderly patient, tense itchy blisters, mouth spared = bullous pemphigoid","489",["Robbins ch 25"]],"sjs":["Keratinocyte death along the dermal-epidermal junction","A spectrum of immune-mediated keratinocyte death. Erythema multiforme is mostly infection-triggered and limited.","Target lesions after herpes labialis = erythema multiforme","251, 490",["Robbins ch 25"]],"psoriasis":["Keratinocytes proliferate too fast under T-cell signaling","T-cell cytokines (IL-17, IL-23, TNF) drive keratinocytes to divide and climb the epidermis too quickly, so cells reach the surface still carrying nuclei.","Silvery plaques on the elbows + pitted nails","485",["Robbins ch 25","Katzung ch 61"]],"eczema":["IgE-driven (atopic) or type IV (contact) skin inflammation","Atopic dermatitis is a leaky, itchy skin barrier in an atopic person — raised serum IgE, often with asthma, allergic rhinitis and food allergy.","Itchy flexural rash in a child with asthma = atopic dermatitis","485",["Robbins ch 25","Robbins ch 6"]],"acne":["Plugged, inflamed pilosebaceous units","Acne is multifactorial: more sebum (androgens), abnormal shedding of keratinocytes that plugs the follicle (comedones), Cutibacterium acnes colonization, and inflammation.","Comedones = acne; none = rosacea","484, 485",["Katzung ch 61","Robbins ch 25"]],"erythnodosum":["Inflammation of subcutaneous fat (panniculitis)","A panniculitis — the inflammation is in the subcutaneous fat, not in the skin itself.","Tender shin nodules + hilar adenopathy = sarcoidosis","492, 695",["Robbins ch 25","Robbins ch 15"]],"skininfect":["S aureus and S pyogenes at every depth","The name depends on how deep the infection goes: epidermis (impetigo), upper dermis and lymphatics (erysipelas), deep dermis and fat (cellulitis), a walled-off pocket (abscess), fascia (necrotizing fasciitis).","Honey-colored crust = impetigo","487",["Robbins ch 8","Robbins ch 25"]],"vasctumors":["Proliferations of small blood vessels","Mostly benign capillary proliferations, told apart by age, behavior and the inflammatory cells in them.","Bleeding red nodule on the gum of a pregnant woman = pyogenic granuloma","486",["Robbins ch 11"]],"bgcircuit":["Two opposing loops through the striatum","The basal ganglia take cortical input and feed it back to the cortex through the thalamus to scale movement. The thalamus is held under a constant GABA brake by the GPi.","D1 Rect pathway","511",["Fundamental Neuroscience ch 26","Katzung ch 28"]],"hemiballismus":["Loss of the subthalamic nucleus","Without the subthalamic nucleus driving the GPi, the indirect pathway loses its output and the thalamus is released — the opposite side of the body flings wildly.","Half of the body going ballistic","533",["Fundamental Neuroscience ch 26","Guyton ch 57"]],"tremors":["Where the lesion is decides when the tremor shows","A resting tremor comes from the substantia nigra (Parkinson disease) and disappears with movement. An intention tremor comes from the cerebellum and worsens as the hand nears its target.","Tremor that improves with a drink = essential tremor","533",["Katzung ch 28"]],"hyperkinetic":["Involuntary movements from basal ganglia and metabolic disease","Each abnormal movement has its own look and its own list of causes; most come from the basal ganglia, while myoclonus and asterixis often mean a metabolic problem.","Chorea = dancing","533",["Katzung ch 28"]],"psp":["Tau accumulates in the midbrain and basal ganglia","A Parkinson-plus syndrome: parkinsonism plus early loss of vertical gaze and cognitive decline, with midbrain atrophy.","Parkinsonism + vertical gaze palsy + hummingbird sign","534",["Robbins ch 28","Katzung ch 28"]],"lewy":["α-Synuclein Lewy bodies in the cortex","The same α-synuclein inclusions as Parkinson disease, but in the cortex from the start. By convention it is Lewy body dementia if cognitive and motor symptoms begin within a year of each other; otherwise it is dementia secondary to Parkinson disease.","Old man with vivid visual hallucinations, dream enactment and a shuffling gait","535",["Katzung ch 28","Kaplan & Sadock ch 3"]],"nph":["Enlarged ventricles stretch the corona radiata","CSF pressure rises only episodically, but the ventricles enlarge and distort the periventricular fibers of the corona radiata — including those to the legs and bladder.","Wobbly, wacky and wet","536",["Robbins ch 28","Kaplan & Sadock ch 3"]],"dementiarev":["Decline in cognition with intact consciousness","Dementia is a decline in memory or executive function with a clear sensorium — unlike delirium. Before calling it neurodegenerative, rule out the causes that can be reversed.","Always check TSH, B12 and syphilis in new dementia","534",["Kaplan & Sadock ch 3"]],"studydesigns":["Who is compared, and in which direction in time","Observational studies watch rather than intervene. The design sets which measure you can calculate — prevalence, an odds ratio or a relative risk — and whether you can show an association at all.","Starts with disease → case-control → odds ratio","256",[]],"rct":["Randomize, control and blind","An experimental study comparing two or more interventions in people. Quality rises when it is randomized, controlled and double-blinded. Drugs pass through phases before and after approval.","Once randomized, always analyzed","257",[]],"oddsratio":["The 2 × 2 table: exposure (a, b) over no exposure (c, d)","In the 2 × 2 table, rows are exposure (yes: a, b · no: c, d) and columns are disease (yes: a, c · no: b, d).","You take a case to the OR","258, 266",[]],"riskreduction":["Differences in risk, and how many people that means","Ratios say how much more likely; differences say how much more often. The differences turn into the numbers that matter at the bedside.","NNT = 1 / ARR","258",[]],"sensspec":["Fixed properties of the test itself","Sensitivity = TP/(TP + FN): of everyone with the disease, the fraction who test positive. Specificity = TN/(TN + FP): of everyone without it, the fraction who test negative.","SN-N-OUT · SP-P-IN","260",[]],"ppvnpv":["What a result means for this patient","PPV = TP/(TP + FP): the chance that a positive result is true. NPV = TN/(TN + FN): the chance that a negative result is true. Unlike sensitivity and specificity, they change with prevalence (pretest probability).","PPV follows prevalence; NPV moves against it","260",[]],"cutoff":["Trading sensitivity against specificity","Healthy and diseased values overlap, so any cutoff misclassifies someone. Moving it trades one kind of error for the other. The ROC curve plots sensitivity against 1 − specificity for every possible cutoff.","Area under the curve 1.0 = perfect test; 0.5 = coin flip","260",[]],"likelihood":["How much a result shifts the odds","A likelihood ratio says how much more likely a given result is in someone with the disease than in someone without it. Multiply pretest odds by it to get posttest odds.","Odds × LR = new odds","259",[]],"confounding":["A third variable distorts — or genuinely changes — the association","A confounder is linked to both exposure and outcome without being on the causal path; it creates a false association that disappears after stratification (coffee seems to cause lung cancer because coffee drinkers smoke).","Coffee and lung cancer — smoking is the confounder","263",[]],"distribution":["Describing where the data sit and how spread out they are","Mean (most affected by outliers), median (middle value), mode (most common, least affected by outliers). Standard deviation describes the spread of values; standard error describes how precisely the sample mean estimates the population mean: SE = SD/√n.","The mean follows the tail","264",[]],"typeerrors":["The two ways a hypothesis test can be wrong","05, and H0 is rejected when p < α. Type II error (β): failing to reject a false null — a false negative. Power = 1 − β: the chance of finding an effect that really exists.","1st time the boy cries wolf: type I (false alarm) · 2nd time: type II (missed wolf)","265",[]],"ci":["The range expected to hold the true value","A confidence interval is the range within which the true population value is expected to fall with a given probability: CI = 1 − α. 58 for 99%).","Ratio CI crosses 1 = not significant","266",[]],"bioavail":["Fraction of a dose that reaches the systemic circulation","Bioavailability (F) is the fraction of an administered dose that reaches the systemic circulation unchanged. IV dosing is 100% by definition.","Oral dose much bigger than IV dose → big first-pass effect","229",["Katzung ch 3"]],"vd":["Amount of drug in the body ÷ plasma concentration","A theoretical volume that relates how much drug is in the body to how much is in the plasma. Drugs that stay in the blood have a small Vd; drugs that leave it for tissues and fat have a huge one.","High Vd drug in overdose → dialysis will not help","229",["Katzung ch 3"]],"clearance":["How fast the body removes the drug","Clearance is the volume of plasma cleared of drug per unit time: CL = rate of elimination ÷ plasma concentration = Vd × Ke. 7 × Vd ÷ CL. Steady state is reached when elimination equals administration.","Steady state in 4–5 half-lives, whatever the dose","229",["Katzung ch 3"]],"urineph":["Ionized drug cannot cross back out of the urine","Only the nonionized form crosses membranes, so ionized drug in the tubule is trapped and excreted. Weak acids ionize in alkaline urine; weak bases ionize in acidic urine.","Aspirin overdose → alkalinize the urine","231",["Katzung ch 1"]],"antagonists":["What an antagonist does to the agonist's curve","The shape change in the dose-response curve tells you the type of antagonist.","Buprenorphine can precipitate withdrawal in someone on full opioids","233",["Katzung ch 2"]],"ti":["TD50 ÷ ED50","A measure of drug safety: the median toxic dose divided by the median effective dose (TITE: Therapeutic Index = TD50 / ED50). A higher index is safer.","TITE: therapeutic index = TD50 / ED50","233",["Katzung ch 1","Katzung ch 2"]],"druginteract":["","How two substances combine, from 2 + 2 = 4 to 2 + 2 < 4.","Carbidopa + levodopa = potentiation","234",["Katzung ch 2","Kaplan & Sadock ch 21"]],"localanes":["Voltage-gated Na⁺ channels, blocked from inside the axon","Local anesthetics are tertiary amines. The uncharged form crosses the axonal membrane; once inside, the charged form binds the inner portion of the voltage-gated Na⁺ channel and blocks conduction.","Amides have 2 i's","565, 688",["Katzung ch 26"]],"musclerelax":["Central (spinal cord or brainstem) or direct on muscle","Each works at a different level: baclofen on spinal GABA-B receptors, tizanidine as a central α₂ agonist, cyclobenzaprine in the brainstem, and dantrolene directly on the muscle (ryanodine receptor).","Baclofen acts on the back","567",["Katzung ch 27"]],"pfts":["Can air get out, or can air get in?","Obstructive disease closes airways early at high lung volumes, trapping air: FEV₁ falls more than FVC, so FEV₁/FVC drops below 70%, and RV, FRC and TLC rise.","Low ratio = obstruction; normal ratio with low TLC = restriction","692",["Costanzo ch 5","Robbins ch 15"]],"bronchiectasis":["Permanently dilated, inflamed bronchi","An infection on top of obstruction or poor mucus clearance sets off a dysregulated host response; the chronic bronchial inflammation leaves the airways permanently dilated and full of pus.","Cups of foul sputum every day + dilated airways on CT","693",["Robbins ch 15"]],"sarcoid":["Noncaseating granulomas in many organs","An immune-mediated disease that seeds noncaseating granulomas everywhere, especially the lungs and hilar nodes. Granuloma macrophages carry 1α-hydroxylase, so they activate vitamin D and raise calcium.","Young Black woman + bilateral hilar adenopathy + erythema nodosum","695",["Robbins ch 15"]],"hp":["Mixed type III/IV reaction to inhaled organic antigens","Repeated inhalation of organic antigens — thermophilic Actinomyces, Aspergillus, bird proteins — triggers a mixed immune-complex and T-cell reaction in the alveoli.","Farmer with fever and dyspnea after handling moldy hay","694",["Robbins ch 15"]],"sleepapnea":["Breathing stops for over 10 seconds during sleep","Repeated apneas fragment sleep and cause nocturnal hypoxia. Obstructive: effort continues against a closed airway. Central: the drive to breathe fails.","Obese snorer who falls asleep at red lights","697",["Kaplan & Sadock ch 15","Guyton ch 42"]],"atelectasis":["Collapse of alveoli","Four ways to collapse alveoli: obstructive (a blocked airway — foreign body, mucus plug, tumor — lets the trapped air resorb), compressive (a pleural effusion or mass squeezes the lung), contraction (scarring distorts alveoli, eg, sarcoidosis), adhesive (no…","Dull base with the trachea pulled toward it = atelectasis","698, 699",["Robbins ch 15"]],"effusion":["Fluid between the pleural layers","Fluid collects when hydrostatic pressure rises or oncotic pressure falls (transudate), or when vessels become leaky from inflammation or tumor (exudate).","Protein ratio over 0.5 or LDH ratio over 0.6 = exudate","699",["Robbins ch 15","Robbins ch 4"]],"pneumothorax":["Air in the pleural space","Air entering the pleural space collapses the lung. In a tension pneumothorax air enters but cannot leave; rising pressure shoves the mediastinum aside, kinks the IVC and cuts venous return — obstructive shock.","Tall thin young smoker with sudden chest pain","700",["Robbins ch 15","Moore ch 4"]],"pneumonia":["Where the infection sits in the lung","The pattern on the chest film points to the organism.","Alcoholic who aspirates → right lower lobe abscess","698, 701",["Robbins ch 15","Robbins ch 8"]],"clubbing":["Megakaryocytes lodge in the fingertips and release growth factors","The angle between the nail bed and nail plate exceeds 180°. One idea: with an intrapulmonary shunt, platelets and megakaryocytes bypass the lung filter, lodge in the digital vessels and release PDGF and VEGF.","New clubbing in a smoker → lung cancer until proven otherwise","698",["Robbins ch 15","Robbins ch 7"]],"schizo":["Mesolimbic dopamine excess · mesocortical deficit","A chronic psychotic illness. Too much dopamine in the mesolimbic pathway is thought to drive the positive symptoms, and too little in the mesocortical pathway the negative and cognitive ones — which is why D₂ blockade helps hallucinations far more than apathy.","Voices commenting on a young man's actions for 8 months","577",["Kaplan & Sadock ch 5","Katzung ch 29"]],"briefpsych":["Same symptoms as schizophrenia, shorter course","The psychotic disorders are told apart by how long the symptoms last. The same picture is called brief psychotic disorder under a month, schizophreniform disorder from 1 to 6 months, and schizophrenia after 6 months.","Psychosis for 2 weeks after a car crash, then back to normal = brief psychotic disorder","577",["Kaplan & Sadock ch 5"]],"schizoaffective":["Psychosis that outlasts the mood episodes","Mood episodes and schizophrenia-type psychosis in the same illness. The deciding feature is psychosis on its own — 2 weeks or more with no mood episode.","Hallucinations that continue for weeks after the depression lifts","576",["Kaplan & Sadock ch 5","Katzung ch 29"]],"delusional":["A single fixed false belief","One or more delusions for 1 month or more without the other features of schizophrenia. Outside the delusion the person functions and behaves normally.","Convinced the neighbour is poisoning her water, otherwise holds her job","577",["Kaplan & Sadock ch 5"]],"delirium":["Acute global brain dysfunction from a medical cause","An acute, fluctuating disturbance of attention and awareness caused by an illness, drug or withdrawal.","Confused at night after surgery, clear in the morning","575",["Kaplan & Sadock ch 3","Kaplan & Sadock ch 1"]],"mdd":["Monoamine and stress-axis dysregulation","Episodes of low mood or loss of interest that last at least 2 weeks and impair function. The monoamine theory explains why serotonin and norepinephrine drugs help, but the weeks they take reflect slower receptor and neuroplastic change.","SIG E CAPS for 2 weeks","578",["Kaplan & Sadock ch 7","Kaplan & Sadock ch 15"]],"dysthymia":["Chronic low-grade depression","Depressed mood on most days for 2 years or more (1 year in children) with at least two other depressive symptoms, never free of them for more than 2 months.","'I have been down for as long as I can remember' — 3 years, never well","578",["Kaplan & Sadock ch 7"]],"peripartum":["Mood change in pregnancy or after delivery","Three disorders of increasing severity and decreasing frequency follow delivery. Telling them apart by timing, function and psychosis decides between reassurance and admission.","Day 3 tears that pass = blues","579",["Kaplan & Sadock ch 7","Katzung ch 30"]],"bipolar":["Episodes of mania or hypomania","A mood disorder defined by elevated episodes. One manic episode makes it bipolar I; hypomania plus a major depressive episode, with no mania ever, makes it bipolar II.","Four days without sleep, new business plans, spending spree","578",["Kaplan & Sadock ch 6","Kaplan & Sadock ch 21"]],"suicide":["Risk factors for death by suicide","Assess every patient with a mood disorder for suicide risk. A previous attempt is the strongest single predictor; women attempt more often, men die more often, and in the US firearms are the commonest method.","Older man, widowed, drinking, with a gun at home","579",["Kaplan & Sadock ch 1","Kaplan & Sadock ch 7"]],"ect":["A controlled generalized seizure under anesthesia","A brief tonic-clonic seizure induced under general anesthesia and neuromuscular blockade. It works faster than antidepressants and is the most effective treatment for severe depression.","Catatonic patient refusing food and water","579",["Kaplan & Sadock ch 22","Kaplan & Sadock ch 21"]],"panic":["Recurrent surges of sympathetic fear","Recurrent unexpected panic attacks followed by a month or more of fear of the next attack or avoidance. The attacks are the body's alarm response firing without danger.","Young woman in the ED convinced she is having a heart attack, normal ECG","580",["Kaplan & Sadock ch 8","Kaplan & Sadock ch 21"]],"gad":["Excessive worry about many things","Uncontrollable worry about everyday matters — work, health, family — on most days for 6 months or more, out of proportion to any real threat.","Worries about everything, tense, sleeps badly, for a year","580",["Kaplan & Sadock ch 8","Kaplan & Sadock ch 21"]],"phobia":["Fear triggered by one object or situation","Marked fear of a particular object or situation lasting 6 months or more, which the person usually recognizes as excessive and avoids.","Avoids a promotion that needs presentations","580",["Kaplan & Sadock ch 8","Kaplan & Sadock ch 23"]],"ocd":["Cortico-striato-thalamic circuit","Obsessions are intrusive, unwanted thoughts that cause distress; compulsions are repetitive acts done to neutralize them. The patient knows the thoughts are their own and unwanted (ego-dystonic), unlike obsessive-compulsive personality disorder.","Hands raw from washing 40 times a day","580",["Kaplan & Sadock ch 9","Kaplan & Sadock ch 2"]],"ptsd":["Fear memory that will not extinguish","After a life-threatening trauma, the fear response stays switched on. The same symptoms are called acute stress disorder for 3 days to 1 month and PTSD when they last more than 1 month.","Veteran with nightmares and startle months after deployment","581",["Kaplan & Sadock ch 10"]],"adjustment":["Distress out of proportion to a stressor","Emotional or behavioral symptoms that begin within 3 months of an identifiable stressor — divorce, job loss, illness — and fade within 6 months of the stressor ending, without meeting criteria for another disorder.","Sad and not sleeping since the divorce 6 weeks ago, not meeting MDD criteria","581",["Kaplan & Sadock ch 10"]],"clustera":["Odd, eccentric — 'weird'","A personality disorder is an inflexible, pervasive pattern of thinking and behaving that starts by early adulthood, causes distress or impairment, and that the person usually sees as normal (ego-syntonic).","Loner engineer who has no wish for friends = schizoid","582",["Kaplan & Sadock ch 19"]],"antisocial":["Disregard for others' rights","A Cluster B disorder of persistent disregard for and violation of the rights of others, without remorse. It can only be diagnosed at 18 or older, and needs evidence of conduct disorder before age 15.","Charming man with a long criminal record who feels no guilt","574",["Kaplan & Sadock ch 19"]],"borderline":["Unstable mood, identity and relationships","A Cluster B disorder of instability in relationships, self-image and mood, with marked impulsivity. Splitting — seeing people as all good or all bad — is its signature defense.","'The nurses are cruel but you, doctor, are wonderful'","582",["Kaplan & Sadock ch 19","Kaplan & Sadock ch 23"]],"clusterb":["Dramatic, emotional, erratic — 'wild'","Cluster B holds antisocial, borderline, histrionic and narcissistic personality disorder. All four are dramatic and erratic; the last two are told apart by what the patient needs from others.","Demands to see only the department chief = narcissistic","582",["Kaplan & Sadock ch 19"]],"clusterc":["Anxious, fearful — 'worried'","Cluster C patients are anxious and fearful. Obsessive-compulsive personality disorder is ego-syntonic — the patient thinks the rules are right — unlike obsessive-compulsive disorder, where the thoughts are unwanted.","Longs for friends but will not join without a guarantee of being liked = avoidant","582",["Kaplan & Sadock ch 19"]],"malingering":["Intentional symptoms · external gain","Not a mental illness. The patient consciously fakes or exaggerates symptoms for a concrete outside reward — money, time off work, drugs, avoiding prosecution.","Back pain that started the day the lawsuit was filed","583",["Kaplan & Sadock ch 12"]],"factitious":["Intentional symptoms · unconscious need for the sick role","The patient deliberately produces or fakes illness, but the drive is internal — to be cared for as a patient (primary gain), not for money or escape.","Nurse with recurrent hypoglycemia and low C-peptide","583",["Kaplan & Sadock ch 12","Kaplan & Sadock ch 9"]],"somaticsx":["Unconscious symptoms · unconscious motivation","The symptoms are not faked. In somatic symptom disorder real bodily symptoms come with excessive, persistent worry and time spent on them; in illness anxiety disorder there are few symptoms but a fixed fear of having a serious disease.","Sure her headaches are a tumor after three normal MRIs = illness anxiety","583",["Kaplan & Sadock ch 12"]],"conversion":["Neurologic loss with no neurologic lesion","Loss of motor or sensory function that does not fit any neurologic disease, often after an acute stressor. The patient is not faking.","Sudden leg paralysis the day after witnessing an accident, calm about it","583",["Kaplan & Sadock ch 12"]],"dissociative":["Splitting off of memory, identity or perception","Dissociation disconnects memory, identity, emotion or perception from awareness — a defense against overwhelming trauma. Reality testing stays intact, which separates these from psychosis.","Found in another city with no memory of who she is = fugue","575",["Kaplan & Sadock ch 11"]],"anorexia":["Starvation → ↓ leptin → ↓ GnRH","Restriction driven by fear of weight gain and a distorted body image leaves body weight dangerously low. Starvation lowers leptin, which switches off GnRH — hence amenorrhea and bone loss.","Thin teenage athlete with fine body hair and no periods","584",["Kaplan & Sadock ch 13"]],"refeeding":["Insulin surge drives phosphate, K⁺ and Mg²⁺ into cells","When a starved patient eats, insulin rises and pushes phosphate, potassium and magnesium into cells to make ATP and glycogen. Body stores are already depleted, so serum levels crash.","Confused and weak on day 3 of feeding a patient with anorexia","584, 609",["Robbins ch 9","Marks ch 3"]],"bulimia":["Binge then purge","Recurrent binges with compensatory purging — vomiting, laxatives, diuretics, fasting, exercise — at least weekly for 3 months. Weight is usually normal or slightly high, unlike anorexia.","Normal-weight student with swollen cheeks and knuckle calluses","584",["Kaplan & Sadock ch 13"]],"bingeeat":["Binges without purging","Recurrent episodes of eating large amounts with loss of control, at least weekly for 3 months, with distress but no compensatory purging. It raises the risk of obesity and type 2 diabetes.","Eats a whole cake alone at night, never vomits","584, 590",["Kaplan & Sadock ch 13"]],"pica":["Eating non-food substances","Persistent eating of non-food items for 1 month or more when this is not developmentally or culturally normal. Craving ice (pagophagia) or dirt (geophagia) is a classic clue to iron deficiency.","Pregnant woman crunching ice all day","424, 584",["Kaplan & Sadock ch 2","Robbins ch 14"]],"sexdys":["Desire · arousal · orgasm · pain","Problems with desire, arousal, orgasm or pain during sex. The first question is whether the cause is psychological or organic — preserved nighttime or morning erections point to a psychological cause.","Morning erections intact → performance anxiety","584",["Kaplan & Sadock ch 16"]],"genderdys":["Distress from incongruent gender identity","Marked incongruence between gender identity and gender assigned at birth, lasting more than 6 months and causing distress or impaired function.","The diagnosis requires distress, not nonconformity","584",["Kaplan & Sadock ch 17"]],"alcohol":["GABA-A positive modulator · NMDA inhibitor","Ethanol enhances GABA-A chloride currents and blunts NMDA glutamate excitation, so the brain slows. Chronic use downregulates GABA-A and upregulates NMDA receptors — the setup for withdrawal when drinking stops.","AST:ALT over 2 — 'make a toAST to alcohol'","588, 590",["Kaplan & Sadock ch 4","Katzung ch 23"]],"nicotine":["Nicotinic ACh receptor agonist (α4β2 in the VTA)","Nicotine stimulates nicotinic receptors on VTA dopamine neurons and releases dopamine in the nucleus accumbens. Its withdrawal is mild, but it is among the most addictive drugs and relapse is common.","Gains weight after quitting","589, 594",["Kaplan & Sadock ch 4","Katzung ch 32"]],"caffeine":["Adenosine receptor antagonist","Adenosine builds up while awake and promotes sleep through A₂A receptors. Caffeine blocks adenosine receptors, so it promotes wakefulness; it also blunts the effect of adenosine given for SVT.","Weekend headache in a heavy weekday coffee drinker","589",["Kaplan & Sadock ch 4","Katzung ch 20"]],"mdma":["Reverses SERT (more than DAT and NET)","MDMA reverses the serotonin transporter, dumping serotonin (and some dopamine and norepinephrine) into the synapse. It is a stimulant with hallucinogenic features, used at dance parties.","Seizure at a dance party with a sodium of 120","589",["Katzung ch 32","Kaplan & Sadock ch 4"]],"cannabis":["CB₁ receptor agonist (Gi)","THC activates presynaptic CB₁ receptors, which inhibit GABA release onto VTA dopamine neurons — disinhibition, like opioids. Endocannabinoids (anandamide, 2-AG) are retrograde messengers at the same receptors.","Red eyes, munchies, time slows","589",["Katzung ch 32","Kaplan & Sadock ch 4"]],"sud":["Drug-driven plasticity in the mesolimbic reward pathway","Every addictive drug raises dopamine in the nucleus accumbens, by stimulating VTA neurons (nicotine), blocking or reversing transporters (cocaine, amphetamines) or disinhibiting them (opioids, cannabis, benzodiazepines).","Tolerance alone is not addiction","585",["Kaplan & Sadock ch 4","Katzung ch 32"]],"stageschange":["Matching the talk to the patient's readiness","Patients move through predictable stages when changing a habit. The right intervention depends on the stage — pushing a plan on someone who does not yet see a problem backfires.","'I know I drink too much but it helps me relax' = contemplation","586",["Kaplan & Sadock ch 1","Kaplan & Sadock ch 4"]],"sleepstages":["Suprachiasmatic nucleus · pineal melatonin","Sleep runs in 4–6 cycles of about 90 minutes. Each cycle descends through NREM stages to slow-wave sleep and then enters REM; REM periods lengthen toward morning.","Delta = deepest · spindles = N2","507",["Kaplan & Sadock ch 15","Guyton ch 60"]],"narcolepsy":["Loss of orexin (hypocretin) neurons in the lateral hypothalamus","Orexin holds wakefulness steady. Without it, sleep and REM intrude into waking: the patient falls asleep suddenly and drops straight into REM.","Collapses when laughing at a joke, awake throughout","585",["Kaplan & Sadock ch 15","Katzung ch 22"]],"parasomnias":["Partial arousal from N3, or REM gone wrong","Abnormal behaviors at sleep-stage boundaries. Arousal disorders erupt from slow-wave (N3) sleep and leave no memory; nightmares arise in REM and are remembered.","Child screams at 11 pm and remembers nothing = night terror","507",["Kaplan & Sadock ch 15"]],"rbd":["Loss of REM atonia","The brainstem circuit that paralyzes muscles during REM fails, so the patient acts out dreams, often violently. It often precedes a synucleinopathy by years.","Older man punches his wife while dreaming of a fight","507",["Kaplan & Sadock ch 15"]],"insomnia":["Hyperarousal · GABA-A, orexin and melatonin drug targets","Difficulty falling or staying asleep with daytime impairment. Behavioral treatment works best long term; each hypnotic class hits a different sleep switch.","First line is sleep hygiene and CBT, not a pill","562",["Kaplan & Sadock ch 15","Katzung ch 22"]],"circadian":["Body clock out of step with the day","The suprachiasmatic nucleus sets a roughly 24-hour clock that light resets each morning. When the clock and the required schedule disagree, sleep comes at the wrong time.","Cannot sleep before 3 am but sleeps well until noon","507, 508",["Kaplan & Sadock ch 15"]],"milestones":["Motor · social · language · cognitive","Milestones are ranges, not dates. A child who misses several, or loses skills already gained, needs assessment for developmental delay.","'Mama' and 'dada' by 10 months","572",["Kaplan & Sadock ch 2"]],"adhd":["Prefrontal catecholamine signaling","Inattention, hyperactivity and impulsivity, present before age 12 and in two or more settings — home and school, for instance. Intelligence is normal; it often persists into adulthood.","Cannot sit still at school or at home, loses everything","574",["Kaplan & Sadock ch 2"]],"autism":["Early-onset social communication disorder","Deficits in social communication plus restricted, repetitive behaviors and interests, beginning in early childhood. Rett syndrome is a separate X-linked disorder in girls with normal early development followed by regression.","Lines toys in rows, no pretend play, few words at 3","60, 574",["Kaplan & Sadock ch 2","Robbins ch 5"]],"conductodd":["Disruptive behavior in childhood","Three childhood patterns of anger and rule-breaking, told apart by whom they target and whether mood is persistently irritable.","Argues with teachers but not peers = ODD","574",["Kaplan & Sadock ch 2"]],"tourette":["Basal ganglia–cortical circuits","Sudden, rapid, recurrent, nonrhythmic motor and vocal tics. Tourette syndrome needs both motor and vocal tics for more than a year, starting before age 18.","Boy with blinking, throat clearing and handwashing rituals","574",["Kaplan & Sadock ch 2","Katzung ch 28"]],"intellectual":["Global vs single-domain cognitive deficit","Intellectual disability is a global deficit in reasoning and learning with impaired adaptive function. A specific learning disorder affects one academic skill with normal general intelligence.","Bright child who cannot learn to read = dyslexia","574",["Kaplan & Sadock ch 2"]],"separation":["Childhood anxiety disorders","Separation anxiety is normal in toddlers. It becomes a disorder when fear of separation from an attachment figure is excessive for the child's age and lasts 4 weeks or more; selective mutism is anxiety that silences a child in some settings.","Stomach aches every school morning, fine on weekends","574, 581",["Kaplan & Sadock ch 2"]],"enuresis":["Bedwetting arises from N3 sleep","Repeated voiding or soiling in a child old enough to be continent. Bedwetting is commonest and usually outgrown.","7-year-old wets the bed but is dry by day","585",["Kaplan & Sadock ch 14"]],"childabuse":["Report every suspicion","Every suspected case must be reported to child protective services — the physician does not need proof. Neglect is the commonest form of maltreatment.","Infant with retinal hemorrhages and a vague story of a fall from the couch","273, 573",["Kaplan & Sadock ch 2","Kaplan & Sadock ch 1"]],"egodefenses":["Unconscious ways to reduce anxiety","Defenses are mostly unconscious ways to manage conflict and painful feelings. Mature ones are healthy; immature ones distort reality or behavior.","Angry at the boss, yells at the dog = displacement","570, 571",["Kaplan & Sadock ch 19","Kaplan & Sadock ch 23"]],"conditioning":["Learning by association or consequence","In classical conditioning a neutral stimulus paired with one that naturally evokes a response comes to evoke it alone (Pavlov's bell). In operant conditioning a voluntary behavior is shaped by what follows it.","Seatbelt chime stops when you buckle up = negative reinforcement","570, 590",["Kaplan & Sadock ch 23"]],"grief":["A normal response to loss","Grief is not a disorder. It includes guilt, sadness, yearning, somatic symptoms and even brief hallucinations of the deceased, and it follows no fixed stages.","Hears her late husband's voice at night, 3 weeks after the funeral — normal grief","572",["Kaplan & Sadock ch 29"]],"conjunctivitis":["Inflamed conjunctiva","Inflammation of the conjunctiva makes the eye red without pain or loss of vision. The discharge and the timing after birth point to the cause.","Red, watery eye after a cold with a preauricular node = adenovirus","549",["Robbins ch 8","Robbins ch 29"]],"refractive":["Cornea and lens fail to focus light on the retina","The cornea and lens bend light onto the retina. If the eye is the wrong length, or the cornea is unevenly curved, the image focuses in front of or behind it.","45-year-old holding the menu at arm's length = presbyopia","549",["Guyton ch 50","Pawlina ch 24"]],"cataract":["Opacified or displaced lens","A cataract is a cloudy lens — painless, gradual, often bilateral loss of vision with glare. The lens hangs from zonular fibers that weaken in some connective tissue and metabolic diseases.","Infant with cataracts and vomiting after milk = galactosemia","550",["Robbins ch 29","Robbins ch 5"]],"glaucoma":["Aqueous outflow blocked → optic neuropathy","Aqueous humor made by the ciliary body drains through the trabecular meshwork and canal of Schlemm. Raised pressure (usually) slowly kills optic nerve fibers, cupping the disc and taking vision from the periphery inward.","Halos, eye pain and vomiting after entering a dark cinema","550, 551, 568",["Katzung ch 10","Pawlina ch 24"]],"uveitis":["Inflamed iris, ciliary body or choroid","Inflammation of the uvea — iris, ciliary body and choroid. Anterior uveitis (iritis) causes a painful red eye with photophobia; posterior uveitis affects the choroid and retina.","Young man with back stiffness and a painful red eye = ankylosing spondylitis","475, 549, 553",["Robbins ch 29","Robbins ch 26"]],"amd":["Macular degeneration · choroidal neovascularization","Degeneration of the macula takes central vision while peripheral vision remains. In the wet form, new choroidal vessels leak and bleed under the retina.","Older patient whose door frames look wavy","552, 557",["Robbins ch 29","Katzung ch 55"]],"retinopathy":["Damaged retinal microvessels","Chronic hyperglycemia makes retinal vessels leak and close; the ischemic retina then releases VEGF and grows fragile new vessels. Chronic hypertension thickens and narrows the arterioles.","AV nicking and a macular star in a patient with BP 220/130","552",["Robbins ch 29","Robbins ch 24"]],"retinalocc":["Blocked inflow or outflow of the retina","An embolus (usually from a carotid plaque) blocks the central retinal artery, and the retina whitens except at the fovea. Thrombosis of the retinal vein backs blood up into the retina.","Curtain of blindness then a cherry-red spot = central retinal artery occlusion","552",["Robbins ch 29","Moore ch 9"]],"retinaldetach":["Neurosensory retina pulled off the pigment epithelium","When the neurosensory retina separates from the pigment epithelium it loses its choroidal blood supply, and photoreceptors die unless it is reattached quickly.","Flashes, floaters, then a curtain in a myopic man","552",["Robbins ch 29","Pawlina ch 24"]],"retinitispig":["Inherited photoreceptor degeneration","Photoreceptors and the retinal pigment epithelium degenerate. Night vision and the periphery go first.","Young man who cannot see at dusk, with bone-spicule pigment","552",["Robbins ch 29","Pawlina ch 24"]],"papilledema":["Raised ICP blocks axoplasmic flow in the optic nerve","Raised intracranial pressure is transmitted along the optic nerve sheath and stalls axoplasmic flow, so the optic discs swell — usually both.","Headache worse lying down with bilateral swollen discs","536, 553",["Robbins ch 28","Robbins ch 29"]],"opticneuritis":["Demyelinated optic nerve","Inflammatory demyelination of the optic nerve, often the first sign of multiple sclerosis. Signals from that eye travel slowly and weakly.","Young woman with a painful, blurred eye and an RAPD","190, 250, 537",["Fundamental Neuroscience ch 20","Robbins ch 28"]],"rapd":["Asymmetric afferent limb (retina or optic nerve)","Light in either eye normally constricts both pupils. If one optic nerve or retina carries a weaker signal, swinging the light from the good eye to the bad one makes both pupils dilate.","Swinging flashlight — both dilate on the bad side","554",["Fundamental Neuroscience ch 28","Fundamental Neuroscience ch 33"]],"lightnear":["Dorsal midbrain (pretectal) damage","The light reflex runs through the pretectal nuclei of the dorsal midbrain; the near (accommodation) response takes a more ventral route. Damage near the pretectum spares the near response — light-near dissociation.","Accommodates but does not react = Argyll Robertson","145, 542",["Fundamental Neuroscience ch 28","Guyton ch 52"]],"cn46palsy":["Superior oblique (IV) · lateral rectus (VI)","Each extraocular muscle has one nerve: LR₆ SO₄ R₃ — lateral rectus by VI, superior oblique by IV, the rest by III. A weak muscle shows as double vision in the direction it should pull.","Tilts head to the left to stop double vision = right CN IV","519, 555, 556, 557",["Fundamental Neuroscience ch 28","Moore ch 9"]],"ino":["Medial longitudinal fasciculus","The MLF links the CN VI nucleus to the opposite CN III nucleus so both eyes turn together. When it is cut, the eye on the side of the lesion cannot adduct on lateral gaze, and the abducting eye shows nystagmus.","INO = Ipsilateral adduction failure, Nystagmus Opposite","558",["Fundamental Neuroscience ch 14","Fundamental Neuroscience ch 28"]],"cavernous":["CN III, IV, V1, V2, VI and sympathetics in one sinus","The cavernous sinus beside the pituitary carries the internal carotid, CNs III, IV, V1, V2 and VI and the sympathetic fibers to the eye. One lesion there hits several nerves at once.","Proptosis, fever and ophthalmoplegia after a squeezed nose pimple","557",["Moore ch 9","Robbins ch 28"]],"strabismus":["Misaligned eyes · undeveloped visual cortex","When the eyes are misaligned early in life, the brain suppresses one eye's blurred or double image, and that eye's visual cortex fails to develop — amblyopia.","Child with an inward-turning eye and poor acuity on that side","553, 555",["Guyton ch 52","Fundamental Neuroscience ch 28"]],"blowout":["Inferior rectus and fat trapped in the maxillary sinus","A blow to the globe raises orbital pressure and fractures the thin floor into the maxillary sinus, trapping the inferior rectus and orbital fat.","Hit by a baseball, cannot look up, numb cheek","555",["Moore ch 9"]],"vfdefects":["Where along the visual pathway","Nasal retinal fibers (temporal fields) cross at the chiasm. So lesions in front of the chiasm affect one eye, at the chiasm both temporal fields, and behind it the same half-field of both eyes.","Bumps into door frames on both sides = bitemporal hemianopia from a pituitary tumor","557",["Fundamental Neuroscience ch 20"]],"migraine":["Trigeminovascular activation · CGRP and substance P","Activation of trigeminal afferents to meningeal vessels releases vasoactive neuropeptides — CGRP and substance P — causing neurogenic inflammation and throbbing pain.","Throbbing one-sided headache with zigzag lights beforehand","532",["Katzung ch 16","Kaplan & Sadock ch 21"]],"clusterha":["Periorbital pain with autonomic signs","Excruciating one-sided periorbital pain with autonomic signs on the same side, in repetitive attacks.","Man woken nightly by stabbing eye pain with a running nose","532",["Katzung ch 16"]],"trigeminal":["CN V root compressed by a vascular loop","Most cases come from an aberrant artery pressing on the trigeminal root, demyelinating it so that touch fires pain fibers.","Shooting cheek pain when shaving","532",["Moore ch 9","Fundamental Neuroscience ch 14"]],"iih":["Raised ICP with normal imaging","Raised intracranial pressure without a mass or hydrocephalus, associated with dural venous sinus stenosis. Swollen optic discs threaten vision.","Obese young woman on minocycline for acne with headache and papilledema","536",["Fundamental Neuroscience ch 6","Robbins ch 28"]],"otitisext":["Infected external auditory canal","Infection of the external canal, most often by Pseudomonas. In older patients with diabetes it can invade bone — malignant (necrotizing) otitis externa.","Swimmer with pain on tugging the ear","547",["Robbins ch 8","Robbins ch 16"]],"otitismedia":["Infected middle ear behind a blocked eustachian tube","Eustachian tube dysfunction traps fluid in the middle ear, and nasopharyngeal colonizers overgrow. The middle ear is continuous with the mastoid air cells, so infection can spread there.","Toddler tugging the ear with fever and a bulging drum","547",["Robbins ch 16","Robbins ch 8"]],"cholesteatoma":["Keratinizing squamous epithelium in the middle ear","'Skin in the wrong place': keratinized squamous epithelium grows into the middle ear through a retraction pocket or perforation, accumulates keratin and erodes bone.","Chronic painless foul discharge after years of ear infections","548",["Robbins ch 16","Pawlina ch 25"]],"otosclerosis":["Stapes footplate fixed in the oval window","Abnormal bone remodeling around the oval window first fibroses and then ossifies the stapes footplate in place, so sound cannot be passed to the inner ear.","Young adult with gradual conductive loss, mother had the same","548",["Fundamental Neuroscience ch 21","Robbins ch 16"]],"hearingloss":["Outer and middle ear vs cochlea and CN VIII","Conductive loss blocks sound before the cochlea (wax, fluid, perforation, ossicles); sensorineural loss damages hair cells or the auditory nerve.","Weber to the bad ear = conductive","547, 548",["Fundamental Neuroscience ch 21","Guyton ch 53"]],"ototox":["Cochlear hair cells","Several drugs damage cochlear hair cells, causing sensorineural hearing loss and tinnitus. Combinations add up — aminoglycosides are especially toxic with loop diuretics.","Gentamicin plus furosemide in the ICU, then hearing loss","186, 250, 445, 548, 626",["Katzung ch 45","Katzung ch 15"]],"vertigo":["Inner ear vs brainstem and cerebellum","Vertigo is a false sense of spinning. Peripheral causes in the inner ear are commoner; central causes in the brainstem or cerebellum (stroke, MS, posterior fossa tumor) must not be missed.","Vertigo with diplopia and ataxia = posterior circulation stroke until proven otherwise","548",["Fundamental Neuroscience ch 22","Fundamental Neuroscience ch 28"]],"bppv":["Otoconia loose in a semicircular canal","Debris (otoconia) drifts into a semicircular canal and moves with gravity, so head turns produce brief bursts of vertigo.","Spins for 30 seconds every time she rolls over in bed","548",["Fundamental Neuroscience ch 22","Pawlina ch 25"]],"meniere":["Excess endolymph in the inner ear","Too much endolymph distends the membranous labyrinth, disturbing both the cochlea and the vestibular organs.","'Men wear vests' — vertigo, tinnitus, hearing loss","548",["Fundamental Neuroscience ch 22","Pawlina ch 25"]],"vestneuritis":["Inflamed vestibular nerve or labyrinth","Inflammation of the vestibular nerve causes severe continuous vertigo without hearing loss. When the whole labyrinth is inflamed (labyrinthitis, otitis interna), hearing is lost too.","Days of nonstop spinning and vomiting, hearing intact = vestibular neuritis","166, 548",["Fundamental Neuroscience ch 21","Fundamental Neuroscience ch 22"]],"sinusitis":["Blocked sinus ostia","When sinus drainage into the nose is blocked, secretions collect and become inflamed. The maxillary sinus is affected most — its ostium sits high, so it drains against gravity.","Maxillary pain worse bending forward after a cold","690",["Moore ch 9","Robbins ch 16"]],"epistaxis":["Kiesselbach plexus · sphenopalatine artery","Most nosebleeds come from Kiesselbach plexus on the anterior septum, where several arteries anastomose. Dangerous bleeds are posterior, from the sphenopalatine artery.","Teen boy with recurrent heavy nosebleeds and one blocked nostril = angiofibroma","690",["Moore ch 9","Robbins ch 16"]],"pharyngitis":["Viral far more often than bacterial","Most sore throats are viral (rhinovirus, adenovirus, influenza, RSV). Group A streptococcus is the main bacterial cause and the one worth treating, because of rheumatic fever.","Sandpaper rash and strawberry tongue after a sore throat = scarlet fever","134, 136, 162",["Robbins ch 8","Robbins ch 16"]],"epiglottitis":["Swollen epiglottis obstructing the airway","Infection swells the epiglottis and can suddenly close the airway. H influenzae type b was the classic cause; it still occurs, even in vaccinated children.","Toxic, drooling child leaning forward with stridor","140, 167, 182, 727",["Robbins ch 16","Robbins ch 8"]],"headneckscc":["Field cancerization of the upper aerodigestive mucosa","Most head and neck cancers are squamous cell carcinomas. Carcinogens bathe a wide area of mucosa, so several independent tumors can arise — field cancerization.","Smoker and drinker with a nonhealing tongue ulcer","383, 690",["Robbins ch 16","Katzung ch 54"]],"salivary":["Parotid, submandibular and sublingual glands","Salivary glands can be blocked by stones, inflamed by infection or autoimmunity, or grow tumors — mostly benign in the parotid.","Painless parotid mass that recurs after enucleation = pleomorphic adenoma","383",["Robbins ch 16"]],"klumpke":["Lower trunk — C8, T1","Traction on the lower trunk (C8–T1) paralyzes the intrinsic hand muscles. Lumbricals normally flex the MCP and extend the IP joints, so without them the fingers claw.","'Clawmpke' — clawed hand after grabbing a branch while falling","452",["Moore ch 3","Moore ch 8"]],"longthoracic":["Serratus anterior (C5–C7)","The long thoracic nerve (roots C5–C7, 'wings of heaven') supplies serratus anterior, which holds the scapula against the chest wall and rotates it to raise the arm overhead.","Scapula sticks out after a mastectomy with node dissection","452",["Moore ch 3"]],"axillarynerve":["Deltoid and teres minor (C5–C6)","The axillary nerve lies against the surgical neck of the humerus, so a fracture there or an anterior dislocation injures it.","Anterior shoulder dislocation, then cannot abduct and a numb lateral shoulder","450",["Moore ch 3"]],"musculocut":["Biceps, brachialis, coracobrachialis (C5–C7)","The musculocutaneous nerve flexes the elbow and supinates the forearm, then becomes the lateral cutaneous nerve of the forearm.","Cannot flex the elbow or turn a doorknob, numb lateral forearm","450–451",["Moore ch 3"]],"radialnerve":["Extensors of elbow, wrist and fingers (C5–T1)","The radial nerve supplies all the extensors. It is compressed in the axilla (crutches, arm hung over a chair — 'Saturday night palsy') or injured in the spiral groove by a midshaft humerus fracture.","Woke after a night drinking with his arm over a chair — wrist drop","450, 452",["Moore ch 3"]],"mediannerve":["Wrist and finger flexors, LOAF muscles (C5–T1)","The median nerve flexes the wrist and lateral fingers and runs the thenar muscles. Where it is cut decides the picture: high lesions lose finger flexion, low lesions only the thenar muscles and lateral lumbricals.","Child with a supracondylar fracture who cannot make a full fist","450",["Moore ch 3"]],"carpaltunnel":["Median nerve under the transverse carpal ligament","The median nerve shares the carpal tunnel with nine flexor tendons under the flexor retinaculum. Anything that crowds the tunnel compresses it.","Pregnant woman with tingling thumb and index finger","453, 463",["Moore ch 3"]],"ulnarnerve":["Intrinsic hand muscles (C8–T1)","The ulnar nerve runs most of the intrinsic hand muscles — interossei, medial lumbricals, hypothenar muscles, adductor pollicis. Distal lesions claw more, because the ulnar half of flexor digitorum profundus still pulls the fingers down.","Cyclist with tingling little finger and a weak grip","450, 453",["Moore ch 3"]],"rotatorcuff":["Supraspinatus, infraspinatus, teres minor, subscapularis","Four muscles (SItS — small t for teres minor) hold the humeral head in the glenoid. The supraspinatus tendon passes under the acromion and is the one most often impinged or torn.","Shoulder pain and weak abduction with a positive empty-can test","451",["Moore ch 3"]],"femoralobt":["Quadriceps (femoral L2–L4) · adductors (obturator L2–L4)","The femoral nerve extends the knee and supplies the anterior thigh; the obturator nerve adducts the thigh and supplies its medial skin.","Anticoagulated patient with a retroperitoneal bleed and a buckling knee","456",["Moore ch 7","Moore ch 5"]],"meralgia":["Lateral femoral cutaneous nerve under the inguinal ligament","The lateral femoral cutaneous nerve (L2–L3) is purely sensory. Compressed where it passes under the inguinal ligament, it causes burning numbness without weakness.","Pregnant woman with burning outer thigh, strength normal","456",["Moore ch 7"]],"sciaticnerve":["Hamstrings and everything below the knee (L4–S3)","The sciatic nerve supplies the hamstrings and splits into the common peroneal and tibial nerves. The tibial nerve plantarflexes and inverts the foot and supplies the sole.","Cannot stand on tiptoe after a knee injury","457",["Moore ch 7","Moore ch 6"]],"peroneal":["Dorsiflexors and evertors (L4–S2)","The common peroneal nerve wraps around the fibular neck, where it is easily compressed or injured. PED: Peroneal Everts and Dorsiflexes.","Foot drop after a fibular neck fracture","457",["Moore ch 7"]],"glutealnerve":["Gluteus medius and minimus (superior) · maximus (inferior)","The superior gluteal nerve (L4–S1) runs the hip abductors that keep the pelvis level when standing on one leg. The inferior gluteal nerve (L5–S2) runs gluteus maximus, the hip extensor.","Hip drops on the left when standing on the right leg = right superior gluteal nerve","457",["Moore ch 7"]],"pudendal":["Perineum and external sphincters (S2–S4)","The pudendal nerve supplies sensation to the perineum and the external urethral and anal sphincters. It can be blocked at the ischial spine for childbirth.","Numb perineum after a long bike ride","457",["Moore ch 6"]],"reflexroots":["Which root carries each reflex","Each stretch reflex runs through particular roots, so a lost reflex localizes a root lesion. They count up in order.","Lost ankle jerk with a herniated L5–S1 disc = S1 root","458, 523",["Fundamental Neuroscience ch 33","Moore ch 2"]],"kneeinj":["Ligaments and menisci of the knee","The cruciates stop the tibia sliding forward (ACL) or back (PCL); the collaterals resist side-to-side stress; the menisci cushion the joint.","Football player hit from the side with a planted foot — unhappy triad","454, 464",["Moore ch 7"]],"wristinj":["Carpal and metacarpal bones","The scaphoid is the most often fractured carpal bone, and its blood supply enters distally — so a proximal fracture can starve the proximal fragment.","Fell on an outstretched hand, tender snuffbox, normal x-ray","453, 463",["Moore ch 3"]],"overuse":["Tendons and palmar fascia","Repetitive loading thickens tendons and their sheaths; Dupuytren contracture instead thickens the palmar fascia.","New mother with pain at the base of the thumb lifting her baby","450, 465",["Moore ch 3"]],"compartment":["Pressure in a closed fascial compartment","Rising pressure inside a fascial compartment first blocks venous outflow, then collapses arterioles — muscle and nerve become ischemic and necrotic, releasing myoglobin.","Tibial fracture with escalating pain on stretching the toes","465",["Moore ch 7"]],"achalasia":["Lost inhibitory (NO, VIP) neurons in the myenteric plexus","In achalasia the inhibitory neurons of Auerbach plexus degenerate, so the LES cannot relax and peristalsis fails. Food and liquid pile up above a tight sphincter.","Dysphagia to solids and liquids with a bird's beak","384",["Robbins ch 17","Robbins ch 8"]],"zenker":["False diverticulum through Killian triangle","Pharyngoesophageal dysmotility pushes mucosa out through a weak spot between the thyropharyngeal and cricopharyngeal parts of the inferior constrictor (Killian triangle).","Old man with bad breath who regurgitates yesterday's dinner","391",["Robbins ch 17","Moore ch 8"]],"pud":["Acid and pepsin beat mucosal defense","Ulcers form when acid and pepsin overwhelm the mucosal barrier. H pylori causes most of both types; NSAIDs remove prostaglandin protection.","Pain eased by food in a man gaining weight = duodenal ulcer","387",["Robbins ch 17","Katzung ch 62"]],"zes":["Gastrin-secreting tumor","A gastrinoma — usually in the duodenum, otherwise the pancreas — drives relentless acid secretion. Acid also inactivates pancreatic enzymes in the small bowel, causing malabsorption.","Ulcers in the jejunum with diarrhea and high calcium = MEN1","357",["Robbins ch 17","Robbins ch 24"]],"pyloric":["Hypertrophied pyloric sphincter","Hypertrophy and hyperplasia of the pyloric muscle obstruct the gastric outlet in young infants — the commonest cause of gastric outlet obstruction at that age.","4-week-old firstborn boy with projectile vomiting and an olive","366",["Robbins ch 17"]],"sbo":["Mechanical block vs hypomotility","In obstruction, fluid and gas build up above a blockage and the bowel collapses below; strangulation can make it ischemic. In ileus, the bowel stops moving with no blockage at all.","Prior appendectomy, now vomiting with air-fluid levels = adhesive SBO","393",["Robbins ch 17","Bootcamp.com Gastroenterology"]],"sibo":["Too many bacteria, or too little bowel","The small bowel normally holds few bacteria. Low acid, stasis or blind loops let colonic-type bacteria overgrow, deconjugating bile salts and consuming B12.","Bloating and B12 deficiency after gastric bypass","392–393",["Robbins ch 17"]],"hirschsprung":["Absent ganglion cells in the distal colon","Neural crest cells fail to migrate all the way down, so the distal colon lacks Auerbach and Meissner plexuses and cannot relax. The normal bowel above dilates (megacolon) with a transition zone.","Newborn with Down syndrome who has not passed meconium","61, 391",["Robbins ch 17","Fundamental Neuroscience ch 29"]],"ibs":["Disordered gut–brain interaction","Chronic abdominal pain tied to bowel habits, with no structural disease.","Young woman with pain relieved by defecation and alternating diarrhea and constipation","389, 390",["Robbins ch 17","Katzung ch 62"]],"gibleed":["Ligament of Treitz divides them","Bleeding above the ligament of Treitz usually shows as hematemesis or melena; below it, as hematochezia.","Black tarry stools = upper source","387",["Robbins ch 17","Bootcamp.com Gastroenterology"]],"laxatives":["Water into the lumen · motility","Laxatives either hold water in the stool or stimulate the colon. Antidiarrheals slow motility through gut μ-opioid receptors without reaching the brain.","Diabetic with early satiety and vomiting undigested food → metoclopramide","378, 407, 408, 584",["Katzung ch 62","Kaplan & Sadock ch 13"]],"tcellact":["TCR–MHC (signal 1) + B7–CD28 (signal 2)","A naïve T cell needs two signals. Signal 1: its TCR recognizes antigen on MHC (II for CD4⁺, I for CD8⁺). Signal 2: costimulation from B7 (CD80/86) on the antigen-presenting cell binding CD28.","Antigen without costimulation = anergy","101",["Katzung ch 55","Robbins ch 6"]],"ctla4ig":["Bind B7 (CD80/86) → no CD28 costimulation","Fusion proteins of the CTLA-4 extracellular domain with the IgG1 Fc region. They bind B7 (CD80/86) and so block signal 2 — T cells see antigen without costimulation.","Block signal 2 and the T cell goes anergic","",["Katzung ch 55","Katzung ch 36"]],"mtor":["mTOR — the response to IL-2","Sirolimus binds FKBP like tacrolimus, but the complex blocks mTOR rather than calcineurin — so IL-2 is made but the cell cannot respond to it.","Transplant drug that spares the kidney but raises lipids","118",["Katzung ch 55"]],"mmf":["IMP dehydrogenase → no de novo purines","Mycophenolate reversibly inhibits IMP dehydrogenase, the gateway to guanine nucleotides. Lymphocytes depend on de novo purine synthesis, so B- and T-cell proliferation stalls.","IMP dehydrogenase blocker — watch for CMV","119",["Katzung ch 55","Katzung ch 36"]],"acuterej":["T cells against donor MHC · new donor-specific antibodies","Weeks to months after transplant. Cellular rejection is CD8⁺ and/or CD4⁺ T cells attacking donor MHC (type IV hypersensitivity); humoral rejection is like hyperacute, but with antibodies made after the transplant.","Kidney graft failing 6 weeks after transplant, lymphocytes on biopsy","117",["Robbins ch 6","Katzung ch 55"]],"chronicrej":["Indolent cellular and humoral injury → arteriosclerosis","Over months to years, recipient CD4⁺ T cells respond to donor peptides presented on recipient APCs, with both cellular and antibody components (types II and IV).","Lung transplant patient years later with progressive airflow obstruction = bronchiolitis obliterans","117",["Robbins ch 6","Katzung ch 55"]],"earlydev":["Implantation → gastrulation → organogenesis","The embryonic period (weeks 3–8) builds every organ, which is why it is the window when teratogens do the most damage.","Week 2 = two layers · week 3 = three layers · week 4 = four limbs and four heart chambers","630",["Langman ch 5","Langman ch 6"]],"germlayers":["Three layers plus neural crest","Every organ traces back to a germ layer, and defects in one layer cluster together.","Adrenal medulla is neural crest; adrenal cortex is mesoderm","631",["Langman ch 6","Langman ch 18"]],"teratogens":["Injury during organogenesis (weeks 3–8)","The embryo is most vulnerable during organogenesis. Before implantation exposure is all-or-none; after week 8 it mainly affects growth and function.","Flipper limbs = thalidomide","632",["Langman ch 9","Katzung ch 59"]],"pharyngeal":["Clefts ectoderm · arches mesoderm + neural crest · pouches endoderm","The neck and face are built from pharyngeal clefts (outside), arches (middle) and pouches (inside) — CAP, outside to inside.","3rd pouch makes the thymus and the lower parathyroids","637, 638",["Langman ch 17","Moore ch 8"]],"neckcysts":["Midline vs lateral neck remnants","The thyroid descends from the foramen cecum at the base of the tongue to the neck, trailing the thyroglossal duct. A persistent cervical sinus from the 2nd–4th clefts forms a lateral cyst.","Midline lump that rises when he sticks out his tongue","330",["Moore ch 8","Langman ch 17"]],"treacher":["Underdeveloped first-arch structures","Both under-build the mandible and face; Treacher Collins is a neural crest disorder.","Tiny jaw, tongue blocking the airway, cleft palate","638",["Langman ch 17"]],"cleft":["Failed fusion of facial processes","Cleft lip and cleft palate have separate causes and fusion steps, though they often occur together.","Cleft lip = maxillary + medial nasal processes; cleft palate = palatine shelves","501, 639",["Langman ch 17","Moore ch 9"]],"ntd":["Neural tube fails to close by week 4","The neural tube should close by the end of week 4. If it does not, the overlying vertebrae, meninges and skin fail too.","Folate before conception prevents them","501",["Langman ch 18","Fundamental Neuroscience ch 5"]],"holopros":["Forebrain fails to divide · neurons fail to migrate","In holoprosencephaly the forebrain does not split into two hemispheres (a field defect at weeks 3–4, linked to sonic hedgehog). In lissencephaly neurons fail to migrate, leaving a smooth brain.","Single central eye and a monoventricle = holoprosencephaly (trisomy 13)","501",["Fundamental Neuroscience ch 5","Langman ch 18"]],"chiari":["Posterior fossa malformations","Crowded or underdeveloped posterior fossa structures herniate through the foramen magnum or leave a cyst in place of the vermis.","Cape-like loss of pain and temperature in a young adult = syrinx with Chiari I","502",["Robbins ch 28","Fundamental Neuroscience ch 5"]],"tef":["Faulty separation of trachea and esophagus","The foregut normally splits into trachea and esophagus. The commonest anomaly is esophageal atresia with a distal fistula from the trachea to the lower esophagus.","Drooling newborn who chokes at the first feed; the NG tube will not pass","366",["Langman ch 14","Robbins ch 17"]],"walldefects":["Failed lateral body-fold closure","Lateral fold closure normally seals the abdominal wall around the umbilical ring. Failure lets abdominal contents out — through a separate defect (gastroschisis) or through the umbilical ring itself (omphalocele).","Bowel floating free beside the cord = gastroschisis","365, 501",["Langman ch 7","Langman ch 15"]],"potter":["No fetal urine → no amniotic fluid","Fetal urine makes most of the amniotic fluid. Without it (oligohydramnios) the fetus is compressed and the lungs cannot develop — pulmonary hypoplasia kills.","Babies who can't 'pee' in utero get Potter sequence","596",["Langman ch 16","Robbins ch 10"]],"horseshoe":["Fusion, branching and outlet anomalies of the urinary tract","The kidneys ascend from the pelvis during development; the ureteric bud may split early; and a membrane can persist in the male urethra.","Low-lying fused kidney under the IMA in Turner syndrome","597",["Moore ch 5","Langman ch 16"]],"pph":["Excess bleeding after delivery","After delivery, the uterus must contract hard to clamp the spiral arteries at the placental bed. Anything that stops it contracting, or a tear, retained tissue or coagulopathy, causes hemorrhage.","Boggy uterus after a long labor","343, 657, 658",["Robbins ch 22","Katzung ch 37"]],"amenorrhea":["Hypothalamus → pituitary → ovary → outflow tract","Work up absent periods along the axis: is she pregnant, is the outflow tract present, is the ovary working, and is the hypothalamus or pituitary driving it?","Primary amenorrhea, short stature, webbed neck = Turner","655, 656, 662",["Katzung ch 40","Robbins ch 24"]],"athero":["Cholesterol plaque in the tunica intima","A disease of elastic arteries and large and medium muscular arteries.","Fatty streak → fibrous plaque → complicated atheroma","305",["Robbins ch 11"]],"aaa":["Transmural inflammation and matrix degradation","A localized dilation of the abdominal aorta driven by inflammation through all three layers and breakdown of the extracellular matrix. It is usually infrarenal, where the vasa vasorum is sparse.","Older male smoker with a pulsatile abdominal mass","306",["Robbins ch 11","Moore ch 5"]],"taa":["Cystic medial degeneration","Cystic medial degeneration weakens the wall of the thoracic aorta. Tertiary syphilis does it by obliterative endarteritis of the vasa vasorum.","Tall patient with lens dislocation and a dilated aortic root","306",["Robbins ch 11"]],"dissection":["Longitudinal intimal tear → false lumen","Blood enters the media through an intimal tear and tracks along it, creating a false lumen. Stanford A involves the ascending aorta; Stanford B only the descending aorta below the left subclavian.","Hypertensive man with tearing chest pain into the back and unequal arm pressures","307",["Robbins ch 11","Robbins ch 12"]],"pad":["Flow-limiting atherosclerotic stenosis of the limb arteries","Atherosclerotic narrowing limits flow to the legs, so muscle becomes ischemic when demand rises.","Calf pain after a block of walking that stops with rest","305",["Robbins ch 11","Katzung ch 12"]],"dvt":["Virchow triad — stasis, hypercoagulability, endothelial damage","A clot forms in a deep vein when the Virchow triad (SHE) is present: Stasis, Hypercoagulability, Endothelial damage. Proximal leg veins (iliac, femoral, popliteal) are the source of pulmonary emboli.","Swollen calf after a long flight","321",["Robbins ch 4","Katzung ch 34"]],"htnemerg":["BP ≥ 180/≥ 120 — with or without acute end-organ damage","Urgency: severe hypertension without acute end-organ damage. Emergency: severe hypertension with it. Arterioles may show fibrinoid necrosis.","BP 220/130 with confusion and papilledema","304",["Robbins ch 11","Katzung ch 11"]],"syncope":["Transient loss of consciousness from ↓ cerebral blood flow","Three kinds. Reflex (most common): vasovagal, situational, carotid sinus hypersensitivity. Orthostatic: hypovolemia, drugs, autonomic failure.","Fainted while standing in a hot crowd, after feeling warm and nauseated","318",["Robbins ch 12","Costanzo ch 4"]],"hypovshock":["Volume depletion → ↓ preload","Too little volume returns to the heart, so preload, stroke volume and output fall; the body clamps down to compensate.","Trauma patient, cold and clammy, flat neck veins","317",["Costanzo ch 4","Guyton ch 24"]],"distshock":["Systemic vasodilation → ↓ SVR","Vessels dilate throughout the body, so the primary disturbance is a fall in SVR (afterload). In early sepsis and anaphylaxis the heart compensates with high output; after CNS injury it cannot, because sympathetic drive to the heart is lost too.","Hypotensive but warm and flushed","317",["Guyton ch 24","Robbins ch 4"]],"sicksinus":["Age-related degeneration of the SA node","The SA node wears out with age and fires unreliably.","Older patient with dizzy spells and long pauses on Holter","312",["Guyton ch 13"]],"bactmening":["Organisms by age · PMN-rich CSF with low glucose","The likely organism depends on age. CSF shows ↑ opening pressure, ↑ neutrophils, ↑ protein and ↓ glucose.","Fever, stiff neck, cloudy CSF full of neutrophils","125, 135, 140, 176",["Katzung ch 51","Robbins ch 28"]],"viralmening":["Lymphocytic CSF with normal glucose","Viral meningitis gives ↑ lymphocytes with normal glucose, and the opening pressure and protein are normal or only mildly raised.","Summer meningitis with lymphocytes and normal glucose","176",["Robbins ch 28","Robbins ch 8"]],"tb":["Acid-fast rod · caseating granulomas","Primary infection forms a Ghon complex (Ghon focus in the mid/lower lobe + hilar nodes). Over 90% heal by fibrosis and calcification. Reactivation (secondary TB) favors the lung apices because the organism is highly aerobic, forming fibrocaseous cavities.","Upper-lobe cavity with night sweats and weight loss","138, 193",["Robbins ch 8","Robbins ch 15"]],"mac":["Acid-fast rods, often multidrug resistant","M avium–intracellulare causes disseminated, non-TB disease in AIDS, most often when the CD4⁺ count falls below 50/mm³.","AIDS patient with CD4 30, fever and diarrhea","138, 193",["Katzung ch 47"]],"icp":["CPP = MAP − ICP","Cerebral perfusion depends on the gradient between mean arterial pressure and intracranial pressure: CPP = MAP − ICP. Falling blood pressure or rising ICP lowers it; when CPP reaches 0 there is no cerebral perfusion and the brain dies.","Hypertension, bradycardia and irregular breathing after a head bleed","299, 512, 626",["Robbins ch 28","Katzung ch 25"]],"herniation":["Brain pushed past dural folds or through the foramen magnum","A mass forces brain tissue under the falx, through the tentorial notch or down into the foramen magnum. Coma and death follow when the brainstem is compressed.","Epidural bleed, then a fixed dilated pupil on the same side","543",["Robbins ch 28","Moore ch 9"]],"hydroceph":["↑ CSF volume → ventricular dilation","Too much CSF dilates the ventricles, with or without raised pressure.","Only the ventricles upstream of a block dilate","536",["Fundamental Neuroscience ch 6","Robbins ch 28"]],"ethprinciples":["Autonomy · beneficence · nonmaleficence · justice","Four principles guide most answers, and they can pull against each other.","Autonomy, beneficence, nonmaleficence, justice","267, 272",["Kaplan & Sadock ch 27"]],"capacity":["Can this patient make this decision now?","Capacity is judged by a physician for a specific healthcare decision. Competence is a legal determination by a judge about decision-making in general.","Patient with schizophrenia who clearly understands and refuses surgery has capacity","267–268",["Kaplan & Sadock ch 28","Kaplan & Sadock ch 1"]],"consent":["Disclosure · understanding · capacity · voluntariness","Consent is a process, not a signature. The patient must understand the diagnosis and the risks and benefits of the proposed treatment and its alternatives, including no treatment, and may revoke consent at any time — even orally.","Unconscious trauma patient → implied consent","268, 272",["Kaplan & Sadock ch 27"]],"minors":["Under 18 — parental consent, with exceptions","Parental consent is generally required for a minor, but laws vary by state, and there are standing exceptions.","16-year-old asking for contraception — no parental consent needed","268, 272, 273",["Kaplan & Sadock ch 28"]],"surrogate":["What would the patient have wanted?","Without capacity or an advance directive, people who know the patient decide what the patient would have done.","The patient's known wishes beat the surrogate's own preference","269, 273",["Kaplan & Sadock ch 29","Kaplan & Sadock ch 27"]],"confid":["Privacy, with narrow exceptions to prevent harm","Confidentiality protects privacy and autonomy. The patient may waive it. Breaking it requires serious, imminent harm that cannot be prevented any other way.","Patient threatens a named person → duty to protect","269, 272",["Kaplan & Sadock ch 28","Kaplan & Sadock ch 27"]],"reporting":["When the physician must act","Some situations oblige the physician to report or refuse, whatever the relationship.","Colleague smells of alcohol on rounds → report","269, 273",["Kaplan & Sadock ch 27"]],"communication":["Structured patient communication","Mnemonics for building rapport, delivering bad news and helping patients change.","First ask what the patient already understands (SPIKES: Perception)","270, 271, 272",["Kaplan & Sadock ch 1"]],"vsreflex":["Visceral afferent → dorsal horn interneuron → somatic and sympathetic efferents","Visceral afferents (chemo-, mechano- and thermoreceptors) fire with inflammation, ischemia, capsule stretch or distension.","Organ disease shows up as paraspinal heat, moisture and splinting at its own levels","",["OCOM OMM","Foundations of Osteopathic Medicine ch 43"]],"somatovisc":["Somatic afferent → spinal cord → visceral efferent","The reverse direction: a somatic dysfunction (vertebral, rib or myofascial strain) sends nociceptive input into its segment and alters the function of a viscus supplied by the same segment.","Palpitations with a clean cardiac workup and a 2nd rib dysfunction","",["OCOM OMM","Foundations of Osteopathic Medicine ch 43"]],"viscvisc":["Viscus → ganglia or spinal cord → another viscus","Irritation or expansion of one organ alters the function of another through shared ganglia or spinal segments, without a somatic link.","One organ's distension changes another organ's function","",["OCOM OMM","Foundations of Osteopathic Medicine ch 43"]],"facilitation":["Interneurons held near threshold","Ongoing nociceptive bombardment (visceral or somatic) holds the interneurons of one spinal segment in chronic subthreshold depolarization.","A segment that overreacts to any input","",["OCOM OMM","Foundations of Osteopathic Medicine ch 43"]],"tart":["Impaired function of the somatic system and its related vascular, lymphatic and neural elements","Somatic dysfunction is diagnosed by finding at least some of the TART criteria: Tissue texture changes, positional Asymmetry, Restriction of motion and Tenderness.","TART","",["Foundations of Osteopathic Medicine ch 43","OCOM OMM"]],"sympathicotonia":["Chronic sympathetic hyperactivity from somatic dysfunction or visceral disease","When facilitation keeps sympathetic outflow high, each organ shifts in a predictable direction.","Constipation, urinary retention and sweating together","",["OCOM OMM","Foundations of Osteopathic Medicine ch 72"]],"vagusomm":["CN X (plus CN III, VII, IX in the head)","The vagus carries parasympathetic outflow to the heart, lungs, trachea, esophagus, stomach, liver, gallbladder, pancreas, spleen, kidneys, small intestine, ascending colon and proximal two-thirds of the transverse colon.","Pancreatitis with tissue change at OA, C1 and C2 = vagal afferents","",["OCOM OMM","Foundations of Osteopathic Medicine ch 6"]],"pelvicsplanch":["S2–S4 parasympathetic outflow","The sacral division supplies the distal third of the transverse colon, descending and sigmoid colon, rectum, bladder detrusor and the pelvic reproductive organs.","Chronic sigmoid constipation with sacral tissue change","",["OCOM OMM","Foundations of Osteopathic Medicine ch 6"]],"omheadneck":["Sympathetic T1–T4 (course: T1–T5) · CN III, VII, IX, X","Sympathetics to the head and neck leave the upper thoracic cord and ascend through the cervical chain. Parasympathetics come from cranial nerves III, VII, IX and X.","Most head and neck posterior points sit on C1 or C2","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"ombeth":["Four anterior Chapman points share the 2nd ICS beside the sternum","The lab chart flags four organs whose anterior Chapman points all sit in the second intercostal space close to the sternum: Bronchi, Esophagus, Thyroid and Heart.","Tender pea-sized nodule in the 2nd ICS beside the sternum","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omheart":["Sympathetic T1–T5, left · parasympathetic vagus","Cardiac sympathetics leave the upper thoracic cord (the course gives T1–T6, with the heaviest concentration of cardiac nociceptive afferents at T4).","Left T2–T3 paraspinal heat and splinting with chest pressure","",["OCOM OMM","Foundations of Osteopathic Medicine ch 71"]],"omstomach":["Esophagus T2–T6 · stomach T5–T9 via the celiac ganglion · vagus","The esophagus takes upper thoracic sympathetics (T2–T6; Osmosis groups it with the lungs at T2–T7). The stomach takes T5–T9 through the celiac ganglion, and the vagus supplies both.","GERD with a tender left 5th ICS point","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omliver":["Sympathetic T5–T9 (course alternative T6–T10) via the celiac ganglion · vagus","The liver and gallbladder share the celiac outflow (T5–T9) with the stomach, but their findings lie on the right.","Cholecystitis with right-sided midthoracic tissue change","",["OCOM OMM","OCOM OMM"]],"ompancspleen":["Sympathetic T5–T9 via the celiac ganglion · vagus","Both organs take celiac outflow. On the Chapman chart they mirror each other at the 7th intercostal space: pancreas on the right, spleen on the left.","Right 7th ICS = pancreas · left 7th ICS = spleen","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omsmallint":["Sympathetic T9–T11 (Osmosis: T10–T11) via the superior mesenteric ganglion · vagus","The small bowel takes lower thoracic outflow through the superior mesenteric ganglion; the vagus supplies its parasympathetics.","Tender points across the 8th–10th intercostal spaces","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omcolon":["Ascending + proximal ⅔ transverse: T10–T11 (SMG), vagus · distal colon and rectum: T12–L2 (IMG), S2–S4","The colon splits at the distal third of the transverse colon. Proximal to it: T10–T11 sympathetics through the superior mesenteric ganglion and vagal parasympathetics.","Diverticulitis with tender points along the lateral thigh","",["OCOM OMM","OCOM OMM"]],"omappendix":["Sympathetic T12 (Osmosis)","Both charts put the appendix point at the tip of the right 12th rib.","Tender tip of the right 12th rib","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omkidney":["Kidneys and upper ureters T10–T11 · lower ureters T11–L2 · vagus to the kidney","Kidneys, upper ureters and gonads share T10–T11 through the superior mesenteric and aorticorenal ganglia.","Ureteral stone referring through the aorticorenal ganglion","",["An Osteopathic Approach to Diagnosis and Treatment ch 22","OCOM OMM"]],"omadrenal":["Sympathetic T10 (Osmosis) · medulla releases catecholamines","The adrenal points sit just above the kidney points, front and back.","Chronic stress and a tight adrenal region","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"omrepro":["Gonads T10–T11 · uterus, prostate T12–L2 (Osmosis: uterus T10–L2) · S2–S4","Gonads follow their embryologic origin up to T10–T11; the uterus, cervix and prostate take lower outflow. Posterior points cluster between the PSIS and the L5 spinous process.","Points between the PSIS and L5 = pelvic organs","",["An Osteopathic Approach to Diagnosis and Treatment ch 22","OCOM OMM"]],"omlimbs":["Arms T2–T7 (Osmosis: T2–T8) · legs T11–L2","The limbs get sympathetic supply only — there is no parasympathetic innervation to the arms and legs.","No parasympathetics to the limbs","",["OCOM OMM","An Osteopathic Approach to Diagnosis and Treatment ch 22"]],"fryette":["How side bending and rotation couple in the thoracic and lumbar spine","Harrison Fryette described how side bending and rotation pair up in the thoracic and lumbar spine. Principle I (neutral): side bending and rotation go to opposite sides, rotation toward the convexity, across a group of vertebrae.","Neutral group curve = Type I · single flexed or extended segment = Type II","",["Foundations of Osteopathic Medicine ch 31","Atlas of Osteopathic Techniques ch 5"]],"ribraise":["Sympathetic chain ganglia lie just anterior to the rib heads","Lifting the rib angles works directly on the sympathetic trunk ganglia in front of the rib heads. It briefly stimulates sympathetic output, then produces a sustained down-regulation of excess sympathetic tone.","Calm the sympathetic chain through the rib heads","",["OCOM OMM","OCOM OMM"]],"subocc":["Vagus at the jugular foramen · superior cervical ganglion","Releasing the occipitoatlantal joint and C2 normalizes vagal (parasympathetic) tone and also influences the superior cervical sympathetic ganglion.","Treat OA–C2 for the vagus","",["OCOM OMM","OCOM OMM"]],"ganglioninh":["Celiac (upper border of L1) · superior mesenteric (L1–L2) · inferior mesenteric (L3)","Steady, deep, gentle pressure over the prevertebral ganglia in front of the aorta reduces sympathetic outflow to the gut and pelvis. It relieves visceral spasm, lowers sphincter tone, improves perfusion and restores peristalsis.","Post-op ileus with spastic sphincters","",["OCOM OMM","Foundations of Osteopathic Medicine ch 42"]],"thoracicinlet":["T1, the 1st ribs and the manubrium — where the lymph ducts drain","The thoracic duct and right lymphatic duct empty into the subclavian veins at the thoracic inlet, so fascial restriction here obstructs systemic and pulmonary lymph drainage.","Open the drain before you pump","",["OCOM OMM","Foundations of Osteopathic Medicine ch 72"]],"diaphragmrel":["The thoracoabdominal 'two-chambered pump'","Relaxing a hypertonic diaphragm restores its vertical excursion and the pressure gradient between chest and abdomen.","Restore the pump that moves lymph","",["OCOM OMM","Foundations of Osteopathic Medicine ch 78"]],"lymphpump":["Alternating intrathoracic and intra-abdominal pressure","Rhythmic pressure changes push lymph centrally through one-way valved vessels. Lymphatic channels themselves contract about 5–8 times per minute at rest.","Pneumonia → thoracic lymphatic pump","",["OCOM OMM","Foundations of Osteopathic Medicine ch 72"]],"mesentericlift":["Decongest the bowel · restore colonic sliding","The intestines hang in a stretch-sensitive mesentery that carries their arteries, veins and lymphatics. A mesenteric lift draws the loops gently toward their root, relieving traction and freeing lymph flow.","Heavy, congested lower abdomen → mesenteric lift","",["OCOM OMM","Foundations of Osteopathic Medicine ch 55"]],"counterstrain":["Indirect, passive positioning","The patient is passively positioned to shorten the tissue around an active tender point until the tenderness falls by about 70% or more, held about 90 seconds, then slowly returned to neutral.","Fold over the tender point, hold 90 seconds","",["OCOM OMM","OCOM OMM"]],"met":["Direct, active — patient contracts against the physician","The patient performs an isometric contraction against a precise counterforce from the physician; the barrier is then re-engaged. It lengthens hypertonic muscles, increases range of motion and mobilizes joints.","Patient pushes, physician holds","",["OCOM OMM","OCOM OMM"]],"hvla":["Direct thrust through the restrictive barrier","A quick, short thrust through the barrier of a localized joint restriction to restore joint play.","The technique most often contraindicated","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"mfr":["Direct or indirect loading of fascia until it releases","Myofascial tissue is engaged and held, toward the barrier (direct) or toward ease (indirect), until it releases. Soft tissue technique reduces hypertonicity and improves local blood flow to clear irritating metabolites.","Hold the fascia until it lets go","",["OCOM OMM","OCOM OMM"]],"stilltech":["Indirect to direct, with compression","The segment is taken into its position of ease, a compression (force vector) is added, and it is then carried through neutral into the previously restricted range before returning to neutral.","Ease → compress → through the barrier","",["OCOM OMM","OCOM OMM"]],"fpr":["Indirect, with compression","The regional curve is flattened, a compression is applied to disengage the segment, and it is placed into its position of ease (exaggerating the named dysfunction) for 3–5 seconds before returning to neutral.","Flatten, compress, ease, hold 3–5 seconds","",["OCOM OMM","OCOM OMM"]],"fivemodels":["Structure-function lenses for a treatment plan","Each model looks at the same patient through a different lens, and a plan usually draws on several.","Five lenses, one patient","",["OCOM OMM","Foundations of Osteopathic Medicine (4e) ch 42"]],"psoassyn":["Iliopsoas spasm · L1/L2 Type II FRS is the key lesion","A spasm of the iliopsoas flexes and compresses the lumbar spine. The upper lumbar segment (L1 or L2) holds a Type II FRS dysfunction rotated toward the tight psoas — the key lesion that must be released first or the lower lumbar and SI findings recur.","Leaning forward and toward one side, can't extend the hip","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"discdz":["Nucleus pulposus through a torn annulus","A protrusion bulges with the annulus intact. If the annulus tears and the nucleus pulposus extrudes, it is an extrusion; a fragment no longer attached to the disc is a sequestration.","Sciatica after lifting","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"spinalstenosis":["A narrowed canal — worse in extension","The canal narrows further when the lumbar spine extends, so symptoms follow posture.","Leg pain on walking that eases when leaning over a cart","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"spondy":["Pars interarticularis defect · forward slip","Spondylolysis is a stress fracture of the pars interarticularis, at L5 in about 95% of cases. Spondylolisthesis is the forward translation of a vertebra on the one below (a backward slip is retrolisthesis).","Adolescent athlete with extension pain and a step-off","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"lld":["Sacral base unleveling","An anatomic or functional difference in leg length tilts the sacral base and pelvis, and the spine compensates above it. It strains the iliolumbar ligaments and perpetuates quadratus lumborum trigger points.","New back pain after a hip replacement","",["Foundations of Osteopathic Medicine ch 93","OCOM OMM"]],"iliolumbar":["Iliolumbar ligament insertion, just superior and lateral to the PSIS","Postural decompensation (often a short leg) or repetitive microtrauma strains the iliolumbar ligament, leaving exquisite tenderness at its insertion on the iliac crest.","Tender just above and lateral to the PSIS with groin referral","",["OCOM OMM","Foundations of Osteopathic Medicine ch 93"]],"ucs":["Tight upper trapezius/levator + pectorals · weak deep neck flexors + lower scapular stabilizers","Two diagonals cross at the shoulders. Tight: upper trapezius, levator scapulae, suboccipitals (behind) and pectoralis major and minor, SCM, scalenes (in front).","Desk worker with forward head and rounded shoulders","",["OCOM OMM","OCOM OMM"]],"lcs":["Tight erector spinae + hip flexors · weak abdominals + gluteals","Tight: thoracolumbar erector spinae (behind) and iliopsoas and rectus femoris (in front). Weak: rectus abdominis, transversus abdominis and obliques, and gluteus maximus and medius.","Anterior pelvic tilt with weak glutes","",["OCOM OMM","OCOM OMM"]],"chapmanpt":["Visceral-autonomic-lymphatic congestion in the deep fascia","Frank Chapman and Charles Owens described them in the 1930s: small, tender, gangliform nodules found in predictable places, reflecting visceral, autonomic (mostly sympathetic) and lymphatic disturbance.","Tender pea-sized nodule in the 2nd intercostal space beside the sternum = heart","",["An Osteopathic Approach to Diagnosis and Treatment ch 22","OCOM OMM"]],"segdx":["Named for the position of ease; flexion or extension decides which","A segment is named for its position of ease — the direction it moves most freely.","More symmetric in extension = extended","",["Foundations of Osteopathic Medicine ch 31","Atlas of Osteopathic Techniques ch 5"]],"ribmotion":["Axis through the costovertebral and costotransverse joints","Each rib turns about an axis through its costovertebral and costotransverse joints. In the upper ribs that axis lies almost coronal, so the front of the rib rises (pump handle) and the chest deepens front to back.","Pump handle deepens the chest, bucket handle widens it","",["Foundations of Osteopathic Medicine ch 35","OCOM OMM"]],"ribresp":["Key rib: the bottom of an inhaled group, the top of an exhaled group","An inhaled rib moves freely up into inhalation but is restricted coming down in exhalation; an exhaled rib is the reverse. A group of ribs is usually held by one key rib: the bottom rib of an inhaled group and the top rib of an exhaled group (BITE).","BITE — Bottom Inhaled, Top Exhaled","",["Foundations of Osteopathic Medicine ch 31","Foundations of Osteopathic Medicine ch 35"]],"innomshear":["Vertical shear between ilium and sacrum","A nonphysiologic vertical shear of the innominate on the sacrum. An upslip (superior shear) usually comes from extreme force when the body’s weight is caught on one leg; it slackens the sacrotuberous ligament.","Weight caught on one leg","",["Foundations of Osteopathic Medicine ch 37","Foundations of Osteopathic Medicine ch 31"]],"vxconj":["Carrier protein turns a T-independent antigen into a T-dependent one","A capsular polysaccharide alone cannot be presented to T cells, so it raises only a T-cell–independent response. Conjugating the capsule to a carrier protein brings in T-cell help and a T-cell–dependent response.","Conjugating the capsule recruits T-cell help","109, 125",["Katzung Appendix 1"]],"passiveimm":["Preformed antibodies — immediate, short-lived, no memory","Passive immunity transfers preformed antibodies. Protection starts at once but lasts only as long as the antibody does (IgG half-life about 3 weeks), and no memory forms.","Fast but short — no memory","103, 108",["Katzung Appendix 1"]],"asplenia":["Loss of IgM, C3b opsonization and splenic filtering","Without a working spleen — after splenectomy or sickle cell autosplenectomy — IgM falls, complement activation and C3b opsonization drop, and the main filter for opsonized encapsulated bacteria is gone.","Howell-Jolly bodies after a splenectomy","96, 125",["Robbins ch 13","Robbins ch 14"]],"encaps":["Polysaccharide capsule resists phagocytosis","A polysaccharide capsule is an antiphagocytic virulence factor. Encapsulated bacteria are cleared once they are opsonized and filtered by the spleen, so a patient without a spleen — with less opsonizing ability — gets severe infections from them.","Please SHiNE my SKiS","116, 125",["Robbins ch 13"]],"heatstroke":["Failure to dissipate heat — core temperature over 40°C","Thermoregulation fails and the core temperature passes 40°C (104°F); Guyton puts the critical range at 105–108°F. Fever comes from cytokines resetting the hypothalamus — heat stroke is a failure to get rid of heat.","Confused recruit, core temperature over 40°C","225, 433, 530",["Robbins ch 9","Guyton ch 74"]],"dcs":["Dissolved nitrogen bubbles out on a fast ascent","Breathing compressed air at depth saturates body water and fat with nitrogen. Surface too fast and the nitrogen comes out of solution as bubbles in tissues and blood — a form of gas embolism.","Diver with joint pain after a fast ascent","691",["Guyton ch 45","Robbins ch 4"]],"elecinj":["Burns plus disrupted cardiac and neural conduction","Current does two kinds of damage: burns at the entry and exit sites and along its path, and ventricular fibrillation or failure of the cardiac and respiratory centers from disrupted nerve conduction.","Grabbed a live wire and could not let go","",["Robbins ch 9"]],"kwashiorkor":["Protein deficit — visceral protein and albumin lost","Protein deprivation out of proportion to the calorie deficit — classically a child weaned early onto an almost all-carbohydrate diet.","Swollen-bellied child with flaky-paint skin","69",["Robbins ch 9"]],"starvation":["Glucose for brain and red cells first, protein last","Starvation is organized to keep glucose flowing to the brain and red cells and to preserve protein.","Ketones feed the brain after day 3","88, 89",["Marks ch 3"]],"venom":["α-Latrotoxin and scorpion venom","Black widow venom contains α-latrotoxin, which causes explosive release of transmitter from cholinergic and adrenergic vesicles. Scorpion sting is on the list of causes of acute pancreatitis.","Explosive transmitter release — α-latrotoxin","320, 404",["Katzung ch 6","Katzung Appendix 1"]],"specialstains":["Match the stain to the organism it was built for","When the Gram stain will not do, each special stain targets a particular structure — mycolic acid for the acid-fast stain, glycogen and mucopolysaccharide for PAS, the polysaccharide capsule of Cryptococcus for India ink and mucicarmine, and fungal walls for…","Help! Certain Bugs Really Try my Patience — Giemsa","123",["Robbins ch 8"]],"anaerobes":["No catalase and/or superoxide dismutase","Anaerobes lack catalase and/or superoxide dismutase, so oxygen damages them. Facultative anaerobes use oxygen as the final electron acceptor when it is there and ferment when it is not.","Anaerobes Can’t Breathe Fresh Air","125",["Katzung ch 45"]],"virulence":["Capsule · protein A · IgA protease · M protein","Virulence factors help bacteria evade the immune response.","Protein A binds Fc — no opsonization","127, 133",["Robbins ch 8"]],"telomerase":["RNA-dependent DNA polymerase that rebuilds chromosome ends","Telomerase is a reverse transcriptase that carries its own RNA template and adds TTAGGG repeats to the 3′ ends of chromosomes, so they do not lose material with every round of replication.","Telomerase TAGs for Greatness and Glory","36",["Marks ch 12"]],"transcription":["RNA polymerase II binds the promoter","RNA polymerase II binds the promoter — an AT-rich upstream sequence with TATA and CAAT boxes — and makes mRNA. Activators bind enhancers and repressors bind silencers, which can sit near, far from, or inside the gene.","rRNA, mRNA, tRNA — polymerases I, II, III in order of use","40",["Marks ch 13","Marks ch 15"]],"rnaproc":["5′ cap · poly-A tail · splicing, all in the nucleus","The first transcript (hnRNA) gets a 7-methylguanosine cap at the 5′ end, a poly-A tail at the 3′ end (signal AAUAAA), and has its introns spliced out — all in the nucleus — before the mRNA leaves for the cytosol.","Introns stay in the nucleus, exons exit","40, 41",["Marks ch 13"]],"translation":["Charge the tRNA, read the codon, move three bases","Aminoacyl-tRNA synthetase (one per amino acid, using ATP) attaches each amino acid to the 3′ CCA end of its tRNA and checks the match.","Going APE — A site, P site, E site","42, 43",["Marks ch 14"]],"pcr":["Denature · anneal · elongate, then repeat","The polymerase chain reaction amplifies a chosen DNA fragment by cycling heat to separate the strands (denaturation), cooling so primers bind (annealing), and warming again so a heat-stable DNA polymerase adds dNTPs (elongation).","Amplify a fragment you already know how to find","50",["Marks ch 16"]],"organelles":["Make on the RER, modify and sort in the Golgi","Proteins bound for secretion, for the membrane or for other organelles are made on the rough ER, where N-linked oligosaccharides are added.","N-linked sugars in the eNdoplasmic reticulum · O-linked in the GOlgi","45",["Pawlina ch 2"]],"vesicles":["Coated vesicles move cargo between compartments","The signal recognition particle (SRP), an abundant cytosolic ribonucleoprotein, carries the ribosome and its growing polypeptide to the RER; without it, protein piles up in the cytosol.","Two (COPII) steps forward, one (COPI) step back","45",["Pawlina ch 2"]],"cytoskel":["Microfilaments · intermediate filaments · microtubules","A network of protein fibers that supports the cell’s structure, moves the cell and its organelles, and divides it. Each filament type has its own job.","Vimentin, desmin, cytokeratin, lamins, GFAP, neurofilaments = intermediate filaments","46",["Pawlina ch 2"]],"pcd":["Dynein arm defect → immotile cilia","Autosomal recessive defect in the dynein arms — the ATPases that bend motile cilia (a 9 doublet + 2 singlet axoneme) by sliding the doublets.","Bronchiectasis + chronic sinusitis + situs inversus","47",["Pawlina ch 5","Robbins ch 15"]],"nakpump":["3 Na⁺ out, 2 K⁺ in, for one ATP","Sits in the plasma membrane with its ATP site on the cytosolic side. Each ATP moves 3 Na⁺ out and 2 K⁺ in — the pump is phosphorylated as Na⁺ leaves and dephosphorylated as K⁺ enters.","2 strikes? K, you’re still in. 3 strikes? Nah, you’re out!","47",["Costanzo ch 1","Guyton ch 4"]],"celljunctions":["Seal, anchor, communicate","Junctions seal an epithelium, tie its cells to each other and to the basement membrane, and let neighboring cells communicate. From apical to basal: tight junction, adherens junction, desmosome, gap junction, hemidesmosome.","Hemidesmosomes are down “bullow” — bullous pemphigoid","482",["Pawlina ch 5"]],"ccbs":["L-type Ca²⁺ channels of vascular smooth muscle","Block voltage-dependent L-type calcium channels. The dihydropyridines — amlodipine, nifedipine, nicardipine, clevidipine, nimodipine — act mainly on vascular smooth muscle and dilate arteries; verapamil and diltiazem act mainly on the heart.","The -dipines work on the vessels; verapamil and diltiazem work on the heart","323",["Katzung ch 11","Katzung ch 12"]],"normalaging":["Less physiologic reserve (homeostenosis), not disease","A time-dependent, progressive decline in organ function that raises susceptibility to disease — linked to telomere shortening, DNA methylation changes and mitochondrial dysfunction.","Older lung: ↑ RV, TLC unchanged","225, 290",["Foundations of Osteopathic Medicine ch 69","OCOM OMM"]],"beers":["Potentially inappropriate medications for older adults","Adverse drug reactions climb with the number of drugs — from about 10% of patients taking one drug to nearly 100% of those taking ten.","New confusion in an older adult — read the medication list first","240, 575, 593",["Katzung ch 60","Foundations of Osteopathic Medicine ch 69"]],"falls":["Stacked intrinsic, environmental and drug risks","Falls are a major geriatric syndrome with overlapping risks.","TUG over 12 seconds = high fall risk","",["OCOM OMM","Foundations of Osteopathic Medicine ch 69"]],"fourms":["What Matters · Medication · Mentation · Mobility","An age-friendly health systems framework, assessed and acted on at the Medicare Annual Wellness Visit. Care of older adults is interprofessional and aims at prevention, health maintenance and function.","4Ms: What Matters, Medication, Mentation, Mobility","",["Foundations of Osteopathic Medicine ch 69"]],"geriomt":["Treat the physiologic age, not the chronologic age","Frail older adults have little homeostatic reserve and respond strongly to physical treatment, so OMT is adapted: a smaller dose, slow and gentle forces, and a technique chosen for the tissue causing the problem.","Osteoporotic patient → indirect techniques, no thrust on the ribs","",["OCOM OMM","Somatic Dysfunction in Osteopathic Family Medicine ch 16"]],"h1blockers":["H1 histamine receptor — reversible inverse agonists","Reversible inhibitors of the H1 histamine receptor (inverse agonists). First-generation drugs enter the CNS and block muscarinic and α-adrenergic receptors as well; second-generation drugs enter the CNS far less, so they sedate far less.","Drowsy after an allergy pill = first generation","705, 250",["Katzung ch 16"]],"coughcold":["NMDA antagonist antitussive · α-agonist decongestants","Dextromethorphan is an antitussive — a synthetic codeine analog that antagonizes NMDA glutamate receptors. Pseudoephedrine and phenylephrine activate α-adrenergic receptors in the nasal mucosa, constricting its vessels.","Decongestant spray for two weeks, now worse congestion → rhinitis medicamentosa","706",["Katzung ch 9","Katzung ch 31"]],"adrskin":["Lupus · gums · gout · myopathy · bone loss · rashes","Musculoskeletal, skin and connective-tissue reactions range from cosmetic (teeth, gums) to life-threatening (Stevens-Johnson syndrome, malignant hyperthermia).","Photosensitivity: Sat for photo — Sulfonamides, Amiodarone, Tetracyclines, Fluoroquinolones","249",["Robbins ch 9","Robbins ch 25"]],"adrneuro":["Movement disorders · neuropathy · seizures · vision","Neurologic reactions cluster in a few classes: dopamine blockers cause movement disorders, several anticancer and TB drugs damage peripheral nerves, and a short list provokes seizures.","Seizure drugs: With seizures, I bit my tongue — isoniazid, bupropion, imipenem, tramadol","250",["Katzung ch 29","Katzung ch 47"]],"adrrenal":["Interstitial nephritis · tubular toxicity · cystitis · cough · fibrosis","Kidney reactions range from inflammation (interstitial nephritis) to direct tubular toxicity; in the lung, drugs cause cough or fibrosis.","Pulmonary fibrosis: My nose cannot breathe bad air","250",["Robbins ch 9","Robbins ch 20"]],"adrmulti":["Antimuscarinic · disulfiram-like · sulfa allergy · pupils","Some reactions span many organs at once — blocking muscarinic receptors throughout the body, or a disulfiram-like reaction to alcohol.","Disulfiram-like: Sorry pals, can’t go mingle","250, 251",["Katzung ch 8","Katzung ch 46"]],"gpid":["Catalase → coagulase → novobiocin · hemolysis → optochin, bacitracin","A short run of bench tests sorts gram-positive cocci. Catalase splits staphylococci (positive, clusters) from streptococci (negative, pairs or chains).","Gram-positive cocci in clusters, coagulase negative, novobiocin resistant → S saprophyticus","132–135",[]],"serummarkers":["Monitor response and recurrence — biopsy makes the diagnosis","Serum tumor markers lack the sensitivity and specificity to diagnose or screen for cancer. They help follow a tumor’s response to treatment and detect recurrence, and several rise in non-neoplastic conditions too.","A marker follows the tumor; the biopsy names it","222",["Robbins ch 7"]],"ihcstains":["Which protein the tumor cell still makes tells you where it came from","Immunohistochemistry stains tissue for proteins typical of a cell lineage. It finds the primary site of a metastasis and classifies tumors that look alike under the microscope.","Undifferentiated tumor, S-100 positive → melanoma or schwannoma","223",["Robbins ch 7","Pawlina ch 2"]],"hcghpl":["Placental hormones made by syncytiotrophoblast","hCG acts like LH to keep the corpus luteum — and so its progesterone — alive for the first 8–10 weeks, until the placenta makes its own estriol and progesterone.","hCG keeps the corpus luteum alive until the luteal-placental shift at 8–10 weeks","652",["Guyton ch 83"]],"lactphys":["Falling estrogen and progesterone release prolactin","After delivery of the placenta, the rapid fall in estrogen and progesterone disinhibits prolactin and lactation begins. Suckling keeps it going: nipple stimulation raises prolactin (milk production) and oxytocin (milk letdown, plus uterine contraction).","Prolactin is pro-lactation; oxytocin is letdown","653, 648",["Guyton ch 83"]],"dermatomes":["One spinal nerve, one strip of skin","A dermatome is the strip of skin supplied by one spinal nerve. There is no C1 dermatome — C1 carries almost no sensory fibers.","T4 at the teat pore · T10 at the belly button","523",["Moore ch 1","Fundamental Neuroscience ch 9"]],"tularemia":["Francisella tularensis — facultative intracellular coccobacillus","Francisella tularensis is a gram-negative coccobacillus that survives inside phagocytes. People catch it from ticks, rabbits and deer flies.","Rabbit or tick exposure, then a skin ulcer with swollen nodes","147, 124, 125",["Katzung ch 45"]],"hypothalnuc":["TAN HATS — thirst, pituitary, hunger, autonomic, temperature, sex","The hypothalamus keeps the body in balance — Thirst and water balance, Adenohypophysis and Neurohypophysis release, Hunger, Autonomic nervous system, Temperature and Sexual urges.","Lateral injury makes you lean · ventromedial injury makes you very massive","508",["Fundamental Neuroscience ch 30"]],"thalnuc":["Every ascending sense but smell relays here","The thalamus relays all ascending sensory information except smell to the cortex, each sense through its own nucleus. The ventral anterior and ventral lateral nuclei relay motor loops instead.","Lateral = light, medial = music","508",["Fundamental Neuroscience ch 15","Fundamental Neuroscience ch 18"]],"limbic":["Feeding, fleeing, fighting, feeling and sex","Structures for emotion, long-term memory, smell, behavior and autonomic control: the hippocampus, amygdalae, mammillary bodies, anterior thalamic nuclei, cingulate gyrus and entorhinal cortex.","The famous 5 F’s","509, 524",["Fundamental Neuroscience ch 31","Kaplan & Sadock ch 3"]],"cortexlesions":["Where the damage is decides the syndrome","Damage to particular cortical and brainstem areas gives recognizable syndromes — useful for localizing a stroke, tumor or degeneration.","Eyes look toward a cortical lesion, away from a pontine one","524",["Fundamental Neuroscience ch 32","Fundamental Neuroscience ch 28"]],"posturing":["Which brainstem tracts are left unopposed","After severe brain injury the posture shows how low the lesion reaches. Above the red nucleus, the rubrospinal and vestibulospinal tracts are left in charge; below it, only the vestibulospinal tract is.","Decorticate — your hands are near the cor (heart)","524",["Fundamental Neuroscience ch 25"]],"bbbcvo":["Tight junctions everywhere but a few windows","The blood-brain barrier keeps circulating substances (bacteria, many drugs) out of the CSF and brain. It is built from tight junctions between nonfenestrated capillary endothelial cells, the basement membrane, pericytes and astrocyte foot processes.","Area postrema — pronounce it “puke”-strema","506",["Fundamental Neuroscience ch 6","Fundamental Neuroscience ch 8"]],"cerebcircuit":["In through the inferior and middle peduncles, out through the superior","The cerebellum modulates movement and aids coordination and balance. Input arrives through the inferior and middle peduncles, Purkinje cells of the cortex project to the deep nuclei, and output leaves through the superior peduncle to the opposite cortex.","Don’t eat greasy foods — dentate, emboliform, globose, fastigial","510",["Fundamental Neuroscience ch 27"]],"gutarteries":["Foregut celiac · midgut SMA · hindgut IMA","Each embryonic gut segment keeps its own artery, parasympathetic nerve and vertebral level. Arteries to the gut are single and branch anteriorly; arteries to non-gut organs are paired and branch laterally and posteriorly.","Splenic flexure and rectosigmoid — the watershed areas","370, 371",["Moore ch 5","Langman ch 15"]],"retroperit":["SAD PUCKER — behind the peritoneum","Retroperitoneal organs sit behind and outside the peritoneal cavity, so an injury to them can collect blood or gas in the retroperitoneal space.","SAD PUCKER","367",["Moore ch 5"]],"portosys":["Where portal and systemic veins meet","In portal hypertension, blood backs up through the places where portal veins meet systemic veins, and those veins dilate.","Varices of the gut, butt and caput","372",["Moore ch 5","Robbins ch 18"]],"inguinalcanal":["Deep ring lateral, Hesselbach triangle medial","The inguinal canal runs from the deep ring (an evagination of transversalis fascia) to the superficial ring. Indirect hernias enter the deep ring lateral to the inferior epigastric vessels; direct hernias push through Hesselbach triangle medial to them.","MDs don’t lie — Medial to the inferior epigastrics = Direct, Lateral = indirect","376, 377",["Moore ch 5"]],"gutwall":["Mucosa · submucosa (Meissner) · muscularis (Auerbach) · serosa","The gut wall has four layers, inside to outside — mucosa, submucosa, muscularis externa and serosa — and two nerve plexuses.","MSMS — mucosa, submucosa, muscularis, serosa","369",["Pawlina ch 17"]],"liverzones":["Zone 1 periportal · zone 2 intermediate · zone 3 pericentral","Blood flows from the portal triads at the edge of each lobule to the central vein, so oxygen falls from zone 1 to zone 3. Bile flows the opposite way.","Acetaminophen and ischemia hit zone 3 first","374",["Pawlina ch 18","Robbins ch 18"]],"celladapt":["Change size, number or type before the cell is injured","Cells adapt to stress in reversible ways that can be physiologic (the uterus in pregnancy) or pathologic (the myocardium in hypertension). If the stress is too great or lasts too long, adaptation gives way to injury.","Barrett esophagus = metaplasia → dysplasia → adenocarcinoma","202",["Robbins ch 2"]],"apoptosis":["ATP-dependent programmed death through caspases","Programmed, ATP-dependent cell death. Three pathways activate caspases, and the cell shrinks, condenses its chromatin, blebs and breaks into apoptotic bodies that macrophages eat.","Bax and Bak are bad for survival · Bcl-2 — be clever, live","204",["Robbins ch 2"]],"necrosis":["Membrane damage, leakage, inflammation","Exogenous injury damages the plasma membrane, contents leak, the cell is digested and its proteins denature, and inflammation follows. The pattern depends on the tissue and the cause.","Caseous = TB granuloma · saponification = pancreatitis","205",["Robbins ch 2"]],"ischemiavuln":["Watershed and far-downstream cells die first","Ischemia is blood supply inadequate for demand — from reduced arterial flow, impaired venous drainage or shock. Cells at the end of the supply line, or between two arteries, go first.","Subendocardium, zone 3, splenic flexure — last in line, first to die","206",["Robbins ch 2","Robbins ch 4"]],"freeradical":["Lipid peroxidation, protein damage, DNA breaks","Free radicals damage membranes (lipid peroxidation), proteins and DNA.","Fenton reaction — iron and copper make radicals","206, 207",["Robbins ch 2"]],"calcification":["Damaged tissue with normal Ca²⁺ vs normal tissue with high Ca²⁺ or PO₄³⁻","Calcium deposits stain deeply basophilic. Where they form tells you the cause: in tissue that is already damaged, or throughout normal tissue because blood calcium or phosphate is high.","PSaMMOMa: Papillary, Somatostatinoma, Meningioma, Mesothelioma, Ovarian, Milk (prolactinoma)","207",["Robbins ch 2"]],"inflamsigns":["Rubor, calor, tumor, dolor, functio laesa","Inflammation removes the cause of injury and the dead cells and starts repair — but it harms the host when excessive (septic shock), prolonged (TB) or misdirected (SLE).","Fever: IL-1 and TNF → PGE₂ in the hypothalamus","209, 210",["Robbins ch 3","Foundations of Osteopathic Medicine ch 93"]],"acuteinflam":["Neutrophils leave postcapillary venules in four steps","An early, innate response — rapid onset (seconds to minutes), short duration (minutes to days). Vasodilation and leaky vessels deliver fluid and proteins, and neutrophils leave the blood at postcapillary venules.","Chemotaxis: C5a, IL-8, LTB₄, kallikrein, PAF","210, 211",["Robbins ch 3"]],"chronicinflam":["Macrophages and T cells — destruction and repair at once","Prolonged inflammation with macrophages, lymphocytes and plasma cells that destroys and repairs tissue at the same time. Granulomas are a pattern of it: activated macrophages wall off a stimulus they cannot clear.","Caseating = infection · noncaseating = sarcoid or Crohn","212, 213",["Robbins ch 3"]],"woundheal":["Inflammatory → proliferative → remodeling","Tissue that cannot regenerate is replaced by connective tissue in three overlapping phases. About 70–80% of tensile strength returns by 3 months, and little more after that.","Type III early, type I late","212, 214",["Robbins ch 3"]],"cardiaceq":["SV = EDV − ESV · EF = SV/EDV · CO = SV × HR · MAP = CO × TPR","A handful of equations link volumes, rates and pressures. Stroke volume rises with contractility and preload and falls with afterload.","SV CAP — contractility, afterload, preload","289, 290",["Costanzo ch 4","Guyton ch 9"]],"heartsounds":["Valves close (S1, S2); filling turbulence (S3, S4)","S1 and S2 are valves closing; S3 and S4 are turbulence as blood fills the ventricle — S3 into a dilated, overfilled ventricle, S4 against a stiff one.","S3 = volume (dilated) · S4 = stiffness (hypertrophy)","292",["Guyton ch 23","Costanzo ch 4"]],"sensoryrec":["Free endings for pain and temperature; corpuscles for touch, vibration, stretch","Each skin and joint receptor is tuned to one kind of stimulus and adapts quickly or slowly.","A delta plane is fast, but a taxC is slow","504",["Guyton ch 48","Fundamental Neuroscience ch 17"]],"stretchrec":["Spindle senses stretch; tendon organ senses tension","Two receptors report on every muscle. The spindle in the muscle belly senses length and drives the stretch reflex; the Golgi tendon organ in the tendon senses tension and switches the muscle off.","Spindle = stretch → contract · tendon organ = tension → relax","461",["Guyton ch 55","Fundamental Neuroscience ch 24"]],"neoprog":["The basement membrane separates in situ from invasive","A neoplasm is an uncontrolled, often monoclonal proliferation of cells, benign or malignant, with two parts: the neoplastic cells and a non-neoplastic stroma of vessels and connective tissue.","Basement membrane intact = in situ · breached = invasive","215, 217",["Robbins ch 7"]],"tumornomen":["Carcinoma = epithelium · sarcoma = mesenchyme","Carcinoma means epithelial origin and sarcoma mesenchymal origin; both terms generally imply malignancy. Benign tumors are generally named by adding -oma to the cell of origin (fibroma, chondroma).","Hamartoma = right place, wrong arrangement · choristoma = right tissue, wrong place","216",["Robbins ch 7"]],"gradestage":["Grade = how the cells look · stage = how far it spread","Grade describes the tumor cells; stage describes how far the tumor has spread. Stage usually predicts survival better.","Stage (spread) determines survival","216",["Robbins ch 7"]],"hallmarks":["Acquired mutations in growth, DNA repair and survival","Cancer comes from (mostly acquired) DNA mutations in genes that control growth, DNA repair and survival. Each hallmark is a capability the tumor gains.","Warburg = aerobic glycolysis","217, 218",["Robbins ch 7"]],"oncogenes":["Gain of function in a proto-oncogene","A gain-of-function mutation turns a normal proto-oncogene into an oncogene. Damage to only one allele is needed.","RET = REceptor Tyrosine kinase","220",["Robbins ch 7"]],"tsgenes":["Loss of function of both alleles (Knudson)","Loss of function raises cancer risk, but both alleles must be lost before the disease appears — the Knudson two-hit hypothesis. Someone who inherits one bad copy needs only one more hit.","Two hits for suppressors, one for oncogenes","220",["Robbins ch 7"]],"cancerepi":["Incidence vs mortality by sex and age","Skin cancer (basal > squamous ≫ melanoma) is the most common cancer and is left out of the usual rankings. Cancer is the second leading cause of death in the United States, after heart disease.","Lung cancer kills the most in both sexes","218",["Robbins ch 7"]],"metsites":["Carcinomas by lymph, sarcomas by blood","Most carcinomas spread by lymphatics and most sarcomas by blood. Metastases to bone, liver, lung and brain are more common than primary tumors of those organs, and they often appear as multiple lesions.","CLaSH — Carcinomas by Lymph, Sarcomas Hematogenously","217, 219",["Robbins ch 7"]],"capfluid":["Starling forces across the capillary wall","Four Starling forces decide whether fluid leaves a capillary or returns to it. Edema is excess fluid in the interstitium, and each cause pushes one of the four.","Two forces push out, two pull in — find the one that changed","301",["Robbins ch 4","Guyton ch 16"]],"thrombosisreg":["Stasis, hypercoagulability, endothelial damage","A thrombus forms when Virchow’s triad is in play. A thrombus formed in flowing blood during life is laminated; a clot that forms after death is not.","Virchow triad = SHE","321, 433, 691",["Robbins ch 4"]],"airemb":["Gas bubbles block flow","Gas bubbles in the circulation block flow. In divers who ascend too fast, nitrogen dissolved at depth comes out of solution; air can also enter during procedures such as central line placement.","Ascending diver → nitrogen bubbles → hyperbaric O₂","691",["Robbins ch 4","Guyton ch 45"]],"lungvol":["Four volumes make four capacities","Four volumes add up to four capacities. Residual volume — and any capacity that contains it — cannot be measured by spirometry.","RV, FRC and TLC can’t be measured by spirometry","682, 683",["Costanzo ch 5","Guyton ch 38"]],"compliance":["How easily the lung fills — ΔV/ΔP","The lungs tend to collapse inward and the chest wall to spring outward; at FRC the two balance. Compliance is the change in lung volume for a change in pressure.","Emphysema is floppy, fibrosis is stiff","679, 683",["Costanzo ch 5","Guyton ch 38"]],"airwayres":["Medium bronchi resist most","Resistance is highest in the large and medium bronchi; the small airways are so many, side by side, that together they resist least. The work of breathing goes to overcoming elastic recoil and airway resistance.","Restrictive = fast and shallow · obstructive = slow and deep","680, 682",["Costanzo ch 5","Guyton ch 38"]],"pulmcirc":["Low pressure, and it constricts when O₂ falls","The pulmonary circulation is low resistance and high compliance. Unlike systemic arterioles, pulmonary vessels constrict when alveolar oxygen falls, steering blood toward ventilated alveoli.","The lung is the one bed that constricts to hypoxia","684, 685",["Costanzo ch 5","Guyton ch 39"]],"odc":["Sigmoid because hemoglobin binds O₂ cooperatively","Hemoglobin binds O₂ cooperatively, so its curve is sigmoid; myoglobin, a single chain, binds more tightly and its curve is not sigmoid. Shifts in the curve match unloading to what the tissue needs.","Left is lower (P50)","687, 688",["Costanzo ch 5","Guyton ch 41"]],"co2trans":["Mostly as bicarbonate made in red cells","CO₂ travels in blood three ways, mostly as bicarbonate made inside red cells by carbonic anhydrase.","Haldane at the lung, Bohr at the tissue","686, 687",["Costanzo ch 5","Guyton ch 41"]],"chemorec":["CO₂ drives breathing; low O₂ only below 60 mm Hg","Breathing is driven mainly by CO₂, sensed through the pH of brain interstitial fluid; low O₂ adds drive through the peripheral chemoreceptors only when it falls far.","Central = CO₂ via CSF pH · peripheral = O₂ < 60","299",["Guyton ch 42","Costanzo ch 5"]],"gastrin":["G cells — antrum and duodenum","Gastrin raises acid mainly by making ECL cells release histamine, rather than by acting on parietal cells directly. It also grows the gastric mucosa and increases motility.","Gastrin works mostly through histamine","378, 380",["Costanzo ch 8","Guyton ch 65"]],"gip":["K cells — duodenum and jejunum","GIP (also called gastric inhibitory peptide) tells the pancreas that food is coming, which is why oral glucose raises insulin more than the same glucose given IV.","Oral glucose beats IV glucose for insulin release","378",["Costanzo ch 8","Guyton ch 65"]],"ghrelin":["Stomach — the hunger hormone","Ghrelin from the stomach raises appetite.","Ghrowlin’ stomach","378",["Costanzo ch 8","Guyton ch 65"]],"vip":["Parasympathetic ganglia — sphincters, gallbladder, small intestine","VIP pulls water and electrolytes into the gut and relaxes intestinal smooth muscle and sphincters.","VIPoma = WDHA","378",["Costanzo ch 8","Guyton ch 64"]],"gastricacid":["H⁺/K⁺-ATPase driven by histamine, ACh and gastrin","Parietal cells secrete acid when histamine, acetylcholine and gastrin stimulate them — and histamine from ECL cells carries most of gastrin’s effect.","Three keys open the parietal cell: histamine, ACh, gastrin","379, 380",["Costanzo ch 8","Guyton ch 65"]],"pancsec":["Acinar enzymes · ductal bicarbonate","The pancreas secretes an isotonic fluid whose anions shift with flow — high Cl⁻ at low flow, high HCO₃⁻ at high flow — and enzymes, most as inactive zymogens.","Enterokinase lights the trypsin fuse","380",["Costanzo ch 8","Guyton ch 65"]],"renalclear":["Cx = Ux × V / Px","Clearance is the volume of plasma completely cleared of a substance per unit time. Comparing it with GFR shows what the tubule did to that substance.","Compare clearance with GFR to see what the tubule did","600",["Costanzo ch 6","Guyton ch 27"]],"gfrcalc":["Glomerular filtration rate ≈ 100 mL/min","Inulin is freely filtered and neither reabsorbed nor secreted, so its clearance equals GFR. Creatinine clearance is the everyday estimate.","Inulin = true GFR · creatinine slightly overshoots","600, 601",["Costanzo ch 6","Guyton ch 27"]],"erpf":["PAH clearance · FF = GFR / RPF","PAH is filtered and secreted so completely that nearly all of it entering the kidney is excreted, so its clearance estimates renal plasma flow.","PAH for flow, inulin for filtration","600, 601",["Costanzo ch 6","Guyton ch 27"]],"rbfauto":["Myogenic reflex and tubuloglomerular feedback","Two mechanisms hold renal blood flow and GFR steady when perfusion pressure changes, protecting the kidney.","Stretch → constrict · more salt at the macula densa → constrict","600",["Costanzo ch 6","Guyton ch 27"]],"reabsec":["Filtered vs excreted tells you which","Compare what was filtered with what was excreted: if less came out, the tubule reabsorbed the difference; if more, it secreted it.","Prerenal kidneys hold on to sodium","602, 620",["Costanzo ch 6","Guyton ch 28"]],"glucthresh":["Glucosuria from ~200 mg/dL","At normal plasma levels, glucose is completely reabsorbed in the proximal tubule by Na⁺/glucose cotransport. Above the threshold, the transporters run out.","Threshold ~200 mg/dL · Tm ~375 mg/min","602",["Costanzo ch 6","Guyton ch 28"]],"apgar":["Appearance, Pulse, Grimace, Activity, Respiration","The Apgar score rates a newborn’s condition at 1 and 5 minutes after delivery, 0–2 points for each of five signs (10 points total).","APGAR — Appearance, Pulse, Grimace, Activity, Respiration","652",["Kaplan & Sadock ch 2","Robbins ch 10"]],"prm":["Five involuntary, interdependent motions","Sutherland’s model of an inherent, involuntary rhythm, separate from breathing with the diaphragm.","Five parts: brain and cord, CSF, membranes, cranial bones, sacrum","",["Atlas of Osteopathic Techniques ch 18"]],"cri":["The palpable rhythm of the primary respiratory mechanism","The biphasic fluctuation palpated in the cranial bones. 1 Hz, or 6 cycles a minute — which reflect sympathetic vasomotor tone.","CRI about 8–14 cycles a minute","",["Atlas of Osteopathic Techniques ch 18","OCOM OMM"]],"sbsflexext":["Motion named at the sphenobasilar synchondrosis","Cranial motion is named for what happens at the sphenobasilar synchondrosis (SBS), where the sphenoid meets the occiput just below the sella turcica.","Flexion = external rotation = a wider, shorter skull","",["Atlas of Osteopathic Techniques ch 18"]],"cv4":["Still point technique","The physician follows the occiput into extension, then resists its return to flexion until the fluctuation stops — a still point — and holds until the cranial rhythmic impulse returns.","Still point","",["Atlas of Osteopathic Techniques ch 18","OCOM OMM"]],"csmethod":["The classic counterstrain sequence","The patient is passively placed in the position of greatest comfort while the physician monitors the counterstrain (tender) point, held 90 seconds, then returned slowly to neutral — an indirect technique.","Fold over the point, 90 seconds, at least 70% better","",["Atlas of Osteopathic Techniques ch 9"]],"hematuriaapproach":["Read the urine: casts, red cell shape, protein","Casts mean the red or white cells came from the glomeruli or tubules; blood without casts comes from elsewhere in the urinary tract — a stone, a bladder tumor.","Casts = glomerulus or tubule; no casts = stone, tumor or bladder","112, 428, 465, 566, 612, 613, 616, 617, 619, 624",["Robbins ch 20","Robbins ch 21"]],"eqpot":["Each ion pulls toward its own voltage","When a membrane is permeable to an ion, the ion diffuses down its concentration gradient until the charge it carries builds a voltage that exactly opposes further net diffusion — its equilibrium (Nernst) potential.","Each ion drives the membrane toward its own equilibrium potential","",["Costanzo ch 1","Guyton ch 5"]],"rmp":["Set mostly by K⁺","At rest, nerve and muscle membranes are far more permeable to K⁺ and Cl⁻ than to Na⁺ and Ca²⁺, so the resting potential sits close to the K⁺ equilibrium potential and far from that of Na⁺.","Rest is set by K⁺","504",["Costanzo ch 1","Guyton ch 5"]],"nerveap":["Na⁺ in, then K⁺ out","An inward current brings the membrane to threshold, the potential at which an action potential becomes inevitable. Voltage-gated Na⁺ channels open and Na⁺ rushes in, driving the upstroke toward the Na⁺ equilibrium potential.","Na⁺ in, then K⁺ out","504",["Costanzo ch 1","Guyton ch 5"]],"refractory":["Why a nerve cannot fire again at once","During the absolute refractory period — almost the whole action potential — no stimulus, however strong, can fire another, because the Na⁺ inactivation gates stay closed until the membrane repolarizes.","Absolute: Na⁺ gates inactivated · relative: K⁺ still open","",["Costanzo ch 1"]],"conduction":["Bigger and myelinated = faster","Two things speed conduction: a larger fiber (lower internal resistance) and myelin (higher membrane resistance between nodes), both of which let current spread farther along the axon before it decays.","Bigger and myelinated = faster","503",["Costanzo ch 1","Fundamental Neuroscience ch 3"]],"fibertypes":["Aα to C — biggest and fastest to smallest and slowest","Nerve fibers are classified by diameter, conduction velocity and myelination.","A delta plane is fast, but a taxC is slow","504",["Costanzo ch 3"]],"glia":["Support, myelin, CSF and defense","Glia support neurons. CNS glia come from neuroectoderm — except microglia, which come from mesoderm; PNS glia come from neural crest.","Oligodendrocyte: one cell, many axons · Schwann: one cell, one axon","503",["Pawlina ch 12","Fundamental Neuroscience ch 2"]],"seafoodtox":["Na⁺ channels shut — or held open","Two seafood toxins act on voltage-gated Na⁺ channels: tetrodotoxin blocks them, ciguatoxin opens them.","Hot feels cold after reef fish = ciguatera","246",["Costanzo ch 1"]],"fluidcomp":["Where the body’s water is","Total body water is about 60% of body weight: two-thirds inside cells (ICF, 40%) and one-third outside (ECF, 20%). The ECF is three-quarters interstitial fluid and one-quarter plasma.","60-40-20: total water, inside, outside","599",["Costanzo ch 6","Guyton ch 25"]],"fluidshifts":["Water follows osmolarity across cell membranes","NaCl stays in the ECF, and water crosses cell membranes only when ECF and ICF osmolarities differ. A gain or loss changes the ECF first; any change in its osmolarity then moves water until both compartments match again.","Sweat is hyposmotic","",["Costanzo ch 6","Guyton ch 25"]],"countercurrent":["Building the medullary osmotic gradient","The loop of Henle deposits NaCl in the deep medulla. The thick ascending limb pumps NaCl out but is impermeable to water (the single effect); flow of tubular fluid carries the effect deeper, building the corticopapillary osmotic gradient.","Thick ascending limb: salt out, water stays","608",["Costanzo ch 6","Guyton ch 29"]],"freewater":["ADH decides whether free water is kept","Free water — water without solute — is generated in the diluting segments (thick ascending limb and early distal tubule), where solute is reabsorbed without water.","Diluting segments: thick ascending limb and early distal tubule","608",["Costanzo ch 6","Guyton ch 29"]],"polyuriadx":["Water restriction, then desmopressin","006, osmolality usually under 300 mOsm/kg). Serum osmolality, a water restriction test and a dose of desmopressin sort them.","Concentrates when water is withheld = primary polydipsia","342",["Costanzo ch 6","Guyton ch 29"]],"soundcond":["From air to fluid","Sound in air must become pressure waves in the fluid-filled inner ear, whose impedance is much higher. The tympanic membrane and ossicles match the impedance: a large eardrum funnels force onto the small oval window, and the ossicles add lever advantage.","Big eardrum, small oval window = impedance matching","519, 547, 638",["Costanzo ch 3","Guyton ch 53"]],"cochlea":["Bending stereocilia let K⁺ in","The cochlea has three fluid-filled ducts. The scala vestibuli and scala tympani hold perilymph, like ECF; the scala media holds endolymph — high K⁺, low Na⁺, made by the stria vascularis.","Base = high pitch, apex = low pitch","547, 548",["Costanzo ch 3","Guyton ch 53"]],"audpath":["Bilateral above the cochlear nuclei","CN VIII ends in the cochlear nuclei of the medulla.","One deaf ear = ear, nerve or cochlear nucleus","",["Costanzo ch 3","Guyton ch 53"]],"vestibular":["Angular vs linear acceleration","The vestibular organ has three perpendicular semicircular canals and two otolith organs, filled with endolymph. Canals sense angular (rotational) acceleration: the cupula in each ampulla is dragged through the endolymph.","Canals = turning · otoliths = tilting and linear motion","548",["Costanzo ch 3","Fundamental Neuroscience ch 22"]],"nystagmus":["Named for the fast phase","When the head rotates, the eyes first drift opposite the rotation to hold gaze (the slow phase), then jump in the direction of rotation (the fast phase).","COWS: cold opposite, warm same","548",["Costanzo ch 3","Fundamental Neuroscience ch 22"]],"dcmltract":["Fine touch, vibration, position — crosses in the medulla","Pressure, vibration, fine touch and conscious proprioception.","Synapse in the medulla, then cross","504, 521, 522, 544",["Fundamental Neuroscience ch 17","Guyton ch 48"]],"stttract":["Synapse in the dorsal horn, cross within a segment or two","Pain and temperature arrive on Aδ and C fibers from free nerve endings.","Ascending tracts synapse then cross","521, 522, 544",["Fundamental Neuroscience ch 18","Guyton ch 49"]],"csttract":["Voluntary movement — crosses at the pyramids","The upper motor neuron starts in the primary motor cortex (precentral gyrus), descends through the posterior limb of the internal capsule and the cerebral peduncle, crosses at the pyramidal decussation in the caudal medulla and runs down the opposite lateral…","Descending tract: cross, then synapse","521, 522, 544",["Fundamental Neuroscience ch 25","Guyton ch 56"]],"accommodation":["Ciliary muscle contracts, the lens rounds up","Focusing on a near object, parasympathetic fibers in CN III contract the ciliary muscle. That relaxes the lens ligaments (zonular fibers), and the elastic lens capsule lets the lens become thicker and more convex — more refractive power.","Near vision = parasympathetic: ciliary muscle contracts, lens rounds","519, 549, 550",["Guyton ch 50","Guyton ch 52"]],"retinacells":["Rods for dim light, cones for color and detail","Light passes through the inner retina to reach the photoreceptors at the back, against the pigment epithelium.","Rods = night · cones = color","192, 549, 552",["Costanzo ch 3","Guyton ch 51"]],"phototrans":["Light closes Na⁺ channels — the photoreceptor hyperpolarizes","Rhodopsin is opsin (a G protein–coupled receptor) plus 11-cis retinal, an aldehyde of vitamin A. Light converts 11-cis to all-trans retinal, forming metarhodopsin II, which activates the G protein transducin.","Light → ↓ cGMP → Na⁺ channels close → hyperpolarization","",["Costanzo ch 3","Guyton ch 51"]],"viscortex":["Retina → LGN → area 17","Ganglion cell axons form the optic nerves; nasal fibers cross at the optic chiasm, so each optic tract carries the opposite visual field to the lateral geniculate body of the thalamus.","Nasal fibers cross","508",["Costanzo ch 3","Guyton ch 52"]],"pharynxanat":["Three parts, a ring of tonsils, two nerves","The pharynx runs from the cranial base to the cricoid cartilage (C6), where it becomes the esophagus — the pharyngoesophageal junction is the narrowest part of the alimentary tract.","Gag reflex: CN IX in, CN X out","519, 638, 690",["Moore ch 8"]],"larynxmus":["Open, close, tense","The vocal folds bound the rima glottidis. Intrinsic laryngeal muscles move the arytenoid cartilages and change the tension and length of the folds — opening the airway for breathing, closing it for phonation and swallowing.","Posterior cricoarytenoid: the only one that opens","638",["Moore ch 8"]],"laryngealnerves":["Superior vs recurrent laryngeal","Both laryngeal nerves come from CN X. The superior laryngeal nerve splits into an internal branch (sensory to the mucosa above the vocal folds) and an external branch (motor to the cricothyroid).","Hoarse after thyroid surgery = recurrent laryngeal nerve","286, 288, 347, 703, 704",["Moore ch 8"]],"swallowing":["Voluntary, then a brainstem reflex, then peristalsis","Swallowing starts voluntarily, then becomes an automatic reflex run by the swallowing (deglutition) center in the medulla and lower pons, carried out through CN V, IX, X and XII.","Primary peristalsis follows the swallow; secondary follows distension","384",["Guyton ch 64","Costanzo ch 8"]],"gaslaws":["Each gas exerts its own share of the pressure","Dalton’s law: in a gas mixture, each gas exerts the pressure it would exert alone, so its partial pressure is the total pressure times its fractional concentration.","Water vapor always takes 47 mm Hg","685",["Costanzo ch 5","Guyton ch 40"]],"respmem":["Thin, vast, and fast","Between alveolar air and the red cell, O₂ and CO₂ cross the respiratory membrane.","Area × pressure difference ÷ thickness","684",["Guyton ch 40","Costanzo ch 5"]],"bronchcirc":["Systemic blood for the lung’s own tissues","The lungs have two circulations.","Bronchial: high pressure, low flow · pulmonary: low pressure, high flow","",["Guyton ch 39","Guyton ch 41"]],"pulmpress":["Low pressure, high compliance","The pulmonary circulation carries the whole cardiac output at about one-fifth of systemic pressure.","25/8, mean 15 · capillary 7 · left atrium 2","300, 684",["Guyton ch 39","Costanzo ch 5"]],"westzones":["Whether capillary pressure beats alveolar air pressure","In an upright lung, gravity adds hydrostatic pressure toward the base and takes it away at the apex: the lung is about 30 cm tall, a 23 mm Hg difference — about 15 mm Hg above the heart and 8 below.","Zone 1 is dead space","685",["Guyton ch 39","Costanzo ch 5"]],"pulmex":["More flow at almost the same pressure","In heavy exercise, pulmonary blood flow can rise 4- to 7-fold while pulmonary arterial pressure barely rises.","Recruit and distend — resistance falls","",["Guyton ch 39","Guyton ch 41"]],"pulmedema":["A safety factor of about 21 mm Hg","Fluid exchange in the lung follows the same Starling forces as other tissues, but the numbers keep the lung dry: capillary pressure is low, interstitial pressure is negative and lymphatics pump continually.","Safety factor ≈ 28 − 7 = 21 mm Hg","316",["Guyton ch 39","Robbins ch 15"]],"pleura":["Lymphatic pumping keeps it negative","A few milliliters of mucoid fluid lie between the visceral and parietal pleura, so the lungs slide easily as they move.","Pleural pressure ≈ −7 mm Hg; collapse pressure ≈ −4","",["Guyton ch 39"]],"tissueo2":["Delivery versus use","In the tissues the gradients run the other way: arterial blood (PO₂ about 95, PCO₂ 40 mm Hg) meets interstitial fluid at a PO₂ of about 40 and a PCO₂ of about 45.","Cells need only 1–3 mm Hg","687",["Guyton ch 41","Guyton ch 40"]],"fxdescribe":["Skin, pieces, alignment, and why it broke","A fracture is a loss of bone integrity from mechanical injury, weakened bone, or both — the commonest pathologic condition of bone. A handful of qualifiers describe each one and steer treatment.","Open = bone meets the outside world → antibiotics + debridement","",["Robbins ch 26","Moore ch 7"]],"fxheal":["Hematoma → soft callus → hard callus → remodel","Torn vessels form a hematoma that seals the fracture and gives a fibrin scaffold for inflammatory cells, fibroblasts and capillaries; platelets and inflammatory cells release PDGF, TGF-β and FGF, which activate osteoprogenitor cells in the periosteum and…","Soft callus ~1 week, bony callus ~2 weeks","",["Robbins ch 26","Pawlina ch 8"]],"salterharris":["The growth plate is weaker than the ligaments around it","In children the physis (growth plate) is weaker than the bone and ligaments around it, and its weakest level is the zone of provisional calcification, so it is a common site of fracture.","I straight across · II above (metaphysis) · III lower (epiphysis) · IV through both · V crushed","",["Moore ch 7","Moore ch 3"]],"clavfx":["Medial fragment up, shoulder drops","The clavicle is one of the most often fractured bones — common in children (and as birth trauma) and in contact and cycling athletes.","Junction of middle and lateral thirds is the weak point","463",["Moore ch 3","Pawlina ch 8"]],"shoulderdisloc":["Anterior, in young athletes — watch the axillary nerve","The glenohumeral joint trades stability for movement, so it dislocates often.","Anterior dislocation → test deltoid sensation","450",["Moore ch 3"]],"elbowinj":["Supracondylar → median nerve · medial epicondyle → ulnar nerve","Children’s elbows break near the distal humerus; adults and children both dislocate it posteriorly. Each bony landmark carries a nerve, so the fracture site predicts the nerve at risk.","Supracondylar → median · medial epicondyle → ulnar","450",["Moore ch 3"]],"forearmfx":["Break one forearm bone, look for a dislocated joint","The radius and ulna are bound together by the interosseous membrane, so a fracture of one is likely to come with dislocation of the nearest joint.","Monteggia: ulna + radial head · Galeazzi: radius + distal radioulnar joint","467",["Moore ch 3"]],"hipfx":["Posterior dislocation shortens and internally rotates; neck fracture externally rotates","The hip is the strongest, most stable joint, so acquired dislocation needs great force, while femoral neck fractures split by age: high-energy impacts in the young, low-energy falls in osteoporotic older women.","Posterior dislocation: shortened, medially rotated · neck fracture: laterally rotated","456, 457, 467",["Moore ch 7"]],"patellainj":["Almost always lateral","When the patella dislocates it nearly always goes laterally, because the quadriceps pulls along the oblique line of the femur. The medial, more horizontal pull of vastus medialis and the forward-projecting lateral femoral condyle normally resist this.","Lateral dislocation, greater Q-angle, vastus medialis resists it","",["Moore ch 7","OCOM Ortho"]],"anklefx":["Inversion of the plantarflexed foot tears the ATFL","The ankle is the most frequently injured major joint, and sprains are the commonest injury. Almost all are inversion injuries of the weight-bearing, plantarflexed foot — stepping on an uneven surface or landing on an inverted foot.","ATFL first — inversion, plantarflexion","458",["Moore ch 7"]],"footfx":["Heel from a height, metatarsals from stress or inversion","Each foot bone breaks in its own typical way.","Inversion → 5th metatarsal avulsion by fibularis brevis","",["Moore ch 7"]],"stressfx":["Too much load, too soon","A stress fracture develops slowly after a period of increased activity in which bone takes repetitive loads faster than it can remodel.","New, repetitive load on unconditioned bone","496",["Robbins ch 26","Moore ch 7"]],"achilles":["An audible snap on push-off","Inflammation of the calcaneal (Achilles) tendon accounts for 9–18% of running injuries: microscopic tears of its collagen, especially just above the calcaneal attachment, cause pain with walking.","Snap on push-off, palpable gap, cannot rise on the toes","",["Moore ch 7"]],"sever":["The Osgood-Schlatter of the heel","Sever disease is the commonest cause of heel pain in children of about 8–15 years: the Achilles tendon pulls repeatedly on the open calcaneal apophysis.","Active child + heel pain + squeeze test","",[]],"flatfoot":["Flexible in children, acquired in adults","A flat sole is normal before about age 3 because of a thick fat pad; the medial longitudinal arch appears as the fat is lost.","Adult-onset flat foot → think tibialis posterior","",["Moore ch 7"]],"clubfoot":["Inverted, plantarflexed, adducted","The common congenital clubfoot (about 2 per 1000 births, boys twice as often, both feet in half) twists the foot at the subtalar joint: the foot is inverted, the ankle plantarflexed (“equino”, like a horse’s hoof) and the forefoot adducted.","Ponseti: cast, cut the Achilles, brace","",["Moore ch 7","Langman ch 12"]],"littleleague":["Throwing through an open growth plate","Repetitive throwing stresses the vulnerable open growth plates of skeletally immature athletes. Overuse, fatigue, poor mechanics, and sport specialization with year-round play and little rest drive these injuries.","Young pitcher + shoulder pain → proximal humeral physis","",["Moore ch 3"]],"bonecells":["Builders, sensors and resorbers","Osteoprogenitor cells from mesenchymal stem cells become osteoblasts, which secrete bone matrix; an osteoblast that has walled itself in with its own matrix is an osteocyte.","Osteoblast builds · osteocyte senses · osteoclast crushes","462",["Pawlina ch 8","Guyton ch 80"]],"compactbone":["Concentric lamellae around a vascular canal","Mature (lamellar) bone is built from osteons (Haversian systems): concentric lamellae of matrix around a central osteonal (Haversian) canal that carries the vessels and nerves.","Haversian canal runs lengthwise · Volkmann canal runs across","461",["Pawlina ch 8"]],"ossification":["With or without a cartilage model","Bones form in one of two ways, distinguished by whether a cartilage model comes first. In intramembranous ossification, mesenchymal cells condense and differentiate directly into osteoblasts.","Membranous: skull, face, mandible, clavicle","461",["Pawlina ch 8"]],"growthplate":["Five zones from cartilage to bone","Bones lengthen at the epiphyseal plate: new cartilage is made on the epiphyseal side and replaced by bone on the diaphyseal side, so the plate stays the same thickness while the bone grows.","Reserve → proliferation → hypertrophy → calcification → resorption","462",["Pawlina ch 8","Guyton ch 76"]],"boneremodel":["Coupled resorption and formation","The adult skeleton is remodeled continually: osteoclasts resorb and osteoblasts rebuild.","RANKL builds osteoclasts; OPG is the decoy","462, 467, 497",["Pawlina ch 8","Robbins ch 26"]],"cartilage":["Same matrix, different fibers","All three cartilages share a hydrated matrix of proteoglycan aggregates (60–80% water) that resists compression; they differ in their fibers.","Hyaline II · elastic II + elastin · fibro I + II","",["Pawlina ch 7"]],"jointtypes":["Fibrous, cartilaginous, synovial","Joints are classed by what unites the bones. Fibrous joints are joined by fibrous tissue, cartilaginous joints by hyaline cartilage or fibrocartilage, and synovial joints by a capsule around a joint cavity — the commonest type, providing free movement.","Elbow = hinge, hip = ball and socket, atlantoaxial = pivot","",["Moore ch 1"]],"synovialjt":["Capsule, synovium, fluid, articular cartilage","In a synovial joint, the bones are united by a joint capsule — an outer fibrous layer lined by a serous synovial membrane — around a joint cavity that is normally a potential space holding a little lubricating synovial fluid, secreted by the synovial membrane.","Synovium secretes the fluid; cartilage takes the load","",["Moore ch 1","Pawlina ch 7"]],"tendonlig":["Parallel collagen for maximum strength","Dense regular connective tissue is the working part of tendons, ligaments and aponeuroses: densely packed collagen fibers in parallel array, little ground substance, and the fiber-making cells lined up between the bundles.","Regular = parallel = tendons and ligaments","",["Pawlina ch 6"]],"movements":["Flexion bends, extension straightens","Movements are named by the plane and axis they occur in. Flexion bends a joint, decreasing the angle between the bones; extension straightens it, increasing the angle — both in sagittal planes around a transverse axis.","Fully inverted = plantarflexed — the position of a sprained ankle","",["Moore ch 1"]],"ghaction":["Builds protein, burns fat, spares glucose","Growth hormone (somatotropin) from the anterior pituitary acts directly on tissues and indirectly through IGF-1 (somatomedin C), made mainly by the liver in response to GH; plasma IGF-1 closely follows GH secretion.","GH → liver → IGF-1","333, 341, 343",["Guyton ch 76","Costanzo ch 9"]],"ghcontrol":["GHRH up, somatostatin down, pulses in deep sleep","GH is released in pulses under two hypothalamic controls: GHRH (44 amino acids, from the arcuate and ventromedial nuclei) stimulates it and somatostatin (14 amino acids, from periventricular neurons) inhibits it.","Sleep, hypoglycemia, stress, puberty, exercise","332, 333",["Guyton ch 76","Costanzo ch 9"]],"posteriorpit":["Made in the hypothalamus, released from nerve endings","ADH (vasopressin) and oxytocin are made in hypothalamic neurons — ADH mainly in the supraoptic nuclei, oxytocin mainly in the paraventricular nuclei — carried down their axons bound to neurophysins, and released from nerve endings in the posterior pituitary…","Supraoptic = ADH · paraventricular = oxytocin","331, 332, 333, 341",["Guyton ch 76","Costanzo ch 9"]],"insulinsecr":["Glucose in, ATP up, K⁺ channel shut, Ca²⁺ in","Blood glucose is the main controller of insulin release. Glucose enters the β cell through GLUT2 at a rate proportional to its blood level; glucokinase phosphorylates it — the rate-limiting step and the glucose sensor — and its metabolism raises ATP.","α₂ lowers, β₂ raises insulin","338",["Guyton ch 79","Costanzo ch 9"]],"insulinact":["Store everything","The insulin receptor is a tetramer of two extracellular α subunits, which bind insulin, and two membrane-spanning β subunits, which then autophosphorylate and act as a tyrosine kinase.","Receptor tyrosine kinase → IRS → GLUT4","338, 341",["Guyton ch 79","Costanzo ch 9"]],"glucagonact":["The hyperglycemic hormone","Glucagon is a 29-amino-acid peptide from the islet α cells. It binds a Gs-coupled receptor on hepatocytes → adenylyl cyclase → cAMP → protein kinase A → phosphorylase kinase → phosphorylase a → glycogen breakdown.","Gs → cAMP → PKA","337, 341",["Guyton ch 79","Costanzo ch 9"]],"pthaction":["Raise calcium, trash phosphate","PTH, an 84-amino-acid peptide from the parathyroid chief cells, raises ionized Ca²⁺ by acting on bone, kidney and (through vitamin D) gut. The N-terminal 1–34 fragment has full activity; the kidney clears intact PTH within minutes but its fragments for hours.","PTH = phosphate-trashing hormone","336, 337",["Guyton ch 80","Costanzo ch 9"]],"calcitriol":["Skin → liver 25 → kidney 1α","Cholecalciferol (vitamin D₃) is made in the skin when ultraviolet light strikes 7-dehydrocholesterol, or comes from food.","Liver 25, kidney 1 — PTH turns on the 1","336, 341",["Guyton ch 80","Costanzo ch 9"]],"calcitonin":["Opposes PTH, but barely matters in adults","1% of the gland), lowers plasma Ca²⁺ by inhibiting osteoclast resorption. Its main stimulus is a rise in ionized Ca²⁺ — the opposite of PTH.","Calcitonin tones down calcium","222, 337",["Guyton ch 80","Pawlina ch 8"]],"ionizedca":["Alkalemia lowers ionized calcium","Plasma calcium exists in three forms: ionized (free) — about 45–50%, the only biologically active form; bound to albumin — about 40%; complexed to anions such as phosphate, sulfate and citrate — the rest.","Alkalosis → tetany","337",["Costanzo ch 9","Costanzo ch 7"]],"cortisolact":["A BIG FIB","Cortisol from the zona fasciculata, carried on corticosteroid-binding globulin, is the body’s main glucocorticoid: it mobilizes fuel, supports blood pressure and restrains inflammation and immunity.","Cortisol is A BIG FIB","340",["Guyton ch 78","Costanzo ch 9"]],"thyroidact":["The 7 B’s","Only free hormone is active. T3 binds the nuclear thyroid receptor with greater affinity than T4 and changes gene transcription. T3 and T4 need specific transporters to enter cells.","Thyroid hormone: the 7 B’s","335",["Guyton ch 77","Costanzo ch 9"]],"psychinterview":["Open-ended first, in a series of funnels","The initial interview gathers what is needed for a criteria-based diagnosis and a person-centered treatment plan.","Open → closed, then open again for each new topic","272",["Kaplan & Sadock ch 1"]],"psychros":["SIGECAPS, mania, CAGE","The psychiatric review of systems screens each major symptom cluster so no disorder is missed, whatever the chief complaint.","SIGECAPS for depression","",["Kaplan & Sadock ch 1","DeGowin ch 15"]],"mse":["The psychiatric physical exam","The mental status examination (MSE) is an objective, cross-sectional snapshot of the patient’s mental functioning at the time of the interview — gathered throughout the interview, from the first moments, by observation and direct questions.","Not fully alert = organic until proven otherwise","",["Kaplan & Sadock ch 1","DeGowin ch 15"]],"moodaffect":["Mood is reported, affect is observed","Mood is the patient’s internal, sustained emotional state — subjective, so best recorded in the patient’s own words (“sad,” “angry,” “anxious”).","Mood = climate (what they say) · affect = weather (what you see)","",["Kaplan & Sadock ch 1"]],"thoughtproc":["How thoughts connect","Thought process describes how ideas are linked, not what they are about. Normal thinking is linear, organized and goal-directed.","Circumstantial gets there · tangential never does · loose never connects","576",["Kaplan & Sadock ch 1"]],"thoughtcont":["What the patient thinks about","Thought content covers preoccupations, obsessions and compulsions, delusions, paranoia, and suicidal and homicidal thoughts.","Delusion = false, fixed, not culturally shared","576",["Kaplan & Sadock ch 1"]],"perception":["No stimulus vs a misread stimulus","Hallucinations are perceptions with no stimulus to account for them; an illusion is a misperception of a real stimulus (hearing the wind in the trees as one’s name being called).","Auditory → psychiatric · visual, tactile, olfactory → think medical","575, 576",["Kaplan & Sadock ch 1","DeGowin ch 15"]],"cogscreen":["Alert? Oriented? Attending? Remembering?","The sensorium and cognition section tests alertness, orientation, concentration, memory and higher functions. Standardized screens help, though none is perfect.","Digit span = attention","",["Kaplan & Sadock ch 1","DeGowin ch 15"]],"violencerisk":["Past violence predicts future violence","When a patient threatens or hints at violence, assess further. A past history of violence is the best predictor of future violence.","History, victim, plan, steps","",["Kaplan & Sadock ch 1"]],"psychformul":["Rule out the medical cause first","Psychiatric symptoms can be primary or can come from another medical condition, a substance or a medication.","Not alert or nonauditory hallucinations → look for organic disease","576",["DeGowin ch 15","Kaplan & Sadock ch 1"]],"childassess":["Several informants, standardized scales","Child assessment pulls information from parents, teachers and the child, and adds standardized rating scales and a focused neurologic and physical exam.","Soft signs are nonfocal","",["Kaplan & Sadock ch 2","Kaplan & Sadock ch 1"]],"acidprod":["CO₂ leaves by the lungs, fixed acid by the kidneys","4) despite large daily acid loads in two forms. Volatile acid is CO₂, the end product of aerobic metabolism (13,000–20,000 mmol/day), which combines with water to form carbonic acid and is breathed out.","Volatile = CO₂ (lungs) · fixed = sulfuric + phosphoric (kidneys)","",["Costanzo ch 7","Guyton ch 31"]],"hhbuffer":["Best within 1 pH unit of the pK","A buffer is a weak acid and its conjugate base; it takes up or releases H⁺ so that pH changes little. The Henderson-Hasselbalch equation, pH = pK + log([A⁻]/[HA]), gives the pH of a buffered solution: when pH equals pK, half the buffer is in each form.","Buffer best at pK ± 1","609",["Costanzo ch 7","Guyton ch 31"]],"intrabuffer":["Deoxyhemoglobin is the better buffer","5) and proteins buffer H⁺. 9) lie in the physiologic range.","H⁺ in, K⁺ out (unless an organic anion goes with it)","",["Costanzo ch 7"]],"hco3reabs":["Recapture all the buffer first","9% of filtered HCO₃⁻ (about 4320 mEq/day at a GFR of 180 L/day) is reabsorbed, mostly in the early proximal tubule.","Angiotensin II drives Na⁺–H⁺ exchange → contraction alkalosis","609, 611",["Costanzo ch 7","Guyton ch 31"]],"newhco3":["Every H⁺ excreted makes a new HCO₃⁻","To excrete the fixed acid made each day, the kidneys secrete H⁺ and send it out on urinary buffers — as titratable acid (mainly phosphate) and as NH₄⁺.","Titratable acid is buffer-limited; NH₄⁺ is adaptable","611",["Costanzo ch 7","Guyton ch 31"]],"abcompensation":["Restore the ratio, not the numbers","Because pH depends on the HCO₃⁻/PCO₂ ratio, each primary disorder triggers a compensating change in the other term. Respiratory compensation for metabolic disorders is immediate; renal compensation for respiratory disorders is delayed (hours to days).","Lungs compensate fast, kidneys slow","609, 610",["Costanzo ch 7","Guyton ch 31"]],"jandamodel":["Stress makes some muscles tight and others weak","Vladimir Janda showed that muscle imbalance is a central nervous system response to stress and chronic overload, not an isolated muscle injury.","Tonic → tight · phasic → weak","",["OCOM OMM","OCOM OMM"]],"recipinhib":["Contract one muscle, relax its antagonist","Sherrington’s law of reciprocal inhibition: when a prime mover contracts — or becomes chronically hypertonic — spinal interneurons inhibit its direct antagonist.","Spindle Ia → excite agonist, inhibit antagonist","461",["Guyton ch 55","OCOM OMM"]],"funcpath":["Normal imaging, abnormal movement","Structural pathology is static, permanent tissue damage — fractures, ligament tears, acute disc herniations, spondylosis, structural scoliosis.","Functional = normal films, abnormal motor firing","",["OCOM OMM"]],"tucs":["A one-sided, three-dimensional upper crossed syndrome","Torsional UCS (TUCS; Morris, Bonnefin and Darville) updates Janda’s two-dimensional, sagittal model into three planes.","One shoulder forward, head tilted to it, tender C2 → look for an MPFL","",["OCOM OMM"]],"posturexam":["Static alignment, then how the muscles fire","Static and dynamic screening shows which muscles are tight and which are inhibited before treatment begins.","Chin should nod first","",["OCOM OMM","OCOM OMM"]],"crossedomt":["Release the tight side first","Step 1 of Janda’s plan releases the hypertonic group with OMT; step 2 resets facilitated segments. The Week 9 lab techniques:","MET: 3–5 s, pause, new barrier, ×3","",["OCOM OMM","OCOM OMM"]],"jandaseq":["Never strengthen a muscle before releasing its antagonist","Janda’s golden sequencing rule: never try to strengthen a weak, inhibited muscle before releasing its tight, hypertonic antagonist.","Release → reset → retrain → integrate","",["OCOM OMM","OCOM OMM"]],"visclisten":["Global pull, then layer by layer","The osteopathic visceral screen assesses the structure–function relationship of the organs. General listening: a hand on the standing patient’s head senses the direction of global fascial pull.","Anterior pull = viscera · posterior = spine/dura","",["OCOM OMM"]],"visctx":["Direct into the barrier, or indirect toward ease","Direct visceral treatment engages the restrictive barrier, guiding the organ or its attachments gently but firmly into tension to lengthen shortened tissue, break fascial adhesions and restore distensibility.","No spleen pump in mono","",["OCOM OMM","OCOM OMM"]],"visclandmarks":["Where to put your hands","Layer palpation of the abdomen depends on knowing where each organ projects onto the surface.","Pylorus 4–5 fingers above the umbilicus · Oddi 2 cm up and right","",["OCOM OMM"]],"visclab":["Supine patient, hold to release, reassess","Every visceral lab technique starts with the indication (a functional visceral component — constipation, postoperative ileus, abdominal discomfort, nausea, vomiting, diarrhea, IBS — or a viscerosomatic reflex) and ends with reassessment.","Liver pump from the right, spleen pump from the left","",["OCOM OMM","OCOM OMM"]],"cardiacomm":["T2–T3 on the left","Cardiac sympathetics come from T1–T6 (nociceptive afferents heaviest at T4).","Reproducible by palpation → chest wall","",["OCOM OMM","Foundations of Osteopathic Medicine ch 43"]],"cardiacomt":["Calm the sympathetics, open the pump","In heart failure, upper thoracic (T1–T6) somatic dysfunction facilitates the cord and drives sympathetic output: arteriolar constriction raises afterload, faster rates shorten filling, and restricted ribs and diaphragm weaken the two-chambered thoracic pump…","Rib raising 1–6 for the heart","",["OCOM OMM","OCOM OMM"]],"thoraciclab":["Position, hold 90 s · contract 3–5 s · thrust at end exhalation","The thoracic review lab treats dysfunctions that may accompany cardiac disease with three techniques.","Counterstrain: 70% relief, 90 s","",["OCOM OMM","OCOM OMM"]],"respmechomm":["The lung is passive — the thorax does the work","The lung parenchyma is passive; skeletal muscle acting on the bony thorax changes its volume. By Boyle’s law, as the thorax enlarges in inspiration, intrathoracic and intrapleural pressures fall below atmospheric and air flows in.","Diaphragm down + ribs up → ↓ intrathoracic pressure → inspiration","",["OCOM OMM","OCOM OMM"]],"copdomm":["Restore the chest wall, not just the lung","Chronic air trapping in COPD keeps the chest from returning to rest: a barrel chest with a larger AP diameter, a flattened diaphragm whose horizontal fibers pull the lower costal margin inward on inspiration (Hoover sign), and respiratory muscles held short…","Barrel chest + Hoover sign = hyperinflation","",["OCOM OMM","OCOM OMM"]],"lungdev":["Week 4 foregut bud; alveoli keep forming for years","At about 4 weeks the respiratory diverticulum (lung bud) grows out of the ventral wall of the foregut, induced by retinoic acid from the adjacent mesoderm switching on TBX4 in the endoderm.","Every Pulmonologist Can See Alveoli","678",["Langman ch 14"]],"lungmalform":["Too little lung, a stray bud, a blocked nose","Pulmonary hypoplasia is a poorly developed bronchial tree with abnormal histology — classically from a congenital diaphragmatic hernia (usually left-sided) or bilateral renal agenesis and oligohydramnios (Potter sequence).","Cyanosis worse when feeding, better when crying","678–679",["Langman ch 14","Robbins ch 15"]],"airwayhisto":["Cartilage rings, then plates, then none","The trachea and bronchi are lined by respiratory epithelium — pseudostratified ciliated columnar epithelium.","Rings → plates → no cartilage","679",["Pawlina ch 19"]],"pneumocytes":["Few cells covering most of the surface","Type I alveolar cells are extremely thin squamous cells that line most of the alveolar surface (95% in Pawlina, 97% in First Aid) yet make up only 40% of the lining cells by number; occluding junctions make them a tight barrier, and they cannot divide.","Type I: 40% of cells, 95% of surface","679",["Pawlina ch 19","Langman ch 14"]],"kidneydev":["Pronephros, mesonephros, metanephros","Three overlapping kidney systems form from intermediate mesoderm in cranial-to-caudal order. The pronephros (7–10 solid cervical cell groups, week 4) is vestigial and gone by the end of week 4.","Ureteric bud → collecting system; blastema → nephron","596",["Langman ch 16"]],"cloacadev":["The urorectal septum splits front from back","During weeks 4–7 the urorectal septum, a wedge of mesoderm between the allantois and the hindgut, grows caudally and divides the cloaca into the urogenital sinus in front and the anorectal canal behind; its tip becomes the perineal body, an anchor for…","Urine from the umbilicus = patent urachus","636",["Langman ch 16","Langman ch 15"]],"nephronhisto":["Filter, then reclaim","The renal corpuscle is the glomerulus (a capillary tuft) plus Bowman capsule.","GBM negative charge = heparan sulfate","598",["Pawlina ch 20"]],"urotract":["An epithelium that stretches but does not leak","Every excretory passage except the urethra has the same three-layer wall: a mucosa lined by transitional epithelium, a muscularis of smooth muscle and an adventitia (serosa in places).","Umbrella cells flatten as the bladder fills","",["Pawlina ch 20","Moore ch 6"]],"neuraxis":["The axis bends at the midbrain","Directional terms give the position of one structure relative to another along the long axis of the CNS (the neuraxis): rostral toward the nose and caudal toward the tail; medial nearer the midline.","T2: water is white","",["Fundamental Neuroscience ch 1"]],"lesionlocal":["One side of the face, the other side of the body = brainstem","Most deficits fall into one of three patterns. Motor or sensory deficits on the same side of the head and body usually mean a lesion in the cerebral hemisphere.","Crossed = brainstem","",["Fundamental Neuroscience ch 1","Fundamental Neuroscience ch 11"]],"brainvesicles":["Three primary vesicles, five secondary","After the anterior neuropore closes, the neural tube forms three primary vesicles: prosencephalon (forebrain), mesencephalon (midbrain) and rhombencephalon (hindbrain).","Pros → tel + di · mes stays · rhomb → met + myel","",["Fundamental Neuroscience ch 5","Fundamental Neuroscience ch 1"]],"cncomponents":["Motor medial, sensory lateral","Brainstem nuclei sort by functional component.","Basal = motor = medial","516",["Fundamental Neuroscience ch 10","Fundamental Neuroscience ch 11"]],"medulla":["Closed below the obex, open above","The medulla oblongata (myelencephalon) is the most caudal brainstem segment, from the foramen magnum, where it is continuous with the cervical cord, to the pons.","XII exits preolivary; IX, X postolivary","515–516",["Fundamental Neuroscience ch 11"]],"pons":["Corticospinal bundles broken up by pontine nuclei","The pons has an anterior basilar pons and a posterior tegmentum.","Facial colliculus = VI nucleus + VII genu","515–516",["Fundamental Neuroscience ch 12"]],"midbrain":["Roof, floor, feet","In cross-section the midbrain has three regions. The tectum (roof), behind the cerebral aqueduct, carries the superior and inferior colliculi (the corpora quadrigemina).","Red nucleus = superior colliculus level","515–516",["Fundamental Neuroscience ch 13"]],"viscafferent":["One neuron from organ to CNS","Visceral sensory fibers are pseudounipolar neurons with cell bodies in posterior root ganglia or in the inferior ganglia of IX and X; they travel with the autonomic nerves (through the white rami) and a single primary neuron carries the signal from the organ…","Visceral nociceptors: stretch & ischemia, not cutting","",["Fundamental Neuroscience ch 19"]],"viscpain":["Dull, diffuse and felt somewhere else","Visceral pain is diffuse and hard to localize: receptor density is low, receptive fields are large and the input converges in the pathway — so pain from the upper abdomen is felt only as “epigastric”.","Referred pain = convergence on shared tract cells","387, 523",["Fundamental Neuroscience ch 19","Foundations of Osteopathic Medicine ch 43"]],"nts":["Taste in front, viscera behind","The solitary tract and nucleus in the medulla receive essentially all visceral afferent input carried by VII, IX and X.","Rostral NTS = gustatory nucleus","516",["Fundamental Neuroscience ch 19","Fundamental Neuroscience ch 23"]],"baroreflex":["Stretch → slow the heart, relax the vessels","Baroreceptors are stretch receptors in the walls of the carotid sinus and aortic arch that respond to rapid rises or falls in blood pressure.","Carotid sinus → IX · aortic arch → X","299",["Guyton ch 18","Fundamental Neuroscience ch 19"]],"autodysreflexia":["A full bladder can trigger a hypertensive crisis","After a spinal cord injury at about T6 or higher, sympathetic reflexes below the lesion lose their descending control and become hyperactive (denervation hypersensitivity also contributes).","Injury at T6 or above + full bladder → hypertensive crisis","",["Fundamental Neuroscience ch 29","Fundamental Neuroscience ch 19"]],"olfactpath":["The only sense that skips the thalamus","The olfactory epithelium covers the roof of the nasal cavity, the superior septum and the superior turbinate.","Smell: no thalamic relay","519",["Fundamental Neuroscience ch 23","Guyton ch 54"]],"smelldisorders":["Most “taste loss” is really smell loss","Anosmia is loss of smell; hyposmia is reduced sensitivity.","Normal taste test + “can’t taste food” = smell problem","508, 656",["Fundamental Neuroscience ch 23"]],"tastepath":["An ipsilateral pathway from tongue to insula","Taste buds sit in papillae. Fungiform papillae (mushroom-shaped, among the nongustatory filiform papillae) carry the buds of the anterior two-thirds of the tongue — chorda tympani of VII.","Anterior 2/3 = VII · posterior 1/3 = IX","364, 519",["Fundamental Neuroscience ch 23","Guyton ch 54"]],"clearratio":["Compare every clearance with inulin","Inulin is freely filtered and neither reabsorbed nor secreted, so its clearance equals GFR — a glomerular marker. Dividing any substance’s clearance by the inulin clearance gives the clearance ratio (Cx/Cinulin), which is also its fractional excretion.","Ratio > 1 = secreted · < 1 = reabsorbed or not filtered","600",["Costanzo ch 6"]],"bunratio":["Urea is reabsorbed; creatinine is not","Both urea and creatinine leave the blood by glomerular filtration, so both rise when GFR falls — which is why BUN and serum creatinine are used to estimate GFR.","BUN:Cr > 20 → think volume","601, 620",["Costanzo ch 6","Robbins ch 20"]],"eabv":["Sodium content sets ECF volume","The body’s Na⁺ content sets the ECF volume; Na⁺ concentration reflects water balance. Positive Na⁺ balance expands the ECF (blood volume, blood pressure, edema, weight gain); negative balance contracts it.","Content → volume · concentration → water","606",["Costanzo ch 6","Guyton ch 30"]],"gtbalance":["The proximal tubule keeps up with GFR","Glomerulotubular balance keeps the proximal tubule reabsorbing a constant fraction — about 67% — of the filtered Na⁺ and water even when GFR changes.","GFR up → filtration fraction up → πc up → reabsorption up","601",["Costanzo ch 6"]],"aldoescape":["Why Conn syndrome causes hypertension but not edema","With excess mineralocorticoid (Conn syndrome), Na⁺ retention is only transient.","Conn: high BP, low K⁺, no edema","299, 354, 606",["Guyton ch 30","Costanzo ch 6"]],"obstructuro":["Concentrating fails first, GFR later","Even with complete obstruction, glomerular filtration continues for a while because the filtrate diffuses back into the renal interstitium and perirenal spaces and returns through lymphatics and veins — which is why the pelvis and calyces dilate.","Obstruction: concentrating defect first","618",["Robbins ch 20"]],"chemsynapse":["Calcium in, vesicle fuses, transmitter out","At a chemical synapse the presynaptic terminal is separated from the postsynaptic cell by a synaptic cleft about 200–300 Å (20–30 nm) wide.","Ca²⁺ → synaptotagmin → SNARE fusion","130, 136",["Fundamental Neuroscience ch 4","Guyton ch 46"]],"rectypes":["Fast channels vs slow second messengers","Transmitter receptors work in one of two ways. Ionotropic receptors are ligand-gated ion channels: the binding site is part of the same protein that forms the pore, so they open within milliseconds.","Ionotropic = fast channel","235, 237",["Fundamental Neuroscience ch 4","Guyton ch 46"]],"psps":["Add up enough EPSPs to reach threshold","An EPSP moves the membrane toward threshold — typically Na⁺ entering through a cation channel. An IPSP moves it away — Cl⁻ entering (GABAA, glycine) or K⁺ leaving.","EPSP = toward threshold · IPSP = away","",["Guyton ch 46","Fundamental Neuroscience ch 4"]],"ntclasses":["Amino acids, amines, peptides, gases & lipids","Most synapses use one of four small-molecule transmitters — glutamate, GABA, glycine or acetylcholine — and are tuned by modulators: the biogenic amines (monoamines) dopamine, norepinephrine, epinephrine and serotonin, plus histamine, and the neuropeptides.","Glutamate excites, GABA and glycine inhibit","505",["Fundamental Neuroscience ch 4","Guyton ch 46"]],"ntclear":["Transporters, enzymes or diffusion","A transmitter’s action ends in one of three ways: reuptake by a membrane transporter into the terminal or glia, enzymatic breakdown in the cleft, or diffusion away.","Amines → reuptake · ACh → esterase · NO → diffusion","",["Fundamental Neuroscience ch 4"]],"synapsedx":["Release, cleft or receptor?","A synaptic disorder is worked out in steps: which synapse and transmitter (neuromuscular junction, autonomic target or central pathway); which step fails or is overdriven — presynaptic release, clearance from the cleft, or the postsynaptic receptor; and the…","Which synapse → which step → which net effect","130, 235",["Fundamental Neuroscience ch 4","Guyton ch 46"]],"motorunit":["The final common pathway","Lower motor neurons in the anterior horn and cranial nerve motor nuclei are the final common path: every descending pathway and spinal reflex acts through them.","Small units first","461",["Fundamental Neuroscience ch 24","Fundamental Neuroscience ch 25"]],"spinalcirc":["Circuits built into the cord","Most descending and reflex input reaches motor neurons through spinal interneurons.","Renshaw cell: axon collateral → inhibits neighboring motor neurons","",["Guyton ch 55","Fundamental Neuroscience ch 24"]],"bsmotor":["Posture and balance from below the cortex","Brainstem pathways control posture, balance and orienting movements. The lateral vestibulospinal tract (lateral vestibular nucleus) descends ipsilaterally through the whole cord and excites antigravity extensors.","Lateral vestibulospinal = ipsilateral extensors","524",["Fundamental Neuroscience ch 24","Fundamental Neuroscience ch 13"]],"motorcortex":["Plan, then execute","Corticospinal fibers arise from six cortical regions.","Leg medial, face lateral","513",["Fundamental Neuroscience ch 25","Guyton ch 56"]],"cstsomato":["Where the leg fibers run","Corticospinal axons converge through the corona radiata into the posterior limb of the internal capsule, somatotopically arranged in about its caudal half: fibers to upper cord levels lie rostral and those to lumbosacral (leg) levels lie caudal.","Capsule: leg fibers caudal · crus: leg lateral","",["Fundamental Neuroscience ch 25"]],"corticonuc":["Most cranial nerve nuclei get both hemispheres","Corticonuclear fibers from the face area of motor cortex reach the motor nuclei of cranial nerves V, VII and XII, the nucleus ambiguus (IX, X) and the accessory nucleus (XI); axons to the trigeminal motor nuclei end on interneurons beside the nuclei.","Lower face: contralateral · upper face: bilateral","546",["Fundamental Neuroscience ch 25"]],"neinetwork":["One network, shared signals","The nervous, endocrine and immune systems work as a single, integrated neuro-endocrine-immune (NEI) network linked by shared signaling molecules and feedback loops.","Pain → hypothalamus → cortisol + sympathetic tone","",["OCOM OMM"]],"omthomeo":["Free the vessels, nerves and lymphatics","Because the body is a unit, reducing somatic dysfunction lowers systemic stress and restores fluid dynamics through three routes described in the course.","Lowest pressure (veins, lymph) collapses first","",["OCOM OMM"]],"immunehomeo":["Healing signals that can turn into a pain cycle","Tissue injury or sustained somatic tension triggers local release of inflammatory mediators — interleukins, substance P, calcitonin gene-related peptide (CGRP), histamine and prostaglandins.","Mediators heal, but chronic accumulation sensitizes","",["OCOM OMM"]],"neiaging":["Shrinking reserve","With normal aging the immune and endocrine systems lose functional reserve (homeostenosis), leaving older adults less able to absorb a stressor.","Older adults: weaker T and B cells, more autoantibodies","",["OCOM OMM"]],"ansomm":["Thoracolumbar vs craniosacral","The autonomic divisions act less as opponents than as cooperative, complementary partners that maintain homeostasis.","No parasympathetics to the limbs","",["OCOM OMM","OCOM OMM"]],"autolevels":["Which segment supplies which organ","The course maps each organ to its sympathetic levels (thoracolumbar outflow T1–L2) and its parasympathetic supply.","Heart: ventricles T1–3, atria T4–5","",["OCOM OMM"]],"reflexhist":["How viscerosomatic reflexes were proven","Osteopathic reflex concepts rest on more than a century of observation and experiment.","Burns 1907: pericardium → T2–T5 spasm","",["OCOM OMM"]],"kneeflow":["Trauma, danger, arthritis, nerve, then the pain generator","The course works up knee pain with history, examination and studies to answer five questions in order: (1) Is the pain related to trauma? (2) Is a dangerous medical condition the cause — fracture, dislocation, infection, vascular injury?","Trauma → danger → arthritis → nerve → pain generator","",["OCOM Ortho","OCOM Ortho"]],"kneeoa":["A clinical diagnosis; exercise and education first","Knee osteoarthritis is diagnosed clinically. The NICE criteria: persistent activity-related pain in one or a few joints, age 45 or older, and morning stiffness lasting 30 minutes or less, without features of an inflammatory arthritis.","Morning stiffness ≤ 30 min, age ≥ 45","472",["OCOM Ortho","Robbins ch 26"]],"pfpsrehab":["Anterior knee pain from a valgus knee","Patellofemoral syndrome (“chondromalacia patella”, “runner’s knee”) is extremely common — 25–40% of all knee problems seen in clinic. It is usually overuse, sometimes a fall onto a flexed knee.","Weak hips → valgus knee → patellofemoral pain","466",["OCOM Ortho"]],"pcllcl":["Usually braced, unless multiligament or avulsion","PCL injuries are relatively uncommon (rugby, wrestling, football, hockey, car crashes) and follow a fall onto a flexed knee with the ankle plantarflexed or forced hyperflexion.","Isolated PCL or grade 2 LCL → brace + PT","454, 464",["OCOM Ortho","Moore ch 7"]],"hipflow":["Image the hip, even for knee pain","Hip pain follows the same five questions as the knee: trauma? a dangerous medical condition (infection, malignancy, fracture)? osteoarthritis or another arthritis?","Hip OA loses internal rotation first","466",["OCOM Ortho"]],"septichip":["The child who won’t bear weight","A septic hip is infection of the femoroacetabular joint: fever, malaise, vomiting, pain with motion, loss of motion, swelling, warmth.","4 of 4 Kocher criteria ≈ 99.6% septic","474",["OCOM Ortho"]],"avnarco":["Catch it before collapse","In avascular necrosis of the femoral head, MRI has near 100% sensitivity and detects disease while plain films are still normal; CT is not favored in children.","Stage I: X-ray normal, MRI abnormal","469",["OCOM Ortho","Robbins ch 26"]],"fingertendon":["Can’t extend the tip vs can’t flex the tip","Mallet finger, the most common finger tendon injury, follows forced flexion of an actively extended fingertip — the extensor tendon tears from the distal phalanx (± a small dorsal avulsion fragment).","Mallet = extensor, splint 6 weeks","",["OCOM Ortho","OCOM Ortho"]],"thumbucl":["A torn thumb UCL that cannot heal on its own","Forced radial deviation (abduction) and hyperextension of the thumb MCP joint ruptures the ulnar collateral ligament — “skier’s thumb” (acute, partial tears most often from skiing; complete tears from falls) or “gamekeeper’s thumb” (chronic degeneration).","Stener = adductor aponeurosis in the way","",["OCOM Ortho","OCOM Ortho"]],"triggerfinger":["A tendon that catches at the A1 pulley","Trigger finger is stenosing flexor tenosynovitis: the flexor tendon catches on its pulley as it glides — usually the A1 pulley at the MCP joint, which thickens, often with a fibrous nodule on the tendon.","A1 pulley at the MCP","",["OCOM Ortho"]],"dislocs":["Check the vessel, the tendon and the syndesmosis","Dislocations are reduced promptly, but each joint has an associated injury that decides the outcome.","Knee dislocation: ABI < 0.9 → CTA","",["OCOM Ortho"]],"lungdefense":["Mucus, cilia, macrophages, neutrophils","Inhaled microbes are normally trapped in the mucous blanket and swept up the mucociliary escalator; organisms reaching the alveoli are phagocytosed by alveolar macrophages, which can also carry them up onto the escalator or recruit neutrophils; complement…","Smoking paralyzes the escalator","680",["Robbins ch 15"]],"lobarstages":["Congestion → red → gray → resolution","Lobar pneumonia (classically S pneumoniae) consolidates a whole lobe and passes through four classic stages.","Red = RBCs + neutrophils + fibrin · gray = RBCs broken down","702",["Robbins ch 15"]],"lungabscess":["Right-sided, single, anaerobic","A lung abscess is a localized area of suppurative necrosis. Aspiration of infected material is the most frequent cause — during altered consciousness (alcohol, seizures, anesthesia, coma) with a depressed cough or gag reflex.","Aspiration → right lung → anaerobes","188, 702",["Robbins ch 15"]],"mycolab":["No wall, slow to grow, sticks with P1","Mycoplasmas are the smallest self-replicating organisms capable of cell-free existence.","No cell wall → no Gram stain, no β-lactams","148",["Robbins ch 15"]],"pneumocarriage":["Most carriers never get sick","S pneumoniae (gram-positive, lancet-shaped diplococci) is the most common cause of community-acquired acute pneumonia, yet it is part of the endogenous flora in about 20% of adults — so organisms on a sputum Gram stain can give a false positive.","PCV removes vaccine types → others move in","125, 134",["Robbins ch 15"]],"deepneck":["Hot-potato voice; watch the mediastinum","A peritonsillar abscess is pus between the tonsillar capsule and the pharyngeal constrictor muscle, closely tied to a preceding acute tonsillitis; incidence peaks in young adult life (15–19 years).","Peritonsillar pus → drain it; neck infection can fall into the mediastinum","691",["Moore ch 8","Robbins ch 16"]],"depspec":["Melancholic, atypical, seasonal, peripartum — or a medical cause","DSM specifiers describe the shape of a depressive episode. With melancholic features: loss of pleasure or of reactivity to pleasure plus severe despair, morning worsening, early waking, psychomotor change, weight loss and excessive guilt.","Melancholic = no pleasure, worse in the morning, guilt","",["Kaplan & Sadock ch 7"]],"pmdd":["Luteal symptoms that vanish with menses","Premenstrual disorders — up to 12% of women — are psychiatric or somatic symptoms in the luteal phase that impair function and resolve shortly after menses.","PMDD: ≥ 5 symptoms, ≥ 1 affective, gone the week after menses","593",["OCOM Psych","Kaplan & Sadock ch 7"]],"deptx":["Hospitalize? How long? Which therapy?","The first decision is whether to hospitalize.","≥ 6 months or the last episode’s length","",["Kaplan & Sadock ch 7","Kaplan & Sadock ch 23"]],"cogbeh":["Change the thoughts, change the behavior","Cognitive therapy (Beck) explains depression by the cognitive triad — negative thoughts about the self, the world and the future.","Triad: self, world, future","",["Kaplan & Sadock ch 23"]],"briefdyn":["Short, focused, for motivated patients","Brief dynamic therapies (Malan, Mann, Davanloo, Sifneos) treat a focal conflict in a limited number of sessions and select patients carefully — high motivation and psychological mindedness are recurring requirements.","Sifneos: circumscribed complaint + oedipal focus","",["Kaplan & Sadock ch 23"]],"forensic":["When the law steps in","All states allow involuntary hospitalization when a patient is a danger to self or others; some also when the patient cannot care for himself or herself (parens patriae).","Duty to protect, not just to warn","",["Kaplan & Sadock ch 28"]],"psyethics":["Beneficence vs autonomy","Paternalism is using the psychiatrist’s judgment about the best course for the patient. Weak paternalism: acting beneficently when the patient’s impaired faculties prevent an autonomous choice.","Weak paternalism = impaired autonomy","",["Kaplan & Sadock ch 27","Kaplan & Sadock ch 28"]],"sexgenes":["SRY → SOX9 → SF1 → AMH · WNT4 → DAX1 ⊣ SOX9","The SRY gene on the short arm of the Y chromosome (Yp11) makes the testis-determining factor, a transcription factor that starts a cascade of downstream genes.","SRY → SOX9 → SF1 → Sertoli, Leydig, AMH","639–640",["Langman ch 16"]],"vaginadev":["Paramesonephric ducts above, urogenital sinus below","The vagina has a dual origin: the upper portion, including the fornices, comes from the paramesonephric (uterine) canal and the lower portion from the urogenital sinus.","Upper vagina = paramesonephric · lower vagina = urogenital sinus","640",["Langman ch 16"]],"testsynth":["LH → cholesterol desmolase … 17β-hydroxysteroid dehydrogenase → testosterone","LH makes Leydig cells synthesize testosterone by increasing the activity of cholesterol desmolase — the first step of the steroid pathway, as ACTH drives it in the adrenal cortex.","Testes: no 21- or 11β-hydroxylase, but 17β-HSD → testosterone","646",["Costanzo ch 10"]],"hptfeedback":["Testosterone ⊣ hypothalamus and pituitary · inhibin ⊣ FSH","Testosterone feeds back on both the hypothalamus and the anterior pituitary, inhibiting GnRH and LH; at the hypothalamus it lowers both the frequency and amplitude of GnRH pulses.","Testosterone suppresses GnRH and LH · inhibin suppresses FSH","646, 655, 674",["Costanzo ch 10"]],"androgenact":["Tissues with 5α-reductase answer to DHT; the rest to testosterone","Some androgen target tissues contain 5α-reductase and respond to dihydrotestosterone; others lack it and respond to testosterone itself. The split explains the 5α-reductase deficiency phenotype and what a 5α-reductase inhibitor does.","Voice, muscle, growth spurt = testosterone · prostate, hair, sebaceous glands = DHT","640, 676",["Costanzo ch 10","Guyton ch 81"]],"steroidrec":["Hormone → receptor → nucleus → dimer on response elements → transcription","Steroid hormones diffuse into the target cell and bind a specific receptor in the cytosol or nucleus.","Receptor + hormone → dimer on DNA → new protein","656, 676",["Costanzo ch 9","Guyton ch 81"]],"gonadpanel":["Read testosterone with LH (and FSH)","Pair testosterone with LH to place the problem. Low testosterone, high LH: hypergonadotropic (primary) hypogonadism — the testis fails. Low testosterone, low LH: hypogonadotropic (secondary) — the hypothalamus or pituitary fails.","Low T + high LH = the testis is the problem","655–656",["Costanzo ch 10","Guyton ch 81"]],"nephrosclerosis":["Arteriolar hyalinization → focal ischemia","Nephrosclerosis is the nonspecific package of glomerulosclerosis, tubulointerstitial scarring, arteriosclerosis and arteriolosclerosis that is strongly associated with hypertension (also with advanced age and African descent, and sometimes seen without…","Grain-leather kidneys of long-standing hypertension","350",["Robbins ch 20"]],"malignephro":["Hyperplastic arteriolosclerosis","Severe (malignant) hypertension means systolic pressure above 180 or diastolic above 120 mm Hg with renal failure and retinal hemorrhages and exudates, with or without papilledema.","Onion-skin arterioles + fibrinoid necrosis = malignant hypertension","",["Robbins ch 20"]],"ahus":["Defective complement regulation injures endothelium","The thrombotic microangiopathies share two triggers: endothelial injury and excessive platelet activation. Shiga toxin–mediated HUS follows food contaminated by Shiga-like toxin–producing E coli or Shigella dysenteriae type 1.","No diarrhea, normal ADAMTS13 = complement","432",["Robbins ch 20"]],"ckdprog":["Fewer nephrons → glomerular hypertension → sclerosis","Once any renal disease destroys enough nephrons to cut GFR to about 30–50% of normal, progression to end-stage kidney disease proceeds at a steady rate, independent of the original insult.","Hyperfiltration of the survivors is what keeps CKD progressing","",["Robbins ch 20"]],"ciliopathy":["Primary cilium senses flow → Ca²⁺ signal restrains proliferation","The favored hypothesis puts the cilium–centrosome complex of tubular epithelial cells at the center of polycystic disease.","Cyst disease = broken flow sensor","622",["Robbins ch 20"]],"nephronoph":["Nephrocystins — a ciliopathy","Nephronophthisis is a group of progressive disorders with medullary cysts concentrated at the corticomedullary junction; as a group it is the most common genetic cause of end-stage kidney disease in children and young adults.","Child with polyuria, small kidneys and corticomedullary cysts","",["Robbins ch 20"]],"medsponge":["Dilated medullary collecting ducts","Medullary sponge kidney is multiple cystic dilations of the collecting ducts in the medulla — relatively common and usually innocuous. It occurs in adults, is usually found radiographically, and renal function is usually normal.","Stones and infections with normal renal function","",["Robbins ch 20"]],"mcdk":["Ureteric bud fails to induce the metanephric mesenchyme","Renal dysplasia is a sporadic disorder, unilateral or bilateral and often cystic: an enlarged, very irregular, multicystic kidney with cysts from millimeters to centimeters lined by flattened epithelium.","Cartilage in a cystic infant kidney","596–597",["Robbins ch 20"]],"lbptriage":["Acute  12 wk","4 °F, immunosuppression, IV drug use, recent indwelling catheter), fracture (osteoporosis, chronic corticosteroids, older age, recent trauma) and malignancy (cancer history, unexplained weight loss, age > 50, no improvement after 1 month of conservative care).","Red flags = cauda equina, infection, fracture, cancer","520",["OCOM OMM","OCOM OMM"]],"discbio":["Endplate diffusion fails → annular fissures → nerve ingrowth","The intervertebral disc is avascular: it gets nutrients only by diffusion from the capillaries of the adjacent vertebral endplates and has no lymphatic scavenger cells.","Outer third of the annulus hurts; the nucleus does not","",["OCOM OMM"]],"lumbarexam":["L4 heel walk · L5 great toe · S1 toe walk","Test L1–S1 to localize root compromise. L4: medial leg and foot · tibialis anterior (ankle dorsiflexion, heel walking) · patellar reflex.","Neck flexion that worsens leg pain = dural tension","458",["OCOM OMM","OCOM OMM"]],"lbpstruct":["History → medical exam → neuro exam → structural exam","The evaluation runs: history with red and yellow flags → general medical exam (vitals; abdominal, genitourinary and leg vascular exams — vascular claudication mimics neurogenic) → neurologic exam → osteopathic structural exam.","Examine the painful region last","",["OCOM OMM","OCOM OMM"]],"lbpomt":["Match the technique to acuity, tolerance and pathology","Technique choice depends on the patient’s age, tolerance, acute versus chronic state and the underlying spinal pathology.","Acute flare → counterstrain · chronic facet stiffness → articulatory","",["OCOM OMM"]],"lbpcontra":["Absolute: no thrust at that region · relative: gentle and indirect, elsewhere","Absolute — no HVLA, and often no manipulation of the region at all: acute vertebral fracture, a medically unstable patient, ruptured or dissecting abdominal aortic aneurysm, bony metastasis at the target segment, acute spinal osteomyelitis or diskitis, cauda…","Metastasis at the segment = absolute","",["OCOM OMM","OCOM OMM"]],"lbpplan":["A 6–8-week conservative trial, then reassess","For nonspecific mechanical low back pain the standard is a 6- to 8-week conservative trial: education, home exercise (knee-to-chest, pelvic tilts, stretching), core stabilization, physical or occupational therapy and judicious OMT — with a written summary…","6–8 weeks conservative · see acute patients again in 2–3 days","",["OCOM OMM"]],"lbpcase":["Knee injury → gait change → sacral torsion → L5 dysfunction","The course case: a 52-year-old man with 3 weeks of right low back pain that began after a left knee meniscus injury made him limp.","Back pain that started with a knee","",["OCOM OMM"]],"orbitwalls":["Four walls of a quadrangular pyramid","The orbit is a quadrangular pyramid with its base anterolateral and apex posteromedial. Roof: orbital part of the frontal bone (lesser wing of the sphenoid near the apex) — separates the orbit from the anterior cranial fossa.","Lamina papyracea = paper-thin medial wall","",["Moore ch 9"]],"orbitapex":["Optic canal medial to the superior orbital fissure","The apex of the orbit is the optic canal in the lesser wing of the sphenoid, just medial to the superior orbital fissure. The optic canal carries the optic nerve and ophthalmic artery.","II in the canal; III, IV, V1, VI in the fissure","",["Moore ch 9"]],"eyelids":["Levator (III) + superior tarsal (sympathetic) open; orbicularis (VII) closes","The tarsi are the dense connective-tissue skeleton of the eyelids.","Two muscles open the lid, one closes it","",["Moore ch 9"]],"lacrimal":["CN VII → pterygopalatine ganglion → lacrimal gland","The lacrimal gland, in the superolateral orbit, secretes lacrimal fluid (saline with lysozyme) through 8–12 ducts into the lateral superior conjunctival fornix.","Tears drain to the inferior meatus","",["Moore ch 9"]],"lidlumps":["Infected gland vs blocked gland vs cancer that mimics both","A hordeolum (sty) is a painful, red, suppurative swelling from acute infection or an obstructed duct of an eyelid gland at the lash line.","Painful = hordeolum · painless = chalazion","559",["Moore ch 9","Robbins ch 29"]],"corneadz":["Bowman layer breaks · endothelial cell loss","Keratoconus (about 1 in 2000) is progressive thinning and ectasia of the cornea without inflammation or vessels — a conical cornea with irregular astigmatism that spectacles correct poorly; rigid contact lenses help, and transplantation works well.","Keratoconus = Bowman layer breaks · Fuchs = guttata and endothelial loss","",["Robbins ch 29"]],"pterygium":["Actinic damage in the interpalpebral fissure","Both are submucosal conjunctival elevations from actinic (sun) damage, so they sit in the interpalpebral fissure. A pinguecula is small and yellowish, astride the limbus but not on the cornea.","Farmer with a triangle growing onto the cornea","",["Robbins ch 29"]],"eyeoptics":["The cornea does most of the bending","The refractive index of a transparent substance is the ratio of the velocity of light in air to its velocity in the substance. Refractive power is measured in diopters: 1 meter divided by the focal length (a lens focusing at 1 m = 1 diopter).","59 D total: cornea two-thirds, lens about 20 D","549",["Guyton ch 50"]],"lensaccom":["Ciliary muscle contracts → zonules slacken → lens rounds up","At rest the suspensory ligaments (zonules) hold the lens fairly flat. Contracting the ciliary muscle relaxes the ligaments, and the elastic lens capsule lets the lens become more spherical — more convex, more refractive power, near focus.","Near vision: ciliary muscle contracts, zonules slacken","550",["Guyton ch 50"]],"aqueous":["Ciliary processes → posterior chamber → pupil → angle → canal of Schlemm","Aqueous humor is formed at about 2–3 µL/min, almost all by active secretion from the epithelium of the ciliary processes: Na⁺ is pumped into the intercellular spaces, pulling Cl⁻ and HCO₃⁻ with it, and water follows by osmosis.","Made by the ciliary processes, drained by the canal of Schlemm","550",["Guyton ch 50"]],"kinchain":["Is the distal segment fixed or free?","Closed kinetic chain: the proximal segment moves on a fixed distal segment (leg press, squats, elliptical walker) — used for shoulder and knee rehabilitation and dynamic stability.","Squat = closed chain · leg extension = open chain","",["OCOM Ortho"]],"exercisetypes":["What the muscle length does during the effort","Concentric: the muscle shortens as it contracts (flexion phase of a biceps or hamstring curl) — builds mass and strength. Eccentric: it contracts while lengthening (extension phase of the curl) — sport-specific strengthening to prevent injury.","Eccentric = contracting while lengthening","",["OCOM Ortho"]],"ptultrasound":["Thermal vs nonthermal effects","Therapeutic ultrasound works through thermal effects (continuous ultrasound heats tissue) and nonthermal effects (pulsed ultrasound is thought to speed healing by altering membrane permeability, ionic concentration gradients and cellular biochemical activity).","Continuous heats; pulsed does not","",["OCOM Ortho"]],"phonoionto":["Drive a drug through the skin with sound or with current","Phonophoresis uses ultrasound to drive topical medications (usually analgesics or steroids) through the skin — a corticosteroid or NSAID mixed into an aqueous base at 10% and applied at 1–2 W/cm²; risk of thermal injury.","Phono = sound · ionto = current","",["OCOM Ortho"]],"estim":["Fire an action potential: muscle contraction or altered sensory input","Electrical stimulation generates an action potential in nerve tissue, causing a muscle contraction or altering sensory input. Electrical muscle stimulation gives isometric activation — for spasm, atrophy and strengthening.","TENS: gate control + endogenous opioids","",["OCOM Ortho"]],"lllt":["Photochemical, not thermal","Low-level laser therapy appears to act through a photochemical rather than thermal effect: cytochrome oxidase may absorb photons in the 600–900 nm range, increasing ATP production and oxidative metabolism; one trial showed lower prostaglandin E2 in…","FDA-approved for carpal tunnel pain","",["OCOM Ortho"]],"ptphases":["Cold and isometrics → heat and isotonics → strengthening","Acute (: cold, electrical stimulation, pulsed ultrasound · isometric exercise and gentle active range of motion · gentle massage.","Acute: cold + isometrics · subacute: heat + isotonics","",["OCOM Ortho"]],"ptrx":["Diagnosis · frequency and duration · protocol · precautions · signature",", three times a week for four weeks), the specific protocols or treatments wanted, safety precautions (range-of-motion and weight-bearing limits, illnesses that affect therapy) and the physician’s signature and date, which the therapist needs before treating.","No frequency, no precautions, no signature → not a complete prescription","",["OCOM Ortho"]],"limbiclobe":["A cortical ring on the medial hemisphere, plus the nuclei and tracts wired to it","The limbic lobe is the cortex on the most medial edge (the limbus) of the hemisphere: from front to back the subcallosal area, the cingulate gyrus and its isthmus, the parahippocampal gyrus and the uncus, plus the hippocampal formation.","Limbic lobe = cortex only · limbic system = cortex plus nuclei and tracts","509",["Fundamental Neuroscience ch 31"]],"papez":["Hippocampus → fornix → mammillary body → anterior thalamus → cingulate → back","Proposed by James Papez in the late 1930s as the anatomic substrate of emotion — emotion mediated through the hypothalamus and controlled by cortical fibers.","Hippocampus → fornix → mammillary body → mammillothalamic tract → anterior thalamus → cingulate → cingulum → entorhinal cortex","524, 575",["Fundamental Neuroscience ch 31"]],"hippoform":["Entorhinal cortex → dentate → CA3 → CA1 → subiculum → fornix","The hippocampal formation is the subiculum, the hippocampus proper (horn of Ammon, fields CA1–CA4) and the dentate gyrus — three-layered allocortex of the medial temporal lobe.","Perforant path in, fornix out","524",["Fundamental Neuroscience ch 31","Fundamental Neuroscience ch 22"]],"memconsol":["Short-term → (hippocampus) → long-term · declarative vs procedural","Immediate (sensory) memory lasts seconds and short-term memory minutes — the 7 to 10 digits of a phone number, held only while you keep thinking about them.","Declarative = knowing that (hippocampus) · procedural = knowing how (cerebellum, basal ganglia)","524",["Guyton ch 58","Fundamental Neuroscience ch 31"]],"amnesia":["Cannot form new memories vs cannot recall old ones","Retrograde amnesia is the inability to remember what happened before a CNS insult; anterograde amnesia is the inability to form new memories after it.","Anterograde = cannot form new · retrograde = cannot recall old","64, 575",["Fundamental Neuroscience ch 31"]],"amygdala":["Tags what matters and drives the fear response through the hypothalamus","The amygdaloid complex is an almond-shaped group of nuclei in the rostromedial temporal lobe, internal to the uncus, just rostral to the hippocampal formation and the tip of the temporal horn.","Amygdala = aversion center · nucleus accumbens = gratification center","524",["Fundamental Neuroscience ch 31","Guyton ch 59"]],"kluverbucy":["Bilateral anterior temporal (amygdala) destruction","Bilateral temporal lobe lesions that largely abolish the amygdaloid complex — first described after temporal lobectomy in monkeys; in people after trauma, temporal lobe surgery for epilepsy, or HSV-1 encephalitis.","Puts the car keys in her mouth after HSV encephalitis","524",["Fundamental Neuroscience ch 31","Guyton ch 59"]],"accumbens":["Ventral tegmental dopamine → accumbens: the gratification center","The nucleus accumbens lies in the rostral, ventral forebrain where the head of the caudate and the putamen meet.","Accumbens = pleasure (dopamine) · amygdala = fear (glutamate)","505, 509",["Fundamental Neuroscience ch 31","Katzung ch 32"]],"septal":["Rostral to the anterior commissure · a two-way highway to the brainstem","The septal nuclei sit just rostral to the anterior commissure in the medial wall of the hemisphere, extending into the base of the septum pellucidum.","Midline septal infarct → rage","",["Fundamental Neuroscience ch 31"]],"lutealshift":["hCG keeps the corpus luteum alive until the placenta takes over","Without fertilization the corpus luteum regresses about 12 days after ovulation and menses follows.","hCG is the LH of pregnancy","651–652",["Guyton ch 83","Costanzo ch 10"]],"fpunit":["Fetal adrenal DHEA-S → fetal liver 16-OH → placenta → estriol","The placenta cannot make estrogens from scratch.","Estriol is a fetal adrenal product finished by the placenta","61, 648, 652",["Costanzo ch 10","Guyton ch 83"]],"p4preg":["Quiets the uterus and feeds the embryo","Progesterone comes in moderate amounts from the corpus luteum early in pregnancy and later in tremendous amounts from the placenta. It is as essential to pregnancy as estrogen.","Progesterone is pro-gestation","648, 651",["Guyton ch 83","Costanzo ch 10"]],"relaxin":["Corpus luteum and placental peptide · a vasodilator","A 48-amino-acid polypeptide secreted by the corpus luteum and placental tissues; hCG increases its secretion.","","",["Guyton ch 83","Costanzo ch 10"]],"hcsmetab":["A weak growth hormone that saves glucose for the fetus","A 22,000-dalton placental protein secreted from about the fifth week and rising throughout pregnancy in proportion to placental weight — in amounts several times greater than all the other pregnancy hormones combined.","The diabetogenic placental hormone","651–652",["Guyton ch 83","Costanzo ch 10"]],"pregglands":["Pituitary up, gonadotropins down","Almost every maternal endocrine gland responds to pregnancy. The anterior pituitary enlarges at least 50% and makes more ACTH, TSH and prolactin, while FSH and LH are almost totally suppressed by placental estrogen and progesterone.","","651",["Guyton ch 83","Costanzo ch 10"]],"geronto":["Normal aging narrows the reserve; disease is something else","Gerontology is the science of the aging process itself; geriatrics is the clinical care of older adults.","Homeostenosis = narrow reserve, narrow margin for error","",["OCOM OMM","OCOM OMM"]],"gerimodels":["Heel lifts, water, breathing rate — the geriatric doses","Homeostenosis changes how each osteopathic model of care is applied to an older patient.","Heel lift in an older adult: ≤ 1/8 inch","",["OCOM OMM","OCOM OMM"]],"gericontra":["Absolute: unstable, infected or cancerous segments · relative: skip the thrust, treat around it","Osteopenia, inflammation and unstable structures change what manual force can safely do in older patients.","","",["OCOM OMM","OCOM OMM"]],"stillsteps":["Ease → compress → through neutral into the barrier → back to neutral","Indications: articular somatic dysfunction with intersegmental restriction and myofascial dysfunction with hypertonicity or fascial bind.","Still goes through the barrier; FPR stays in ease","",["OCOM OMM","Foundations of Osteopathic Medicine ch 56"]],"fprsteps":["Flatten · compress · exaggerate the ease · 3–5 s · neutral","Facilitated positional release is indirect and passive: flatten the regional curve (the cervical lordosis, or the thoracic kyphosis with the patient seated), disengage the spine with compression, exaggerate the named dysfunction — the position of ease — with…","Flatten, compress, ease, hold 3–5 seconds","",["OCOM OMM","OCOM OMM"]],"sarcomakaryo":["Simple: one translocation, young patients · complex: aneuploid chaos, older adults","Sarcomas are malignant mesenchymal tumors thought to arise from mesenchymal stem cells that acquire driver mutations.","Simple karyotype = young patient, one specific translocation","216",["Robbins ch 26"]],"lipoma":["The most common soft tissue tumor of adults","A benign tumor of mature fat and the most common soft tissue tumor in adults. Most solitary lipomas carry rearrangements of chromosome 12q that dysregulate HMGA2, a regulator of chromatin structure.","","216",["Robbins ch 26"]],"liposarcoma":["MDM2 amplification · FUS::DDIT3 · complex karyotype","The most common sarcoma of adulthood, arising in deep soft tissue of the proximal extremities and retroperitoneum in people in their 50s and 60s.","Retroperitoneal fatty mass with MDM2 amplification","216",["Robbins ch 26"]],"nodfasc":["Fast-growing, self-limited, clonal — USP6","A self-limited fibroblastic and myofibroblastic proliferation of young adults, usually on the forearm, chest or back, that grows rapidly over weeks to months; 10–50% follow trauma.","Rapid growth and many mitoses, yet benign","",["Robbins ch 26"]],"fibromatosis":["Superficial: palm, sole, penis · deep: desmoid (Wnt/β-catenin)","Superficial fibromatoses are benign fibroblastic proliferations: Dupuytren contracture (palmar fascia — puckering and a slowly progressive flexion contracture, more common with age), Ledderhose disease (plantar) and Peyronie disease (penile — curvature and…","Desmoid in the abdominal wall of a patient with FAP","465",["Robbins ch 26"]],"rmssarc":["The most common soft tissue sarcoma of childhood","A malignant tumor with skeletal-muscle differentiation.","Grape-like vaginal mass in a toddler = sarcoma botryoides","216, 223, 444, 662",["Robbins ch 26"]],"smoothmuscle":["Benign: uterus and skin · malignant: retroperitoneum and great veins","Leiomyoma arises most often in the uterus (fibroid) but also in skin (pilar leiomyoma, from the erector pili muscles) and deep soft tissue; soft-tissue lesions are 1–2 cm fascicles of eosinophilic spindle cells with blunt-ended nuclei, cured by excision.","","216",["Robbins ch 26"]],"synsarc":["t(X;18) SS18::SSX — not from synovium","Named because early cases sat near the knee, but it does not arise from synovium and shows variable epithelial differentiation. About 10% of soft tissue sarcomas; adolescents and young adults, usually a deep mass in the thigh or leg present for years.","Young adult, deep thigh mass, keratin-positive spindle cells, t(X;18)","",["Robbins ch 26"]],"camdefs":["Alongside conventional care · instead of it · coordinated with it","Complementary health practices are used together with conventional care; alternative means used in place of standard care, a term falling out of favor.","Complementary = alongside · alternative = instead","",["OCOM Ortho"]],"camuse":["Pain is the top reason; meditation the top practice","Eisenberg’s 1993 survey surprised the medical community by showing that more than 30% of Americans used complementary products and practices.","","",["OCOM Ortho"]],"dshea":["DSHEA 1994: no disease claims, only “structure and function”","” The FTC polices false or deceptive advertising.","“Supports joint health” is allowed; “treats arthritis” is not","251, 587",["OCOM Ortho"]],"natprod":["Melatonin, omega-3s, cannabinoids, AREDS antioxidants","Natural products are complex mixtures whose effects also depend on the user’s diet, health and microbiome. ”","","",["OCOM Ortho"]],"mindbody":["Mind-based therapies with trial evidence","Therapies whose main input is mental: conventional psychotherapy such as cognitive behavioral therapy and complementary practices such as meditation, mindfulness-based stress reduction (MBSR) and relaxation techniques, including biofeedback.","First-line treatment of chronic insomnia: CBT-I","",["OCOM Ortho"]],"acupuncture":["Physical input through defined points — best evidence in chronic pain","A family of procedures that stimulate defined anatomic points, usually with thin, solid metal needles manipulated by hand or electrically — part of the major Asian medical traditions.","","",["OCOM Ortho"]],"taichiyoga":["Movement with meditation","Practices that combine physical and psychological input. ” Yoga combines physical postures, breathing and meditation.","Knee OA: tai chi is strongly recommended","",["OCOM Ortho"]],"wholesystems":["Multicomponent systems with their own diagnostic frameworks","Multicomponent “whole health” systems combine several interventions within their own diagnostic and therapeutic framework: traditional Chinese medicine (acupuncture, herbs, massage, exercise, diet), Ayurveda (the East Indian system), naturopathy (low-dose…","","",["OCOM Ortho"]],"glomstarling":["GFR = Kf × [(PGC − PBS) − πGC]","Glomerular filtration is driven by Starling pressures, with the oncotic pressure of Bowman space taken as zero because almost no protein is filtered.","Only the oncotic pressure changes along the glomerular capillary","600–601",["Costanzo ch 6","Guyton ch 27"]],"chargesel":["At equal size: cationic > neutral > anionic","The glomerular capillary wall has three layers: endothelium with 70–100 nm pores (too large to stop proteins, small enough to stop blood cells), the three-layered basement membrane — the most significant barrier to plasma proteins — and podocytes, whose…","A negative barrier repels negative albumin","599",["Costanzo ch 6","Guyton ch 27"]],"nephrontypes":["Short loops in the outer cortex · long loops from the corticomedullary border","Superficial cortical nephrons — the majority — have glomeruli in the outer cortex and short loops of Henle that reach only the outer medulla.","Juxtamedullary = long loops = concentrated urine","",["Costanzo ch 6","Guyton ch 26"]],"fluidmeasure":["Volume = (amount injected − amount excreted) ÷ concentration","A marker spreads into whichever compartment its physical properties allow. After equilibration, volume = amount in the body ÷ plasma concentration, where the amount is what was injected minus what was lost in the urine.","Inject, equilibrate, subtract urine loss, divide","599",["Costanzo ch 6","Guyton ch 25"]],"khandling":["Proximal 67% · thick ascending limb 20% · the distal nephron decides","5 mEq/L), and intake varies from 50 to 150 mEq/day, so urinary excretion must match intake (external K⁺ balance).","The distal nephron adjusts; the proximal tubule just follows the water","609",["Costanzo ch 6","Guyton ch 30"]],"ksecretion":["Secretion follows the apical electrochemical gradient","The basolateral Na⁺-K⁺-ATPase pumps K⁺ into the principal cell; K⁺ then leaves mostly across the luminal membrane through ROMK channels, where permeability and the electrochemical gradient are larger.","Low Mg²⁺ unplugs ROMK","609",["Costanzo ch 6","Guyton ch 30"]],"hifswitch":["O₂ present → PHD hydroxylates HIF-1α → VHL → proteasome","Hypoxia-inducible factors are DNA-binding transcription factors found in virtually all oxygen-breathing species — the body’s “master switch” for hypoxia.","No O₂ → no hydroxylation → HIF survives","539",["Guyton ch 44","Guyton ch 33"]],"alttable":["Barometric pressure falls; the 21% does not","Barometric pressure falls with altitude — 760 mm Hg at sea level, 523 at 10,000 ft, 349 at 20,000 ft and 87 at 50,000 ft — and inspired PO₂ falls with it (159 → 18 mm Hg) while O₂ stays about 21% of the gas.","10,000 ft ≈ 90% saturation","688",["Guyton ch 44","Guyton ch 40"]],"ventresp":["CO₂ is the main controller; O₂ matters only when it falls far","5 have less than a tenth of that effect. O₂ has almost no direct effect on the respiratory center — it acts through the peripheral chemoreceptors.","Acute altitude ≈ 1.65× · acclimatized ≈ 5×","299",["Guyton ch 42","Guyton ch 44"]],"acclim":["More breathing, more red cells, more diffusion, more capillaries, better cells","Days to weeks at altitude bring five adaptations: ① a great increase in pulmonary ventilation, ② more red cells, ③ greater pulmonary diffusing capacity, ④ more vascularity of peripheral tissues, and ⑤ better use of O₂ by the cells.","","688",["Guyton ch 44"]],"altnatives":["Born to it — better than any acclimatized lowlander","People born and living above 13,000 ft in the Andes and Himalayas (one Peruvian group lives at 17,500 ft and works at 19,000 ft) are superior to even the best-acclimatized lowlanders.","","",["Guyton ch 44"]],"altillness":["Rapid ascent above 8,000–9,000 ft","Acute mountain sickness — fatigue, headache, dizziness, nausea and vomiting — can begin a few hours to about 2 days after rapid ascent above 8,000–9,000 ft in unacclimatized people; a few become severely ill and can die unless given O₂ or brought down quickly.","Descend or give O₂","688",["Guyton ch 44"]],"cftrclass":["I none · II misfolded (ΔF508) · III gating · IV conductance · V less · VI unstable","2) is a cAMP/PKA-regulated, ATP-gated anion channel for Cl⁻ and HCO₃⁻ that also inhibits ENaC. , R117H); V reduced amount of normal protein; VI unstable at the membrane.","ΔF508 = class II, stuck in the endoplasmic reticulum","58",["Robbins ch 10"]],"cfcourse":["Exocrine pancreas first, islets later","Exocrine pancreatic insufficiency affects 85–90% of patients (those with two severe alleles): ducts plug, acini atrophy and fibrose, and only islets remain in fibrofatty stroma.","Infertile man with absent vasa deferentia → test for CFTR mutations","58",["Robbins ch 10"]],"cbzones":["Medial, intermediate and lateral zones, each with its own nucleus","Three rostrocaudal zones run through the lobes: medial (vermal), intermediate (paravermal) and lateral (hemisphere). They are defined by their connections, and the deficit after a lesion depends mainly on which zone is hit.","Vestibulo = balance and eyes · spino = trunk and tone · ponto = planning skilled limb movement","510",["Fundamental Neuroscience ch 27","Guyton ch 57"]],"cbpeduncle":["Inferior and middle carry input · superior carries output and crosses","Three pairs of peduncles anchor the cerebellum to the brainstem.","Restiform = rope from the cord · brachium pontis = from the pons · brachium conjunctivum = the way out","510",["Fundamental Neuroscience ch 27"]],"cbcompare":["Compares intended with actual movement and corrects it","The cerebellum takes in a copy of the motor command — the anterior spinocerebellar tract reports what reached the anterior horns, an efference copy — and feedback on what the limbs actually did, compares them, and sends subconscious corrections that raise or…","Uncoordinated, never weak","510",["Guyton ch 57","Fundamental Neuroscience ch 27"]],"cbipsi":["A hemisphere lesion shows on its own side of the body","Cerebellar signs appear on the same side as a hemisphere lesion because the cerebellum acts through the corticospinal and rubrospinal tracts.","Two crossings = same side","510, 524",["Fundamental Neuroscience ch 27"]],"cbataxia":["Falls only with eyes closed = sensory; unsteady with eyes open = cerebellar","Ataxia is uncoordinated movement. The Romberg test checks position sense of the legs and trunk with vision removed: feet together, eyes closed.","Romberg sign = steady eyes open, falls eyes closed → posterior columns","524, 544",["Fundamental Neuroscience ch 33","Fundamental Neuroscience ch 27"]],"cbarteries":["Vertebral gives PICA · basilar gives AICA and SCA","The PICA (from the vertebral artery) supplies the posterolateral medulla including the restiform body, the choroid plexus of the fourth ventricle and the caudomedial inferior cerebellum including the vermis.","PICA → vertebral · AICA, SCA → basilar","518, 526",["Fundamental Neuroscience ch 27","Fundamental Neuroscience ch 8"]],"cbcauses":["Alcohol, posterior fossa tumors and inherited degenerations","Alcohol damages the cerebellum in about 1% of people with alcohol use disorder, giving truncal ataxia, an unsteady gait and nystagmus; granule cells, and in advanced cases Purkinje cells, are lost in the superior anterior vermis, with Bergmann gliosis…","Alcohol → anterior superior vermis → gait and trunk","524",["Robbins ch 28"]],"ccas":["Posterior lobe and vermis lesions change thinking and mood","Patients with disease confined to the cerebellum can show prominent behavioral changes when the posterior lobe and vermis are involved: impaired executive function (planning, set-shifting, verbal fluency, abstract reasoning, working memory), poor spatial…","Cerebellum lesion + flat affect + poor planning, no ataxia needed","",["Fundamental Neuroscience ch 27"]],"duralayers":["Dura · dural border cells · arachnoid barrier · subarachnoid space · pia","The dura (pachymeninx) has a periosteal part stuck to the skull — tenaciously at sutures and the skull base — and a meningeal part, with no clear line between them.","No natural subdural space — blood splits the dural border cells","514",["Fundamental Neuroscience ch 7"]],"duralfolds":["Falx cerebri, tentorium, falx cerebelli, diaphragma sellae","Where the meningeal dura draws away from the periosteal dura it forms rigid infoldings, and the venous sinuses sit where they leave the skull.","Sinuses sit where the folds leave the skull","543",["Fundamental Neuroscience ch 7"]],"sinuses":["Superior sagittal → confluence → transverse → sigmoid → internal jugular","Venous sinuses are endothelium-lined channels between the periosteal and meningeal dura that communicate with one another and receive the cerebral veins and, through the arachnoid villi, the CSF.","SSS → confluence → transverse → sigmoid → IJV","514, 557",["Fundamental Neuroscience ch 7","Fundamental Neuroscience ch 8"]],"cvst":["Clot in a cerebral vein or sinus → congestion, venous infarct, raised pressure","Clots form in the larger veins — superficial cortical or internal cerebral veins — or in the sinuses, most often the transverse (the left more often) or superior sagittal sinus; several sinuses are often involved.","Postpartum or on the pill + headache + papilledema → think venous sinus thrombosis","514",["Fundamental Neuroscience ch 8"]],"csfflow":["Choroid plexus → ventricles → subarachnoid space → arachnoid villi → venous sinus","The choroid plexus of the lateral, third and fourth ventricles makes most CSF by an active, energy-using process: NaCl is actively transported into the ventricle and water follows passively; large molecules ride across in vesicles.","Monro → aqueduct → Luschka and Magendie","515",["Fundamental Neuroscience ch 6","Fundamental Neuroscience ch 7"]],"ventwalls":["The adult neural canal, shaped by the brain around it","The ventricles are the adult form of the neural canal, and each brain vesicle keeps its part: telencephalon → lateral ventricles, diencephalon → third ventricle, mesencephalon → cerebral aqueduct, rhombencephalon → fourth ventricle, spinal cord → central…","Caudate in the lateral wall, hippocampus in the temporal horn","515",["Fundamental Neuroscience ch 6","Fundamental Neuroscience ch 15"]],"lpcsf":["Needle into the lumbar cistern between L3–L4 or L4–L5","A lumbar puncture samples CSF and measures its pressure. The needle enters the lumbar cistern — CSF, the roots of the cauda equina and the filum terminale internum, below the end of the cord — between the third and fourth or fourth and fifth lumbar vertebrae.","Clearing blood = traumatic tap","515",["Fundamental Neuroscience ch 6","Fundamental Neuroscience ch 7"]],"carotidsys":["Cervical · petrous · cavernous · cerebral → ACA and MCA","Blood reaches the brain through the internal carotid and vertebral arteries.","The cerebral ICA gives ophthalmic, PComm, anterior choroidal, then splits into ACA and MCA","514, 518",["Fundamental Neuroscience ch 8"]],"vbsystem":["Two vertebrals join into the basilar at the pontomedullary junction","Each vertebral artery arises from the subclavian artery (V1), climbs through the transverse foramina of C6 to C2 (V2), loops around the atlas to the atlanto-occipital membrane (V3) and pierces the dura (V4); the two join at the pontomedullary junction to…","Brainstem + cerebellum + occipital lobe = vertebrobasilar","514, 518",["Fundamental Neuroscience ch 8"]],"willis":["The anastomotic ring joining the carotid and vertebrobasilar systems","An arterial ring at the base of the brain links the anterior (carotid) and posterior (vertebrobasilar) circulations: the two ACAs joined by the anterior communicating artery, the internal carotids, the posterior communicating arteries and the two PCAs.","ACom joins the ACAs · PCom joins ICA to PCA","514",["Fundamental Neuroscience ch 8"]],"aneursites":["At branch points of the circle of Willis — ACom most of all","About 85% of intracranial aneurysms are on the internal carotid system: anterior communicating artery or its junction with the ACA (30–35%), internal carotid at the posterior communicating artery (25–30%), and the MCA bifurcation (20%).","Blown pupil + ptosis + thunderclap headache → PCom aneurysm","530",["Fundamental Neuroscience ch 8"]],"cerebveins":["Superficial veins to the sinuses · deep veins to Galen and the straight sinus","Veins on the lateral hemisphere drain into the superior sagittal and transverse sinuses and into the large anastomotic veins of Trolard (superior) and Labbé (inferior), which connect those sinuses with the superficial middle cerebral vein — and that vein…","Internal cerebral veins → Galen → straight sinus","514",["Fundamental Neuroscience ch 8"]],"asddx":["Social communication deficits + restricted, repetitive behavior, from early childhood","DSM-5 merged the former autism subtypes into one spectrum with two domains: persistent deficits in social communication and interaction (reciprocity, nonverbal communication such as eye contact and gesture, forming relationships) and restricted, repetitive…","Two domains: social communication + restricted, repetitive","574",["Kaplan & Sadock ch 2"]],"spcd":["Social use of language impaired — without restricted or repetitive behavior","New in DSM-5: persistent difficulty using verbal and nonverbal communication for social purposes without the restricted, repetitive interests and behaviors that define autism.","Autism minus the repetitive behaviors","574",["Kaplan & Sadock ch 2"]],"asdbio":["Heritable, polygenic, with a few known genetic syndromes","Twin studies show strong heritability: concordance 36% in monozygotic vs 0% in dizygotic pairs in one study, about 96% vs 27% in another. Fragile X, the most common inherited cause, is present in 2–3% of people with autism; tuberous sclerosis in up to 2%.","Platelet serotonin is the oldest autism biomarker","574",["Kaplan & Sadock ch 2"]],"asdtx":["Behavioral intervention for the core · risperidone or aripiprazole for irritability","Core symptoms are treated with behavioral and educational programs. The UCLA/Lovaas model is intensive, manualized applied behavior analysis given one-to-one for many hours a week.","Lovaas = intensive one-to-one ABA · ESDM = naturalistic, parent-delivered","574",["Kaplan & Sadock ch 2"]],"adhddx":["6 symptoms (5 from age 17), before 12, in two or more settings","DSM-5 requires symptoms for at least 6 months, present before age 12, in more than one setting, with functional impairment: 6 or more inattentive and/or hyperactive–impulsive symptoms, or 5 or more from age 17.","6 before 17 · 5 from 17","574",["Kaplan & Sadock ch 2"]],"stimmech":["Block DAT and NET · amphetamines also push dopamine out","Methylphenidate and amphetamines block the dopamine and norepinephrine transporters; amphetamines, entering as false substrates, also promote presynaptic efflux of dopamine (da Silva 2023).","Amphetamine = blocker + releaser","574, 589",["Kaplan & Sadock ch 21","Kaplan & Sadock ch 2"]],"stimside":["Meals for appetite · earlier doses for sleep · overlap for rebound","Common stimulant effects are headache, stomachache, nausea, insomnia and reduced appetite.","Appetite → meals · sleep → earlier · rebound → overlap or long-acting","574",["Kaplan & Sadock ch 21","Kaplan & Sadock ch 2"]],"atomox":["Selective norepinephrine reuptake inhibitor with minimal abuse potential","Atomoxetine blocks the norepinephrine transporter.","No abuse potential, boxed warning for suicidality","574",["Kaplan & Sadock ch 2","Kaplan & Sadock ch 21"]],"dsmlogic":["Syndrome + duration + impairment − other causes","There are few specific signs or laboratory tests in psychiatry, so diagnosis rests on a complete history from the patient and collateral informants, and on excluding medical illness (DeGowin).","No impairment → no disorder","576",["DeGowin ch 15","Kaplan & Sadock ch 1"]],"mimics":["Could a medical or substance cause fully explain it?","A psychiatric diagnosis never lowers the probability of organic disease, and delayed diagnosis of medical illness in psychiatric patients is all too common — evaluate both together (DeGowin).","New drug + new symptoms → blame the drug first","576",["DeGowin ch 15","Kaplan & Sadock ch 1"]],"psychreport":["History, MSE, formulation, DSM-5 diagnosis, plan","Kaplan & Sadock’s report runs: identifying data, chief complaint, present illness, past psychiatric history, substance use, medical, family, developmental and social history, review of systems, mental status examination, physical exam, formulation, DSM-5…","Formulation = biologic + psychological + social","576",["Kaplan & Sadock ch 1","DeGowin ch 15"]],"suicideassess":["Every threat taken seriously · safety first · psychiatric evaluation now","Suicide attempts are a common and often fatal outcome of psychiatric illness. Expressed ideation, threats, gestures and attempts are progressively more serious signs of a life-threatening situation.","Ideation → threat → gesture → attempt","579",["DeGowin ch 15","Kaplan & Sadock ch 1"]],"purinecat":["Hypoxanthine → xanthine → uric acid by xanthine oxidase","Uric acid is the end product of purine catabolism. Nucleotides lose their phosphate and ribose; the base from IMP, hypoxanthine, is oxidized by xanthine oxidase to xanthine; guanine is deaminated by guanase to xanthine.","No uricase in humans","35, 473",["Marks ch 39","Robbins ch 26"]],"urateexc":["Most gout is reduced renal excretion","Uric acid is filtered by the glomerulus and almost completely reabsorbed by the proximal tubule; a small fraction is secreted distally and excreted.","90% under-excrete","473",["Robbins ch 26","Katzung ch 36"]],"goutpath":["Crystals → inflammasome → IL-1 → neutrophils","8 mg/dL urate exceeds its solubility, and monosodium urate crystals precipitate in joints.","6.8 mg/dL = saturation","473",["Robbins ch 26","Katzung ch 36"]],"goutclin":["Asymptomatic → acute → intercritical → chronic tophaceous","Robbins’ four stages: asymptomatic hyperuricemia (from puberty in men, after menopause in women); acute arthritis — sudden excruciating pain, warmth and redness, sometimes mild fever, usually one joint, with 50% of first attacks in the first MTP joint…","Podagra = first MTP","473",["Robbins ch 26"]],"goutflare":["Calm the inflammation; urate lowering comes later","Colchicine relieves the pain and inflammation of gouty arthritis in 12–24 hours without changing urate metabolism.","Colchicine = tubulin → no neutrophil migration","473, 46",["Katzung ch 36","Robbins ch 26"]],"cppdpath":["Crystals form in cartilage, then shed into the joint","Unlike urate, calcium pyrophosphate crystals form in hyaline cartilage and fibrocartilage: breakdown of cartilage proteoglycans, which normally inhibit mineralization, lets CPP crystallize around chondrocytes.","Gout crystals in the joint fluid · CPP crystals in the cartilage","473, 402",["Robbins ch 26"]],"hypoxtypes":["Oxygenation · shunt · transport · tissue use","Guyton classifies cellular hypoxia by where the chain breaks: (1) inadequate oxygenation in the lungs — from outside (too little O₂ in the air, hypoventilation from neuromuscular disease) or from lung disease (hypoventilation from high airway resistance or…","Normal PaO₂ does not rule out tissue hypoxia","686, 687",["Guyton ch 43"]],"o2therapy":["Superb for low inspired O₂ and diffusion; little help for transport or use defects","Guyton: in atmospheric hypoxia, O₂ fully corrects the problem. In hypoventilation, breathing 100% O₂ moves five times as much O₂ into the alveoli per breath — very helpful, but it does nothing for the CO₂.","O₂ fixes the air side, not the blood or the cell","686",["Guyton ch 43"]],"hypoxeffect":["Depressed mental activity and reduced work capacity","Severe hypoxia kills cells throughout the body; lesser degrees mainly cause depressed mental activity, sometimes to coma, and reduced work capacity of muscle (Guyton ch 43).","The brain has no anaerobic reserve","686",["Guyton ch 43","Guyton ch 62"]],"hypercap":["Only hypoventilation and circulatory failure retain CO₂","Hypoxia brings hypercapnia only when it is caused by hypoventilation or circulatory deficiency. Low inspired O₂, too little hemoglobin and poisoned oxidative enzymes involve only O₂.","CO₂ diffuses 20× faster than O₂","686",["Guyton ch 43"]],"abgmethod":["pH glass electrode · CO₂ through bicarbonate · O₂ by polarography","Blood gases are measured within a minute from a drop of blood (Guyton). pH: a glass electrode and a reference electrode; the voltage difference is read as pH.","pH glass · CO₂ via bicarbonate pH · O₂ polarography","",["Guyton ch 43"]],"maxflow":["Past a point, more effort collapses the airways as fast as it pushes air","During a forced expiration, flow reaches a maximum that more effort cannot raise: squeezing the chest raises alveolar pressure but compresses the bronchioles by the same amount, so resistance rises as fast as driving pressure (Guyton).","Effort-independent flow","692",["Guyton ch 43"]],"bronchtone":["Circulating epinephrine dilates · vagal acetylcholine constricts","Direct sympathetic control of the bronchioles is weak, because few sympathetic fibers penetrate the central lung; but circulating epinephrine (and norepinephrine) from the adrenal medulla dilates them through β receptors.","β₂ dilates, ACh constricts","237",["Guyton ch 38"]],"coughreflex":["Vagus → medulla → closed glottis, then explosive release","The larynx and carina are the most sensitive to touch; terminal bronchioles and alveoli respond to corrosive gases.","Cough: vagus · sneeze: trigeminal","",["Guyton ch 38","Guyton ch 42"]],"bonezones":["Shaft · flare · growth plate · end","The shaft is the diaphysis: small cross-section, thick cortex. Toward the ends the bone flares into the metaphysis, and the very ends are the epiphyses, where the cross-section is large and the cortex thin.","Diaphysis = shaft · metaphysis = flare","",["OCOM Ortho","OCOM Ortho"]],"pedremodel":["Young, near a growing physis, in the plane of motion → remodels","A growing bone remodels toward adult shape.","Remodels best: young, near the physis, in the plane of the joint","",["OCOM Ortho","OCOM Ortho"]],"kneefx":["Intra-articular — restore the joint surface or arthritis follows","A tibial plateau fracture involves the proximal tibial metaphysis and epiphysis; left uneven, the joint surface wears quickly into post-traumatic arthritis (Practical Office Orthopedics).","Schatzker I–III lateral or central · IV medial · V–VI both plateaus or the shaft","",["OCOM Ortho","OCOM Ortho"]],"tibshaft":["High energy, often open; intramedullary nail in adults","Tibial shaft fractures are about 2% of adult fractures, with peaks around ages 20 and 50, mostly from sports and car collisions and usually high energy (course lecture).","Toddler + new limp + spiral tibial line","",["OCOM Ortho","OCOM Ortho"]],"openfx":["Bone meets the outside world → infection risk","A fracture is open when it communicates with the outside through a laceration or other skin defect. Open fractures carry a high risk of infection and need immediate evaluation (Practical Office Orthopedics).","Antibiotics within 1 hour","",["OCOM Ortho","OCOM Ortho"]],"anklestab":["The higher the fibular fracture, the more likely the syndesmosis is torn","Ankle fractures occur in about 187 per 100,000 people a year, mostly malleolar: 60–70% unimalleolar, 15–20% bimalleolar, 7–12% trimalleolar; young men and women aged 50–70 (course lecture).","Weber A below · B at · C above the syndesmosis","",["OCOM Ortho"]],"eyemovtypes":["Saccade · pursuit · vergence · VOR · optokinetic","Three “targeting” movements put the fovea on a target: saccades (fast jumps to each new target), smooth pursuit (following a moving target) and vergence (changing the angle between the eyes for distance).","Saccade fastest · VOR quickest to start · vergence the only disconjugate one","524",["Fundamental Neuroscience ch 28"]],"hgaze":["PPRF → abducens nucleus → MLF → opposite medial rectus","The paramedian pontine reticular formation (PPRF) is the horizontal gaze center.","Nucleus = gaze palsy · nerve = one muscle · MLF = INO","524, 558",["Fundamental Neuroscience ch 28"]],"pulsestep":["Burst neurons give the pulse · an integrator holds the step","A saccade needs two motor-neuron signals. The pulse — a burst of firing — overcomes orbital viscosity and throws the eye toward the target: burst frequency codes speed, the number of spikes codes amplitude.","Pulse = go there · step = stay there","524",["Fundamental Neuroscience ch 28"]],"vgaze":["Midbrain–diencephalon junction","Vertical gaze palsies come from lesions at the midbrain–diencephalon junction.","Vertical gaze = midbrain · horizontal gaze = pons","542, 558",["Fundamental Neuroscience ch 28"]],"corteye":["Voluntary saccades from cortex · reflexive saccades from the colliculus","Stimulating the cortical eye fields or the superior colliculus triggers contralateral saccades.","Stimulate an eye field → eyes go the opposite way","524",["Fundamental Neuroscience ch 28"]],"pursuitokn":["Cortex → pons → flocculus → vestibular nuclei → eye nuclei","Smooth pursuit follows slow, predictable targets (usually 30 degrees/s or less, up to 100).","Pursuit runs through the flocculus","524",["Fundamental Neuroscience ch 28","Fundamental Neuroscience ch 22"]],"neartriad":["Converge, round the lens, constrict the pupil","Looking from far to near, the eyes converge (both medial recti, a disconjugate movement), the lens rounds up for more refractive power, and the pupil constricts for depth of field — the near triad.","Near triad = converge + accommodate + constrict","",["Fundamental Neuroscience ch 28"]],"pupilpath":["Retina → pretectum → both Edinger-Westphal nuclei → CN III → ciliary ganglion","Luminance-coding retinal ganglion cells project through the optic nerve and tract (about half cross at the chiasm) to the olivary pretectal nucleus, which projects to both Edinger-Westphal nuclei, crossing in the posterior commissure.","Afferent defect = RAPD · efferent (CN III) defect = that pupil never constricts","554",["Fundamental Neuroscience ch 28"]],"cervspond":["Wear and tear of discs, facets and ligaments","Age-related (sometimes post-traumatic) degeneration of the cervical spine: disc degeneration, facet arthropathy, osteophytes, and ossification or hypertrophy of the posterior longitudinal ligament and ligamenta flava.","Spondylosis on films ≠ the cause of the pain","458",["OCOM Ortho"]],"cervradic":["C5 shoulder · C6 thumb · C7 middle finger · C8 little finger","Impaired function of one or more cervical nerve roots from inflammation, ischemia or both — structural or not, often from spondylosis; about 107 per 100,000 men and 64 per 100,000 women.","Spurling: specific, not sensitive","458",["OCOM Ortho","OCOM Ortho"]],"cervmyel":["Hands clumsy, legs stiff, reflexes brisk","Compression of the cervical cord adds upper motor neuron signs to neck pain: weakness, impaired fine hand movement, and spasticity of the arms and legs.","Lhermitte + Hoffman + clumsy hands = cervical cord","458",["OCOM Ortho","OCOM Ortho"]],"backflags":["Most resolve in 6 weeks · look for the dangerous few","Neck and back pain come from trauma and biomechanical injury, degeneration, inflammation, infection (diskitis, meningitis, epidural abscess), infiltration (metastasis, cord tumors) and compression (epidural hematoma or abscess); often no specific cause is…","Under 6 weeks and no red flags → no imaging","458",["OCOM Ortho","OCOM Ortho"]],"mechlbp":["Pain from the spine’s own support structures","Mechanical low back pain arises from the spine, discs or surrounding soft tissues — degenerative or post-traumatic — with a lifetime risk of up to 80%.","Morning stiffness that eases with activity = spondylosis","458",["OCOM Ortho"]],"lumbradic":["Herniated disc or spondylosis pinching a root","Impaired function of one or more lumbar roots — traumatic or insidious, from inflammation or ischemia, sometimes infectious or metabolic (diabetes); the commonest causes are a herniated nucleus pulposus and degenerative spondylosis.","Toe drag = L5","458",["OCOM Ortho"]],"osmobal":["Fixed intracellular protein pulls water in · effectively impermeant Na⁺ outside pulls back","Proteins cannot cross the membrane, and the cell holds about 10 times the protein of the interstitium and 100 times that of CSF.","Pump fails → Na⁺ leaks in → water follows → cell swells","504",["Fundamental Neuroscience ch 3"]],"aquaporins":["Water-only pores","Aquaporins let cells reach osmotic equilibrium quickly: each pore passes single water molecules — about 3 × 10⁹ a second — while excluding all other molecules, making the membrane semipermeable.","Aquaporin = water only, no ions","237, 333",["Fundamental Neuroscience ch 3"]],"restk":["Tandem-pore K⁺ channels set it","At rest the membrane is far more permeable to K⁺ than to Na⁺: tandem-pore (two-pore-domain, K2P) K⁺ channels establish the resting membrane potential.","Resting potential sits near E_K because K⁺ leaks","504",["Fundamental Neuroscience ch 3"]],"ionchanfam":["Voltage, ligand, cyclic-nucleotide, mechanical, acid, temperature","Fundamental Neuroscience’s channel families: voltage-gated Na⁺, K⁺ and Ca²⁺ channels make action potentials and transmitter release; tandem-pore K⁺ channels set the resting potential; CNG (cyclic-nucleotide-gated) channels link smell and vision to voltage;…","HCN = pacemaker · CNG = eyes and nose · Piezo = touch · ASIC = acid","504",["Fundamental Neuroscience ch 3"]],"gradedap":["One decays with distance · the other regenerates","Sensations begin as graded potentials: continuous changes in membrane conductance whose size follows stimulus strength — bigger stimuli, bigger generator potentials, more action potentials.","Graded = local, decremental, summating · AP = all-or-none, propagated","504",["Fundamental Neuroscience ch 3"]],"nachtox":["Use-dependent block vs pore block vs slowed inactivation","Local anesthetics (and some antiarrhythmics and phenytoin) bind a site inside the Na⁺ channel pore reachable only when the channel is open — so the block is use-dependent: the more the channel opens, the more channels are plugged.","TTX: closed channel, outside · local anesthetic: open channel, inside","246",["Fundamental Neuroscience ch 3"]],"demyelin":["Three reasons the action potential fails","Losing myelin, as in multiple sclerosis, interrupts saltatory conduction for three reasons: the internodal membrane has no Na⁺ channels to regenerate the signal; without insulation the internode’s capacitance rises and resistance falls; and K⁺ channels…","Demyelination: no Na⁺ channels in the internode, leaky membrane, exposed K⁺ channels","",["Fundamental Neuroscience ch 3"]],"psyrxchoose":["Pharmacokinetics, pharmacodynamics and the patient’s history","Outcome depends on the drug, the patient and the illness.","Worked before for the patient or family → use it again","",["Kaplan & Sadock ch 21"]],"combaug":["Same indication = combination · different indication = augmentation","Two psychotropics with the same approved indication used together is combination therapy; adding a drug with another indication is augmentation — often a drug not primarily psychotropic, such as thyroid hormone added to an antidepressant.","Thyroid hormone + antidepressant = augmentation","",["Kaplan & Sadock ch 21"]],"txfail":["Diagnosis · side effect or symptom · dose and time · interaction · adherence","Plan the next step before starting, because the drug may not work. Repeated failures prompt reassessment (Kaplan & Sadock): 1 Was the diagnosis right — including an undiagnosed medical condition or recreational drug use?","Before calling it resistant: diagnosis, dose, time, interactions, adherence","",["Kaplan & Sadock ch 21"]],"discont":["Short half-life + abrupt stop = withdrawal","As a rule, the more abruptly a drug is stopped and the shorter its elimination half-life, the more likely clinically significant withdrawal is; with short-acting drugs, withdrawal can follow missed doses or occur between doses.","Paroxetine worst, fluoxetine mildest","",["Kaplan & Sadock ch 21"]],"somcause":["Amplified sensations · a learned request for the sick role","Two models (Kaplan & Sadock).","Amplify the sensation · escape into the sick role","583",["Kaplan & Sadock ch 12"]],"funcsigns":["Findings that don’t fit anatomy","Kaplan & Sadock’s distinctive exam findings in conversion disorder: Hoover test — pressure is felt under the “paralyzed” leg as the other leg lifts; give-away weakness; a “paralyzed” hand dropped toward the face falls beside it, not on it; sensory loss that…","Hoover sign = functional leg weakness","583",["Kaplan & Sadock ch 12"]],"somcare":["One physician · scheduled visits · fewer tests · CBT","Kaplan & Sadock: see patients at regularly scheduled appointments rather than symptom-driven ones, do a brief exam focused on the complaint at each visit, avoid unnecessary diagnostic procedures, invasive treatments and hospitalizations, never say “it’s all…","Scheduled, not symptom-triggered, visits","583",["Kaplan & Sadock ch 12"]],"factcare":["Team meetings · empathic, face-saving · no ambush","Kaplan & Sadock: treat by clinical judgment, remembering subjective complaints may be deceptive; hold regular interdisciplinary meetings to reduce staff conflict and splitting; manage staff countertransference; steer the patient toward psychiatric care in an…","Confront gently, as a team","583",["Kaplan & Sadock ch 12"]],"gcmech":["Cytoplasmic receptor → nucleus → gene transcription","Without hormone, the glucocorticoid receptor sits in the cytoplasm bound to chaperone heat-shock proteins (two hsp90 molecules).","GRE = transactivation · NF-κB/AP-1 = transrepression","119",["Katzung ch 39"]],"gcpotency":["Short · intermediate · long acting","75 mg (long acting) · fludrocortisone 10 : 250, 2 mg (mineralocorticoid).","Dex: long, strong, no salt · fludro: salt","353",["Katzung ch 39"]],"gcmetab":["Catabolic, diabetogenic, anti-inflammatory","Glucocorticoids raise blood glucose through gluconeogenesis and by inhibiting glucose uptake by muscle; they stimulate hormone-sensitive lipase (lipolysis), while the insulin they provoke drives lipogenesis — a net increase in fat deposition with more fatty…","Steroids: ↑ neutrophils, ↓ everything else","353",["Katzung ch 39"]],"gcsupp":["More than 2 weeks of steroids can suppress the HPA axis","Corticosteroids given for more than 2 weeks may suppress the adrenal. After weeks to months of therapy, cover stress: about twice the dose for 24–48 hours for minor stress, up to ten times for 48–72 hours for severe stress such as trauma or major surgery.","On steroids > 2 weeks → stress-dose and taper","248, 353",["Katzung ch 39"]],"vdj":["Cut-and-join gene segments make each receptor unique","Antigen receptors are assembled by V(D)J recombination. The heavy chain (and TCR β) joins D to J first, then V to DJ; light chains (κ, λ) and TCR α join only V and J.","Heavy: VDJ · light: VJ · D–J first","100, 103",["OCOM Rheum","OCOM Rheum"]],"gcenter":["AID drives both","After antigen and T-cell help, B cells in the germinal centers of lymph nodes, Peyer patches and other secondary lymphoid tissue proliferate and undergo somatic hypermutation of their V regions, receptor editing, class-switch recombination, affinity…","AID = hypermutation + switching","103",["OCOM Rheum"]],"tdti":["Why polysaccharide vaccines are conjugated to protein","T-independent antigens activate B cells without T-cell help: TI-1 antigens are polyclonal stimulators, TI-2 antigens are polymers that cross-link the B-cell receptor.","Polysaccharide alone = T-independent, IgM, little memory","103, 109",["OCOM Rheum"]],"lcfield":["Smoke mutates a whole field of mucosa · 3p loss comes first","Tobacco carcinogens mutagenize large areas of the respiratory mucosa at once, so “benign” bronchial epithelium of smokers already carries cancer-gene changes — a field effect.","3p loss in normal-looking smoker bronchus = field effect","703",["Robbins ch 15"]],"lcadeno":["Peripheral · the most common type · targetable mutations","An invasive epithelial tumor with glandular differentiation or mucin. It is now the most common lung cancer in both sexes and the usual type in never-smokers.","Peripheral glandular tumor in a never-smoking woman → think EGFR","703",["Robbins ch 15","Katzung ch 54"]],"lcais":["Graded by invasion: 0 mm · ≤ 5 mm · more","Lung adenocarcinomas are classified by how far they invade. Adenocarcinoma in situ (formerly bronchioloalveolar carcinoma) is ≤ 3 cm and grows only along pre-existing alveolar septa — a pure lepidic pattern with no stromal, vascular or pleural invasion.","Pure lepidic ≤ 3 cm = in situ · ≤ 5 mm invasion = minimally invasive","703",["Robbins ch 15"]],"lcscc":["Central · keratin pearls · p40 · smoking","Strongly tied to smoking and more common in men. It is preceded by squamous metaplasia, dysplasia and carcinoma in situ — a phase that can last years, when atypical cells may appear in sputum while the chest film is normal.","Central hilar mass + hypercalcemia + keratin pearls","703",["Robbins ch 15"]],"lcsclc":["Neuroendocrine · almost all smokers · metastatic at diagnosis","A highly malignant neuroendocrine carcinoma — only about 1% occurs in nonsmokers. There is no known preinvasive phase; it is the most aggressive lung tumor, metastasizes widely and is virtually always fatal.","Central tumor + SIADH or Cushing in a smoker","703",["Robbins ch 15","Katzung ch 54"]],"lclarge":["Undifferentiated vs neuroendocrine — two separate tumors","Large cell carcinoma is an undifferentiated malignant epithelial tumor without the features of the other types — large nuclei, prominent nucleoli, moderate cytoplasm, no glands, no squamous differentiation.","Large cell = no differentiation at all","703",["Robbins ch 15"]],"lccarcinoid":["Low-grade neuroendocrine · polypoid in a mainstem bronchus","Low-grade malignant epithelial neuroendocrine tumors, 1–5% of lung tumors, usually in people under 60, equal in both sexes, and 20–40% nonsmokers.","Young nonsmoker, hemoptysis, smooth pink endobronchial polyp","703",["Robbins ch 15"]],"lctarget":["EGFR TKIs · ALK inhibitors · checkpoint inhibitors","Adenocarcinomas with activating kinase mutations respond to matching inhibitors, which prolong survival; tumors that recur often carry new resistance mutations — proof the drug was hitting its target.","EGFR → osimertinib · ALK → alectinib","446",["Katzung ch 54","Robbins ch 15"]],"lclocal":["What a growing tumor presses on","Any lung carcinoma can reach the pleura and spread in the pleural cavity or pericardium, and most involve bronchial, tracheal or mediastinal nodes.","Shoulder pain + Horner = Pancoast","703, 704",["Robbins ch 15"]],"lcparaneo":["Hormones and antibodies from the tumor","Hormones made by lung cancer cells can cause syndromes before the tumor is visible; clinically significant ones occur in 1–10% of patients.","Small cell: ACTH, ADH, Lambert-Eaton · squamous: PTHrP","224, 352, 703",["Robbins ch 15"]],"lungmets":["The most common lung tumor — multiple peripheral nodules","The lung is the most common site of metastatic neoplasms. Carcinomas and sarcomas from anywhere in the body reach it through blood or lymphatics or by direct extension (esophageal carcinoma, mediastinal lymphoma).","Many round peripheral nodules = metastases","219",["Robbins ch 15","Robbins ch 7"]],"lungbenign":["The uncommon lung tumors","Pulmonary hamartoma is a relatively common benign “coin lesion” found incidentally — solitary, under 3–4 cm, well circumscribed, made of cartilage (most often), fibrous tissue and fat with entrapped respiratory epithelium in clefts.","Popcorn coin lesion with cartilage = hamartoma","703",["Robbins ch 15"]],"pitdev":["Oral ectoderm + diencephalon","The hypophysis develops from two completely different parts: Rathke pouch, an ectodermal outpocketing of the stomodeum (primitive mouth) just in front of the oropharyngeal membrane, and the infundibulum, a downward extension of the diencephalon.","Anterior = oral ectoderm · posterior = neuroectoderm","331",["Langman ch 18"]],"pitportal":["Releasing hormones reach the anterior lobe by portal blood","5–1 g — sits in the sella turcica, a bony cavity at the base of the skull, joined to the hypothalamus by the pituitary (hypophysial) stalk.","Median eminence → portal veins → anterior pituitary","342",["Guyton ch 76"]],"pitstalk":["Dopamine is a brake; everything else needs a push","Almost all pituitary secretion depends on the hypothalamus.","Cut the stalk: everything falls except prolactin","342",["Guyton ch 76","Robbins ch 24"]],"pitcells":["Somatotropes 30–40% · corticotropes 20%","At least five cell types: somatotropes (GH), corticotropes (ACTH), thyrotropes (TSH), gonadotropes (LH and FSH) and lactotropes (prolactin).","Acid PiG: prolactin and GH are acidophils","331",["Guyton ch 76"]],"glycoprot":["Same α chain · β gives specificity","TSH, FSH and LH are glycoproteins of two noncovalently linked subunits, neither active alone. Their α subunits are identical (made from the same mRNA); the β subunit confers biologic specificity.","α common · β specific","331",["Costanzo ch 9","Katzung ch 37"]],"pomc":["One precursor, cut many ways","ACTH, γ- and β-lipotropin, β-endorphin and MSH all come from one precursor, pro-opiomelanocortin (POMC), transcribed from a single gene.","Hyperpigmentation + pituitary mass after bilateral adrenalectomy = Nelson","331",["Costanzo ch 9","Robbins ch 24"]],"hypopit":["Appears after about 75% of the gland is lost","Anterior pituitary hypofunction appears when about 75% of the parenchyma is gone.","Empty sella on MRI = CSF where the pituitary should be","343",["Robbins ch 24","Guyton ch 76"]],"pitnet":["Too much hormone, or a mass in the sella","The most common cause of hyperpituitarism is a pituitary neuroendocrine tumor (PitNET, formerly adenoma) of the anterior lobe, classified by the hormones and transcription factors it expresses.","Bitemporal hemianopsia + headache = sellar mass","343",["Robbins ch 24"]],"ghdwarf":["Proportionate but slow growth","Most dwarfism results from childhood panhypopituitarism: the body develops in proportion but slowly — a 10-year-old may look 4–5 — and without gonadotropins the child does not go through puberty.","GH alone missing → short but sexually mature","333",["Guyton ch 76","Katzung ch 37"]],"ghpulse":["Pulses every ~2 h · biggest in deep sleep · peak at puberty","Growth hormone is secreted in pulses about every 2 hours; the largest burst comes within an hour of falling asleep, in stages III and IV.","GH peaks soon after sleep onset","332",["Costanzo ch 9","Katzung ch 37"]],"phscale":["pH 7.4 = 40 nEq/L","4. Two cautions: as [H⁺] rises, pH falls; and the relation is logarithmic, so equal pH changes are not equal [H⁺] changes.","7.4 ↔ 40 · 7.1 ↔ 80","610",["Costanzo ch 7","Guyton ch 31"]],"buffpk":["Within 1 pH unit of the pK","4. Outside that range, small additions of H⁺ swing the pH widely.","pK ± 1 · plenty of it · CO₂ can leave","609",["Costanzo ch 7","Guyton ch 31"]],"hhcalc":["pH = 6.1 + log(HCO₃⁻ / 0.03 × PCO₂)","03 × PCO₂)), with HCO₃⁻ in mEq/L and PCO₂ in mm Hg. 4.","Ratio 20 : 1 = pH 7.4","609",["Costanzo ch 7","Guyton ch 31"]],"uag":["Na⁺ + K⁺ − Cl⁻","In a normal anion gap (hyperchloremic) metabolic acidosis, the urinary anion gap — urine Na⁺ + K⁺ − Cl⁻ — estimates ammonium excretion, because NH₄⁺ leaves with Cl⁻.","Negative = gut · positive = kidney","610, 611",["Costanzo ch 7"]],"drta":["α-intercalated cells cannot secrete H⁺","5 even when plasma HCO₃⁻ is very low, and hypokalemia.","Can’t acidify the urine, ever","611, 617",["Costanzo ch 7","Guyton ch 31"]],"renalca":["Coupled to Na⁺ until the distal tubule","Only the 60% of plasma Ca²⁺ not bound to protein is filtered; over 99% of the filtered load is reabsorbed. Reabsorption tracks Na⁺ in the proximal tubule and loop and is uncoupled from it only in the distal tubule.","Loop diuretics dump Ca²⁺; thiazides save it","606, 608",["Costanzo ch 6","Guyton ch 30"]],"casr":["High Ca²⁺ shuts off NKCC2","Hypercalcemia binds a Ca²⁺-sensing receptor in the thick ascending limb.","Ca²⁺ high → NKCC2 off → calciuria","349",["Costanzo ch 6"]],"renalpo4":["Na⁺-phosphate cotransport · overflow","About 90% of plasma phosphate is filtered (10% is protein-bound).","Phosphate is a proximal-tubule-only story","606",["Costanzo ch 6","Guyton ch 30"]],"pthneph":["Both through cAMP","PTH binds a basolateral receptor coupled to adenylyl cyclase by a G protein. In the proximal tubule the cAMP cascade inhibits Na⁺-phosphate cotransport (retrieving the cotransporters and lowering the Tm) → phosphaturia.","PTH: phosphate out, calcium in","336, 349",["Costanzo ch 6"]],"renalmg":["25 · 65 · < 5","Unlike Ca²⁺, most Mg²⁺ is reabsorbed in the loop: the proximal tubule takes only about 25%, the thick ascending limb about 65% — mainly paracellular, driven by the lumen-positive voltage, with claudins — and the distal and collecting tubules under 5% by…","Mg²⁺ follows the loop’s voltage","606",["Guyton ch 30","Costanzo ch 6"]],"ckdphos":["Fewer nephrons, phosphate retention","Creatinine and urea rise almost in proportion to the nephrons lost.","PTH can only dump phosphate that is filtered","621, 622",["Guyton ch 32","Costanzo ch 6"]],"respmus":["Diaphragm for quiet breathing · rib raisers for more","Quiet breathing is almost entirely the diaphragm: it contracts to lengthen the chest cavity, and expiration is passive recoil of the lungs and chest wall.","Raise the ribs = inspire","682",["Guyton ch 38"]],"breathpress":["Pleural −5 → −7.5 · alveolar −1 → +1 cm H₂O","With the glottis open and no airflow, every part of the airway is at atmospheric (0) pressure. 5 L in about 2 seconds, then rises to about +1 to push it out.","Transpulmonary = alveolar minus pleural","679",["Guyton ch 38"]],"lungthorax":["200 vs 110 mL / cm H₂O","The lungs alone stretch by about 200 mL for each cm H₂O of transpulmonary pressure.","Chest wall halves the compliance","679",["Guyton ch 38"]],"laplace":["P = 2T / r","Surface tension in an alveolus creates a collapsing pressure P = 2 × surface tension / radius. 5 times as much.","Small alveoli + no surfactant = collapse","679",["Guyton ch 38"]],"wob":["3–5% at rest","The work of inspiration has three parts: compliance (elastic) work to expand the lungs against their recoil, tissue resistance work against the viscosity of lung and chest wall, and airway resistance work.","Breathing is cheap — until the lungs are stiff or narrow","682",["Guyton ch 38"]],"alvvent":["V̇A = rate × (VT − VD) · PaCO₂ ∝ V̇CO₂ / V̇A","Only the air that reaches the gas-exchange areas counts. With a tidal volume of 500 mL, dead space of 150 mL and 12 breaths/min, alveolar ventilation is 12 × (500 − 150) = 4200 mL/min.","Double the ventilation, halve the PaCO₂","683",["Guyton ch 38","Costanzo ch 5"]],"shwork":["Trauma? → intrinsic vs extrinsic → glenohumeral vs not","The course workflow (UpToDate) branches first on a history of trauma.","First question: was there trauma?","",["OCOM Ortho"]],"shextrinsic":["The shoulder hurts but the joint is fine","A shoulder complaint likely comes from outside the shoulder when the pain is vague, diffuse or poorly localized; comes with other symptoms such as dyspnea, abdominal pain or diaphoresis; is sharp, shooting or “electric” and radiates to the neck or down the…","Painless glenohumeral motion + systemic symptoms = look elsewhere","",["OCOM Ortho"]],"shoa":["Anterior, abduction & ER vs superior, adduction & flexion","Osteoarthritis is the most common arthritis of both joints, though both are less often affected than other joints. Most patients are over 70, women more than men.","AC = top of the shoulder, cross-body pain","",["OCOM Ortho"]],"impinge":["Supraspinatus squeezed under the acromion","Impingement traps the cuff — usually the supraspinatus — between the humeral head and the acromion, in the subacromial space, which is extra-articular (outside the capsule).","Overhead pain at night = cuff","451",["OCOM Ortho"]],"rctear":["Partial · full thickness · massive","Rotator cuff injury is impingement or tears — from degenerative tendinopathy or trauma.","Can’t hold the arm up = drop arm","451",["OCOM Ortho"]],"frozen":["Global loss of motion with no other explanation","A gradual, global limitation of shoulder motion in multiple planes with no other explanation. Its pathology is not well understood. Lifetime prevalence 2–5%, peak in the mid-50s; 6–17% get it in the other shoulder.","Diabetic with a stiff shoulder in every direction","",["OCOM Ortho"]],"shextragh":["Focal tenderness outside the joint","An intrinsic cause outside the glenohumeral joint gives focal pain and tenderness outside the joint, and gentle passive glenohumeral motion generally does not hurt.","Point tenderness + painless passive motion = outside the joint","",["OCOM Ortho"]],"edsclass":["Some defect in collagen","The common thread in every Ehlers-Danlos syndrome is an abnormality of collagen — in a structural collagen gene or in an enzyme or matrix protein needed to make and assemble it — so EDS is inherited both dominantly and recessively.","Different step, same broken collagen","48, 49",["Robbins ch 5"]],"edskypho":["No hydroxylysine, no cross-links","The best characterized recessive form and the most common autosomal recessive EDS. Mutations in PLOD1 sharply reduce lysyl hydroxylase, which hydroxylates lysine residues during collagen synthesis.","PLOD1 → lysyl hydroxylase → cross-links","49",["Robbins ch 5"]],"edsproc":["N-terminal propeptide left on","In both, procollagen type I is not converted to collagen: the noncollagen N- and C-terminal domains normally cut off by specific peptidases stay on.","Same step: structural = dominant, enzyme = recessive","49",["Robbins ch 5"]],"edsvasc":["Arteries, bowel and uterus rupture","Vascular EDS comes from abnormal type III collagen.","Thin skin, arterial or bowel rupture = COL3A1","49",["Robbins ch 5"]],"edsclassic":["COL5A1/COL5A2 · TNXB","Most classic EDS carries mutations in the type V collagen genes COL5A1 and COL5A2 (dominant).","Classic = type V collagen","49",["Robbins ch 5"]],"edshyper":["The one form without a known gene","The genetic basis is known in every form of EDS except the hypermobility type (autosomal dominant, gene unknown).","Most common EDS, no gene","49",["Robbins ch 5"]],"vocalize":["Larynx vibrates · mouth shapes · cavities resonate","Speech has two mechanical parts: phonation by the larynx, whose vocal folds act as the vibrator, stretched and positioned by the intrinsic laryngeal muscles; and articulation by the lips, tongue and soft palate.","Larynx makes the tone; the cavities color it","",["Guyton ch 38"]],"vcnodule":["Singer’s nodules — benign, bilateral, hoarse","Reactive nodules (polyps) develop on the true vocal cords, most often in heavy smokers or in people who strain their voices (singer’s nodules).","Bilateral nodules in a singer or teacher","",["Robbins ch 16"]],"chewing":["CN V3 muscles · brainstem rhythm · more surface for enzymes","Most muscles of chewing are innervated by the motor branch of the fifth cranial nerve, and chewing is controlled by brainstem nuclei — stimulating reticular areas near the brainstem taste centers causes rhythmic chewing.","Drop, stretch, rebound — the chewing reflex","",["Guyton ch 64"]],"transthy":["Thyrotoxic, then hypothyroid, then usually normal","Subacute granulomatous (de Quervain) thyroiditis follows a viral illness (coxsackievirus, mumps, measles, adenovirus, SARS-CoV-2), peaks at 40–50, women about 4 : 1.","Painful thyroid after a cold, low uptake = de Quervain","345",["Robbins ch 24"]],"goiter":["Low hormone → high TSH → a bigger gland","Diffuse nontoxic (simple) goiter enlarges the whole gland without nodules; follicles are enlarged and full of colloid. In endemic goiter, low dietary iodine lowers hormone synthesis, TSH rises and drives follicular hypertrophy and hyperplasia.","Iodine deficiency → TSH ↑ → goiter","345, 346",["Robbins ch 24"]],"follneo":["Same cells — only invasion tells them apart","A follicular adenoma is a solitary, circumscribed nodule of uniform follicles, usually with an intact capsule; circumscription without invasion is required for the diagnosis.","Follicular = blood · papillary = lymph","347",["Robbins ch 24"]],"papca":["Most common · Orphan Annie nuclei · nodes","Nearly 85% of thyroid cancers in the United States, usually at 25–50, and most of those linked to prior ionizing radiation.","Psammoma bodies + clear grooved nuclei","347",["Robbins ch 24"]],"anapca":["One of the most aggressive cancers known","Undifferentiated tumors that no longer resemble follicular cells — epithelioid, spindled, pleomorphic or giant-cell rich — often with foci of papillary or follicular carcinoma, consistent with origin from a well-differentiated cancer.","Older patient, neck mass growing over weeks","347",["Robbins ch 24"]],"nkcell":["Kill cells that lose MHC class I","NK cells recognize and destroy severely stressed or abnormal cells — virus-infected and tumor cells. They are 5–10% of blood lymphocytes and express CD16 (an IgG Fc receptor), so they also kill antibody-coated cells (ADCC).","Missing self (MHC I low) = NK target","106",["Robbins ch 6"]],"dendritic":["Catch antigen at the border, present it in the node","Dendritic cells sit under epithelia and in the interstitium of all tissues, capture protein antigens and display peptides to T cells.","DC = the messenger from tissue to node","101",["Robbins ch 6"]],"macrophage":["Blood monocyte → tissue macrophage","Monocytes and neutrophils are the blood phagocytes recruited to infection; monocytes enter tissues and mature into macrophages, the dominant cells of chronic inflammation.","Kupffer · microglia · alveolar macrophage = resident macrophages","97, 101",["Robbins ch 6"]],"prr":["Germline receptors for microbial patterns","Innate receptors are encoded in the germline, the same in every person and every cell that expresses them. Phagocytes, dendritic cells and many epithelial cells use them to sense microbial products (PAMPs) and dead cells.","Germline receptors, same in everyone = innate","97",["Robbins ch 6"]],"innadapt":["Fast and fixed vs slow, specific, and remembered","Innate immunity is always present and reacts immediately: epithelial barriers, phagocytes (neutrophils, macrophages), dendritic cells, NK and other innate lymphoid cells, and plasma proteins such as complement.","Innate: minutes, same every time · adaptive: days, better the second time","97",["Robbins ch 6"]],"effmech":["Pressure · permeability · oncotic · suction · lymph","Normally no more than 15 mL of clear serous fluid lubricates the pleura.","Five ways to fill the pleural space","699",["Robbins ch 15"]],"pleuritis":["Serous → fibrinous → pus","Serous, serofibrinous and fibrinous pleuritis share an inflammatory basis.","Pus in the pleural space = empyema","699",["Robbins ch 15"]],"hydrothorax":["Clear fluid · blood · milky lymph","Hydrothorax is a noninflammatory collection of clear, straw-colored fluid, most often from heart failure (with pulmonary congestion), and also with generalized edema in renal failure or cirrhosis.","Milky pleural fluid = thoracic duct","699",["Robbins ch 15"]],"sft":["Pedunculated · CD34 and STAT6 positive","A soft-tissue tumor that favors the pleura, driven by a NAB2::STAT6 fusion from a cryptic chromosome 12 inversion. It is dense fibrous tissue, often attached to the pleura by a pedicle, from 1–2 cm to enormous, staying on the lung surface.","Pedunculated pleural mass, STAT6+ = solitary fibrous tumor","",["Robbins ch 15"]],"pleuralmets":["Far more common than primary pleural tumors","Secondary tumors of the pleura far outnumber primary ones. The most frequent come from the lung and breast; ovarian carcinomas implant widely in both the abdominal and thoracic cavities.","Pleural tumor? Think metastasis first","699",["Robbins ch 15"]],"insdefic":["Hormone-sensitive lipase on · proteolysis on","Insulin normally activates lipoprotein lipase in adipose capillaries (pulling VLDL fatty acids into fat cells) and inhibits hormone-sensitive lipase, so stored triglyceride stays put.","No insulin: fat out of adipose, amino acids out of muscle","88",["Guyton ch 79"]],"dmdx":["HbA1c ≥ 6.5% · fasting ≥ 126 · 2-hour ≥ 200","5%. Except for a random glucose with classic signs, each needs confirming on a separate day.","6.5 · 126 · 200","350",["Robbins ch 24"]],"bphpath":["Type 2 5α-reductase lives in the stroma","Dihydrotestosterone is the main prostatic androgen, made from testosterone by type 2 5α-reductase, which is expressed in stromal cells, not epithelium.","Stromal DHT drives BPH; finasteride blocks it","672, 673",["Robbins ch 21","Katzung ch 40"]],"hgpin":["Benign glands keep basal cells — cancer loses them","High-grade prostatic intraepithelial neoplasia (HGPIN) is a precursor: large, branching, architecturally benign acini lined by atypical cells with prominent nucleoli, but they still keep at least part of a basal cell layer and an intact basement membrane.","Basal cells present = benign or PIN · absent = cancer","672",["Robbins ch 21"]],"gleason":["Primary pattern + secondary pattern","Prostate cancer is graded by gland pattern. Grade 1: uniform round glands in circumscribed nodules; grade 5: cords, sheets and solid nests infiltrating stroma.","Gleason = sum of the two commonest patterns","672",["Robbins ch 21"]],"calcstone":["Supersaturation · hypercalciuria · uric acid nucleation","Most stones contain calcium — about 70% by Robbins (calcium oxalate, or oxalate with phosphate; First Aid says about 80%).","Uric acid seeds calcium oxalate","617",["Robbins ch 20"]],"semen":["Seminal vesicles ~60% · prostate ~30% · vas deferens ~10%","Each seminal vesicle joins the ampulla of the ductus deferens to form an ejaculatory duct, which runs through the prostate into the prostatic urethra.","Fructose = seminal vesicles · milky, alkaline, PSA = prostate","646, 647",["Guyton ch 81","Pawlina ch 22"]],"rbfnum":["About a quarter of the cardiac output","25 L/min (1800 L/day) by Costanzo. Flow equals the renal artery–vein pressure gradient divided by resistance, set mainly by two arteriole sets in series — afferent and efferent.","Small organs, a quarter of the cardiac output","600",["Guyton ch 27","Costanzo ch 6"]],"myogenic":["Stretch opens Ca²⁺ channels → the afferent arteriole contracts","Higher arterial pressure stretches the afferent arteriole; stretch-activated Ca²⁺ channels open in the smooth muscle, more Ca²⁺ enters, wall tension rises and resistance increases — so renal blood flow and GFR stay constant.","Stretch → Ca²⁺ in → constrict","600",["Costanzo ch 6"]],"tgf":["More NaCl at the macula densa → adenosine → afferent constriction","When GFR rises, more Na⁺ and Cl⁻ reach the macula densa and enter its cells on the Na⁺-K⁺-2Cl⁻ cotransporter.","Macula densa senses NaCl, adenosine squeezes the afferent","600",["Costanzo ch 6"]],"rbfvaso":["Ang II squeezes the efferent most · prostaglandins protect","Constrictors: sympathetic nerves, angiotensin II, endothelin (and NSAIDs, by removing prostaglandins). Dilators: PGE₂, PGI₂, nitric oxide, bradykinin, dopamine, ANP.","Ang II: efferent first · NSAIDs: afferent loses its dilator","600, 601",["Costanzo ch 6"]],"kinternal":["98% of K⁺ is inside cells","About 98% of body K⁺ is intracellular, so a small shift out of cells is large relative to the small extracellular pool.","Most K⁺ is hidden inside cells","608",["Costanzo ch 6"]],"kinsulin":["Na⁺/K⁺-ATPase does the moving","Insulin stimulates Na⁺-K⁺-ATPase and moves K⁺ into cells — physiologically, it clears the K⁺ of a meal into cells. β₂-agonists also drive K⁺ in; β₂-antagonists and α-agonists shift it out, α-antagonists in.","Insulin and β₂ push K⁺ in","608",["Costanzo ch 6"]],"kacid":["H⁺ in, K⁺ out","Intracellular fluid buffers H⁺, but H⁺ cannot cross membranes alone — it needs an accompanying anion or must be exchanged for a cation, which is K⁺.","Acidosis → hyperkalemia (unless the acid brings its own anion)","608",["Costanzo ch 6"]],"kout":["Water drags K⁺ out · broken cells spill it","Hyperosmolarity pulls water out of cells; the intracellular K⁺ concentration rises and K⁺ diffuses out — water flow “drags” K⁺ with it. Cell lysis releases large amounts of K⁺: burns, rhabdomyolysis and tumor cells destroyed by chemotherapy.","Osmolarity, lysis, exercise: K⁺ out","608",["Costanzo ch 6"]],"epiclass":["Simple or stratified · squamous, cuboidal or columnar","Epithelium is named by two features: the number of layers — simple (one) or stratified (two or more) — and the shape of the surface cells: squamous (wider than tall), cuboidal (about equal) or columnar (taller than wide).","Count the layers, look at the top cells","",["Pawlina ch 5"]],"simsq":["One flat layer · exchange and lubrication","One layer of flat cells — ideal for rapid transport across it. Where: the vascular system (endothelium), body cavities (mesothelium), Bowman capsule of the kidney, and the respiratory spaces of the lung.","Flat and single = exchange","",["Pawlina ch 5"]],"simcub":["One layer of cubes · absorption and secretion","One layer of cells about as tall as they are wide. Where: small ducts of exocrine glands, the surface of the ovary (germinal epithelium), kidney tubules and thyroid follicles.","Thyroid follicles and kidney tubules = cuboidal","",["Pawlina ch 5","Robbins ch 21"]],"pseudostrat":["Looks layered · every cell touches the basement membrane","It appears stratified, but every cell rests on the basement membrane; some just do not reach the surface — so it is really a simple epithelium.","Airway lining = pseudostratified ciliated columnar","680",["Pawlina ch 5"]],"strsq":["Many layers, flat on top · protection","Several layers with flat surface cells, typical of surfaces under friction. Where: epidermis (keratinized), oral cavity and esophagus, vagina (nonkeratinized).","Skin keratinized · mouth, esophagus, vagina not","",["Pawlina ch 5"]],"transitional":["Calyces → ureters → bladder → proximal urethra","A stratified epithelium with features that let it distend. Where: the lower urinary tract from the minor calyces to the proximal urethra — renal calyces, ureters, bladder, urethra.","Urinary passages = transitional","",["Pawlina ch 5"]],"apical":["Absorb · absorb or sense · move or sense","Microvilli are finger-like projections on most epithelial cells; their number and shape track absorptive capacity — tall, packed microvilli in absorptive cells.","Microvilli absorb · cilia move · stereocilia are long microvilli","46",["Pawlina ch 5"]],"epimeta":["One mature epithelium replaced by another","Metaplasia is a reversible switch from one mature epithelial type to another, an adaptive response to stress or chronic inflammation produced by reprogramming epithelial stem cells.","Smoker’s bronchus and Barrett esophagus = metaplasia","202",["Pawlina ch 5"]],"ctproper":["Cells and ground substance vs packed collagen","Loose connective tissue: thin, sparse collagen fibers, many cell types and abundant gel-like ground substance through which O₂, nutrients, CO₂ and wastes diffuse to and from small vessels.","Tendon = dense regular · dermis = dense irregular","",["Pawlina ch 6"]],"adipose":["Store energy vs make heat","White adipose tissue is the main type in adults.","Brown fat keeps the newborn warm","76",["Pawlina ch 9","Robbins ch 9"]],"pap":["Macrophages cannot clear surfactant · GM-CSF","A rare disease of defective alveolar macrophage function from deficient GM-CSF signaling: surfactant accumulates in the alveolar and bronchiolar spaces, giving bilateral patchy asymmetric opacities.","Surfactant-filled alveoli + anti-GM-CSF antibodies","",["Robbins ch 15"]],"visstreams":["Magno = fast black-and-white · parvo = color and detail","The dorsal lateral geniculate nucleus has six layers. Layers I and II (magnocellular) receive type M ganglion cells — a rapidly conducting but color-blind pathway with poor point-to-point detail.","Where = dorsal, parietal · what = ventral, temporal","",["Guyton ch 52"]],"ctxlobes":["Six lobes, each bounded by a named sulcus","On the basis of its major sulci the cortex is divided into six lobes: five on the surface — frontal, parietal, temporal, occipital and the limbic lobe on the medial surface — and the insular lobe, hidden inside the lateral sulcus.","Six lobes: four named for skull bones, plus the insula and the limbic lobe","",["Fundamental Neuroscience ch 16"]],"ctxlayers":["Layer IV takes input · layer V sends output","Neocortex has six layers. Layer IV, the internal granular layer of stellate cells, is the main input layer; layer V is the main projection layer.","Sensory cortex: fat layer IV · motor cortex: fat layer V","",["Fundamental Neuroscience ch 32"]],"ctxareas":["Sensory · motor · unimodal · multimodal","Cortex falls into four functional categories: primary sensory, motor, unimodal association and multimodal association cortex. Primary sensory areas (except olfaction) receive thalamocortical fibers from relay nuclei of their own modality.","3-1-2 feel · 4 move · 17 see · 41 hear · 44/45 speak","524, 529",["Fundamental Neuroscience ch 32"]],"ctxwhite":["Within a hemisphere · across · up and down","All fibers linking cortex with other regions pass through the subcortical white matter, which holds three kinds of fibers.","Corpus callosum = the biggest commissure","",["Fundamental Neuroscience ch 16"]],"ctxdominance":["Left hemisphere in almost everyone right-handed","In most people language is processed in the left hemisphere: lesions that impair language are left-sided in about 95% of cases.","Right-handed → left-dominant, almost always","524",["Fundamental Neuroscience ch 32"]],"agnosia":["The sensation is intact; its meaning is lost","Agnosias are higher-level disorders of perception, usually confined to one sense: the patient cannot recognize complex stimuli — faces or letters by sight, tunes or words by sound — although the primary sensation is intact.","Sees the face, cannot say whose it is","526",["Fundamental Neuroscience ch 32","Guyton ch 58"]],"apraxia":["Strength intact, the learned act fails","Apraxia is a disorder of motor control after damage to parietal association cortex, premotor cortex or the supplementary motor area.","Knows the hammer, cannot use it","",["Fundamental Neuroscience ch 32","Fundamental Neuroscience ch 25"]],"prefrontal":["Plans for future operation","The prefrontal association cortex is the large expanse in front of the primary motor and premotor cortices — the other major region of multimodal association cortex.","Prefrontal = the brain’s planner","524",["Fundamental Neuroscience ch 32"]],"aldoaction":["ENaC, Na⁺/K⁺-ATPase and ROMK — after a delay","Aldosterone is lipid-soluble, so it diffuses into tubular epithelial cells and binds a cytoplasmic mineralocorticoid receptor (MR).","Steroid → nucleus → new channels, so slow","339",["Guyton ch 78"]],"aldoctrl":["K⁺ and Ang II strong · ACTH permissive · Na⁺ and ANP brake","Aldosterone secretion by the zona glomerulosa is controlled almost independently of cortisol and androgens. Raised extracellular K⁺ and raised angiotensin II are by far the most potent stimuli — a small percentage rise in K⁺ can increase secretion severalfold.","K⁺ up or Ang II up → aldosterone up","339",["Guyton ch 78"]],"adrandro":["Weak androgens from the zona reticularis","The adrenal cortex continually secretes moderately active male hormones, the most important being dehydroepiandrosterone (DHEA), especially in fetal life.","Women’s pubic and axillary hair = adrenal androgens","339",["Guyton ch 78"]],"adrmed":["About 80% epinephrine · effects last 5–10 times longer","Sympathetic stimulation of the adrenal medullae releases large amounts of epinephrine and norepinephrine into the blood — on average about 80% epinephrine and 20% norepinephrine.","Hormone version of the sympathetic system — slower and longer","234, 355",["Guyton ch 61"]],"catsynth":["Tyrosine → dopa → dopamine → NE → epinephrine","Synthesis begins in the axoplasm and finishes inside the secretory vesicles: tyrosine is hydroxylated to dopa, dopa is decarboxylated to dopamine, dopamine is transported into the vesicles and hydroxylated to norepinephrine.","Methylation is the adrenal’s extra step","82, 331",["Guyton ch 61","Costanzo ch 2"]],"epine":["NE squeezes vessels · epinephrine drives the heart and metabolism","Norepinephrine constricts most vessels, including those of muscle, so it greatly raises total peripheral resistance and arterial pressure.","NE: pressure up, reflex bradycardia · Epi: output up, diastolic may fall","241",["Guyton ch 61","Katzung ch 9"]],"reninrel":["Low pressure · sympathetic · low distal Na⁺ → renin","Renin release from the kidney cortex is stimulated by reduced renal arterial pressure, sympathetic stimulation, and reduced Na⁺ delivery to the distal tubule.","Renin is rate-limiting; ACE lives on endothelium","605",["Katzung ch 11"]],"acei":["Less angiotensin II, more bradykinin","Captopril and the other -prils block peptidyl dipeptidase — the enzyme that converts angiotensin I to II and, as plasma kininase, inactivates bradykinin.","Cough and angioedema = bradykinin","628",["Katzung ch 11","OCOM Nephro"]],"aliskiren":["Blocks the first step","Aliskiren, the first nonpeptide renin inhibitor, binds renin and blocks its action on angiotensinogen, lowering plasma renin activity, angiotensin I and II and aldosterone.","Renin inhibitor: no angiotensin I made","628",["Katzung ch 17","Katzung ch 11"]],"mras":["Block aldosterone at its receptor","Spironolactone and eplerenone bind mineralocorticoid receptors and blunt aldosterone’s action in the collecting tubule; amiloride and triamterene instead block ENaC directly.","Spironolactone → gynecomastia; eplerenone spares it","627",["Katzung ch 15"]],"raasgfr":["Lose angiotensin II, lose efferent tone","Normally angiotensin II helps hold up GFR by constricting the efferent arteriole.","Efferent relaxes → GFR falls","628",["OCOM Nephro","Katzung ch 11"]],"plasmaosm":["2 × Na⁺ + glucose/18 + BUN/2.8","8 (Na⁺ in mEq/L, glucose and BUN in mg/dL). Normal body-fluid osmolarity is about 290 mOsm/L — 300 for simplicity. Osmolarity is per liter of solution; osmolality per kilogram of water, nearly the same in body fluids.","Double the sodium, add the small change","599",["Costanzo ch 6","Guyton ch 25"]],"tonicity":["Only impermeant solute moves water","Isotonic, hypotonic and hypertonic describe what a solution does to cell volume, which depends on its impermeant solute. Isosmotic, hyperosmotic and hypo-osmotic describe only its osmolarity relative to cells, whether or not the solute can enter.","Tonicity = impermeant solute · osmolarity = all solute","599",["Guyton ch 25"]],"hyponat":["Sodium lost, or water gained","Plasma Na⁺ is normally 135–145 mmol/L.","Correct chronic hyponatremia slowly","342, 538",["Guyton ch 25"]],"rapath":["CD4 T cells, cytokines and citrullinated antigens","The autoimmune response is started by CD4⁺ helper T cells reacting against a joint antigen.","Citrulline + HLA-DR4 + smoking","472",["Robbins ch 26"]],"raser":["ACPA is the specific one","Anti-citrullinated peptide antibody (ACPA) is a diagnostic marker found in up to 70% of patients, and with T cells reactive to citrullinated proteins may add to disease severity and persistence.","ACPA specific · RF sensitive but not specific","472",["Robbins ch 26"]],"rapannus":["Villous synovium eats cartilage","The synovium becomes edematous and hyperplastic with delicate bulbous villi.","Pannus → fibrous → bony ankylosis","472",["Robbins ch 26"]],"raclin":["MCP and PIP, morning stiffness · DIP and CMC, worse with use","RA is a symmetric arthritis of small joints first — hands and feet, then wrists, ankles, elbows and knees. In the hand it involves the MCP and PIP joints, unlike osteoarthritis.","RA: MCP + PIP, spares DIP","472, 473",["Robbins ch 26"]],"dmards":["Slow the joint damage, not just the pain","Conventional synthetic DMARDs include methotrexate, azathioprine, hydroxychloroquine, cyclophosphamide, cyclosporine, leflunomide, mycophenolate and sulfasalazine.","Methotrexate first; biologics when it is not enough","496",["Katzung ch 36"]],"suparth":["S. aureus most often · the setting predicts the rest","Bacteria usually reach the joint by hematogenous spread. S. aureus is the most common cause at all ages in the United States. Neonates: group B streptococcus or spread from epiphyseal osteomyelitis.","Hot single joint → tap it","474",["Robbins ch 26","OCOM Rheum"]],"synfluid":["Gram stain, culture, count, crystals — before antibiotics","Before antibiotics, synovial fluid goes for Gram stain, culture, white cell count with differential and crystals, with two sets of blood cultures and radiographs.","Tap before treating","474",["OCOM Rheum"]],"lymearth":["Knee effusions in recurring attacks","Lyme arthritis is a late manifestation, beginning weeks to months after infection; about 30% of US patients present this way, often without a remembered rash.","Big swollen knee in an outdoorsy patient → Lyme serology","144",["OCOM Rheum","Robbins ch 26"]],"mtss":["Diffuse posteromedial tibial pain in runners","Repetitive activity overloads the posterior compartment muscles — tibialis posterior, soleus, flexor digitorum longus — causing a traction periostitis at their origins on the posteromedial tibia, then bone remodeling, a weak cortex, cortical thickening and,…","Diffuse = shin splints · focal = stress fracture","465",["OCOM Ortho"]],"gastroc":["Lunge forward with the ankle dorsiflexed","Injury comes from sudden acceleration from a standstill with the ankle dorsiflexed — lunging forward — an eccentric overstretch, probably as the muscle shifts from eccentric to isometric contraction.","Tennis leg = medial gastrocnemius","",["OCOM Ortho"]],"anklesprain":["Lateral 70–90% · inversion of the plantarflexed foot","Lateral sprains (ATFL, then calcaneofibular and posterior talofibular ligaments) are 70–90% of sprains, from inversion with the foot plantarflexed; the ATFL tears in about 70%.","ATFL first","458",["OCOM Ortho","OCOM Ortho"]],"pttd":["Too many toes · cannot do a single heel raise","A progressive degenerative disease of the tibialis posterior tendon, which runs behind the medial malleolus into the medial arch and stabilizes the hindfoot.","Adult flatfoot = tibialis posterior","",["OCOM Ortho","OCOM Ortho"]],"achtend":["Stretch and load it · never inject it","Achilles tendinopathy (tendinitis, paratendinitis, tendinosis, enthesopathy) can be acute or chronic and insertional or midportion, usually after an increase in activity.","No steroid near the Achilles","",["OCOM Ortho","OCOM Ortho"]],"heelpain":["Heel pain behind the calcaneus — adult bursa or child apophysis","The retrocalcaneal bursa lies between the posterior calcaneus and the Achilles tendon, just above its insertion; its inflammation is strongly tied to Achilles tendinosis and calcaneal enthesopathy.","Child’s heel pain after running = Sever","",["OCOM Ortho"]],"plantarfasc":["First-step heel pain in the morning","The plantar fascia runs from the plantar calcaneus to the metatarsal heads like a bowstring, holding up the arch.","Morning first-step heel pain","465",["OCOM Ortho"]],"legnerves":["Think of them when compartment pressures are normal","Consider a nerve injury when the picture suggests exertional compartment syndrome but pressures are normal. The usual culprits are the common peroneal, superficial peroneal and saphenous nerves; trauma can injure all three.","Normal compartment pressures → think nerve","457",["OCOM Ortho"]],"anxrx":["Start low, go slow, wait 8–12 weeks","SSRIs are first-line for most anxiety disorders (SNRIs too for GAD, panic disorder and social anxiety disorder). Start low and go slow; higher routine doses are not recommended, though a subgroup benefits.","SSRI now, benzo bridge, judge at 8–12 weeks, keep 6 months","580",["Kaplan & Sadock ch 8"]],"gadsadtx":["GAD: SSRI/SNRI · social: SSRI/SNRI or CBT · phobia: exposure","GAD: SSRIs and SNRIs first; alternatives agomelatine, pregabalin, buspirone and quetiapine.","Phobia → exposure, not pills","580, 581",["Kaplan & Sadock ch 8"]],"behavtx":["Change without insight","Behavior therapy assumes change can happen without insight into causes.","Graded exposure + relaxation","",["Kaplan & Sadock ch 8"]],"rad":["Grossly pathologic care → withdrawn or indiscriminately friendly","Both disorders are aberrant social behaviors in a young child that reflect grossly negligent parenting and maltreatment disrupting normal attachment; the diagnosis presumes caregiving deprivation is the cause.","Neglect → withdrawn (RAD) or too friendly with strangers (DSED)","",["Kaplan & Sadock ch 2"]],"macroglos":["Overgrowth, stored material or hormone excess","The tongue enlarges when the whole body overgrows (Beckwith-Wiedemann), when material is stored in it — amyloid, glycogen (Pompe), glycosaminoglycans (hypothyroidism) — or when growth hormone is in excess.","Big tongue: Down, Beckwith-Wiedemann, hypothyroid, acromegaly, amyloid, Pompe","85, 208, 343, 345, 624",["Robbins ch 6","Robbins ch 10"]],"leukoplak":["White or red patches that precede oral cancer","Leukoplakia is a white patch or plaque that cannot be scraped off and fits no other diagnosis; every one is treated as precancerous until a biopsy says otherwise.","White patch in a smoker that will not scrape off = leukoplakia — biopsy it","383",["Robbins ch 16","Bootcamp.com Gastroenterology"]],"hairyleuk":["EBV-driven white plaques on the lateral tongue","EBV drives the squamous cells of the oral mucosa to proliferate in an immunocompromised host, building fluffy, hyperkeratotic white patches.","HIV plus an unscrapable white plaque on the side of the tongue = EBV hairy leukoplakia","173, 487",["Robbins ch 16","Robbins ch 6"]],"tongueanat":["Arch 1 body, arches 3–4 root, somite muscles","The body (anterior two-thirds) grows from two lateral lingual swellings and the tuberculum impar of the 1st arch; the root (posterior third) from the copula of arches 2–4, where the 3rd arch overgrows the 2nd — so IX, not VII, supplies it.","Touch V3/IX, taste VII/IX, motor XII — except palatoglossus (X)","364, 527, 638",["Langman ch 17","Moore ch 9"]],"bifiduvula":["The mildest cleft of the secondary palate","Clefts behind the incisive foramen come from failed fusion of the palatine shelves that build the secondary palate. They range from a cleft of the whole secondary palate down to a split uvula alone — the mildest form.","Forked uvula = the mildest cleft palate","639",["Langman ch 17","Bootcamp.com Gastroenterology"]],"salivaphys":["Hypotonic saliva, run only by nerves","Acini make an isotonic, plasma-like primary saliva; the water-tight ducts then absorb Na⁺ and Cl⁻ and secrete K⁺ and HCO₃⁻, so the final saliva is hypotonic and rich in K⁺ and HCO₃⁻.","Saliva is hypotonic, high in K⁺ and HCO₃⁻","519, 584, 631",["Costanzo ch 8","Guyton ch 65"]],"xerostomia":["Too little saliva — drugs, Sjögren, radiation","Saliva rinses away bacteria and food, buffers acid, and carries lysozyme, thiocyanate, IgA, calcium and phosphate. Without it the mucosa dries, ulcerates and gets infected, and caries run rampant.","Dry mouth and rampant caries after neck radiation or on anticholinergics","239, 240, 243, 474",["Robbins ch 16","Guyton ch 65"]],"epidcells":["Keratinocytes plus three resident minorities","Keratinocytes, about 85% of epidermal cells, build the keratin barrier and are glued together by desmosomes. Three minority cells live among them: melanocytes make pigment, Langerhans cells catch antigen, and Merkel cells sense touch.","Same melanocyte count in every skin color — melanosomes differ","101, 138, 484, 504",["Pawlina ch 15","Robbins ch 25"]],"lesprim":["Flat or raised, solid or fluid, above or below 1 cm","Most lesion words answer two questions: is it flat or raised, and is it solid, fluid-filled or transient? The 1 cm mark then splits the small word from the large one.","Flat = macule or patch · raised = papule, plaque or nodule · fluid = vesicle or bulla","483",["Robbins ch 25","Bootcamp.com Dermatology"]],"lessec":["Shedding, drying, scratching and tissue loss","These words describe what has happened to the surface: shed keratin (scale), dried exudate (crust), damage from scratching and rubbing, and loss of tissue — graded by whether the basement membrane is exposed.","Erosion spares the basement membrane; an ulcer goes through it","483, 487",["Robbins ch 25","Bootcamp.com Dermatology"]],"dermmicro":["Which epidermal layer is changed, and how","Each term names a change in one layer of the epidermis: too much stratum corneum, nuclei kept where they should be lost, a thicker granular or spinous layer, fluid between keratinocytes, or keratinocytes that come apart.","Parakeratosis = nuclei left in the stratum corneum","483",["Robbins ch 25","Bootcamp.com Dermatology"]],"osmolax":["Unabsorbed solute keeps water in the lumen","Soluble compounds the gut cannot absorb leave an osmotic load in the lumen. Because fecal water stays isotonic throughout the colon, water is held with them — stool becomes more liquid, the bowel distends, and peristalsis follows.","Lactulose: acidify the colon, trap NH₄⁺","408, 399",["Katzung ch 62","Bootcamp.com Gastroenterology"]],"prokinetic":["Lift dopamine’s brake, mimic motilin, or boost ACh","In the gut, dopamine dampens cholinergic stimulation of smooth muscle.","Metoclopramide empties the stomach but can leave tardive dyskinesia","407, 408, 378, 250, 532, 587",["Katzung ch 62","Bootcamp.com Gastroenterology"]],"emesisrx":["Four inputs, five receptors — match the drug to the trigger","Vomiting is coordinated in the medulla by the nucleus tractus solitarius and neighbouring nuclei (the “vomiting center”).","Motion sickness → H₁/M₁ blockers; chemotherapy → 5-HT₃, NK₁ and D₂ blockers","506, 407",["Katzung ch 62","Guyton ch 67"]],"d2emetic":["D₂ block in the chemoreceptor trigger zone","Drugs from the antipsychotic families stop nausea by blocking D₂ receptors in the chemoreceptor trigger zone. Phenothiazines also block muscarinic receptors, and their antihistamine action makes them sedating.","Antiemetic that sedates and causes dystonia = a phenothiazine","407, 532, 587",["Katzung ch 62","Katzung ch 16"]],"motionrx":["Block M₁ and H₁ on the vestibular route","Motion excites the vestibular labyrinth; signals travel through the vestibular nuclei and cerebellum to the chemoreceptor trigger zone and vomiting center.","Seasick → scopolamine patch or an older antihistamine","506, 240, 705",["Katzung ch 62","Katzung ch 16"]],"nodalart":["Both nodes usually hang off the right coronary artery","The SA nodal artery usually arises as an atrial branch of the RCA (about 60%), otherwise from the left coronary (about 40%).","SA and AV nodes: usually the RCA","288, 310",["Moore ch 4","Bootcamp.com Cardiology"]],"swanganz":["A venous catheter that reads the left atrium from the pulmonary artery","The Swan-Ganz (pulmonary artery) catheter is a venous catheter passed through the right atrium and ventricle into the pulmonary artery and pushed until it wedges in a small branch.","Wedge pressure ≈ left atrial pressure, except in mitral stenosis","300, 317",["Guyton ch 39","Moore ch 8"]],"ivcanat":["Formed at L5 · through the diaphragm at T8","The IVC — the largest vein, and valveless — forms anterior to L5 from the two common iliac veins, ascends to the right of the aorta and passes through the caval opening in the diaphragm's central tendon at T8, entering the right atrium almost at once.","IVC: formed at L5, through the diaphragm at T8","661, 681, 691",["Moore ch 5","Moore ch 4"]],"antiglobulin":["Is antibody on the red cells, or free in the serum?","Anti-human globulin (the Coombs reagent) binds immunoglobulin or complement sitting on red cells and links the cells together, so coated cells visibly agglutinate.","Direct = antibody on the cells · indirect = antibody in the serum","110, 249, 416",["Robbins ch 14","Bootcamp.com Immunology"]],"psoasabscess":["Pus in the iliopsoas — flank pain, fever, pain on hip extension","A collection of pus in the iliopsoas compartment. It is seeded through the blood or spreads from a neighboring infection — vertebral osteomyelitis, tuberculous spondylitis (Pott disease) or pyelonephritis.","Fever + flank pain + pain on hip extension","456, 463",["Bootcamp.com MSK"]],"catatonia":["A psychomotor syndrome — stupor, mutism, posturing","Catatonia is a syndrome of disturbed movement and behavior seen in several disorders: DSM-5 uses it as a specifier for schizophrenia-spectrum disorders and for manic or depressive episodes (it can also be due to a medical condition or a substance), and…","Mute, motionless patient who holds any posture they are placed in","577, 579",["Kaplan & Sadock ch 5","Kaplan & Sadock ch 22"]],"feeddz":["Effortless regurgitation · or too little intake without body-image fears","Rumination disorder: repeated, effortless, painless regurgitation of partly digested food soon after meals — re-chewed, then swallowed or spat out — for at least 1 month after a period of normal functioning.","Infant arches the back and contentedly brings milk back up after feeds","",["Kaplan & Sadock ch 2"]],"commdz":["DSM-5 communication disorders — language vs speech","DSM-5 separates language disorder — expressive or mixed receptive–expressive deficits: small vocabulary, short or ungrammatical sentences, poorly connected discourse — from the speech disorders: speech sound disorder (formerly phonologic disorder) and…","Says “tup” for cup with normal vocabulary and grammar","",["Kaplan & Sadock ch 2"]],"respctr":["The medulla makes the rhythm, the pons trims inspiration","The dorsal respiratory group (nucleus tractus solitarius) drives inspiration with a ramp signal: diaphragm excitation builds steadily for about 2 seconds, then stops abruptly so elastic recoil gives passive expiration.","Medulla makes the rhythm, the pons cuts inspiration short","",["Guyton ch 42","Costanzo ch 5"]],"astroidh":["Diffuse glioma · IDH + TP53 + ATRX · CNS WHO grade 2–4","A diffusely infiltrating astrocytic glioma defined by three simultaneous changes: IDH1 or IDH2 mutation (the earliest step), TP53 mutation, and ATRX inactivation (a way of evading senescence).","IDH + TP53 + ATRX = astrocytoma; IDH + 1p/19q = oligodendroglioma","",["Robbins ch 28"]],"adrtumor":["Small yellow adenoma vs huge invasive carcinoma","Cortical adenomas are mostly clinically silent and found by chance; a functional one secretes cortisol (Cushing syndrome — suppressed ACTH makes the rest of the cortex atrophy) or aldosterone (Conn syndrome — no atrophy).","Small yellow adrenal nodule on a CT done for something else","352, 354",["Robbins ch 24"]],"metadduct":["Forefoot turned in, hindfoot normal · corrects itself","The commonest foot deformity of newborns (about 5 per 1000 births, often bilateral): the forefoot deviates medially, with the apex at the midtarsal region, while the hindfoot is normal.","Newborn forefoot curves inward; heel and ankle are normal","",["OCOM Ortho"]],"enchondroma":["Benign hyaline cartilage in the medulla of hand and foot bones","A benign tumor of hyaline cartilage arising inside the medullary cavity (a chondroma on the bone surface is juxtacortical). It is the commonest cartilage-producing tumor and the commonest tumor of the hand.","Calcified lucent lesion in a finger phalanx found after a minor fracture","",["Robbins ch 26","Bootcamp.com MSK"]],"siga":["Dimer + J chain + secretory component","IgA is the most produced antibody overall, though its serum concentration is lower. TGF-β drives B cells to switch to IgA.","IgA crosses the epithelium by transcytosis and picks up its secretory component on the way","103",["Pawlina ch 17","OCOM Rheum"]],"nmjtrans":["CHT · ChAT · VAChT · Ca²⁺-triggered release · AChE · end-plate potential","The motor terminal takes choline back up with Na⁺ (CHT), joins it to acetyl-CoA with choline acetyltransferase and packs the ACh into vesicles (VAChT) in quanta of thousands of molecules.","Ca²⁺ in, ACh out, Na⁺ in — the end-plate potential reaches threshold","238, 459",["Guyton ch 7","Katzung ch 6"]],"serosynth":["Tryptophan → 5-HTP → 5-HT → (MAO) 5-HIAA","Serotonin is made from the essential amino acid tryptophan: tryptophan hydroxylase — the rate-limiting step — makes 5-hydroxytryptophan, and the aromatic L-amino acid decarboxylase removes its carboxyl to give 5-HT.","Tryptophan hydroxylase is the rate-limiting step","238",["Fundamental Neuroscience ch 4","Katzung ch 16"]],"medpontine":["Paramedian branches of the basilar artery — medial caudal pons","Paramedian branches of the basilar artery supply the medial basilar pons: the corticospinal fibers, the exiting abducens fibers and, most likely, part of the medial lemniscus.","Eye will not abduct on one side, arm and leg weak on the other","",["Fundamental Neuroscience ch 12","Fundamental Neuroscience ch 28"]],"il5drugs":["IL-5 (mepolizumab, reslizumab) · IL-5Rα (benralizumab)","Mepolizumab and reslizumab bind IL-5; benralizumab binds the IL-5 receptor α. Without IL-5 signaling, eosinophils cannot differentiate, mature, activate or survive — fewer eosinophils in the airway and the blood.","Anti-IL-5 = fewer eosinophils","705",["Katzung ch 20","Bootcamp.com Pulmonology"]],"nispendrin":["Na⁺/I⁻ symporter on the basal membrane · pendrin on the apical membrane","The first step of hormone synthesis.","Perchlorate and pertechnetate block the Na⁺/I⁻ symporter","335",["Katzung ch 38","Guyton ch 77"]],"cerumen":["Earwax plugging the external canal","Ceruminous glands — coiled apocrine-like glands of the outer canal — add their secretion to sebum and shed skin to make cerumen, which carries keratin out of the canal, lubricates it and traps particles.","Wax in the canal: conductive loss, Weber to that ear","548",["Pawlina ch 25","Fundamental Neuroscience ch 21"]],"gastrectomy":["Parietal cells removed or bypassed","Removing or bypassing the stomach takes away the parietal cells — the only source of intrinsic factor, the one essential gastric secretion — and much of the acid.","Megaloblastic anemia years after a gastrectomy","67, 378, 381, 393, 424, 426",["Costanzo ch 8","Robbins ch 14"]],"vsstage":["Warm, moist, boggy — or thick, dry, cool and hard","A reflex changes what the paraspinal tissue feels like as it ages. Acute: a local chemical reaction warms the skin, moisture and skin drag rise, the muscle is boggy and fusiform, and the joint is restricted without a firm end point.","Warm, moist, boggy paraspinals over the organ’s levels = an acute reflex","",["Foundations of Osteopathic Medicine ch 43","OCOM OMM"]],"ironcycle":["Duodenal cytochrome b · DMT1 · ferroportin · transferrin · ferritin","There is no regulated way to excrete iron (losses are ~1 mg/day), so balance is set at absorption.","Vitamin C reduces Fe³⁺ to the absorbable Fe²⁺","67, 209, 381, 423",["Robbins ch 14","Katzung ch 33"]],"lhsurge":["High, sustained estradiol flips feedback: LH surge, then ovulation","For most of the cycle estrogen exerts negative feedback on LH and FSH.","Estrogen high for long enough → feedback flips positive → LH surge → ovulation","649, 675",["Guyton ch 82"]],"micturition":["Parasympathetic empties, sympathetic stores, the pons coordinates","As the bladder fills, stretch receptors — strongest in the posterior urethra — signal through the pelvic nerves to sacral cord segments S2–S3, and the spinal micturition reflex sends parasympathetic output back that contracts the detrusor (M₃ receptors) and…","Parasympathetic voids, sympathetic stores, the pons coordinates","236",["Guyton ch 26","Fundamental Neuroscience ch 29"]],"jugfor":["Three nerves through one hole: taste & gag, voice & swallowing, turn & shrug","CN IX, X and XI leave the skull together through the jugular foramen, in numerical order in front of the internal jugular vein. IX and X arise by rootlets from the lateral medulla and carry sensory ganglia just below the foramen.","Absent gag + hoarse voice + weak shrug = jugular foramen","518",["Moore ch 10"]],"malako":["Soft yellow bladder plaques of foamy macrophages","A chronic inflammatory reaction to long-standing bacterial infection — mostly E coli, occasionally Proteus — that stems from acquired defects in phagocyte function: macrophages take up bacteria but their phagolysosome function is defective, so bacterial…","Yellow bladder plaques of foamy macrophages with Michaelis-Gutmann bodies","",["Robbins ch 21"]],"thalperf":["Small P1 branches to the rostral thalamus","The thalamoperforating arteries belong to the posteromedial branches of the posterior cerebral artery: they arise from its P1 segment near the basilar bifurcation and penetrate deeply to supply rostral areas of the thalamus.","Thalamoperforating occlusion → anterior thalamic infarct → persistent coma","",["Fundamental Neuroscience ch 15","Fundamental Neuroscience ch 19"]],"muscdev":["Back muscles from the myotome on dorsal rami; limbs and body wall on ventral rami","Skeletal muscle comes from paraxial mesoderm. Cells at the dorsomedial and ventrolateral lips of each somite form the dermomyotome, whose myotome cells make the muscles.","Epaxial = back = dorsal rami · hypaxial = limbs and body wall = ventral rami","",["Langman ch 11","Langman ch 12"]],"limbdev":["Week-7 rotation in opposite directions; apoptosis carves the digits","In the seventh week the limbs rotate in opposite directions: the upper limb about 90° laterally, so its extensors lie lateral and posterior and the thumb lateral; the lower limb about 90° medially, so its extensors lie anterior and the big toe medial.","Upper limb rotates laterally, lower limb medially","",["Langman ch 12"]],"functech":["Indirect: stack every motion pair toward ease, then breathe and hold","An indirect method, from William Johnston, that reads the motor system’s response at the start of motion rather than resistance at end range.","Stack ease, breathe, hold 3–5 s, re-examine","",["OCOM OMM"]],"seizure":["Synchronized, high-frequency neuronal firing","A seizure is synchronized, high-frequency firing of a population of neurons. It runs in three phases: aura (the early part — odd smells or tastes), ictal (first symptom to end of seizure activity) and postictal (gradual recovery to baseline).","Aura → ictal → postictal","531",["Katzung ch 24","Kaplan & Sadock ch 3"]],"focalseiz":["Start in one area — most often the medial temporal lobe","Focal seizures begin in a single area of the brain, most commonly the medial temporal lobe. They are split by whether consciousness is kept, and they can spread to become secondarily generalized tonic-clonic seizures.","Odd smell, then lip smacking and staring, then confusion","531",["Katzung ch 24","Kaplan & Sadock ch 3"]],"absence":["Thalamic T-type Ca²⁺ channels · 3 Hz spike-and-wave","Generalized seizures of brief blank staring with 3 Hz spike-and-wave discharges on EEG. They usually begin in childhood (childhood absence epilepsy starts at 4–10 years) and mostly remit by age 12.","Child staring off many times a day, worse when hyperventilating","531",["Katzung ch 24","Guyton ch 60"]],"gtc":["Diffuse from the onset","Generalized seizures involve the brain diffusely from the start.","Bit her tongue, wet herself, confused afterward","531",["Katzung ch 24","Guyton ch 60"]],"pnes":["Seizure-like events without epileptic discharges","Episodes that resemble syncope or tonic-clonic seizures but have no epileptic EEG correlate.","Long thrashing episode with eyes shut and no postictal confusion","531",["Kaplan & Sadock ch 12","Kaplan & Sadock ch 3"]],"phenytoin":["Blocks voltage-gated Na⁺ channels","Holds Na⁺ channels inactivated. A narrow-spectrum drug for focal seizures. Its elimination saturates — zero-order (capacity-limited) kinetics.","Gums, hair, double vision","560",["Katzung ch 24","Kaplan & Sadock ch 21"]],"carbamazepine":["Blocks voltage-gated Na⁺ channels","A narrow-spectrum Na⁺-channel blocker for focal seizures, and first-line for trigeminal neuralgia (with oxcarbazepine). Also a mood stabilizer in bipolar disorder.","Trigeminal neuralgia drug that causes SIADH and agranulocytosis","560",["Katzung ch 24","Kaplan & Sadock ch 21"]],"valproate":["Blocks Na⁺ and Ca²⁺ channels · blocks GABA transaminase","Broad spectrum for focal and generalized seizures (including absence). It blocks Na⁺ and Ca²⁺ channels and inhibits GABA transaminase, so GABA builds up.","Broad spectrum, but liver, pancreas and neural tube","560",["Katzung ch 24","Kaplan & Sadock ch 21"]],"lamotrigine":["Blocks voltage-gated Na⁺ channels","A broad-spectrum Na⁺-channel blocker for focal and generalized seizures, and a mood stabilizer in bipolar disorder.","New rash on lamotrigine → think SJS","560",["Katzung ch 24","Kaplan & Sadock ch 21"]],"ethosuximide":["Blocks T-type Ca²⁺ channels (thalamus)","Blocks the T-type Ca²⁺ channels behind the thalamocortical 3 Hz rhythm. Narrow spectrum: absence seizures only.","Absence seizure → ethosuximide","560",["Katzung ch 24","Kaplan & Sadock ch 21"]],"pnacauses":["Who gets which bug","The likely cause of pneumonia shifts with age and with the setting the patient comes from.","Runts May Cough Chunky Sputum","175",["Robbins ch 15","Katzung ch 51"]],"utibugs":["Ascending infection from the urethra","Most UTIs ascend from the urethra to the bladder (cystitis) and can continue to the kidney (pyelonephritis). They are about 10 times more common in women, whose shorter urethras are colonized by fecal flora.","Young sexually active woman with UTI, nitrite negative → S saprophyticus","178",["Robbins ch 20","Katzung ch 51"]],"hai":["Risk factor → pathogen","E coli (UTI) and S aureus (wound infection) are the two most common causes.","Line infection months after placement = S epidermidis","181",["Katzung ch 51","Robbins ch 8"]],"hivoi":["↓ CD4⁺ → reactivation and dissemination","As CD4⁺ counts fall, past infections reactivate (TB, HSV, shingles), bacterial and fungal infections disseminate, and non-Hodgkin lymphomas appear.","CD4 under 200 with ground-glass opacities → Pneumocystis","173",["Robbins ch 6","Robbins ch 8"]],"unvaccinated":["Vaccine-preventable diseases","First Aid groups the classic vaccine-preventable presentations by system.","Unvaccinated child drooling with stridor → epiglottitis","182",["Robbins ch 8","Katzung Appendix 1"]],"nociception":["TRPV1 → Ca²⁺ influx → Na⁺ channels fire","Mechanical, thermal or chemical stimuli open transient receptor potential vanilloid (TRPV) receptors; Ca²⁺ influx activates Na⁺ channels and the signal travels in Aδ fibers (sharp, acute pain) or C fibers (dull, throbbing, chronic pain).","Aδ = sharp and fast · C = dull and slow","235",["Fundamental Neuroscience ch 18","Katzung ch 31"]],"neuropathicpain":["Upregulated, persistently active voltage-gated Na⁺ channels","Pain from dysfunction of the CNS or PNS itself, carried by upregulated and persistently active voltage-gated Na⁺ channels. Diabetic peripheral neuropathy is the classic example.","Burning, electric pain that ordinary analgesics don't touch","235",["Fundamental Neuroscience ch 18","Katzung ch 30"]],"fibromyalgia":["Widespread pain with normal inflammatory markers","Chronic, widespread musculoskeletal pain with no inflammation to find.","Widespread pain and fatigue with normal labs in a young woman","477",["Katzung ch 30","Kaplan & Sadock ch 21"]],"thalamicpain":["Thalamic lesion → central neuropathic pain","Severe, treatment-resistant neuropathic pain after a thalamic lesion, which may follow a lenticulostriate artery occlusion.","Months after a small thalamic stroke, light touch burns on the opposite side","529",["Fundamental Neuroscience ch 18"]],"phantomlimb":["Reorganization of the primary somatosensory cortex","Burning, aching or electric shock-like pain felt in a limb that is no longer there, associated with reorganization of the 1° somatosensory cortex.","Pain in the foot that was amputated","529",["Fundamental Neuroscience ch 18"]],"tramadol":["Very weak μ agonist + NE and 5-HT reuptake inhibition","A very weak opioid agonist that also blocks reuptake of norepinephrine and serotonin. Used for chronic pain.","Opioid that can cause seizures and serotonin syndrome","567",["Katzung ch 31","Katzung ch 30"]],"capsaicin":["Overstimulates, then desensitizes nociceptive fibers","The hot-pepper compound excessively stimulates and then desensitizes nociceptive fibers, so less substance P is released and pain falls.","Topical hot-pepper cream for neuropathic pain","568",["Fundamental Neuroscience ch 18"]],"ddh":["Abnormal acetabulum development","The acetabulum develops abnormally in the newborn, leaving the hip unstable or dislocated.","Breech newborn with a hip clunk","466",["Moore ch 7","Langman ch 12"]],"lcp":["Idiopathic avascular necrosis of the femoral head","Idiopathic avascular necrosis of the femoral head in a young child.","6-year-old boy limping with a normal first x-ray","466",["Robbins ch 26","Moore ch 7"]],"scfe":["Femoral epiphysis slips off the neck","Increased axial force on the femoral head lets the epiphysis displace relative to the femoral neck — like a scoop of ice cream slipping off a cone.","Obese 12-year-old with knee pain and a limp — check the hip","466",["Moore ch 7","Robbins ch 26"]],"osgood":["Avulsion stress at the tibial tuberosity","Repetitive strain and chronic avulsion of the secondary ossification center of the tibial tuberosity.","Teen athlete with a tender bump below the kneecap","466",["Moore ch 7"]],"patellofemoral":["Overuse anterior knee pain","An overuse injury causing anterior knee pain.","Knee aches after a long movie","466",["Moore ch 7"]],"nursemaid":["Annular ligament slips over the radial head","A sudden pull on the arm makes the immature annular ligament slip over the head of the radius.","Toddler swung by the arms won't use it","466",["Moore ch 3"]],"pedsfx":["Immature bone bends and buckles","Immature bone fails incompletely.","Torus: tension side remains solid","467",["Moore ch 1"]],"avn":["Infarction of bone and marrow","Infarction of bone and marrow, usually very painful. The most common site is the femoral head — a watershed area dependent on the medial circumflex femoral artery.","Long-term steroids, now groin pain","469",["Robbins ch 26"]],"ganglion":["Mucin-filled swelling over a joint or tendon sheath","A mucin-filled swelling over a joint or tendon sheath, most often on the dorsal wrist.","Smooth dorsal wrist lump that lights up","465",["Robbins ch 26"]],"lowerlimboveruse":["Repetitive loading of the leg and foot","Three classic overuse injuries of runners and recruits.","Heel pain with the first step out of bed","465",["Moore ch 7"]],"tmd":["TMJ and muscles of mastication","A multifactorial group of disorders of the temporomandibular joint and the muscles of mastication, including abnormal trigeminal pain processing.","Jaw pain and earache worse with chewing","465",["Moore ch 9"]]};
